  /* 可靠聚焦：场景从 visibility:hidden 过渡期间 focus() 会被静默拒绝，
     因此同步首试 + 有界重试验收（document.activeElement 落位即停），
     且目标所属场景不再是 active 时立即放弃，绝不跨场景抢焦点 */
  const focusReliably = (el) => {
    if (!el) return;
    el.setAttribute("tabindex", "-1");
    let tries = 0;
    const attempt = () => {
      const host = el.closest(".scene");
      if (host && !host.classList.contains("active")) return;
      el.focus({ preventScroll: true });
      if (document.activeElement === el) return;
      if (++tries < 12) setTimeout(attempt, 120);
    };
    attempt();
  };

  /* 下一次 goScene 完成后优先聚焦的元素（由 begin / next-cycle / retry 处理器指定） */
  let pendingSceneFocus = null;

  const goScene = (name) => {
    if (!scenes[name] || veilBusy) return;
    name = resolveScene(name);
    if (name === currentScene) return;
    hydrateSceneImages(name);
    AutoAdvance.clearAll();
    veilBusy = true;
    stopAnomaly();
    stopTrace();
    leaveWatch();
    leaveSwitch();
    leaveDeadletter();
    leaveCancel();
    leaveActing();
    leaveReliquary();
    closeCollapseModal();
    veil.classList.add("on");
    AudioEngine.whoosh();
    let completed = false;
    const complete = () => {
      if (completed) return;
      completed = true;
      const prev = scenes[currentScene];
      if (prev) {
        prev.classList.remove("active");
        prev.scrollTop = 0;
      }
      const next = scenes[name];
      next.classList.add("active");
      currentScene = name;
      sceneInit(name);
      if (location.hash !== "#" + name) location.hash = name;
      next.scrollTop = 0;
      /* 焦点恢复与 veil 收尾必须和场景切换同一拍完成：
         依赖嵌套定时器时，内层定时器一旦丢失就会造成
         veilBusy 永久卡死、veil 常亮与焦点悬空（QA 实测复现） */
      let focusEl = null;
      if (collapseModal && !collapseModal.hasAttribute("hidden") && retryGovernanceBtn) focusEl = retryGovernanceBtn;
      if (!focusEl && pendingSceneFocus && pendingSceneFocus.getClientRects().length > 0) focusEl = pendingSceneFocus;
      pendingSceneFocus = null;
      const title = focusEl || next.querySelector(".sec-title, .ninth-rule, .dead-title");
      if (title) focusReliably(title);
      veil.classList.remove("on");
      veilBusy = false;
    };
    setTimeout(complete, reduced ? 60 : 480);
    /* 看门狗：主转场定时器丢失时兜底完成同一条 complete，路由器永不卡死 */
    setTimeout(complete, reduced ? 600 : 2000);
  };

  const route = () => {
    const name = (location.hash || "#threshold").slice(1);
    const resolved = scenes[name] ? name : "threshold";
    const alreadyThere = resolved === currentScene;
    goScene(resolved);
    initialRouteDone = true;
    if (alreadyThere) sceneInit(resolved);
  };
  window.addEventListener("hashchange", route);

  /* 场景出口按钮 */
  document.addEventListener("click", (e) => {
    const go = e.target.closest("[data-go]");
    if (go) goScene(go.dataset.go);
  });

  /* ============================================================
     经文带（滚动速度驱动）
     ============================================================ */
  const bands = $$(".band").map((band) => {
    const track = band.querySelector(".band-track");
    const unit = track.innerHTML;
    let guard = 0;
    while (track.scrollWidth < window.innerWidth * 1.6 && guard < 24) {
      track.innerHTML += unit;
      guard++;
    }
    const doubled = track.innerHTML;
    track.innerHTML = doubled + doubled;
    return {
      el: track,
      dir: Number(band.dataset.dir) || 1,
      offset: 0,
      period: track.scrollWidth / 2 || 1,
      hover: false,
    };
  });
  /* 经文带是启动期唯一需要量不在场场景尺寸的地方；量完后才让不在场的场景跳过样式与布局（见 styles.css） */
  body.classList.add("scenes-settled");

  bandsEl.addEventListener("pointerenter", () => bands.forEach((b) => (b.hover = true)));
  bandsEl.addEventListener("pointerleave", () => bands.forEach((b) => (b.hover = false)));

  let scrollBoost = 0;

  /* 彩蛋：凝视经文 3 秒，显出不属于经文的一句 */
  let gazeTimer = null;
  let phraseFound = false;
  bandsEl.addEventListener("pointerenter", () => {
    if (phraseFound) return;
    gazeTimer = setTimeout(() => {
      phraseFound = true;
      bandsEl.classList.add("revealed");
      toast("经文里混入了一句不是经文的话。");
    }, 3000);
  });
  bandsEl.addEventListener("pointerleave", () => clearTimeout(gazeTimer));

  /* ============================================================
     视差 + 主循环
     ============================================================ */
  const parTarget = { x: 0, y: 0 };
  const par = { x: 0, y: 0 };

  if (finePointer && !reduced) {
    window.addEventListener("mousemove", (e) => {
      parTarget.x = (e.clientX / window.innerWidth - 0.5) * 2;
      parTarget.y = (e.clientY / window.innerHeight - 0.5) * 2;
    }, { passive: true });
  }

  const loop = () => {
    drawField();

    if (finePointer) {
      ringPos.x += (mouse.x - ringPos.x) * 0.16;
      ringPos.y += (mouse.y - ringPos.y) * 0.16;
      const s = ringEl.offsetWidth / 2;
      ringEl.style.transform = `translate(${ringPos.x - s}px, ${ringPos.y - s}px)`;

      par.x += (parTarget.x - par.x) * 0.05;
      par.y += (parTarget.y - par.y) * 0.05;
      heroArt.style.transform = `translate3d(${par.x * 18}px, ${par.y * 12}px, 0)`;
      doorScene.style.transform = `translate3d(${par.x * -8}px, ${par.y * -5}px, 0)`;
    }

    for (const b of bands) {
      const speed = (0.42 + scrollBoost) * b.dir * (b.hover ? 0.12 : 1);
      b.offset -= speed;
      if (b.offset <= -b.period) b.offset += b.period;
      if (b.offset > 0) b.offset -= b.period;
      b.el.style.transform = `translate3d(${b.offset}px, 0, 0)`;
    }
    scrollBoost *= 0.94;

    requestAnimationFrame(loop);
  };

  if (reduced) {
    drawField();
  } else {
    requestAnimationFrame(loop);
  }

  let resizeTimer;
  window.addEventListener("resize", () => {
    resizeCanvas();
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
      /* 走廊不在场时不参与渲染，量到 0 就沿用上次的周期 */
      bands.forEach((b) => (b.period = b.el.scrollWidth / 2 || b.period));
    }, 250);
  });

  /* ============================================================
     门：纪年 / 敲门 / 低语 / 进入
     ============================================================ */
  const DEATH_DATE = new Date("2026-07-02T00:00:00");
  const eraDays = Math.max(1, Math.floor((Date.now() - DEATH_DATE.getTime()) / 86400000) + 1);
  $("#era-line").textContent = `神死后的第 ${eraDays} 天`;

  /* 子夜彩蛋 */
  const midnight = new Date().getHours() === 0;
  if (midnight) body.classList.add("midnight");

  /* 苏醒状态：门在呼吸 */
  const syncAwake = () => {
    body.classList.toggle("awake", awake);
    statusLine.textContent = awake ? "门在呼吸 · 别靠太近" : "门后没有声音 · 暂时";
  };

  /* 门的不规律颤动 */
  const doorPulse = () => {
    doorScene.classList.add("pulse");
    setTimeout(() => doorScene.classList.remove("pulse"), 340);
  };

  if (!reduced) {
    const schedulePulse = () => {
      const wait = awake ? 2600 + Math.random() * 3000 : 5200 + Math.random() * 5600;
      setTimeout(() => { doorPulse(); schedulePulse(); }, wait);
    };
    schedulePulse();
  }

  /* 敲门 */
  const knockReplies = ["咚。", "咚。咚。", "咚。咚。咚。"];
  let knocks = 0;
  let totalKnocks = 0;
  let ajarTimer = null;
  let decayTimer = null;

  const shakeDoor = () => {
    if (reduced) return;
    [doorImg, doorOpenImg].forEach((img) => img.classList.remove("shaken"));
    void doorImg.getBoundingClientRect();
    [doorImg, doorOpenImg].forEach((img) => img.classList.add("shaken"));
  };

  const closeDoor = () => {
    doorScene.classList.remove("ajar", "opened");
    seamWhisper.textContent = "";
  };

  /* 根据持久苏醒状态恢复门的视觉与可访问性：完成后重新进入 threshold，
     门保持打开且可主动触发转场，但不会自行跳转。 */
  const syncDoorOpenState = () => {
    if (awake) {
      doorScene.classList.add("opened");
      doorBtn.setAttribute("aria-label", "门已打开，点击或按 Enter、Space 继续");
    } else {
      doorScene.classList.remove("opened");
      doorBtn.setAttribute("aria-label", "一扇紧闭的门。可以敲门。不建议。");
    }
    /* v43：回到首页时按当前会话敲门数恢复或隐藏回敲窗口 */
    syncCounterKnockWindow();
  };

  const tryScheduleThreshold = () => {
    if (thresholdConsumed) return;
    AutoAdvance.schedule("threshold", "protocol", {
      before: () => { knocks = 0; thresholdConsumed = true; },
      onSchedule: () => toast("门在你身后合上了。"),
    });
  };

  const knock = () => {
    /* v31 首选锁定：任一门前转场（三敲或热点）已排定后，忽略门/热点输入，
       第一条已接受的转场锁定归宿；离场取消后回来仍可正常敲门/再武装 */
    if (AutoAdvance.has("threshold")) return;
    /* 门已打开的状态下，任何主动激活都重新武装转场（用于 timer 被取消后）。 */
    if (doorScene.classList.contains("opened")) {
      shakeDoor();
      AudioEngine.knock();
      tryScheduleThreshold();
      return;
    }

    knocks++;
    totalKnocks++;
    shakeDoor();
    AudioEngine.knock();
    clearTimeout(decayTimer);

    if (knocks >= 4) {
      knocks = 0;
      clearTimeout(ajarTimer);
      closeDoor();
      AutoAdvance.clear("threshold");
      statusLine.textContent = "门后重归安静。它记下了你的节奏。";
      toast("不要敲第四下。");
      syncCounterKnockWindow();
      return;
    }

    statusLine.textContent = knockReplies[knocks - 1];

    if (knocks === 3) {
      doorScene.classList.add("ajar", "opened");
      seamWhisper.textContent = "……进来";
      AudioEngine.bell();
      doorBtn.setAttribute("aria-label", "门已打开，点击或按 Enter、Space 继续");
      if (!awake) {
        awake = true;
        store.set("goddead_awake", "true");
        body.classList.add("awake");
      }
      statusLine.textContent = "门已经开了。你侧身挤了进去。";
      clearTimeout(ajarTimer);
      tryScheduleThreshold();
    } else {
      /* 敲到一半停手，门当作无事发生 */
      decayTimer = setTimeout(() => {
        if (!doorScene.classList.contains("ajar")) {
          knocks = 0;
          syncAwake();
          syncCounterKnockWindow();
        }
      }, 2600);
    }

    /* v43：每次敲门后同步回敲窗口（1/2 显露、3/0 隐藏） */
    syncCounterKnockWindow();

    /* 彩蛋：敲满七下，它敲回来 */
    if (totalKnocks === 7) {
      setTimeout(() => {
        shakeDoor();
        AudioEngine.knock();
        toast("它敲了回来。");
      }, 1600);
    }
  };

  doorBtn.addEventListener("click", knock);
  doorBtn.addEventListener("keydown", (e) => {
    if (e.key === " ") {
      e.preventDefault();
      knock();
    }
  });

  /* 低语：画叉的位置，血红色，时隐时现 */
  const whisperSpots = $$(".whisper");
  const whisperPool = [
    "别出声", "祂还在听", "门后没有人", "不要数符号",
    "它在数你", "别回答", "你已经被看见了", "灯灭之前离开",
    "不要敲第四下", "门记得每一张脸", "第七条是假的", "回来",
  ];

  if (reduced) {
    whisperSpots[0].textContent = "别出声";
    whisperSpots[0].classList.add("on");
  } else {
    const revealWhisper = (spot) => {
      const phrase = whisperPool[Math.floor(Math.random() * whisperPool.length)];
      spot.innerHTML = Array.from(phrase)
        .map((c, i) => `<span class="ch" style="--i:${i}">${c}</span>`)
        .join("");
      spot.classList.add("on");
      setTimeout(() => {
        spot.classList.remove("on");
        setTimeout(() => { spot.textContent = ""; }, 1400);
      }, 2600 + Math.random() * 2600);
    };

    const cycleWhispers = () => {
      const free = whisperSpots.filter((s) => !s.classList.contains("on"));
      if (free.length) {
        revealWhisper(free.splice(Math.floor(Math.random() * free.length), 1)[0]);
        /* 偶尔两处同时低语 */
        if (Math.random() < 0.4 && free.length) {
          revealWhisper(free[Math.floor(Math.random() * free.length)]);
        }
      }
      setTimeout(cycleWhispers, 1500 + Math.random() * 3200);
    };
    setTimeout(cycleWhispers, 1600);
  }

  /* ============================================================
     文字的异变：页面上的字会自己换一笔
     ============================================================ */
  const corruptPool = "祂死门血肉骨影空哑";

  if (!reduced) {
    let corrupting = false;
    const corruptChar = () => {
      corrupting = false;
      if (document.hidden) return scheduleCorrupt();
      const candidates = $$(".frag, .sec-desc, .ninth-text, .colophon-whisper")
        .filter((el) => el.children.length === 0 && el.textContent.trim().length > 5
          && el.closest(".scene").classList.contains("active"));
      if (!candidates.length) return scheduleCorrupt();
      const el = candidates[Math.floor(Math.random() * candidates.length)];
      const text = el.textContent;
      const i = 1 + Math.floor(Math.random() * (text.length - 2));
      const wrong = corruptPool[Math.floor(Math.random() * corruptPool.length)];
      if (text[i] === wrong) return scheduleCorrupt();
      corrupting = true;
      el.dataset.orig = text;
      el.innerHTML = text.slice(0, i)
        + `<span class="corrupted">${wrong}</span>`
        + text.slice(i + 1);
      setTimeout(() => {
        el.textContent = el.dataset.orig;
        delete el.dataset.orig;
        corrupting = false;
      }, 1300 + Math.random() * 900);
      scheduleCorrupt();
    };
    const scheduleCorrupt = () => {
      setTimeout(corruptChar, 9000 + Math.random() * 14000);
    };
    scheduleCorrupt();
  }

  /* ============================================================
     远处的敲门声（守则其二：假装没有听见）
     ============================================================ */
  const tremble = () => {
    if (reduced) return;
    body.classList.add("tremor");
    setTimeout(() => body.classList.remove("tremor"), 260);
  };

  if (!reduced) {
    const distantKnock = () => {
      if (!document.hidden) {
        tremble();
        AudioEngine.knock(0.13);
        if (Math.random() < 0.35) {
          setTimeout(() => { tremble(); AudioEngine.knock(0.09); }, 700);
        }
      }
      setTimeout(distantKnock, 42000 + Math.random() * 52000);
    };
    setTimeout(distantKnock, 26000 + Math.random() * 20000);
  }

  /* ============================================================
     守则：异变与回应
     ============================================================ */
  let anomalyTimer = null;
  let restoreTimer = null;
  let nineWindow = false;
  let ruleSevenClicks = 0;

  const startAnomaly = () => {
    stopAnomaly();
    if (reduced) return;
    const tick = () => {
      anomalyTimer = setTimeout(() => {
        if (currentScene !== "protocol") return;
        if (Math.random() < 0.65) {
          rulesCount.textContent = "玖";
          rulesCount.classList.add("wrong");
          nineWindow = true;
          restoreTimer = setTimeout(() => {
            rulesCount.textContent = "捌";
            rulesCount.classList.remove("wrong");
            nineWindow = false;
          }, 5200);
        }
        tick();
      }, 7000 + Math.random() * 8000);
    };
    tick();
  };

  const stopAnomaly = () => {
    clearTimeout(anomalyTimer);
    clearTimeout(restoreTimer);
    anomalyTimer = null;
    nineWindow = false;
    if (rulesCount) {
      rulesCount.textContent = "捌";
      rulesCount.classList.remove("wrong");
    }
  };

  rulesCount.addEventListener("click", () => {
    if (nineWindow) {
      nineWindow = false;
      toast("你数出了第九条。它一直在等你数出来。");
      goScene("ninth");
    } else {
      toast("数过了。是捌条。——暂时是捌条。");
    }
  });

  const ruleResponses = {
    1: "你没有听见任何回应。很好。",
    2: "门后没有人。真的没有。",
    3: "九个。你数了，对吧。",
    4: "低语不喜欢被逐字重复。",
    5: "回来的路，你还记得吗？",
    6: "现在几点？你确定吗？",
    7: "别再点这一条了。",
    8: "确认无效。",
  };

  const tryScheduleProtocol = () => {
    if (protocolConsumed) return;
    AutoAdvance.schedule("protocol", "corridor", {
      before: () => { protocolConsumed = true; },
      onSchedule: () => toast("守则已读。走廊在前方。"),
    });
  };

  /* v31 真实分流：其二→回返夹道，其三/其七→失号龛，其四→倒置窥孔；其一保持原主线走廊；
     v37 起其六分流至午夜回拨台；v38 起其八分流至门外代审窗；v39 起其五分流至归路核验站
     （原文与反馈逐字不变，仅目的地变更）。
     「玖」异常走 rulesCount 原逻辑，不被分流覆盖。 */
  const RULE_DETOUR = { 2: "return-passage", 3: "glyph-niche", 4: "peephole-chamber", 5: "return-audit", 6: "midnight-callback", 7: "glyph-niche", 8: "proxy-admission" };

  $$(".rules-list li").forEach((li) => {
    li.setAttribute("tabindex", "0");
    li.setAttribute("role", "button");
    const activate = () => {
      /* v31 首选锁定：任一规则已排定转场后，第一条已接受的转场锁定归宿，
         忽略本场景其他规则输入；「玖」异常走 rulesCount 原逻辑，不受此锁影响 */
      if (AutoAdvance.has("protocol")) return;
      const n = li.dataset.rule;
      li.classList.remove("touched");
      void li.offsetWidth;
      li.classList.add("touched");
      AudioEngine.knock();
      if (n === "7") {
        ruleSevenClicks++;
        if (ruleSevenClicks === 3) ruleSevenNote.textContent = "它知道你注意到它了。";
        if (ruleSevenClicks === 6) ruleSevenNote.textContent = "停下。";
        if (ruleSevenClicks >= 9) {
          ruleSevenClicks = 0;
          ruleSevenNote.textContent = "它在看你读这一条。";
          toast("第七条原谅你了。这次。");
          return;
        }
      }
      toast(ruleResponses[n] || "……");
      const detour = RULE_DETOUR[n];
      if (detour) {
        /* v39：其五分流时同时登记核验站入口（entry=protocol，mark answeredProtocolFive） */
        if (n === "5") markAuditEntry("protocol");
        /* v37：其六分流时同时登记回拨台入口（entry=protocol，mark answeredProtocolSix） */
        if (n === "6") markCallbackEntry("protocol");
        /* v38：其八分流时同时登记代审窗入口（entry=protocol，mark answeredProtocolEight） */
        if (n === "8") markProxyEntry("protocol");
        /* v40 守卫配套：分流落点是 v31 场景时，到访标记在点击时立即持久化（同 v31 热点契约） */
        if (FORECOURT_SCENES.includes(detour)) markForecourtVisited(detour);
        /* 分流取代主线 AutoAdvance；首选锁定已保证此处无未触发 timer，
           clear 仅作防御；点击「玖」仍走 goScene("ninth")，clearAll 会取消这里的调度 */
        AutoAdvance.clear("protocol");
        AutoAdvance.schedule("protocol", detour, {
          delay: branchDelay(),
          before: () => { protocolConsumed = true; },
        });
      } else {
        tryScheduleProtocol();
      }
    };
    li.addEventListener("click", activate);
    li.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        activate();
      }
    });
  });

  /* ============================================================
     v29 旁路支线：回声档案室 / 血管维修井 / 忏悔称量室
     状态统一存 goddead_v29_branches，容错旧/坏 JSON；
     只读不写任何 v28 治理与旧主线状态。
     ============================================================ */
  const BRANCH_KEY = "goddead_v29_branches";
  const BRANCH_SCENES = ["echo", "vein", "confession"];
  const getBranches = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(BRANCH_KEY, "{}")) || {};
    } catch { raw = {}; }
    const visited = {};
    const lastChoice = {};
    BRANCH_SCENES.forEach((b) => {
      visited[b] = Boolean(raw.visited && raw.visited[b] === true);
      lastChoice[b] = typeof (raw.lastChoice && raw.lastChoice[b]) === "string" ? raw.lastChoice[b] : null;
    });
    return { visited, lastChoice };
  };
  const saveBranches = (st) => store.set(BRANCH_KEY, JSON.stringify(st));

  /* 分支转场延迟：普通模式约 0.7–1.0 秒，reduced-motion 约 0.3 秒 */
  const branchDelay = () => reduced ? 300 : 700 + Math.floor(Math.random() * 300);

  const BRANCH_META = {
    echo: {
      responseEl: "#echo-response",
      intro: "回声不是说出去的话。档案室的门自己开了。",
      choices: {
        knock: { btn: "#echo-choice-knock", target: "threshold", response: "敲声顺着听筒爬回门外。它认得你的手。" },
        steps: { btn: "#echo-choice-steps", target: "corridor", response: "脚步声一遍比一遍近。你回到了走廊。" },
        /* v30：03:17 的铃改接入失真转接室（深层），值班室出口移到转接室内 */
        bell: { btn: "#echo-choice-bell", target: "echo-transfer", response: "03:17 的铃没有停。它被转接进了一条失真的线路。" },
      },
    },
    vein: {
      responseEl: "#vein-response",
      intro: "墙里的血管在井下交汇。维修井接受了你的登记。",
      choices: {
        down: { btn: "#vein-choice-down", target: "corridor", response: "顺流。血记得下坡的路，你回到了走廊。" },
        up: { btn: "#vein-choice-up", target: "protocol", response: "逆流。守则的第一条开始发痒。" },
        /* v30：隔离闸改接入逆流泵房（深层），值夜室出口移到泵房应急梯 */
        isolate: { btn: "#vein-choice-isolate", target: "vein-pump", response: "隔离阀后面不是井底。是一间仍在工作的泵房。" },
      },
    },
    confession: {
      responseEl: "#confession-response",
      intro: "忏悔不按句计费，按重量。称量室校准了秤。",
      choices: {
        door: { btn: "#confession-choice-door", target: "protocol", response: "秤承认了那三记敲击。守则等你回去。" },
        seven: { btn: "#confession-choice-seven", target: "corridor", response: "第七条被称出了重量。走廊收下这份坦白。" },
        /* v30：拒绝忏悔改登记进无名罪籍库（深层），不再直接跳回声档案室 */
        refuse: { btn: "#confession-choice-refuse", target: "confession-ledger", response: "拒绝也有重量。它被登记进了一册无名的罪籍。" },
      },
    },
  };

  const syncBranchEntries = () => {
    const st = getBranches();
    BRANCH_SCENES.forEach((b) => {
      const entry = $("#branch-entry-" + b);
      const link = $("#" + b + "-link");
      [entry, link].forEach((el) => {
        if (!el) return;
        if (st.visited[b]) el.removeAttribute("hidden");
        else el.setAttribute("hidden", "");
      });
    });
  };

  const paintBranchChoice = (sceneKey) => {
    const meta = BRANCH_META[sceneKey];
    const st = getBranches();
    Object.keys(meta.choices).forEach((ck) => {
      const btn = $(meta.choices[ck].btn);
      if (btn) btn.setAttribute("aria-pressed", st.lastChoice[sceneKey] === ck ? "true" : "false");
    });
  };

  const enterBranch = (sceneKey) => {
    const meta = BRANCH_META[sceneKey];
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = "";
    paintBranchChoice(sceneKey);
  };

  /* 分支选择：点击/键盘激活 → 短反馈 → 自动进入目标；没有第二个必点按钮。
     v54 起加共享守卫：只有 live scene 上、转场未锁时的第一次接受生效
     （合成/离场/连点调用被拒），九个旧选择的反馈/目标/lastChoice 语义不变；
     v54 计分只挂在接受之后 */
  const chooseBranch = (sceneKey, choiceKey) => {
    const meta = BRANCH_META[sceneKey];
    const choice = meta.choices[choiceKey];
    if (!choice) return;
    if (currentScene !== sceneKey) return;
    if (AutoAdvance.has(sceneKey)) return;
    const st = getBranches();
    st.lastChoice[sceneKey] = choiceKey;
    saveBranches(st);
    paintBranchChoice(sceneKey);
    recordPressureChoice(sceneKey, choiceKey);

    const ok = !choice.guard || choice.guard();
    const target = ok ? choice.target : "corridor";
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = ok ? choice.response : choice.failResponse;
    AudioEngine.knock(0.16);
    /* v30：选择的目标是深层区域时，到访标记在点击时立即持久化（同 v29 残页分流契约） */
    if (DEEP_SCENES.includes(target)) markDeepVisited(target);
    AutoAdvance.schedule(sceneKey, target, { delay: branchDelay() });
  };

  BRANCH_SCENES.forEach((sceneKey) => {
    const meta = BRANCH_META[sceneKey];
    Object.keys(meta.choices).forEach((choiceKey) => {
      const btn = $(meta.choices[choiceKey].btn);
      if (btn) btn.addEventListener("click", () => chooseBranch(sceneKey, choiceKey));
    });
  });

  const paintBranchMemory = () => {
    const memory = $("#branch-memory");
    if (!memory) return;
    const st = getBranches();
    const names = { echo: "回声档案室", vein: "血管维修井", confession: "忏悔称量室" };
    const visitedNames = BRANCH_SCENES.filter((b) => st.visited[b]).map((b) => names[b]);
    if (visitedNames.length === 0) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `你走过 ${visitedNames.length} 条旁路：${visitedNames.join("、")}。主线没有因此变短，但你不再只有一条走廊。`;
    memory.hidden = false;
  };

  /* ============================================================
     v30 深层支线：失真转接室 / 逆流泵房 / 无名罪籍库
     三间二级区域构成可循环三角网络，各保留差异化出口；
     状态独立存 goddead_v30_branch_depth，容错坏 JSON，
     不读不写 v28 治理、v29 支线与旧主线状态。
     ============================================================ */
  const DEPTH_KEY = "goddead_v30_branch_depth";
  const DEEP_SCENES = ["echo-transfer", "vein-pump", "confession-ledger"];
  const DEEP_PARENT = { "echo-transfer": "echo", "vein-pump": "vein", "confession-ledger": "confession" };
  const getDepth = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(DEPTH_KEY, "{}")) || {};
    } catch { raw = {}; }
    const deepVisited = {};
    const lastDeepChoice = {};
    DEEP_SCENES.forEach((d) => {
      deepVisited[d] = Boolean(raw.deepVisited && raw.deepVisited[d] === true);
      lastDeepChoice[d] = typeof (raw.lastDeepChoice && raw.lastDeepChoice[d]) === "string" ? raw.lastDeepChoice[d] : null;
    });
    return { deepVisited, lastDeepChoice };
  };
  const saveDepth = (st) => store.set(DEPTH_KEY, JSON.stringify(st));

  const DEEP_META = {
    "echo-transfer": {
      responseEl: "#echo-transfer-response",
      choices: {
        relay: { btn: "#echo-transfer-choice-relay", target: "vein-pump", response: "失真的语音顺着铜管爬进了血管维护网。" },
        seal: { btn: "#echo-transfer-choice-seal", target: "protocol", response: "你的声音被封进蜡筒。守则背面多了一行空白。" },
        bell: {
          btn: "#echo-transfer-choice-bell", target: "watch", response: "03:17 再次响起。这一回，值班的人接听了。",
          failResponse: "铃声没有找到值班的人。回声把你放回走廊。",
          failTarget: "corridor",
          guard: () => watchUnlocked(),
        },
      },
    },
    "vein-pump": {
      responseEl: "#vein-pump-response",
      choices: {
        release: { btn: "#vein-pump-choice-release", target: "echo-transfer", response: "回声压力泄进了转接室。听筒轻轻发烫。" },
        sediment: { btn: "#vein-pump-choice-sediment", target: "confession-ledger", response: "黑色沉积物沉进罪籍管道。档案页变重了。" },
        ladder: {
          btn: "#vein-pump-choice-ladder", target: "watch", response: "应急梯尽头，是值夜室的地面。",
          failResponse: "应急梯中途断开。你落回了守则的台阶。",
          failTarget: "protocol",
          guard: () => watchUnlocked(),
        },
      },
    },
    "confession-ledger": {
      responseEl: "#confession-ledger-response",
      choices: {
        crossout: { btn: "#ledger-choice-crossout", target: "echo-transfer", response: "划掉的名字没有消失。它变成了一段失真的语音。" },
        archive: { btn: "#ledger-choice-archive", target: "vein-pump", response: "你被归档为仍在场的见证者。泵房开始按你的脉搏运转。" },
        reject: {
          btn: "#ledger-choice-reject", target: () => (watchUnlocked() ? "watch" : "corridor"), response: "整份记录被拒收。三处档案同时咳嗽了一声。",
          failResponse: "记录退回原处。守则替你签收了一行。",
          failTarget: "protocol",
          guard: () => DEEP_SCENES.every((d) => getDepth().deepVisited[d]),
        },
      },
    },
  };

  const syncDeepEntries = () => {
    const st = getDepth();
    DEEP_SCENES.forEach((d) => {
      const entry = $("#branch-entry-" + d);
      const link = $("#" + d + "-link");
      [entry, link].forEach((el) => {
        if (!el) return;
        if (st.deepVisited[d]) el.removeAttribute("hidden");
        else el.setAttribute("hidden", "");
      });
    });
  };

  /* 到访标记在点击时立即持久化：即便转场被回退取消，入口也已出现 */
  const markDeepVisited = (sceneKey) => {
    const st = getDepth();
    if (st.deepVisited[sceneKey]) return;
    st.deepVisited[sceneKey] = true;
    saveDepth(st);
    syncDeepEntries();
  };

  const paintDeepChoice = (sceneKey) => {
    const meta = DEEP_META[sceneKey];
    const st = getDepth();
    Object.keys(meta.choices).forEach((ck) => {
      const btn = $(meta.choices[ck].btn);
      if (btn) btn.setAttribute("aria-pressed", st.lastDeepChoice[sceneKey] === ck ? "true" : "false");
    });
  };

  const enterDeep = (sceneKey) => {
    const meta = DEEP_META[sceneKey];
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = "";
    paintDeepChoice(sceneKey);
  };

  /* 深层选择：点击/键盘激活 → 短反馈 → 自动进入目标；
     条件动作给出差异化出口（watch / corridor / protocol），没有第二个必点按钮 */
  const chooseDeep = (sceneKey, choiceKey) => {
    const meta = DEEP_META[sceneKey];
    const choice = meta.choices[choiceKey];
    if (!choice) return;
    const st = getDepth();
    st.lastDeepChoice[sceneKey] = choiceKey;
    saveDepth(st);
    paintDeepChoice(sceneKey);

    const ok = !choice.guard || choice.guard();
    const target = ok
      ? (typeof choice.target === "function" ? choice.target() : choice.target)
      : (choice.failTarget || "corridor");
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = ok ? choice.response : choice.failResponse;
    AudioEngine.knock(0.16);
    if (DEEP_SCENES.includes(target)) markDeepVisited(target);
    AutoAdvance.schedule(sceneKey, target, { delay: branchDelay() });
  };

  DEEP_SCENES.forEach((sceneKey) => {
    const meta = DEEP_META[sceneKey];
    Object.keys(meta.choices).forEach((choiceKey) => {
      const btn = $(meta.choices[choiceKey].btn);
      if (btn) btn.addEventListener("click", () => chooseDeep(sceneKey, choiceKey));
    });
  });

  const paintDeepMemory = () => {
    const memory = $("#deep-memory");
    if (!memory) return;
    const st = getDepth();
    const names = { "echo-transfer": "失真转接室", "vein-pump": "逆流泵房", "confession-ledger": "无名罪籍库" };
    const visitedNames = DEEP_SCENES.filter((d) => st.deepVisited[d]).map((d) => names[d]);
    if (visitedNames.length === 0) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `你下到了更深的地方：${visitedNames.join("、")}。档案不承认见过你。`;
    memory.hidden = false;
  };

  /* ============================================================
     v31 门前三岔：倒置窥孔 / 失号龛 / 回返夹道
     状态独立存 goddead_v31_forecourt_weave，容错坏 JSON；
     不读不写 v28/v29/v30 与旧主线状态；三个新场景不设解锁门槛，
     干净存档可从门外热点进入，也允许直接 hash 直达（直达即到访）。
     ============================================================ */
  const FORECOURT_KEY = "goddead_v31_forecourt_weave";
  const FORECOURT_SCENES = ["peephole-chamber", "glyph-niche", "return-passage"];
  const FORECOURT_MARKS = [
    "witnessed", "heardInside", "refusedSight",
    "countedNine", "erasedSeven", "tookBlank",
    "followedInward", "knockedInside", "walkedBackward",
  ];
  const FORECOURT_VISIT_KEY = { "peephole-chamber": "peephole", "glyph-niche": "glyph", "return-passage": "returnPassage" };
  const FORECOURT_TRANSITIONS_CAP = 9999;

  const getForecourt = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(FORECOURT_KEY, "{}")) || {};
    } catch { raw = {}; }
    const visited = {};
    Object.values(FORECOURT_VISIT_KEY).forEach((k) => {
      visited[k] = Boolean(raw.visited && raw.visited[k] === true);
    });
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => FORECOURT_MARKS.includes(m)))]
      : [];
    const lastChoice = typeof raw.lastChoice === "string" && FORECOURT_MARKS.includes(raw.lastChoice)
      ? raw.lastChoice
      : null;
    let transitions = Number(raw.transitions);
    if (!Number.isFinite(transitions) || transitions < 0) transitions = 0;
    transitions = Math.min(FORECOURT_TRANSITIONS_CAP, Math.floor(transitions));
    return { visited, marks, lastChoice, transitions };
  };
  const saveForecourt = (st) => store.set(FORECOURT_KEY, JSON.stringify(st));

  const FORECOURT_META = {
    "peephole-chamber": {
      responseEl: "#peephole-response",
      choices: {
        witnessed: { btn: "#peephole-choice-witness", target: "protocol", response: "镜后那只眼，比你晚眨了一次。" },
        heardInside: { btn: "#peephole-choice-listen", target: "return-passage", response: "敲门声从你身后传来。你明明还在门外。" },
        refusedSight: { btn: "#peephole-choice-close", target: "eyelid-archive", response: "黑镜替你继续看着。" },
      },
    },
    "glyph-niche": {
      responseEl: "#glyph-response",
      choices: {
        countedNine: { btn: "#glyph-choice-count", target: "peephole-chamber", response: "你数到九。墙里只回了八声。" },
        erasedSeven: { btn: "#glyph-choice-erase", target: "protocol", response: "第七号消失后，守则多出一行空白。" },
        tookBlank: { btn: "#glyph-choice-blank", target: "unnumbered-vestibule", response: "没有编号的门，为你让出了一条路。" },
      },
    },
    "return-passage": {
      responseEl: "#return-response",
      choices: {
        followedInward: { btn: "#return-choice-follow", target: "glyph-niche", response: "脚印在第七步拐进了墙里。" },
        knockedInside: { btn: "#return-choice-knock", target: "protocol", response: "门外的你，假装没有听见。" },
        walkedBackward: { btn: "#return-choice-backward", target: "reverse-stairwell", response: "你没有转身，却看见走廊迎面而来。" },
      },
    },
  };

  /* 目录入口：首次到访后原子恢复，未访问保持 hidden 不可聚焦 */
  const FORECOURT_LINKS = { "peephole-chamber": "#peephole-link", "glyph-niche": "#glyph-link", "return-passage": "#return-link" };
  const syncForecourtLinks = () => {
    const st = getForecourt();
    FORECOURT_SCENES.forEach((s) => {
      const link = $(FORECOURT_LINKS[s]);
      if (!link) return;
      if (st.visited[FORECOURT_VISIT_KEY[s]]) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  /* 到访标记在点击/进入时立即持久化：即便转场被回退取消，目录入口也已出现 */
  const markForecourtVisited = (sceneKey) => {
    const st = getForecourt();
    const key = FORECOURT_VISIT_KEY[sceneKey];
    if (!key || st.visited[key]) return;
    st.visited[key] = true;
    saveForecourt(st);
    syncForecourtLinks();
  };

  const paintForecourtChoice = (sceneKey) => {
    const meta = FORECOURT_META[sceneKey];
    const st = getForecourt();
    Object.keys(meta.choices).forEach((mark) => {
      const btn = $(meta.choices[mark].btn);
      if (btn) btn.setAttribute("aria-pressed", st.lastChoice === mark ? "true" : "false");
    });
  };

  const enterForecourt = (sceneKey) => {
    markForecourtVisited(sceneKey);
    const meta = FORECOURT_META[sceneKey];
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = "";
    paintForecourtChoice(sceneKey);
    /* v34：未满定额回到回返夹道时展示一次性回流反馈 */
    paintValuationUnderReturn(sceneKey, responseEl);
    /* v35：门债遣返落点一次性反馈；恢复登记所入口的 aria-pressed */
    if (sceneKey === "return-passage") consumeFloorOutcome("debt", responseEl);
    paintFloorEntry(sceneKey);
    /* v37：恢复回拨入口的 aria-pressed */
    paintCallbackEntry(sceneKey);
  };

  /* 前段动作：点击/键盘激活 → 点击时持久化 → 短反馈 → 自动转场；没有第二个继续按钮。
     已有未触发转场时忽略重复激活：marks 不重复、transitions 不重复累计、不重复调度。 */
  const chooseForecourt = (sceneKey, mark) => {
    const meta = FORECOURT_META[sceneKey];
    const choice = meta && meta.choices[mark];
    if (!choice) return;
    if (AutoAdvance.has(sceneKey)) return;
    const st = getForecourt();
    if (!st.marks.includes(mark)) st.marks.push(mark);
    st.lastChoice = mark;
    st.transitions = Math.min(FORECOURT_TRANSITIONS_CAP, st.transitions + 1);
    saveForecourt(st);
    paintForecourtChoice(sceneKey);
    /* v40 守卫配套：前段内部动作的落点同为 v31 场景时，到访标记在点击时立即持久化 */
    if (FORECOURT_SCENES.includes(choice.target)) markForecourtVisited(choice.target);

    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = choice.response;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule(sceneKey, choice.target, { delay: branchDelay() });
  };

  FORECOURT_SCENES.forEach((sceneKey) => {
    const meta = FORECOURT_META[sceneKey];
    Object.keys(meta.choices).forEach((mark) => {
      const btn = $(meta.choices[mark].btn);
      if (btn) btn.addEventListener("click", () => chooseForecourt(sceneKey, mark));
    });
  });

  /* 门外三个热点：干净存档立即可发现。点击即持久化 visited 并计一次改道，
     短反馈后自动转场；已有排队转场（含敲门主路径）时忽略，幂等且不抢门。 */
  const FORECOURT_HOTSPOTS = {
    "hotspot-peephole": { target: "peephole-chamber", note: "日蚀后面，有什么在回看你。" },
    "hotspot-glyph": { target: "glyph-niche", note: "符号少了一个。它让你跟过去数。" },
    "hotspot-return": { target: "return-passage", note: "痕迹在门内侧折返。它等你很久了。" },
  };

  Object.keys(FORECOURT_HOTSPOTS).forEach((id) => {
    const btn = $("#" + id);
    const spot = FORECOURT_HOTSPOTS[id];
    if (!btn) return;
    btn.addEventListener("click", () => {
      if (AutoAdvance.has("threshold")) return;
      const st = getForecourt();
      st.visited[FORECOURT_VISIT_KEY[spot.target]] = true;
      st.transitions = Math.min(FORECOURT_TRANSITIONS_CAP, st.transitions + 1);
      saveForecourt(st);
      syncForecourtLinks();
      btn.classList.add("touched");
      setTimeout(() => btn.classList.remove("touched"), 1200);
      AudioEngine.knock();
      statusLine.textContent = spot.note;
      AutoAdvance.schedule("threshold", spot.target, { delay: branchDelay() });
    });
  });

  /* 痕迹页单行：按已访问项显示，保持八张统计卡不变 */
  const paintForecourtMemory = () => {
    const memory = $("#forecourt-memory");
    if (!memory) return;
    const st = getForecourt();
    const names = [];
    if (st.visited.peephole) names.push("窥孔");
    if (st.visited.glyph) names.push("失号龛");
    if (st.visited.returnPassage) names.push("回返夹道");
    if (names.length === 0) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `门前旁路：${names.join(" / ")}；你在门外改道 ${st.transitions} 次。`;
    memory.hidden = false;
  };

  /* ============================================================
     v32 门内副楼：闭目档案室 / 无号前厅 / 逆向阶井
     状态独立存 goddead_v32_inner_annex，容错坏 JSON；
     不读不写 v28/v29/v30/v31 与旧主线状态；三间新房不设解锁门槛，
     直接 hash 进入只记 visited，不自动触发任何动作。
     ============================================================ */
  const ANNEX_KEY = "goddead_v32_inner_annex";
  const ANNEX_SCENES = ["eyelid-archive", "unnumbered-vestibule", "reverse-stairwell"];
  const ANNEX_MARKS = [
    "searchedSealedSight", "heardBoxBlink", "filedOwnShadow",
    "hungBlankOnTenth", "leftPrintInBlankLedger", "choseUnnumberedExit",
    "climbedTowardLowerFloor", "crossedZerothStep", "lookedBackWithoutTurning",
  ];
  const ANNEX_VISIT_KEY = { "eyelid-archive": "eyelidArchive", "unnumbered-vestibule": "unnumberedVestibule", "reverse-stairwell": "reverseStairwell" };
  const ANNEX_TRANSITIONS_CAP = 9999;

  const getAnnex = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(ANNEX_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const visited = {};
    Object.values(ANNEX_VISIT_KEY).forEach((k) => {
      visited[k] = Boolean(raw.visited && raw.visited[k] === true);
    });
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => ANNEX_MARKS.includes(m)))].slice(0, ANNEX_MARKS.length)
      : [];
    const lastChoice = typeof raw.lastChoice === "string" && ANNEX_MARKS.includes(raw.lastChoice)
      ? raw.lastChoice
      : "";
    let transitions = Number(raw.transitions);
    if (!Number.isFinite(transitions) || transitions < 0) transitions = 0;
    transitions = Math.min(ANNEX_TRANSITIONS_CAP, Math.floor(transitions));
    return { visited, marks, lastChoice, transitions };
  };
  const saveAnnex = (st) => store.set(ANNEX_KEY, JSON.stringify(st));

  const ANNEX_META = {
    "eyelid-archive": {
      responseEl: "#eyelid-response",
      choices: {
        searchedSealedSight: { btn: "#eyelid-choice-search", target: "unnumbered-vestibule", response: "抽屉里没有照片，只有一扇尚未编号的门。" },
        heardBoxBlink: { btn: "#eyelid-choice-listen", target: "protocol", response: "盒子每合一次，守则就少承认你一秒。" },
        filedOwnShadow: { btn: "#eyelid-choice-file", target: "threshold", response: "档案柜收下影子，把人退回门外。" },
      },
    },
    "unnumbered-vestibule": {
      responseEl: "#vestibule-response",
      choices: {
        hungBlankOnTenth: { btn: "#vestibule-choice-tenth", target: "reverse-stairwell", response: "前厅只有九扇门。第十扇在你脚下打开。" },
        leftPrintInBlankLedger: { btn: "#vestibule-choice-print", target: "eyelid-archive", response: "台账拒绝姓名，只收录你曾经看过什么。" },
        choseUnnumberedExit: { btn: "#vestibule-choice-exit", target: "corridor", response: "所有门同时退后，只有走廊没有移动。" },
      },
    },
    "reverse-stairwell": {
      responseEl: "#stairwell-response",
      choices: {
        climbedTowardLowerFloor: { btn: "#stairwell-choice-climb", target: "eyelid-archive", response: "你登上七级台阶，抵达一排闭着的眼睑。" },
        crossedZerothStep: { btn: "#stairwell-choice-zeroth", target: "unnumbered-vestibule", response: "第零级没有高度，却把门的编号全部抹掉。" },
        lookedBackWithoutTurning: { btn: "#stairwell-choice-lookback", target: "protocol", response: "守则从背后念出你的正面。" },
      },
    },
  };

  /* 目录入口：首次到访后原子恢复，未访问保持 hidden 不可聚焦 */
  const ANNEX_LINKS = { "eyelid-archive": "#eyelid-link", "unnumbered-vestibule": "#vestibule-link", "reverse-stairwell": "#stairwell-link" };
  const syncAnnexLinks = () => {
    const st = getAnnex();
    ANNEX_SCENES.forEach((s) => {
      const link = $(ANNEX_LINKS[s]);
      if (!link) return;
      if (st.visited[ANNEX_VISIT_KEY[s]]) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  /* 到访标记：首次真正进入（含直接 hash）立即持久化 */
  const markAnnexVisited = (sceneKey) => {
    const st = getAnnex();
    const key = ANNEX_VISIT_KEY[sceneKey];
    if (!key || st.visited[key]) return;
    st.visited[key] = true;
    saveAnnex(st);
    syncAnnexLinks();
  };

  const paintAnnexChoice = (sceneKey) => {
    const meta = ANNEX_META[sceneKey];
    const st = getAnnex();
    Object.keys(meta.choices).forEach((mark) => {
      const btn = $(meta.choices[mark].btn);
      if (btn) btn.setAttribute("aria-pressed", st.lastChoice === mark ? "true" : "false");
    });
  };

  const enterAnnex = (sceneKey) => {
    markAnnexVisited(sceneKey);
    const meta = ANNEX_META[sceneKey];
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = "";
    paintAnnexChoice(sceneKey);
    /* v33：恢复第四入口的 aria-pressed；两分回入口副楼时展示一次「已复核」反馈 */
    paintReviewEntry(sceneKey);
    paintReviewedReturn(sceneKey, responseEl);
    /* v35：恢复前厅第五入口的 aria-pressed */
    paintFloorEntry(sceneKey);
    /* v51：恢复刻痕牌与阈值异常的原子状态（只重绘不播报） */
    syncAnnexDebts(sceneKey);
    /* v52：按实时总容量恢复「合签三债」入口的显隐 */
    syncSettleEntries();
  };

  /* 副楼动作：首选锁定——已有未触发转场时忽略后续鼠标/Enter/Space 与其他动作；
     第一次被接受时立即保存 mark、lastChoice 与 transitions，短反馈后自动转场 */
  const chooseAnnex = (sceneKey, mark) => {
    const meta = ANNEX_META[sceneKey];
    const choice = meta && meta.choices[mark];
    if (!choice) return;
    if (AutoAdvance.has(sceneKey)) return;
    const st = getAnnex();
    if (!st.marks.includes(mark)) st.marks.push(mark);
    st.lastChoice = mark;
    st.transitions = Math.min(ANNEX_TRANSITIONS_CAP, st.transitions + 1);
    saveAnnex(st);
    paintAnnexChoice(sceneKey);
    addAnnexDebt(choice.btn);

    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = choice.response;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule(sceneKey, choice.target, { delay: branchDelay() });
  };

  ANNEX_SCENES.forEach((sceneKey) => {
    const meta = ANNEX_META[sceneKey];
    Object.keys(meta.choices).forEach((mark) => {
      const btn = $(meta.choices[mark].btn);
      if (btn) btn.addEventListener("click", () => chooseAnnex(sceneKey, mark));
    });
  });

  /* ============================================================
     v51 副楼三债：13 个既有动作按 见证5/失号4/逆行4 各 +1（上限 9），
     任一达 3 原子解锁对应房间的一次条件异常（图像切换，异常热点作为
     新增分支出现在内层区域；13 个旧热点全部保留可见/可聚焦/可点击）。
     独立容错状态键，不读写 v32/v33/v35 或主线；既有反馈/mark/首选锁/
     AutoAdvance 全部保留，只附加记账与阈值切换。 */
  const DEBTS_KEY = "goddead_v51_annex_debts";
  const DEBTS_CAP = 9;
  const DEBTS_THRESHOLD = 3;
  const DEBT_KINDS = ["witness", "unnumbered", "reverse"];
  const DEBT_CN = { witness: "见证", unnumbered: "失号", reverse: "逆行" };
  const DEBT_ORDINALS = ["零", "一", "二", "三", "四", "五", "六", "七", "八", "九"];
  /* 13 个既有动作 → 债值映射（见证 5 / 失号 4 / 逆行 4） */
  const DEBT_BY_BTN = {
    "#eyelid-choice-listen": "witness",
    "#eyelid-choice-review": "witness",
    "#vestibule-choice-print": "witness",
    "#stairwell-choice-lookback": "witness",
    "#stairwell-choice-review": "witness",
    "#eyelid-choice-search": "unnumbered",
    "#eyelid-choice-file": "unnumbered",
    "#vestibule-choice-tenth": "unnumbered",
    "#vestibule-choice-exit": "unnumbered",
    "#vestibule-choice-review": "reverse",
    "#vestibule-choice-floor": "reverse",
    "#stairwell-choice-climb": "reverse",
    "#stairwell-choice-zeroth": "reverse",
  };
  /* 三个阈值异常：异变图、异常热点（新增分支，压内层区域）、播报、逐字反馈与目的地 */
  const DEBT_ANOMALY = {
    "eyelid-archive": {
      debt: "witness", img: "assets/annex-eyelid-witness.webp", anomalyBtn: "#eyelid-debt-witness",
      unlockNote: "闭眼的东西睁开了。", response: "三只眼睛没有看你。它们在核对你身后站着几个你。", target: "unnumbered-vestibule",
      figLabel: "黑漆归档柜下半部三只黄铜眼睑抽屉微微开启，露出潮湿苍白、互相不同方向凝视的眼球",
      baseFigLabel: "黑漆归档柜前一只抽屉微开、露出无号黑色视线档片，左桌放着黄铜听音盒与短听筒，右桌放着红蜡封口的黑色证物袋，前景地面的人形影子被狭长归档缝切断",
    },
    "unnumbered-vestibule": {
      debt: "unnumbered", img: "assets/annex-vestibule-tenth.webp", anomalyBtn: "#vestibule-debt-tenth",
      unlockNote: "门的数目对不上了。", response: "你没有推门。门从你的编号里向内打开。", target: "reverse-stairwell",
      figLabel: "环形九门保持不动，中央无把手黑门的阴影里显出一圈更窄更深的第十扇门框，门楣空白",
      baseFigLabel: "环形前厅环绕九扇挂空白骨瓷号牌的封门，最深处的无把手黑门前悬着独立空白号牌，左前景矮台上摊开无号台账与指印泥，右前景墙柱上有黑色复核投递槽与一枚暗红微光的地下层按钮",
    },
    "reverse-stairwell": {
      debt: "reverse", img: "assets/annex-stairwell-double.webp", anomalyBtn: "#stairwell-debt-double",
      unlockNote: "镜子里多了一座阶井。", response: "镜中的脚先落地，你的脚才想起该抬起来。", target: "eyelid-archive",
      figLabel: "左上窄长黑镜里出现一套与现实楼梯方向相反、透视不可能成立的重复阶井，现实构图不变",
      baseFigLabel: "上下折返的黑石楼梯共用中央平台，台阶上的脚印同时朝向两个方向，左上墙面挂着只映出背后的窄长黑镜，平台横贯一道暗红发亮的第零级接缝，右下扶手柱上放着黄铜异常申报盒与复核章",
    },
  };
  const DEBT_BASE_IMG = {
    "eyelid-archive": "assets/annex-eyelid-tactile.webp",
    "unnumbered-vestibule": "assets/annex-vestibule-tactile.webp",
    "reverse-stairwell": "assets/annex-stairwell-tactile.webp",
  };

  const getDebts = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(DEBTS_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const debts = {};
    DEBT_KINDS.forEach((k) => {
      let n = Number(raw.debts && raw.debts[k]);
      if (!Number.isFinite(n) || n < 0) n = 0;
      debts[k] = Math.min(DEBTS_CAP, Math.floor(n));
    });
    const unlocked = {};
    ANNEX_SCENES.forEach((s) => { unlocked[s] = Boolean(raw.unlocked && raw.unlocked[s] === true); });
    return { debts, unlocked };
  };
  const saveDebts = (st) => store.set(DEBTS_KEY, JSON.stringify(st));

  /* 刻痕牌：三行刻痕跨三牌同步；每行 0–9 个独立刻痕元素组成正规进度组件
     （不用文本符号/emoji），首次补齐 9 个 <b>，之后只切 dp-tick-on 与 aria-label */
  const paintDebtPlate = () => {
    const st = getDebts();
    DEBT_KINDS.forEach((k) => {
      document.querySelectorAll(`.dp-ticks[data-debt-ticks="${k}"]`).forEach((el) => {
        if (el.childElementCount !== DEBTS_CAP) {
          el.textContent = "";
          for (let i = 0; i < DEBTS_CAP; i += 1) {
            const tick = document.createElement("b");
            tick.className = "dp-tick";
            tick.setAttribute("aria-hidden", "true");
            el.appendChild(tick);
          }
        }
        const n = st.debts[k];
        Array.from(el.children).forEach((tick, i) => {
          tick.classList.toggle("dp-tick-on", i < n);
        });
        el.setAttribute("aria-label", `${DEBT_CN[k]} ${n} 道刻痕，上限 ${DEBTS_CAP} 道`);
      });
    });
  };

  /* 债值播报：写当前场景牌面的 aria-live（隐藏场景不播报） */
  const announceDebt = (msg) => {
    const live = document.querySelector("section.scene.active .dp-live");
    if (live) live.textContent = msg;
  };

  /* 阈值原子切换：图像、异常热点、figure 描述同一拍完成；
     13 个旧热点始终保留，不再隐藏任何 base 热点；刷新恢复只重绘不播报 */
  const syncAnnexDebts = (sceneKey) => {
    const meta = DEBT_ANOMALY[sceneKey];
    if (!meta) return;
    const st = getDebts();
    const on = st.unlocked[sceneKey] === true && st.debts[meta.debt] >= DEBTS_THRESHOLD;
    const section = $(`#scene-${sceneKey}`);
    if (!section) return;
    const figure = section.querySelector("figure.branch-figure");
    const img = figure && figure.querySelector(".branch-img");
    const wantSrc = on ? meta.img : DEBT_BASE_IMG[sceneKey];
    setSceneImageSrc(img, wantSrc);
    if (figure) figure.setAttribute("aria-label", on ? meta.figLabel : meta.baseFigLabel);
    const anomaly = $(meta.anomalyBtn);
    if (anomaly) {
      if (on) anomaly.removeAttribute("hidden");
      else { anomaly.setAttribute("hidden", ""); anomaly.setAttribute("aria-pressed", "false"); }
    }
  };

  /* 记账：只在既有动作被首选锁接受后调用，一次动作 +1，上限 9；
     达阈值原子解锁一次并播报，刻痕音很轻 */
  const addAnnexDebt = (btnSel) => {
    const kind = DEBT_BY_BTN[btnSel];
    if (!kind) return;
    const st = getDebts();
    if (st.debts[kind] >= DEBTS_CAP) return;
    st.debts[kind] = Math.min(DEBTS_CAP, st.debts[kind] + 1);
    saveDebts(st);
    paintDebtPlate();
    /* v52：债值跨过 3/6/9 时总容量可能变化，同步「合签三债」入口显隐 */
    syncSettleEntries();
    AudioEngine.knock(0.08);
    const plate = document.querySelector("section.scene.active .debt-plate");
    if (plate) { plate.classList.remove("dp-stir"); void plate.offsetWidth; plate.classList.add("dp-stir"); }
    let msg = `${DEBT_CN[kind]}留下第${DEBT_ORDINALS[st.debts[kind]]}道刻痕`;
    const room = ANNEX_SCENES.find((s) => DEBT_ANOMALY[s].debt === kind);
    if (room && st.debts[kind] >= DEBTS_THRESHOLD && !st.unlocked[room]) {
      st.unlocked[room] = true;
      saveDebts(st);
      msg += `。${DEBT_ANOMALY[room].unlockNote}`;
      syncAnnexDebts(room);
    }
    announceDebt(msg);
  };

  /* 阈值异常触发：直接 hash / 合成点击越权保护——未解锁一律无效；
     与所在房间共用同一把首选锁，逐字反馈后自动转场到既有相邻场景 */
  const chooseDebtAnomaly = (sceneKey) => {
    const meta = DEBT_ANOMALY[sceneKey];
    if (!meta) return;
    const st = getDebts();
    if (!(st.unlocked[sceneKey] === true && st.debts[meta.debt] >= DEBTS_THRESHOLD)) return;
    if (AutoAdvance.has(sceneKey)) return;
    const btn = $(meta.anomalyBtn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const annexMeta = ANNEX_META[sceneKey];
    const responseEl = annexMeta && $(annexMeta.responseEl);
    if (responseEl) responseEl.textContent = meta.response;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule(sceneKey, meta.target, { delay: branchDelay() });
  };

  ANNEX_SCENES.forEach((sceneKey) => {
    const btn = $(DEBT_ANOMALY[sceneKey].anomalyBtn);
    if (btn) btn.addEventListener("click", () => chooseDebtAnomaly(sceneKey));
    /* 变体图随场景预载，阈值切换无闪烁 */
    prefetchWithScene(sceneKey, DEBT_ANOMALY[sceneKey].img);
  });
  paintDebtPlate();
  ANNEX_SCENES.forEach(syncAnnexDebts);

  /* 痕迹页单行：按已访问项显示，保持八张统计卡不变 */
  const paintAnnexMemory = () => {
    const memory = $("#annex-memory");
    if (!memory) return;
    const st = getAnnex();
    const names = [];
    if (st.visited.eyelidArchive) names.push("闭目档案");
    if (st.visited.unnumberedVestibule) names.push("无号前厅");
    if (st.visited.reverseStairwell) names.push("逆向阶井");
    if (names.length === 0) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `门内副楼：${names.join(" / ")}；你在没有楼层的地方改道 ${st.transitions} 次。`;
    memory.hidden = false;
  };

  /* ============================================================
     v52 副楼三债结算：v51 三种债值成为可重复使用的结算容量。
     每类本轮可投入容量 = floor(v51 对应 debt / 3)（0..3，只读 v51，绝不减少
     或改写 v51 state）；总容量 >= 3 时三副楼刻痕牌各出现原生按钮「合签三债」，
     与场景首选锁共用，逐字反馈后自动进入结算所。
     结算所每轮正好投入 3 枚债印（图内三机关 = 原生 hotspot），第三枚后保留
     反馈一拍自动结算：严格多数 → 对应结果房，1/1/1 → 稀有 balanced 落
     #protocol-drift（v42 直 hash 本就始终允许，v52 不读写 v42 状态）。
     独立容错状态键 SETTLE_KEY（v52 唯一存储键），不读写 v28–v51 或主线状态；
     无确认/继续按钮。 */
  const SETTLE_KEY = "goddead_v52_annex_settlement";
  const SETTLE_SCENES = ["house", "gallery", "registry", "appeals"];
  const SETTLE_RESULT_SCENES = ["gallery", "registry", "appeals"];
  const SETTLE_SCENE_NAME = {
    house: "annex-clearinghouse",
    gallery: "unreturned-witness-gallery",
    registry: "registry-before-zero",
    appeals: "descending-appeals-stair",
  };
  const SETTLE_NAME_SCENE = {
    "annex-clearinghouse": "house",
    "unreturned-witness-gallery": "gallery",
    "registry-before-zero": "registry",
    "descending-appeals-stair": "appeals",
  };
  const SETTLE_KINDS = ["witness", "unnumbered", "reverse"];
  const SETTLE_KIND_CN = { witness: "见证", unnumbered: "失号", reverse: "逆行" };
  const SETTLE_OUTCOMES = ["", "witness", "unnumbered", "reverse", "balanced"];
  /* 结算落点：严格多数 → 对应结果房；1/1/1 → 稀有 balanced 落 v42 巡查台 */
  const SETTLE_OUTCOME_TARGET = {
    witness: "unreturned-witness-gallery",
    unnumbered: "registry-before-zero",
    reverse: "descending-appeals-stair",
    balanced: "protocol-drift",
  };
  /* 结果房 ← 对应 outcome（直 hash 守卫用） */
  const SETTLE_RESULT_OUTCOME = { gallery: "witness", registry: "unnumbered", appeals: "reverse" };
  const SETTLE_NUM_CAP = 9999;
  const SETTLE_ENTRY_FEEDBACK = "三债同签。结算所开门，点清你带来的刻痕。";
  const SETTLE_ORDINALS = ["零", "一", "二", "三"];
  /* 每次投入的短反馈：按类与该类本轮第几枚逐字 */
  const SETTLE_DEPOSIT_LEAD = {
    witness: "眼形印眨了一下。",
    unnumbered: "空白瓷盘没有接住影子。",
    reverse: "逆阶模型退后了一级。",
  };
  const settleDepositFeedback = (kind, count) =>
    `${SETTLE_DEPOSIT_LEAD[kind]}${SETTLE_KIND_CN[kind]}债印落下第${SETTLE_ORDINALS[count]}枚。`;
  /* 第三枚后的结算句（追加在第三枚投入反馈之后，逐字） */
  const SETTLE_FINAL = {
    witness: "三印归位。眼形印不肯再闭上——结算所把你判给无归见证席。",
    unnumbered: "三印归位。瓷盘仍然空白——结算所把你判给零前登记库。",
    reverse: "三印归位。逆阶模型倒着走完一级——结算所把你判给倒诉阶。",
    balanced: "三印各一，谁也不肯多数。结算所第一次无法判决，把你退给一块正在漂移的守则板。",
  };
  /* 三间结果房的九个画面动作：真实图中物件上的原生 button，逐字反馈与精确目标 */
  const SETTLE_ACTIONS = {
    gallery: {
      horn: { btn: "#settle-gallery-action-horn", target: "unseated-listening-booth", feedback: "蜡筒没有录下声音，只把你听见它的那一刻倒放了一遍。" },
      seal: { btn: "#settle-gallery-action-seal", target: "witness-carbon-archive", feedback: "印章闭着眼落下，复写纸却多出一位未曾到场的见证人。" },
      chair: { btn: "#settle-gallery-action-chair", target: "eyelid-archive", feedback: "椅背没有映出脸。档案柜却为你的后脑开了三只眼。" },
    },
    registry: {
      plate: { btn: "#settle-registry-action-plate", target: "glyph-niche", feedback: "牌面比零更早，所以所有数字都从它身后绕行。" },
      press: { btn: "#settle-registry-action-press", target: "blank-receipt-press", feedback: "压印机落下时没有留下字，只把空白压得更深了一层。" },
      door: { btn: "#settle-registry-action-door", target: "unnumbered-floor", feedback: "门没有编号。你跨过去以后，身后的楼层先被注销。" },
    },
    appeals: {
      mirror: { btn: "#settle-appeals-action-mirror", target: "reverse-stairwell", feedback: "镜里的你先走完了楼梯，才回头等你的第一步。" },
      gavel: { btn: "#settle-appeals-action-gavel", target: "return-audit", feedback: "法槌从桌底向上落下，把你的归路判成了一次上诉。" },
      bell: { btn: "#settle-appeals-action-bell", target: "bellless-ward", feedback: "钟体摇了三次。病房里每张床却同时回答了第四声。" },
    },
  };
  const SETTLE_RESPONSE_EL = { house: "#settle-response", gallery: "#settle-gallery-response", registry: "#settle-registry-response", appeals: "#settle-appeals-response" };
  const SETTLE_LINKS = { house: "#settle-house-link", gallery: "#settle-gallery-link", registry: "#settle-registry-link", appeals: "#settle-appeals-link" };
  const SETTLE_ENTRY_BTNS = { "eyelid-archive": "#eyelid-settle-entry", "unnumbered-vestibule": "#vestibule-settle-entry", "reverse-stairwell": "#stairwell-settle-entry" };
  const SETTLE_DEPOSIT_BTNS = { witness: "#settle-deposit-witness", unnumbered: "#settle-deposit-unnumbered", reverse: "#settle-deposit-reverse" };

  /* 本轮可投入容量：只读 v51 债值，floor(debt / 3)，每类 0..3；绝不写 v51 */
  const settleCapacity = () => {
    const debts = getDebts().debts;
    const cap = {};
    SETTLE_KINDS.forEach((k) => { cap[k] = Math.floor(debts[k] / 3); });
    return cap;
  };
  const settleUnlocked = () => {
    const cap = settleCapacity();
    return SETTLE_KINDS.reduce((sum, k) => sum + cap[k], 0) >= 3;
  };
  /* 三枚 allocations 的结算结果：严格多数 → 该类；1/1/1 → balanced */
  const settleOutcomeOf = (allocations) => {
    const counts = { witness: 0, unnumbered: 0, reverse: 0 };
    allocations.forEach((a) => { counts[a] += 1; });
    const majority = SETTLE_KINDS.find((k) => counts[k] >= 2);
    return majority || "balanced";
  };

  const getSettlement = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(SETTLE_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(SETTLE_NUM_CAP, Math.floor(n));
    };
    const visited = {};
    SETTLE_SCENES.forEach((s) => { visited[s] = Boolean(raw.visited && raw.visited[s] === true); });
    const cycle = num(raw.cycle);
    const history = {};
    SETTLE_OUTCOMES.slice(1).forEach((o) => { history[o] = num(raw.history && raw.history[o]); });
    const actions = {};
    SETTLE_RESULT_SCENES.forEach((s) => {
      Object.keys(SETTLE_ACTIONS[s]).forEach((a) => { actions[`${s}-${a}`] = num(raw.actions && raw.actions[`${s}-${a}`]); });
    });
    /* allocations 归一：长度 <= 3、白名单、每类不超实时容量、合法连续前缀；
       首个非法项起全部截断，伪造序列不可能拼出非法投入 */
    const cap = settleCapacity();
    let allocations = [];
    if (Array.isArray(raw.allocations)) {
      for (const a of raw.allocations) {
        if (allocations.length >= 3) break;
        if (!SETTLE_KINDS.includes(a)) break;
        if (allocations.filter((x) => x === a).length >= cap[a]) break;
        allocations.push(a);
      }
    }
    /* settled 派生重算：必须长度恰 3 且 outcome 与实时多数推导一致 */
    let outcome = SETTLE_OUTCOMES.includes(raw.outcome) ? raw.outcome : "";
    let settled = raw.settled === true && allocations.length === 3 && outcome !== "" && settleOutcomeOf(allocations) === outcome;
    if (!settled) {
      outcome = "";
      if (allocations.length >= 3) allocations = allocations.slice(0, 2);
    }
    /* pending 两种严格形态，逐字段校验：
       settle：第三枚已接受、结算转场未完成（type/outcome/target/feedback 与固定表一致）；
       action：结果房动作已接受、转场未完成（scene/action/target/feedback 与动作表一致）；
       任一字段错配即归 null。pending 只恢复反馈与转场，不得重复累计 */
    let pending = null;
    if (raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const p = raw.pending;
      if (p.type === "settle" && settled && p.outcome === outcome && p.target === SETTLE_OUTCOME_TARGET[outcome]) {
        const third = allocations[2];
        const expected = settleDepositFeedback(third, allocations.filter((x) => x === third).length) + SETTLE_FINAL[outcome];
        if (p.feedback === expected) pending = { type: "settle", outcome, target: p.target, feedback: expected };
      } else if (p.type === "action") {
        const acts = SETTLE_ACTIONS[p.scene];
        const act = acts && acts[p.action];
        if (act && p.target === act.target && p.feedback === act.feedback) {
          pending = { type: "action", scene: p.scene, action: p.action, target: act.target, feedback: act.feedback };
        }
      }
    }
    /* lastScene / lastAction 只接受白名单且必须互相匹配（v31 glyph-niche 窄例外用） */
    const lastScene = SETTLE_RESULT_SCENES.includes(raw.lastScene) ? raw.lastScene : "";
    const lastAction = lastScene && SETTLE_ACTIONS[lastScene][raw.lastAction] ? raw.lastAction : "";
    return { visited, cycle, history, actions, allocations, settled, outcome, pending, lastScene, lastAction };
  };
  const saveSettlement = (st) => store.set(SETTLE_KEY, JSON.stringify(st));

  const syncSettleLinks = () => {
    const st = getSettlement();
    SETTLE_SCENES.forEach((s) => {
      const link = $(SETTLE_LINKS[s]);
      if (!link) return;
      if (st.visited[s]) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  /* 到访标记：首次真正进入（含合法直达）立即持久化，目录入口原子恢复 */
  const markSettlementVisited = (sceneKey) => {
    const st = getSettlement();
    if (!SETTLE_SCENES.includes(sceneKey) || st.visited[sceneKey]) return;
    st.visited[sceneKey] = true;
    saveSettlement(st);
    syncSettleLinks();
  };

  const settleDelay = () => reduced ? 300 : 900 + Math.floor(Math.random() * 300);

  /* 「合签三债」入口：总容量 >= 3 才出现；hidden 时不可聚焦、合成点击无效 */
  const syncSettleEntries = () => {
    const on = settleUnlocked();
    Object.values(SETTLE_ENTRY_BTNS).forEach((sel) => {
      const btn = $(sel);
      if (!btn) return;
      if (on) btn.removeAttribute("hidden");
      else { btn.setAttribute("hidden", ""); btn.setAttribute("aria-pressed", "false"); }
    });
  };

  /* 结算所重绘：三行实体凹槽（每行 3 孔，点亮已投数）+ 三机关按钮状态。
     凹槽是图内物件，容器 pointer-events:none，只读可访问文本 */
  const paintClearinghouse = () => {
    const st = getSettlement();
    const cap = settleCapacity();
    const locked = AutoAdvance.has("annex-clearinghouse") || st.settled;
    SETTLE_KINDS.forEach((k) => {
      const used = st.allocations.filter((a) => a === k).length;
      const slotsEl = document.querySelector(`[data-settle-slots="${k}"]`);
      if (slotsEl) {
        Array.from(slotsEl.children).forEach((slot, i) => {
          slot.classList.toggle("st-slot-on", i < used);
        });
        slotsEl.setAttribute("aria-label", `${SETTLE_KIND_CN[k]}凹槽 已投 ${used} 枚，本轮容量 ${cap[k]} 枚`);
      }
      const btn = $(SETTLE_DEPOSIT_BTNS[k]);
      if (btn) {
        btn.disabled = locked || used >= cap[k];
        btn.setAttribute("aria-pressed", used > 0 ? "true" : "false");
      }
    });
  };

  /* 进入结算所：到访标记；合法 settle pending（第三枚反馈拍刷新/离场后重返）
     重播逐字反馈并只重建一次目标转场，timer 触发前才清 pending */
  const enterClearinghouse = () => {
    markSettlementVisited("house");
    const st = getSettlement();
    const responseEl = $(SETTLE_RESPONSE_EL.house);
    if (responseEl) responseEl.textContent = "";
    if (st.pending && st.pending.type === "settle") {
      const p = st.pending;
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule("annex-clearinghouse", p.target, {
        delay: settleDelay(),
        before: () => {
          const s = getSettlement();
          if (s.pending && s.pending.type === "settle") {
            s.pending = null;
            saveSettlement(s);
          }
        },
      });
    }
    paintClearinghouse();
  };

  /* 投入债印：在任何状态读写、反馈、音效、timer 前校验 live scene；
     同拍首选锁 + 实时容量校验，快速 click/Enter/Space 同拍不得重复计数；
     第三枚立即派生 outcome、累计历史、持久化 settle pending，保留反馈一拍后自动结算 */
  const depositSettlement = (kind) => {
    if (!SETTLE_KINDS.includes(kind)) return;
    if (currentScene !== "annex-clearinghouse") return;
    if (AutoAdvance.has("annex-clearinghouse")) return;
    const st = getSettlement();
    if (st.settled) return;
    if (st.allocations.length >= 3) return;
    const cap = settleCapacity();
    const used = st.allocations.filter((a) => a === kind).length;
    if (used >= cap[kind]) return;
    st.allocations.push(kind);
    const count = used + 1;
    const responseEl = $(SETTLE_RESPONSE_EL.house);
    if (st.allocations.length === 3) {
      const outcome = settleOutcomeOf(st.allocations);
      const target = SETTLE_OUTCOME_TARGET[outcome];
      const feedback = settleDepositFeedback(kind, count) + SETTLE_FINAL[outcome];
      st.settled = true;
      st.outcome = outcome;
      st.history[outcome] = Math.min(SETTLE_NUM_CAP, st.history[outcome] + 1);
      st.pending = { type: "settle", outcome, target, feedback };
      saveSettlement(st);
      if (responseEl) responseEl.textContent = feedback;
      AudioEngine.knock(0.16);
      AutoAdvance.schedule("annex-clearinghouse", target, {
        delay: settleDelay(),
        before: () => {
          const s = getSettlement();
          if (s.pending && s.pending.type === "settle") {
            s.pending = null;
            saveSettlement(s);
          }
        },
      });
      paintClearinghouse();
      return;
    }
    saveSettlement(st);
    if (responseEl) responseEl.textContent = settleDepositFeedback(kind, count);
    AudioEngine.knock(0.08);
    paintClearinghouse();
  };

  SETTLE_KINDS.forEach((kind) => {
    const btn = $(SETTLE_DEPOSIT_BTNS[kind]);
    if (btn) btn.addEventListener("click", () => depositSettlement(kind));
  });

  /* 三副楼「合签三债」入口：live scene + 实时总容量 + 场景首选锁三重校验，
     未达门槛一律零副作用；已结算（且 settle pending 已消费）再点开启新 cycle，
     未结算的进行中 cycle 原样续投，历史统计跨 cycle 保留 */
  const chooseSettleEntry = (sceneKey) => {
    if (currentScene !== sceneKey) return;
    if (!settleUnlocked()) return;
    if (AutoAdvance.has(sceneKey)) return;
    const st = getSettlement();
    if (st.settled && !st.pending) {
      st.cycle = Math.min(SETTLE_NUM_CAP, st.cycle + 1);
      st.allocations = [];
      st.settled = false;
      st.outcome = "";
    }
    saveSettlement(st);
    const btn = $(SETTLE_ENTRY_BTNS[sceneKey]);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const annexMeta = ANNEX_META[sceneKey];
    const responseEl = annexMeta && $(annexMeta.responseEl);
    if (responseEl) responseEl.textContent = SETTLE_ENTRY_FEEDBACK;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule(sceneKey, "annex-clearinghouse", { delay: branchDelay() });
  };

  ANNEX_SCENES.forEach((sceneKey) => {
    const btn = $(SETTLE_ENTRY_BTNS[sceneKey]);
    if (btn) btn.addEventListener("click", () => chooseSettleEntry(sceneKey));
  });

  /* 结果房重绘：锁定拍内三个热点 disabled；动作计数 > 0 保持 pressed */
  const paintSettleResult = (sceneKey) => {
    const st = getSettlement();
    const locked = AutoAdvance.has("settle-" + sceneKey);
    Object.keys(SETTLE_ACTIONS[sceneKey]).forEach((actionId) => {
      const btn = $(SETTLE_ACTIONS[sceneKey][actionId].btn);
      if (!btn) return;
      btn.disabled = locked;
      btn.setAttribute("aria-pressed", st.actions[`${sceneKey}-${actionId}`] > 0 ? "true" : "false");
    });
  };

  /* 进入结果房：到访标记；合法 action pending 属于本场景时重播逐字反馈并
     只重建一次目标转场 */
  const enterSettleResult = (sceneKey) => {
    markSettlementVisited(sceneKey);
    const st = getSettlement();
    const responseEl = $(SETTLE_RESPONSE_EL[sceneKey]);
    if (responseEl) responseEl.textContent = "";
    if (st.pending && st.pending.type === "action" && st.pending.scene === sceneKey) {
      const p = st.pending;
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule("settle-" + sceneKey, p.target, {
        delay: settleDelay(),
        before: () => {
          const s = getSettlement();
          if (s.pending && s.pending.type === "action" && s.pending.scene === sceneKey && s.pending.action === p.action) {
            s.pending = null;
            saveSettlement(s);
          }
        },
      });
    }
    paintSettleResult(sceneKey);
  };

  /* 九个结果动作：在任何状态读写、反馈、音效、timer 前校验 live scene；
     第一项被接受后同场景三个热点立即 disabled（同拍竞争只记一次），
     逐字反馈 + 动作计数 + lastScene/lastAction 持久化后自动转场，无确认/继续按钮 */
  const runSettleAction = (sceneKey, actionId) => {
    const act = SETTLE_ACTIONS[sceneKey] && SETTLE_ACTIONS[sceneKey][actionId];
    if (!act) return;
    if (currentScene !== SETTLE_SCENE_NAME[sceneKey]) return;
    if (AutoAdvance.has("settle-" + sceneKey)) return;
    const st = getSettlement();
    st.lastScene = sceneKey;
    st.lastAction = actionId;
    st.actions[`${sceneKey}-${actionId}`] = Math.min(SETTLE_NUM_CAP, st.actions[`${sceneKey}-${actionId}`] + 1);
    st.pending = { type: "action", scene: sceneKey, action: actionId, target: act.target, feedback: act.feedback };
    saveSettlement(st);
    const responseEl = $(SETTLE_RESPONSE_EL[sceneKey]);
    if (responseEl) responseEl.textContent = act.feedback;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule("settle-" + sceneKey, act.target, {
      delay: settleDelay(),
      before: () => {
        const s = getSettlement();
        if (s.pending && s.pending.type === "action" && s.pending.scene === sceneKey && s.pending.action === actionId) {
          s.pending = null;
          saveSettlement(s);
        }
      },
    });
    paintSettleResult(sceneKey);
  };

  SETTLE_RESULT_SCENES.forEach((sceneKey) => {
    Object.keys(SETTLE_ACTIONS[sceneKey]).forEach((actionId) => {
      const btn = $(SETTLE_ACTIONS[sceneKey][actionId].btn);
      if (btn) btn.addEventListener("click", () => runSettleAction(sceneKey, actionId));
    });
  });

  syncSettleEntries();
  syncSettleLinks();

  /* 痕迹页单行：合签轮数、四路结算统计与九动作合计，保持八张统计卡不变 */
  const paintSettlementMemory = () => {
    const memory = $("#settlement-memory");
    if (!memory) return;
    const st = getSettlement();
    const rounds = st.history.witness + st.history.unnumbered + st.history.reverse + st.history.balanced;
    const actionTotal = Object.values(st.actions).reduce((sum, n) => sum + n, 0);
    if (rounds === 0 && !st.visited.house) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `三债结算：合签 ${rounds} 轮；见证 ${st.history.witness} / 失号 ${st.history.unnumbered} / 逆行 ${st.history.reverse} / 均衡 ${st.history.balanced}；九个结算动作共 ${actionTotal} 次。`;
    memory.hidden = false;
  };

  /* ============================================================
     v33 异常复核科：可重复复核支线 + 异常保全库 / 误报回收井
     状态独立存 goddead_v33_anomaly_review，容错坏 JSON；
     不读不写 v28–v32 与主线状态；档案顺序由「入口 + cycle」从白名单矩阵
     确定性轮换，禁止裸随机；直接 hash 进入复核科采用 neutral 顺序，
     只展示第一份档案，不自动判断。
     ============================================================ */
  const REVIEW_KEY = "goddead_v33_anomaly_review";
  const REVIEW_SCENES = ["anomaly-review", "evidence-vault", "false-positive-shaft"];
  const REVIEW_RESULT_SCENES = ["evidence-vault", "false-positive-shaft"];
  const REVIEW_ENTRIES = ["neutral", "eyelid", "vestibule", "stairwell"];
  const REVIEW_CASES = ["baseline", "aperture", "rail", "shadow"];
  const REVIEW_MARKS = [
    "sentEyeForReview", "submittedUnnumberedDoor", "reportedUpwardDescent",
    "sealedClearestAnomaly", "returnedBaselineToVestibule", "leftThroughBrokenSeal",
    "retrievedRejectedCase", "appendedFalseReport", "admittedExtraItem",
  ];
  const REVIEW_VISIT_KEY = { "anomaly-review": "review", "evidence-vault": "evidenceVault", "false-positive-shaft": "falsePositiveShaft" };
  const REVIEW_OUTCOMES = ["", "vault", "returned", "shaft"];
  const REVIEW_NUM_CAP = 9999;

  /* 确定性轮换矩阵：行 = 各入口 cycle 0 的顺序，每行恰含一份 baseline 与两份不同异常；
     后续 cycle 按（入口行 + cycle）对矩阵循环移位——同入口连续两轮顺序不同，
     四种档案在多次复核中都会出现 */
  const REVIEW_ORDER_MATRIX = [
    ["baseline", "aperture", "rail"],
    ["shadow", "baseline", "aperture"],
    ["rail", "shadow", "baseline"],
    ["aperture", "baseline", "shadow"],
  ];
  const REVIEW_ENTRY_ROW = { eyelid: 0, vestibule: 1, stairwell: 2, neutral: 3 };
  const reviewOrderFor = (entry, cycle) => REVIEW_ORDER_MATRIX[(REVIEW_ENTRY_ROW[entry] + cycle) % REVIEW_ORDER_MATRIX.length].slice();
  const isValidReviewOrder = (order) => Array.isArray(order) && order.length === 3
    && order.every((c) => REVIEW_CASES.includes(c))
    && new Set(order).size === 3
    && order.filter((c) => c === "baseline").length === 1;

  const getReview = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(REVIEW_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const visited = {};
    Object.values(REVIEW_VISIT_KEY).forEach((k) => {
      visited[k] = Boolean(raw.visited && raw.visited[k] === true);
    });
    const entry = REVIEW_ENTRIES.includes(raw.entry) ? raw.entry : "neutral";
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(REVIEW_NUM_CAP, Math.floor(n));
    };
    const cycle = num(raw.cycle);
    const order = isValidReviewOrder(raw.order) ? raw.order.slice() : reviewOrderFor(entry, cycle);
    let round = num(raw.round);
    if (round > 3) round = 3;
    const decisions = Array.isArray(raw.decisions)
      ? raw.decisions
          .filter((d) => d && typeof d === "object" && REVIEW_CASES.includes(d.caseId)
            && (d.choice === "anomaly" || d.choice === "baseline") && typeof d.correct === "boolean")
          .filter((d, i, arr) => arr.findIndex((x) => x.caseId === d.caseId) === i)
          .slice(0, round)
      : [];
    const outcome = REVIEW_OUTCOMES.includes(raw.outcome) ? raw.outcome : "";
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => REVIEW_MARKS.includes(m)))].slice(0, REVIEW_MARKS.length)
      : [];
    return {
      visited, entry, cycle, order, round,
      correct: num(raw.correct),
      streak: num(raw.streak),
      bestStreak: num(raw.bestStreak),
      mistakes: num(raw.mistakes),
      completedRuns: num(raw.completedRuns),
      vaultEntries: num(raw.vaultEntries),
      shaftEntries: num(raw.shaftEntries),
      decisions, outcome, marks,
    };
  };
  const saveReview = (st) => store.set(REVIEW_KEY, JSON.stringify(st));

  /* 新一轮：由副楼入口、误报井工单或目录重进触发。order 按当前 cycle 生成后再递增，
     使设计矩阵的 cycle 0 行即首轮顺序，且同入口连续两轮顺序不同；
     本轮 round/分数/decisions/outcome 全部清零，bestStreak 与计数跨轮保留 */
  const startReview = (entry) => {
    const st = getReview();
    st.entry = REVIEW_ENTRIES.includes(entry) ? entry : "neutral";
    st.order = reviewOrderFor(st.entry, st.cycle);
    st.cycle = Math.min(REVIEW_NUM_CAP, st.cycle + 1);
    st.round = 0;
    st.correct = 0;
    st.streak = 0;
    st.mistakes = 0;
    st.decisions = [];
    st.outcome = "";
    saveReview(st);
  };

  const REVIEW_CASE_ASSETS = {
    baseline: "assets/anomaly-review-baseline.webp",
    aperture: "assets/anomaly-review-aperture.webp",
    rail: "assets/anomaly-review-rail.webp",
    shadow: "assets/anomaly-review-shadow.webp",
  };
  const REVIEW_CASE_LABELS = ["第一份档案", "第二份档案", "第三份档案"];

  /* 目录入口：首次到访后原子恢复，未访问保持 hidden 不可聚焦 */
  const REVIEW_LINKS = { "anomaly-review": "#review-link", "evidence-vault": "#vault-link", "false-positive-shaft": "#shaft-link" };
  const syncReviewLinks = () => {
    const st = getReview();
    REVIEW_SCENES.forEach((s) => {
      const link = $(REVIEW_LINKS[s]);
      if (!link) return;
      if (st.visited[REVIEW_VISIT_KEY[s]]) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  /* 到访标记：首次真正进入（含直接 hash）立即持久化 */
  const markReviewVisited = (sceneKey) => {
    const st = getReview();
    const key = REVIEW_VISIT_KEY[sceneKey];
    if (!key || st.visited[key]) return;
    st.visited[key] = true;
    saveReview(st);
    syncReviewLinks();
  };

  /* 档案图交叉淡化：双层 img 只切 opacity，不位移不放大，避免动画被误判为异常。
     每层 img 携带自己的 data-case 标记：shadow 案的逆向灯影在源图顶部，
     桌面槽位按该标记单独上移构图（移动端维持原裁切）；逐层标记保证
     换档淡化期间离场层仍按自己的构图淡出，不会被新案的裁切拽动 */
  let reviewCaseFront = true;
  const showReviewCase = (caseId, idx) => {
    const front = $(reviewCaseFront ? "#review-case-img-a" : "#review-case-img-b");
    const back = $(reviewCaseFront ? "#review-case-img-b" : "#review-case-img-a");
    const src = REVIEW_CASE_ASSETS[caseId];
    if (front && back && src && front.getAttribute("src") !== src) {
      back.setAttribute("src", src);
      back.setAttribute("data-case", caseId);
      back.classList.add("is-front");
      front.classList.remove("is-front");
      reviewCaseFront = !reviewCaseFront;
    }
    const label = $("#review-case-label");
    if (label) label.textContent = `${REVIEW_CASE_LABELS[Math.min(idx, 2)]} · 共三份`;
  };

  const paintReviewSlip = (st) => {
    const correctEl = $("#review-stat-correct");
    const streakEl = $("#review-stat-streak");
    const mistakesEl = $("#review-stat-mistakes");
    const bestEl = $("#review-stat-best");
    if (correctEl) correctEl.textContent = st.correct;
    if (streakEl) streakEl.textContent = st.streak;
    if (mistakesEl) mistakesEl.textContent = st.mistakes;
    if (bestEl) bestEl.textContent = st.bestStreak;
  };

  const paintReviewDecisions = (pressedChoice) => {
    const anomalyBtn = $("#review-choice-anomaly");
    const baselineBtn = $("#review-choice-baseline");
    if (anomalyBtn) anomalyBtn.setAttribute("aria-pressed", pressedChoice === "anomaly" ? "true" : "false");
    if (baselineBtn) baselineBtn.setAttribute("aria-pressed", pressedChoice === "baseline" ? "true" : "false");
  };

  /* 整室重绘：复核签 + 当前 round 的档案 + 判断按钮复位。
     恢复只展示当前轮次，不续跑任何已丢失的 timer */
  const paintReview = () => {
    const st = getReview();
    paintReviewSlip(st);
    const idx = Math.min(st.round, 2);
    showReviewCase(st.order[idx], idx);
    paintReviewDecisions("");
  };

  /* 进入复核科：已完成的轮次（含结果已分流）以 neutral 开一轮新档案；
     正在进行的轮次原位恢复；从未开轮的直达（cycle 0）以 neutral 开首轮，
     只展示第一份档案，绝不自动判断 */
  const enterReview = () => {
    markReviewVisited("anomaly-review");
    /* v35 缺层电梯中间档落点：强制 neutral 新轮并展示一次性落点反馈 */
    const v35Arrival = getFloor().outcome === "review";
    if (v35Arrival) startReview("neutral");
    const st = getReview();
    if (st.outcome !== "" || st.round >= 3) startReview("neutral");
    else if (st.cycle === 0 && st.round === 0) startReview("neutral");
    const responseEl = $("#review-response");
    if (responseEl) responseEl.textContent = "";
    if (v35Arrival && responseEl) consumeFloorOutcome("review", responseEl);
    paintReview();
  };

  /* 两分回入口副楼：outcome 记 returned，按本轮入口返回；neutral 回闭目档案室 */
  const REVIEW_ENTRY_TARGET = { eyelid: "eyelid-archive", vestibule: "unnumbered-vestibule", stairwell: "reverse-stairwell", neutral: "eyelid-archive" };

  /* 每轮判断：第一项被接受后，另一个按钮、连点与 Enter/Space 重复事件全部忽略；
     立即反馈并更新账面，短反馈后自动换档，第三轮自动分流，无第二个继续按钮 */
  const decideReview = (choice) => {
    if (AutoAdvance.has("anomaly-review") || AutoAdvance.has("anomaly-review-round")) return;
    const st = getReview();
    if (st.outcome !== "" || st.round >= 3) return;
    const caseId = st.order[st.round];
    if (!REVIEW_CASES.includes(caseId)) return;
    const choseAnomaly = choice === "anomaly";
    const correct = choseAnomaly === (caseId !== "baseline");
    st.decisions.push({ caseId, choice: choseAnomaly ? "anomaly" : "baseline", correct });
    st.round = Math.min(3, st.round + 1);
    let feedback;
    if (correct) {
      st.correct += 1;
      st.streak += 1;
      if (st.streak > st.bestStreak) st.bestStreak = st.streak;
      feedback = choseAnomaly ? "档案边缘渗出一条新编号。复核值 +1。" : "房间保持原样。你第一次因为没看见而被记录。";
    } else {
      st.mistakes += 1;
      st.streak = 0;
      feedback = choseAnomaly ? "复核科收走你的确信。误报 +1。" : "变化没有消失，只是被登记成了你。";
    }
    const responseEl = $("#review-response");
    if (responseEl) responseEl.textContent = feedback;
    AudioEngine.knock(0.16);
    paintReviewSlip(st);
    paintReviewDecisions(choseAnomaly ? "anomaly" : "baseline");

    if (st.round >= 3) {
      /* 第三轮只允许结算一次：completedRuns 精确加一，vault/shaft 计数至多各加一 */
      st.completedRuns = Math.min(REVIEW_NUM_CAP, st.completedRuns + 1);
      let target;
      if (st.correct >= 3) {
        st.outcome = "vault";
        st.vaultEntries = Math.min(REVIEW_NUM_CAP, st.vaultEntries + 1);
        target = "evidence-vault";
      } else if (st.correct === 2) {
        st.outcome = "returned";
        target = REVIEW_ENTRY_TARGET[st.entry];
      } else {
        st.outcome = "shaft";
        st.shaftEntries = Math.min(REVIEW_NUM_CAP, st.shaftEntries + 1);
        target = "false-positive-shaft";
      }
      saveReview(st);
      AutoAdvance.schedule("anomaly-review", target, { delay: branchDelay() });
    } else {
      saveReview(st);
      /* 轮内换档与跨场景转场使用不同 scope，离场时由 clearAll 一并清除 */
      AutoAdvance.schedule("anomaly-review-round", "anomaly-review", {
        delay: branchDelay(),
        before: () => {
          const cur = getReview();
          showReviewCase(cur.order[Math.min(cur.round, 2)], cur.round);
          paintReviewDecisions("");
        },
      });
    }
  };

  const reviewAnomalyBtn = $("#review-choice-anomaly");
  const reviewBaselineBtn = $("#review-choice-baseline");
  if (reviewAnomalyBtn) reviewAnomalyBtn.addEventListener("click", () => decideReview("anomaly"));
  if (reviewBaselineBtn) reviewBaselineBtn.addEventListener("click", () => decideReview("baseline"));

  /* 三间 v32 副楼的第四入口动作：只附加入口，原九动作逐字、mark、反馈与目的地不变 */
  const REVIEW_ENTRY_META = {
    "eyelid-archive": { btn: "#eyelid-choice-review", entry: "eyelid", mark: "sentEyeForReview", response: "没有睁开的眼被装进黑色证物袋，送去复核。" },
    "unnumbered-vestibule": { btn: "#vestibule-choice-review", entry: "vestibule", mark: "submittedUnnumberedDoor", response: "没有编号的门被登记为待复核案。" },
    "reverse-stairwell": { btn: "#stairwell-choice-review", entry: "stairwell", mark: "reportedUpwardDescent", response: "同时向上的下行梯被盖上待复核章。" },
  };

  const paintReviewEntry = (sceneKey) => {
    const meta = REVIEW_ENTRY_META[sceneKey];
    if (!meta) return;
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", getReview().marks.includes(meta.mark) ? "true" : "false");
  };

  /* 第四入口与副楼原九动作共用同一把首选锁（同一 AutoAdvance scope） */
  const chooseReviewEntry = (sceneKey) => {
    const meta = REVIEW_ENTRY_META[sceneKey];
    if (!meta) return;
    if (AutoAdvance.has(sceneKey)) return;
    startReview(meta.entry);
    const st = getReview();
    if (!st.marks.includes(meta.mark)) st.marks.push(meta.mark);
    saveReview(st);
    paintReviewEntry(sceneKey);
    addAnnexDebt(meta.btn);
    const annexMeta = ANNEX_META[sceneKey];
    const responseEl = annexMeta && $(annexMeta.responseEl);
    if (responseEl) responseEl.textContent = meta.response;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule(sceneKey, "anomaly-review", { delay: branchDelay() });
  };

  Object.keys(REVIEW_ENTRY_META).forEach((sceneKey) => {
    const btn = $(REVIEW_ENTRY_META[sceneKey].btn);
    if (btn) btn.addEventListener("click", () => chooseReviewEntry(sceneKey));
  });

  /* 两分回入口副楼时的「已复核」反馈：仅本轮 outcome 为 returned 且入口匹配时
     展示一次，随即消耗，不重复出现 */
  const paintReviewedReturn = (sceneKey, responseEl) => {
    const meta = REVIEW_ENTRY_META[sceneKey];
    if (!meta) return;
    const st = getReview();
    if (st.outcome !== "returned" || st.entry !== meta.entry) return;
    if (responseEl) responseEl.textContent = "复核科已登记这一处异常。房间维持原判。";
    st.outcome = "";
    saveReview(st);
  };

  /* 结果房动作：首选锁定 + 立即反馈 + 自动转场，无第二个继续按钮 */
  const REVIEW_RESULT_META = {
    "evidence-vault": {
      responseEl: "#vault-response",
      choices: {
        sealedClearestAnomaly: { btn: "#vault-choice-seal", target: "eyelid-archive", response: "证物匣闭合时，闭目档案室少了一只眼。" },
        returnedBaselineToVestibule: { btn: "#vault-choice-return", target: "unnumbered-vestibule", response: "没有编号的门拒绝签收，于是把自己打开。" },
        leftThroughBrokenSeal: { btn: "#vault-choice-leave", target: "corridor", response: "编号在中途断裂，断口后面是经文走廊。" },
      },
    },
    "false-positive-shaft": {
      responseEl: "#shaft-response",
      choices: {
        retrievedRejectedCase: { btn: "#shaft-choice-retrieve", target: "anomaly-review", response: "工单背面已经换了一套异常。复核重新开始。", restart: true },
        appendedFalseReport: { btn: "#shaft-choice-append", target: "protocol", response: "守则新增一条：凡看错者，视为看见。" },
        admittedExtraItem: { btn: "#shaft-choice-admit", target: "threshold", response: "回收井退回你的名字，把人送到门外。" },
      },
    },
  };

  const paintReviewResult = (sceneKey) => {
    const meta = REVIEW_RESULT_META[sceneKey];
    const st = getReview();
    Object.keys(meta.choices).forEach((mark) => {
      const btn = $(meta.choices[mark].btn);
      if (btn) btn.setAttribute("aria-pressed", st.marks.includes(mark) ? "true" : "false");
    });
  };

  const enterReviewResult = (sceneKey) => {
    markReviewVisited(sceneKey);
    custodyUnlockButtons(sceneKey);
    const meta = REVIEW_RESULT_META[sceneKey];
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = "";
    paintReviewResult(sceneKey);
    /* v34：破封坠回误报井时展示一次性回流反馈；恢复第四入口的 aria-pressed */
    paintValuationBreachReturn(sceneKey, responseEl);
    paintValuationEntry(sceneKey);
  };

  const chooseReviewResult = (sceneKey, mark) => {
    const meta = REVIEW_RESULT_META[sceneKey];
    const choice = meta && meta.choices[mark];
    if (!choice) return;
    if (currentScene !== sceneKey) return;
    if (AutoAdvance.has(sceneKey)) return;
    const st = getReview();
    if (!st.marks.includes(mark)) st.marks.push(mark);
    saveReview(st);
    /* 工单：开启新 cycle 并自动回复核科（沿用本轮入口，轮换继续移位） */
    if (choice.restart) startReview(st.entry);
    paintReviewResult(sceneKey);
    custodyLockButtons(sceneKey);
    /* v60 截留判定：旧副作用与旧反馈逐字保留，只可能改最终 target */
    const custody = custodySourceBeat(sceneKey, mark, choice.target);
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = choice.response + custody.suffix;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule(sceneKey, custody.target, custody.intercepted
      ? { delay: branchDelay(), before: () => custodySourceArrive() }
      : { delay: branchDelay() });
  };

  REVIEW_RESULT_SCENES.forEach((sceneKey) => {
    const meta = REVIEW_RESULT_META[sceneKey];
    Object.keys(meta.choices).forEach((mark) => {
      const btn = $(meta.choices[mark].btn);
      if (btn) btn.addEventListener("click", () => chooseReviewResult(sceneKey, mark));
    });
  });

  /* 痕迹页单行：完成轮数 / 最佳连续 / 保全与误报回收次数，保持八张统计卡不变 */
  const paintAnomalyMemory = () => {
    const memory = $("#anomaly-memory");
    if (!memory) return;
    const st = getReview();
    if (!st.visited.review && !st.visited.evidenceVault && !st.visited.falsePositiveShaft) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `异常复核：完成 ${st.completedRuns} 轮，最佳连续 ${st.bestStreak}，保全 ${st.vaultEntries} 次，误报回收 ${st.shaftEntries} 次。`;
    memory.hidden = false;
  };

  /* ============================================================
     v34 无主估值室：可重复估值支线 + 定额电梯
     状态独立存 goddead_v34_unclaimed_valuation，容错坏 JSON；
     不读不写 v28–v33 与主线状态；批次由「入口 + cycle」从白名单矩阵
     确定性轮换，禁止裸随机；点击即执行，无确认页、无第二个继续按钮。
     ============================================================ */
  const VAL_KEY = "goddead_v34_unclaimed_valuation";
  const VAL_SCENES = ["unclaimed-valuation", "quota-elevator"];
  const VAL_ENTRIES = ["neutral", "vault", "shaft"];
  const VAL_RELICS = ["thirteenthClock", "toothKey", "hollowIdol", "blackWaxLung", "unopenedEye", "receiptBone"];
  const VAL_MARKS = [
    "sentEvidenceToValuation", "declaredRejectAsAsset",
    "sentQuotaToVestibule", "crossedBrokenFloorScale", "droppedQuotaIntoCorridor",
    ...VAL_RELICS,
  ];
  const VAL_VISIT_KEY = { "unclaimed-valuation": "valuation", "quota-elevator": "quotaElevator" };
  const VAL_OUTCOMES = ["", "quota", "under", "breach"];
  const VAL_NUM_CAP = 9999;

  /* 确定性批次矩阵：行 = 各入口 cycle 0 的批次，每行三件不同证物；
     后续 cycle 按（入口行 + cycle）循环移位——同入口连续两批不同，六件都会出现 */
  const VAL_BATCH_MATRIX = [
    ["thirteenthClock", "toothKey", "hollowIdol"],
    ["blackWaxLung", "unopenedEye", "receiptBone"],
    ["thirteenthClock", "blackWaxLung", "hollowIdol"],
    ["toothKey", "unopenedEye", "receiptBone"],
  ];
  const VAL_ENTRY_ROW = { vault: 0, shaft: 1, neutral: 2 };
  const valBatchFor = (entry, cycle) => VAL_BATCH_MATRIX[(VAL_ENTRY_ROW[entry] + cycle) % VAL_BATCH_MATRIX.length].slice();
  const isValidValBatch = (batch) => Array.isArray(batch) && batch.length === 3
    && batch.every((r) => VAL_RELICS.includes(r))
    && new Set(batch).size === 3;

  /* 两种入口条件：误报井退件自带 1 点溢价但封印更脆；直达与 vault 相同 */
  const VAL_ENTRY_INIT = {
    vault: { value: 0, integrity: 5, quota: 6 },
    shaft: { value: 1, integrity: 4, quota: 7 },
    neutral: { value: 0, integrity: 5, quota: 6 },
  };

  const getValuation = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(VAL_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const visited = {};
    Object.values(VAL_VISIT_KEY).forEach((k) => {
      visited[k] = Boolean(raw.visited && raw.visited[k] === true);
    });
    const entry = VAL_ENTRIES.includes(raw.entry) ? raw.entry : "neutral";
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(VAL_NUM_CAP, Math.floor(n));
    };
    const cycle = num(raw.cycle);
    const batch = isValidValBatch(raw.batch) ? raw.batch.slice() : valBatchFor(entry, cycle);
    const opened = Array.isArray(raw.opened)
      ? [...new Set(raw.opened.filter((r) => batch.includes(r)))].slice(0, 3)
      : [];
    /* ledger 只接受与 opened 顺序一一对应的已计算记录，重载不重算效果 */
    const ledger = Array.isArray(raw.ledger)
      ? raw.ledger
          .filter((l) => l && typeof l === "object" && VAL_RELICS.includes(l.relic)
            && Number.isFinite(Number(l.valueGain)) && Number(l.valueGain) >= 0
            && Number.isFinite(Number(l.damageTaken)) && Number(l.damageTaken) >= 0
            && typeof l.effect === "string")
          .filter((l, i) => l.relic === opened[i])
          .slice(0, opened.length)
          .map((l) => ({ relic: l.relic, valueGain: num(l.valueGain), damageTaken: num(l.damageTaken), effect: l.effect }))
      : [];
    const outcome = VAL_OUTCOMES.includes(raw.outcome) ? raw.outcome : "";
    /* 过期/畸形组合归一：有结果的批次不再活动；活动批次不可能已满三件 */
    let active = raw.active === true && outcome === "";
    if (active && opened.length >= 3) active = false;
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => VAL_MARKS.includes(m)))].slice(0, VAL_MARKS.length)
      : [];
    return {
      visited, entry, cycle, batch, opened, ledger,
      value: num(raw.value),
      integrity: num(raw.integrity),
      quota: Math.max(1, num(raw.quota) || VAL_ENTRY_INIT[entry].quota),
      nextDamageShield: num(raw.nextDamageShield),
      remainingValueBonus: num(raw.remainingValueBonus),
      revealExact: raw.revealExact === true,
      active, outcome,
      bestSettlement: num(raw.bestSettlement),
      completedRuns: num(raw.completedRuns),
      quotaMetRuns: num(raw.quotaMetRuns),
      underRuns: num(raw.underRuns),
      breachRuns: num(raw.breachRuns),
      marks,
    };
  };
  const saveValuation = (st) => store.set(VAL_KEY, JSON.stringify(st));

  /* 新批次：由结果房入口或已完成批次的重进触发。batch 按当前 cycle 生成后再递增，
     使设计矩阵的 cycle 0 行即首批；入口初值写入，本批 ledger/outcome 清空 */
  const startValuation = (entry) => {
    const st = getValuation();
    st.entry = VAL_ENTRIES.includes(entry) ? entry : "neutral";
    st.batch = valBatchFor(st.entry, st.cycle);
    st.cycle = Math.min(VAL_NUM_CAP, st.cycle + 1);
    const init = VAL_ENTRY_INIT[st.entry];
    st.value = init.value;
    st.integrity = init.integrity;
    st.quota = init.quota;
    st.opened = [];
    st.ledger = [];
    st.nextDamageShield = 0;
    st.remainingValueBonus = 0;
    st.revealExact = false;
    st.active = true;
    st.outcome = "";
    saveValuation(st);
  };

  const VAL_RELIC_META = {
    thirteenthClock: { name: "十三时钟", asset: "assets/valuation-thirteenth-clock.webp", base: 2, damage: 1, omen: "钟面多出一格，秒针少走一次。", feedback: "钟替下一件证物少活了一秒。" },
    toothKey: { name: "齿门钥", asset: "assets/valuation-tooth-key.webp", base: 3, damage: 2, omen: "钥匙的齿形与这里每个人的牙都相同。", feedback: "钥匙记住了前面已经打开过几只匣子。" },
    hollowIdol: { name: "空神像", asset: "assets/valuation-hollow-idol.webp", base: 4, damage: 3, omen: "像内没有神，只有一个比外壳更大的空腔。", feedback: "最后一只匣子打开后，空腔把前两件也算进了自己。" },
    blackWaxLung: { name: "黑蜡肺", asset: "assets/valuation-black-wax-lung.webp", base: 2, damage: 2, omen: "它只在别人停止呼吸时起伏。", feedback: "肺替还没打开的匣子各吸进一点价值。" },
    unopenedEye: { name: "未睁之眼", asset: "assets/valuation-unopened-eye.webp", base: 1, damage: 1, omen: "眼皮内侧写着柜台正在隐瞒的数字。", feedback: "闭着的眼把剩余数字看得一清二楚。" },
    receiptBone: { name: "无主回执骨", asset: "assets/valuation-receipt-bone.webp", base: 2, damage: 0, omen: "骨头两端都盖着退件章，中间没有身体。", feedback: "没有收件人的骨头，被按普通附件计价。", feedbackShaft: "退件章被估值室当成了两次所有权转移。" },
  };

  /* 目录入口：首次到访后原子恢复，未访问保持 hidden 不可聚焦 */
  const VAL_LINKS = { "unclaimed-valuation": "#valuation-link", "quota-elevator": "#elevator-link" };
  const syncValuationLinks = () => {
    const st = getValuation();
    VAL_SCENES.forEach((s) => {
      const link = $(VAL_LINKS[s]);
      if (!link) return;
      if (st.visited[VAL_VISIT_KEY[s]]) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  const markValuationVisited = (sceneKey) => {
    const st = getValuation();
    const key = VAL_VISIT_KEY[sceneKey];
    if (!key || st.visited[key]) return;
    st.visited[key] = true;
    saveValuation(st);
    syncValuationLinks();
  };

  const paintValuationSlip = (st) => {
    const valueEl = $("#val-stat-value");
    const integrityEl = $("#val-stat-integrity");
    const quotaEl = $("#val-stat-quota");
    const bestEl = $("#val-stat-best");
    const breachEl = $("#val-stat-breach");
    if (valueEl) valueEl.textContent = st.value;
    if (integrityEl) integrityEl.textContent = st.integrity;
    if (quotaEl) quotaEl.textContent = st.quota;
    if (bestEl) bestEl.textContent = st.bestSettlement;
    if (breachEl) breachEl.textContent = st.breachRuns;
  };

  /* 未估值只显示名称与征兆；未睁之眼揭示剩余准确数字；已估值锁定并显示实收 */
  const paintValuationRelics = (st) => {
    st.batch.forEach((relic, i) => {
      const meta = VAL_RELIC_META[relic];
      const btn = $("#val-relic-" + i);
      const img = $("#val-relic-img-" + i);
      const nameEl = $("#val-relic-name-" + i);
      const omenEl = $("#val-relic-omen-" + i);
      const resultEl = $("#val-relic-result-" + i);
      if (!btn || !meta) return;
      /* 当前批次卡图必须可靠加载解码：eager 加载 + 换批时先隐去旧图，
         新图解码完成再现身——不留白、不闪旧图、不错位 */
      if (img) {
        const showImg = () => img.classList.remove("is-loading");
        if (img.getAttribute("src") !== meta.asset) {
          img.classList.add("is-loading");
          img.addEventListener("load", showImg, { once: true });
          img.setAttribute("src", meta.asset);
          if (img.complete && img.naturalWidth > 0) showImg();
        } else {
          showImg();
        }
      }
      if (nameEl) nameEl.textContent = meta.name;
      const ledgerEntry = st.ledger.find((l) => l.relic === relic);
      const isOpen = st.opened.includes(relic);
      if (isOpen && ledgerEntry) {
        if (omenEl) omenEl.textContent = meta.omen;
        if (resultEl) resultEl.textContent = `+${ledgerEntry.valueGain} · 封印 -${ledgerEntry.damageTaken}`;
        btn.disabled = true;
        btn.setAttribute("aria-label", `${meta.name}，已估值：+${ledgerEntry.valueGain}，封印 -${ledgerEntry.damageTaken}`);
      } else {
        if (st.revealExact) {
          const gain = meta.base + st.remainingValueBonus
            + (relic === "toothKey" ? st.opened.length : 0)
            + (relic === "hollowIdol" && st.opened.length === 2 ? 2 : 0)
            + (relic === "receiptBone" && st.entry === "shaft" ? 2 : 0);
          const damage = Math.max(0, meta.damage - st.nextDamageShield);
          if (omenEl) omenEl.textContent = meta.omen;
          if (resultEl) resultEl.textContent = `预计 +${gain} · 封印 -${damage}`;
        } else {
          if (omenEl) omenEl.textContent = meta.omen;
          if (resultEl) resultEl.textContent = "";
        }
        btn.disabled = !st.active || st.outcome !== "";
        btn.setAttribute("aria-label", `${meta.name}，${meta.omen}`);
      }
    });
  };

  const paintValuationSettle = (st) => {
    const btn = $("#val-settle");
    if (!btn) return;
    btn.disabled = !(st.active && st.outcome === "" && st.opened.length >= 1);
  };

  const paintValuation = () => {
    const st = getValuation();
    paintValuationSlip(st);
    paintValuationRelics(st);
    paintValuationSettle(st);
  };

  /* 进入估值室：已完成（含已分流）的批次以 neutral 开新批次；
     正在进行的批次原位恢复；直达开 neutral 首批，不自动估值、不自动结算 */
  const enterValuation = () => {
    markValuationVisited("unclaimed-valuation");
    const st = getValuation();
    if (!st.active || st.outcome !== "") startValuation("neutral");
    const responseEl = $("#valuation-response");
    if (responseEl) responseEl.textContent = "";
    paintValuation();
  };

  /* 结算：每批只允许完成一次，由 active/outcome 守卫保证；
     满额进定额电梯、未满回回返夹道、破封坠回误报井 */
  const settleValuation = (st, kind) => {
    st.completedRuns = Math.min(VAL_NUM_CAP, st.completedRuns + 1);
    st.active = false;
    st.outcome = kind;
    const responseEl = $("#valuation-response");
    let target;
    if (kind === "quota") {
      st.quotaMetRuns = Math.min(VAL_NUM_CAP, st.quotaMetRuns + 1);
      st.bestSettlement = Math.max(st.bestSettlement, st.value);
      target = "quota-elevator";
      if (responseEl) responseEl.textContent = "定额计合上了盖子。电梯为这批东西下来。";
    } else if (kind === "under") {
      st.underRuns = Math.min(VAL_NUM_CAP, st.underRuns + 1);
      st.bestSettlement = Math.max(st.bestSettlement, st.value);
      target = "return-passage";
      if (responseEl) responseEl.textContent = "定额未满。估值室开始退货。";
    } else {
      st.breachRuns = Math.min(VAL_NUM_CAP, st.breachRuns + 1);
      target = "false-positive-shaft";
      if (responseEl) responseEl.textContent = "封印破了。估值室不再听你说话。";
    }
    saveValuation(st);
    paintValuation();
    AutoAdvance.schedule("unclaimed-valuation", target, { delay: branchDelay() });
  };

  /* 估值一件：最先被接受的点击立即锁定该证物，连点/竞争动作忽略；
     先结算当前加成，再扣除经十三时钟修正后的封印损耗 */
  const valuateRelic = (idx) => {
    if (AutoAdvance.has("unclaimed-valuation") || AutoAdvance.has("valuation-batch")) return;
    const st = getValuation();
    if (!st.active || st.outcome !== "" || st.integrity <= 0) return;
    const relic = st.batch[idx];
    const meta = relic && VAL_RELIC_META[relic];
    if (!meta || st.opened.includes(relic)) return;
    let gain = meta.base + st.remainingValueBonus;
    let effect = "";
    if (relic === "toothKey" && st.opened.length > 0) { gain += st.opened.length; effect = "orderBonus"; }
    if (relic === "hollowIdol" && st.opened.length === 2) { gain += 2; effect = "thirdBonus"; }
    if (relic === "receiptBone" && st.entry === "shaft") { gain += 2; effect = "shaftBonus"; }
    const damage = Math.max(0, meta.damage - st.nextDamageShield);
    st.nextDamageShield = 0;
    if (relic === "thirteenthClock") { st.nextDamageShield = 1; effect = "shieldNext"; }
    if (relic === "blackWaxLung") { st.remainingValueBonus += 1; effect = "boostRemaining"; }
    if (relic === "unopenedEye") { st.revealExact = true; effect = "reveal"; }
    st.value += gain;
    st.integrity = Math.max(0, st.integrity - damage);
    st.opened.push(relic);
    st.ledger.push({ relic, valueGain: gain, damageTaken: damage, effect });
    if (!st.marks.includes(relic)) st.marks.push(relic);
    const responseEl = $("#valuation-response");
    if (responseEl) responseEl.textContent = relic === "receiptBone" && st.entry === "shaft" ? meta.feedbackShaft : meta.feedback;
    AudioEngine.knock(0.16);

    if (st.integrity <= 0) {
      settleValuation(st, "breach");
      return;
    }
    if (st.opened.length >= 3) {
      settleValuation(st, st.value >= st.quota ? "quota" : "under");
      return;
    }
    saveValuation(st);
    paintValuation();
    /* 批次锁：0.7–1.0s（reduced 0.3s）后解除，不切换页面；
       与盖章锁、跨场景转场分 scope，离场由 clearAll 一并清除 */
    AutoAdvance.schedule("valuation-batch", "unclaimed-valuation", { delay: branchDelay(), before: () => {} });
  };

  VAL_RELICS.forEach((_, i) => {
    const btn = $("#val-relic-" + i);
    if (btn) btn.addEventListener("click", () => valuateRelic(i));
  });

  /* 盖章结算：主动止损，不是继续按钮；至少估值一件后随时可用。
     批次锁只约束剩余证物，不阻止盖章——已接受的估值均已持久化 */
  const settleBtn = $("#val-settle");
  if (settleBtn) settleBtn.addEventListener("click", () => {
    if (AutoAdvance.has("unclaimed-valuation")) return;
    const st = getValuation();
    if (!st.active || st.outcome !== "" || st.opened.length === 0) return;
    settleValuation(st, st.value >= st.quota ? "quota" : "under");
  });

  /* v33 两个结果房的第四入口：只附加入口，与原动作共用各自场景首选锁 */
  const VAL_ENTRY_META = {
    "evidence-vault": { btn: "#vault-choice-valuation", entry: "vault", mark: "sentEvidenceToValuation", responseEl: "#vault-response", response: "未封存的证物被搬上估值柜台。" },
    "false-positive-shaft": { btn: "#shaft-choice-valuation", entry: "shaft", mark: "declaredRejectAsAsset", responseEl: "#shaft-response", response: "退件被钉上资产标签，送去估值。" },
  };

  const paintValuationEntry = (sceneKey) => {
    const meta = VAL_ENTRY_META[sceneKey];
    if (!meta) return;
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", getValuation().marks.includes(meta.mark) ? "true" : "false");
  };

  const chooseValuationEntry = (sceneKey) => {
    const meta = VAL_ENTRY_META[sceneKey];
    if (!meta) return;
    if (currentScene !== sceneKey) return;
    if (AutoAdvance.has(sceneKey)) return;
    startValuation(meta.entry);
    const st = getValuation();
    if (!st.marks.includes(meta.mark)) st.marks.push(meta.mark);
    saveValuation(st);
    paintValuationEntry(sceneKey);
    custodyLockButtons(sceneKey);
    /* v60 截留判定：旧副作用与旧反馈逐字保留，只可能改最终 target */
    const custody = custodySourceBeat(sceneKey, meta.mark, "unclaimed-valuation");
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = meta.response + custody.suffix;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule(sceneKey, custody.target, custody.intercepted
      ? { delay: branchDelay(), before: () => custodySourceArrive() }
      : { delay: branchDelay() });
  };

  Object.keys(VAL_ENTRY_META).forEach((sceneKey) => {
    const btn = $(VAL_ENTRY_META[sceneKey].btn);
    if (btn) btn.addEventListener("click", () => chooseValuationEntry(sceneKey));
  });

  /* 一次性回流反馈：未满定额回到回返夹道时展示一次，随即消费 outcome */
  const paintValuationUnderReturn = (sceneKey, responseEl) => {
    if (sceneKey !== "return-passage") return;
    const st = getValuation();
    if (st.outcome !== "under") return;
    if (responseEl) responseEl.textContent = "估值室退回了这批东西。欠额被写在夹道背面。";
    st.outcome = "";
    saveValuation(st);
  };

  /* 一次性回流反馈：破封坠回误报井时展示一次，随即消费 outcome */
  const paintValuationBreachReturn = (sceneKey, responseEl) => {
    if (sceneKey !== "false-positive-shaft") return;
    const st = getValuation();
    if (st.outcome !== "breach") return;
    if (responseEl) responseEl.textContent = "破损证物比工单先落到底部。回收井把裂口登记在你名下。";
    st.outcome = "";
    saveValuation(st);
  };

  /* 定额电梯：点击即反馈并自动转场，无第二个继续按钮 */
  const ELEVATOR_META = {
    sentQuotaToVestibule: { btn: "#elevator-choice-vestibule", target: "unnumbered-vestibule", response: "货梯停在没有编号的一层，门比轿厢先打开。" },
    crossedBrokenFloorScale: { btn: "#elevator-choice-scale", target: "return-passage", response: "红针指向墙内，回返夹道从刻度后面经过。" },
    droppedQuotaIntoCorridor: { btn: "#elevator-choice-corridor", target: "corridor", response: "证物箱先落进经文，轿厢随后才找到楼层。" },
  };

  const paintElevator = () => {
    const st = getValuation();
    Object.keys(ELEVATOR_META).forEach((mark) => {
      const btn = $(ELEVATOR_META[mark].btn);
      if (btn) btn.setAttribute("aria-pressed", st.marks.includes(mark) ? "true" : "false");
    });
  };

  const enterElevator = () => {
    markValuationVisited("quota-elevator");
    const responseEl = $("#elevator-response");
    if (responseEl) responseEl.textContent = "";
    paintElevator();
    /* v35：高信号落点一次性反馈；恢复第四入口的 aria-pressed */
    consumeFloorOutcome("high", responseEl);
    paintFloorEntry("quota-elevator");
  };

  const chooseElevator = (mark) => {
    const meta = ELEVATOR_META[mark];
    if (!meta) return;
    if (AutoAdvance.has("quota-elevator")) return;
    const st = getValuation();
    if (!st.marks.includes(mark)) st.marks.push(mark);
    saveValuation(st);
    paintElevator();
    const responseEl = $("#elevator-response");
    if (responseEl) responseEl.textContent = meta.response;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule("quota-elevator", meta.target, { delay: branchDelay() });
  };

  Object.keys(ELEVATOR_META).forEach((mark) => {
    const btn = $(ELEVATOR_META[mark].btn);
    if (btn) btn.addEventListener("click", () => chooseElevator(mark));
  });

  /* 痕迹页单行：完成批数 / 满额 / 破损 / 最佳结算，保持八张统计卡不变 */
  const paintValuationMemory = () => {
    const memory = $("#valuation-memory");
    if (!memory) return;
    const st = getValuation();
    if (!st.visited.valuation && !st.visited.quotaElevator) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `无主估值：完成 ${st.completedRuns} 批，满额 ${st.quotaMetRuns} 批，破损 ${st.breachRuns} 批，最佳结算 ${st.bestSettlement}。`;
    memory.hidden = false;
  };

  /* ============================================================
     v35 无号层：横向枢纽 + 三间值班房 + 缺层电梯
     状态独立存 goddead_v35_unnumbered_floor，容错坏 JSON；
     不读不写 v28–v34 与主线状态；同轮同房只结算一次；
     点击即执行，无确认页、无继续按钮、无新结局。
     ============================================================ */
  const FLOOR_KEY = "goddead_v35_unnumbered_floor";
  const FLOOR_SCENES = ["unnumbered-floor", "bellless-ward", "seeping-records", "reverse-laundry", "night-shift-registry"];
  const FLOOR_DUTY_SCENES = ["bellless-ward", "seeping-records", "reverse-laundry"];
  const FLOOR_ENTRIES = ["neutral", "vestibule", "quota", "passage", "floor"];
  const FLOOR_ROOMS = ["ward", "records", "laundry"];
  const FLOOR_MARKS = [
    "pressedMissingBasementFloor", "stoppedNeedleAtUnmarkedFloor",
    "heardMuteNightstand", "changedBreathingBedding", "crawledIVTubeIntoWall",
    "driedNamelessPage", "drankSeepedInk", "letRecordsSinkFurther",
    "cutLeadingDrum", "woreReflectionlessUniform", "brushedMirrorCabinWithOldPlate",
    "caughtTomorrowPermit", "openedNightShiftRegistry",
    "borrowedMuteBellPermit", "claimedBlankNamePermit", "signedReverseBadge",
  ];
  const FLOOR_VISIT_KEY = { "unnumbered-floor": "floor", "bellless-ward": "ward", "seeping-records": "records", "reverse-laundry": "laundry", "night-shift-registry": "nightShiftRegistry" };
  const FLOOR_OUTCOMES = ["", "high", "review", "debt"];
  const FLOOR_NUM_CAP = 9999;
  const FLOOR_SIGNAL_CAP = 15; /* 3+4+3 + 无铃证 +2 + v55 巡检核验最多 +3：本轮理论上限 */
  const FLOOR_DEBT_CAP = 14;   /* 1+2+1 + 反面工牌 +4 + v55 误报/漏报最多 +6 */
  /* v36 值班证：permit 与修正值必须互相一致，permitCycle 必须与当前 cycle 一致 */
  const FLOOR_PERMITS = ["none", "muteBell", "blankName", "reverseBadge"];
  const FLOOR_PERMIT_VALUES = { none: [0, 0], muteBell: [2, 0], blankName: [0, 2], reverseBadge: [0, 4] };

  const getFloor = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(FLOOR_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const visited = {};
    Object.values(FLOOR_VISIT_KEY).forEach((k) => {
      visited[k] = Boolean(raw.visited && raw.visited[k] === true);
    });
    const entry = FLOOR_ENTRIES.includes(raw.entry) ? raw.entry : "neutral";
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(FLOOR_NUM_CAP, Math.floor(n));
    };
    let cycle = num(raw.cycle);
    if (cycle < 1) cycle = 1;
    const completed = Array.isArray(raw.completed)
      ? [...new Set(raw.completed.filter((r) => FLOOR_ROOMS.includes(r)))].slice(0, 3)
      : [];
    let settled = raw.settled === true;
    let outcome = FLOOR_OUTCOMES.includes(raw.outcome) ? raw.outcome : "";
    /* 过期组合归一：无结算标记不保留 outcome；不足两房的结算视为过期 */
    if (!settled) outcome = "";
    if (settled && completed.length < 2) { settled = false; outcome = ""; }
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => FLOOR_MARKS.includes(m)))].slice(0, FLOOR_MARKS.length)
      : [];
    /* v36 值班证字段：旧 v35 存档安全默认 none/0/0；
       非法组合或过期证件（permitCycle 与当前 cycle 不一致）归一为 none */
    let permit = FLOOR_PERMITS.includes(raw.permit) ? raw.permit : "none";
    let permitSignal = num(raw.permitSignal);
    let permitDebt = num(raw.permitDebt);
    const permitCycle = num(raw.permitCycle);
    const permitValues = FLOOR_PERMIT_VALUES[permit];
    if (permitSignal !== permitValues[0] || permitDebt !== permitValues[1] || permitCycle !== cycle) {
      permit = "none";
      permitSignal = 0;
      permitDebt = 0;
    }
    return {
      visited, entry, cycle, completed, settled, outcome,
      signal: Math.min(FLOOR_SIGNAL_CAP, num(raw.signal)),
      debt: Math.min(FLOOR_DEBT_CAP, num(raw.debt)),
      completedRuns: num(raw.completedRuns),
      highRuns: num(raw.highRuns),
      reviewRuns: num(raw.reviewRuns),
      debtRuns: num(raw.debtRuns),
      bestRoute: num(raw.bestRoute),
      permit, permitSignal, permitDebt, permitCycle: permit === "none" ? cycle : permitCycle,
      permitRuns: num(raw.permitRuns),
      muteBellRuns: num(raw.muteBellRuns),
      blankNameRuns: num(raw.blankNameRuns),
      reverseBadgeRuns: num(raw.reverseBadgeRuns),
      marks,
    };
  };
  const saveFloor = (st) => store.set(FLOOR_KEY, JSON.stringify(st));

  /* 目录入口：首次到访后原子恢复，未访问保持 hidden 不可聚焦 */
  const FLOOR_LINKS = { "unnumbered-floor": "#floor-link", "bellless-ward": "#ward-link", "seeping-records": "#records-link", "reverse-laundry": "#laundry-link", "night-shift-registry": "#registry-link" };
  const syncFloorLinks = () => {
    const st = getFloor();
    FLOOR_SCENES.forEach((s) => {
      const link = $(FLOOR_LINKS[s]);
      if (!link) return;
      if (st.visited[FLOOR_VISIT_KEY[s]]) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  const markFloorVisited = (sceneKey) => {
    const st = getFloor();
    const key = FLOOR_VISIT_KEY[sceneKey];
    if (!key || st.visited[key]) return;
    st.visited[key] = true;
    saveFloor(st);
    syncFloorLinks();
  };

  const FLOOR_SLIP_IDS = {
    "unnumbered-floor": "floor",
    "bellless-ward": "ward",
    "seeping-records": "records",
    "reverse-laundry": "laundry",
  };
  const paintFloorSlip = (sceneKey, st) => {
    const p = FLOOR_SLIP_IDS[sceneKey];
    if (!p) return;
    const completedEl = $(`#${p}-stat-completed`);
    const signalEl = $(`#${p}-stat-signal`);
    const debtEl = $(`#${p}-stat-debt`);
    if (completedEl) completedEl.textContent = `${st.completed.length}/3`;
    if (signalEl) signalEl.textContent = st.signal;
    if (debtEl) debtEl.textContent = st.debt;
    const bestEl = $("#floor-stat-best");
    if (sceneKey === "unnumbered-floor" && bestEl) bestEl.textContent = st.bestRoute;
  };

  /* 值班房动作：前两条为本房值班（同轮只接受第一次并记入 completed），
     第三条为无收益穿行/离开；全部首选锁 + 短反馈 + 自动转场 */
  const FLOOR_ROOM_META = {
    "bellless-ward": {
      responseEl: "#ward-response",
      choices: {
        heardMuteNightstand: { btn: "#ward-choice-listen", duty: true, signal: 2, debt: 0, target: "reverse-laundry", response: "没有铃声。床头柜里却有人先说了“收到”。" },
        changedBreathingBedding: { btn: "#ward-choice-sheet", duty: true, signal: 3, debt: 1, target: "unnumbered-floor", response: "床单被下面不存在的胸口顶起，又慢慢落下。" },
        crawledIVTubeIntoWall: { btn: "#ward-choice-tube", duty: false, target: "seeping-records", response: "输液管把你当作一滴过大的药，送进潮湿的墙后。" },
      },
    },
    "seeping-records": {
      responseEl: "#records-response",
      choices: {
        driedNamelessPage: { btn: "#records-choice-dry", duty: true, signal: 2, debt: 0, target: "unnumbered-floor", response: "纸干了。你的名字却从背面慢慢渗出来。" },
        drankSeepedInk: { btn: "#records-choice-drink", duty: true, signal: 4, debt: 2, target: "bellless-ward", response: "墨水记住了你的喉咙，档案池暂时忘了你的名字。" },
        letRecordsSinkFurther: { btn: "#records-choice-sink", duty: false, target: "unnumbered-vestibule", response: "档案井下降一格，上方的无号前厅跟着空出一层。" },
      },
    },
    "reverse-laundry": {
      responseEl: "#laundry-response",
      choices: {
        cutLeadingDrum: { btn: "#laundry-choice-drum", duty: true, signal: 2, debt: 0, target: "seeping-records", response: "滚筒停了。里面那件衣服还在继续转身。" },
        woreReflectionlessUniform: { btn: "#laundry-choice-uniform", duty: true, signal: 3, debt: 1, target: "unnumbered-floor", response: "镜面里少了一个人，工服里却多了一次呼吸。" },
        brushedMirrorCabinWithOldPlate: { btn: "#laundry-choice-mirror", duty: false, target: "glyph-niche", response: "镜面认得这个号码，把你送回失号龛继续遗失。" },
      },
    },
  };

  const paintFloorRoom = (sceneKey) => {
    const meta = FLOOR_ROOM_META[sceneKey];
    const st = getFloor();
    const room = FLOOR_VISIT_KEY[sceneKey];
    Object.keys(meta.choices).forEach((mark) => {
      const choice = meta.choices[mark];
      const btn = $(choice.btn);
      if (!btn) return;
      /* 已完成房间的两条值班动作 disabled 保留可见，穿行/离开动作继续可用 */
      btn.disabled = choice.duty && (st.settled || st.completed.includes(room));
      btn.setAttribute("aria-pressed", st.marks.includes(mark) ? "true" : "false");
    });
    paintFloorSlip(sceneKey, st);
  };

  const enterFloorRoom = (sceneKey) => {
    markFloorVisited(sceneKey);
    const meta = FLOOR_ROOM_META[sceneKey];
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = "";
    paintFloorRoom(sceneKey);
    /* v37：恢复现场回拨按钮的 pending/completed 状态（只读 v37 键） */
    paintCallbackRoom(sceneKey);
  };

  const chooseFloorAction = (sceneKey, mark) => {
    const meta = FLOOR_ROOM_META[sceneKey];
    const choice = meta && meta.choices[mark];
    if (!choice) return;
    if (AutoAdvance.has(sceneKey)) return;
    const st = getFloor();
    const room = FLOOR_VISIT_KEY[sceneKey];
    if (choice.duty) {
      /* 同轮同房只结算一次；本轮已结算（settled）不再接受值班 */
      if (st.settled || st.completed.includes(room)) return;
      st.signal = Math.min(FLOOR_SIGNAL_CAP, st.signal + choice.signal);
      st.debt = Math.min(FLOOR_DEBT_CAP, st.debt + choice.debt);
      st.completed.push(room);
    }
    if (!st.marks.includes(mark)) st.marks.push(mark);
    saveFloor(st);
    paintFloorRoom(sceneKey);
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = choice.response;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule(sceneKey, choice.target, { delay: branchDelay() });
  };

  FLOOR_DUTY_SCENES.forEach((sceneKey) => {
    const meta = FLOOR_ROOM_META[sceneKey];
    Object.keys(meta.choices).forEach((mark) => {
      const btn = $(meta.choices[mark].btn);
      if (btn) btn.addEventListener("click", () => chooseFloorAction(sceneKey, mark));
    });
  });

  /* 大厅三扇门与夜班登记窗：始终可选，已完成房间仍可重访 */
  const FLOOR_DOORS = {
    "floor-door-ward": { target: "bellless-ward", response: "门后没有铃声。" },
    "floor-door-records": { target: "seeping-records", response: "门后在渗水。" },
    "floor-door-laundry": { target: "reverse-laundry", response: "门后滚筒先停了。" },
    "floor-door-registry": { target: "night-shift-registry", response: "地面少了一块砖，登记窗从下面升了起来。", mark: "openedNightShiftRegistry", entry: "floor" },
  };

  const paintFloorHub = () => {
    const st = getFloor();
    paintFloorSlip("unnumbered-floor", st);
    const btn = $("#floor-elevator-btn");
    const label = $("#floor-elevator-label");
    if (btn && label) {
      const ready = !st.settled && st.completed.length >= 2;
      btn.disabled = !ready;
      label.textContent = ready ? "召回没有楼层的电梯" : "缺层电梯仍封死";
    }
  };

  /* 进入大厅：已结算的上一轮在此开新轮（cycle+1，本轮清空，累计保留；
     outcome 随旧轮一并消费）；直接 hash 只记 visited，不自动动作 */
  const enterFloor = () => {
    markFloorVisited("unnumbered-floor");
    const st = getFloor();
    if (st.settled) {
      st.cycle = Math.min(FLOOR_NUM_CAP, st.cycle + 1);
      st.completed = [];
      st.signal = 0;
      st.debt = 0;
      st.settled = false;
      st.outcome = "";
      /* v36：新 cycle 同时清空值班证，累计领证次数保留 */
      st.permit = "none";
      st.permitSignal = 0;
      st.permitDebt = 0;
      st.permitCycle = st.cycle;
      saveFloor(st);
    }
    const responseEl = $("#floor-response");
    if (responseEl) responseEl.textContent = "";
    paintFloorHub();
  };

  Object.keys(FLOOR_DOORS).forEach((id) => {
    const btn = $("#" + id);
    const door = FLOOR_DOORS[id];
    if (!btn) return;
    btn.addEventListener("click", () => {
      if (AutoAdvance.has("unnumbered-floor")) return;
      /* v36 登记窗：与三门共用大厅首选锁，点击即记 mark 与 entry */
      if (door.mark) {
        const st = getFloor();
        st.entry = door.entry;
        if (!st.marks.includes(door.mark)) st.marks.push(door.mark);
        saveFloor(st);
        btn.setAttribute("aria-pressed", "true");
      }
      const responseEl = $("#floor-response");
      if (responseEl) responseEl.textContent = door.response;
      AudioEngine.knock(0.16);
      AutoAdvance.schedule("unnumbered-floor", door.target, { delay: branchDelay() });
    });
  });

  /* 缺层电梯：完成任意两房解锁；只结算一次，routeScore = max(0, 信号 - 门债) 三档分流 */
  const floorElevatorBtn = $("#floor-elevator-btn");
  if (floorElevatorBtn) floorElevatorBtn.addEventListener("click", () => {
    if (AutoAdvance.has("unnumbered-floor")) return;
    const st = getFloor();
    if (st.settled || st.completed.length < 2) return;
    const routeScore = Math.max(0, st.signal - st.debt);
    st.completedRuns = Math.min(FLOOR_NUM_CAP, st.completedRuns + 1);
    st.bestRoute = Math.max(st.bestRoute, routeScore);
    const responseEl = $("#floor-response");
    let target;
    if (routeScore >= 4) {
      st.highRuns = Math.min(FLOOR_NUM_CAP, st.highRuns + 1);
      st.outcome = "high";
      target = "quota-elevator";
      if (responseEl) responseEl.textContent = "缺层电梯认出了你的信号，把你抬回仍有定额的高度。";
    } else if (routeScore >= 2) {
      st.reviewRuns = Math.min(FLOOR_NUM_CAP, st.reviewRuns + 1);
      st.outcome = "review";
      target = "anomaly-review";
      if (responseEl) responseEl.textContent = "这条路线没有编号，只能先交给复核科承认。";
    } else {
      st.debtRuns = Math.min(FLOOR_NUM_CAP, st.debtRuns + 1);
      st.outcome = "debt";
      target = "return-passage";
      if (responseEl) responseEl.textContent = "门债比楼层更重。电梯把你吐回写着“回来”的夹道。";
    }
    st.settled = true;
    saveFloor(st);
    paintFloorHub();
    AudioEngine.knock(0.16);
    AutoAdvance.schedule("unnumbered-floor", target, { delay: branchDelay() });
  });

  /* 两处入口：前厅第五动作与定额电梯第四动作，与所在场景共用首选锁 */
  const FLOOR_ENTRY_META = {
    "unnumbered-vestibule": { btn: "#vestibule-choice-floor", entry: "vestibule", mark: "pressedMissingBasementFloor", responseEl: "#vestibule-response", response: "按钮没有下沉。整座前厅却往上抬了一层。" },
    "quota-elevator": { btn: "#elevator-choice-floor", entry: "quota", mark: "stoppedNeedleAtUnmarkedFloor", responseEl: "#elevator-response", response: "指针越过零，停在一块没有被刻出来的黄铜上。" },
    "return-passage": { btn: "#return-choice-registry", entry: "passage", mark: "caughtTomorrowPermit", responseEl: "#return-response", response: "墙缝吐出一张盖着明日日期的值班证，背面写着无号层。", target: "night-shift-registry" },
  };

  const paintFloorEntry = (sceneKey) => {
    const meta = FLOOR_ENTRY_META[sceneKey];
    if (!meta) return;
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", getFloor().marks.includes(meta.mark) ? "true" : "false");
  };

  const chooseFloorEntry = (sceneKey) => {
    const meta = FLOOR_ENTRY_META[sceneKey];
    if (!meta) return;
    if (AutoAdvance.has(sceneKey)) return;
    const st = getFloor();
    st.entry = meta.entry;
    if (!st.marks.includes(meta.mark)) st.marks.push(meta.mark);
    saveFloor(st);
    paintFloorEntry(sceneKey);
    addAnnexDebt(meta.btn);
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = meta.response;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule(sceneKey, meta.target || "unnumbered-floor", { delay: branchDelay() });
  };

  Object.keys(FLOOR_ENTRY_META).forEach((sceneKey) => {
    const btn = $(FLOOR_ENTRY_META[sceneKey].btn);
    if (btn) btn.addEventListener("click", () => chooseFloorEntry(sceneKey));
  });

  /* 三档落点一次性反馈：高信号回定额电梯、中间值交复核科（强制 neutral 新轮）、
     低值坠回回返夹道；展示一次即消费 outcome */
  const consumeFloorOutcome = (tier, responseEl) => {
    const st = getFloor();
    if (st.outcome !== tier) return false;
    if (tier === "high" && responseEl) responseEl.textContent = "缺层电梯认出了你的信号，把你抬回仍有定额的高度。";
    if (tier === "review" && responseEl) responseEl.textContent = "这条路线没有编号，只能先交给复核科承认。";
    if (tier === "debt" && responseEl) responseEl.textContent = "门债比楼层更重。电梯把你吐回写着“回来”的夹道。";
    st.outcome = "";
    saveFloor(st);
    return true;
  };

  /* ============================================================
     v36 夜班登记所：每 cycle 限领一张值班证，领取立即加值并自动回大厅
     ============================================================ */
  const REGISTRY_META = {
    muteBell: { btn: "#permit-choice-mute-bell", resultEl: "#permit-result-mute-bell", name: "无铃证", signal: 2, debt: 0, mark: "borrowedMuteBellPermit", counter: "muteBellRuns", response: "空铃在证背摇了一下，没有出声。楼层信号多认了你两次。" },
    blankName: { btn: "#permit-choice-blank-name", resultEl: "#permit-result-blank-name", name: "失名牌", signal: 0, debt: 2, mark: "claimedBlankNamePermit", counter: "blankNameRuns", response: "号牌没有名字，门债却把你的姓名写了两遍。" },
    reverseBadge: { btn: "#permit-choice-reverse-badge", resultEl: "#permit-result-reverse-badge", name: "反面工牌", signal: 0, debt: 4, mark: "signedReverseBadge", counter: "reverseBadgeRuns", response: "你在背面签字。正面的四道门同时记住了这笔债。" },
  };
  const REGISTRY_PERMIT_LABEL = { none: "未领", muteBell: "无铃证", blankName: "失名牌", reverseBadge: "反面工牌" };

  const paintRegistry = () => {
    const st = getFloor();
    const permitEl = $("#registry-stat-permit");
    const signalEl = $("#registry-stat-signal");
    const debtEl = $("#registry-stat-debt");
    const bestEl = $("#registry-stat-best");
    if (permitEl) permitEl.textContent = REGISTRY_PERMIT_LABEL[st.permit];
    if (signalEl) signalEl.textContent = st.permitSignal;
    if (debtEl) debtEl.textContent = st.permitDebt;
    if (bestEl) bestEl.textContent = st.bestRoute;
    const claimed = st.permit !== "none";
    Object.keys(REGISTRY_META).forEach((key) => {
      const meta = REGISTRY_META[key];
      const btn = $(meta.btn);
      const resultEl = $(meta.resultEl);
      if (!btn) return;
      btn.disabled = claimed;
      btn.setAttribute("aria-pressed", st.permit === key ? "true" : "false");
      if (resultEl) resultEl.textContent = st.permit === key ? `已领 · +${meta.signal} / 门债 +${meta.debt}` : "";
    });
  };

  /* 进入登记所：从已 settled 状态进入先开 v35 新 cycle 再允许领证；
     直接 hash 只记 visited，不自动领取 */
  const enterRegistry = () => {
    markFloorVisited("night-shift-registry");
    const st = getFloor();
    if (st.settled) {
      st.cycle = Math.min(FLOOR_NUM_CAP, st.cycle + 1);
      st.completed = [];
      st.signal = 0;
      st.debt = 0;
      st.settled = false;
      st.outcome = "";
      st.permit = "none";
      st.permitSignal = 0;
      st.permitDebt = 0;
      st.permitCycle = st.cycle;
      saveFloor(st);
    }
    const responseEl = $("#registry-response");
    if (responseEl) responseEl.textContent = "";
    paintRegistry();
  };

  /* 领取一张值班证：第一次合法选择立即写入并加值，三卡竞争/连点/Enter/Space
     只认第一张；同一 cycle 不得再次领取或重复加值 */
  const claimPermit = (permitKey) => {
    const meta = REGISTRY_META[permitKey];
    if (!meta) return;
    if (AutoAdvance.has("night-shift-registry")) return;
    const st = getFloor();
    if (st.settled || st.permit !== "none") return;
    st.signal = Math.min(FLOOR_SIGNAL_CAP, st.signal + meta.signal);
    st.debt = Math.min(FLOOR_DEBT_CAP, st.debt + meta.debt);
    st.permit = permitKey;
    st.permitSignal = meta.signal;
    st.permitDebt = meta.debt;
    st.permitCycle = st.cycle;
    st.permitRuns = Math.min(FLOOR_NUM_CAP, st.permitRuns + 1);
    st[meta.counter] = Math.min(FLOOR_NUM_CAP, st[meta.counter] + 1);
    if (!st.marks.includes(meta.mark)) st.marks.push(meta.mark);
    saveFloor(st);
    paintRegistry();
    const responseEl = $("#registry-response");
    if (responseEl) responseEl.textContent = meta.response;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule("night-shift-registry", "unnumbered-floor", { delay: branchDelay() });
  };

  Object.keys(REGISTRY_META).forEach((permitKey) => {
    const btn = $(REGISTRY_META[permitKey].btn);
    if (btn) btn.addEventListener("click", () => claimPermit(permitKey));
  });

  /* 痕迹页单行：领证次数与三张分布，保持八张统计卡不变 */
  const paintRegistryMemory = () => {
    const memory = $("#registry-memory");
    if (!memory) return;
    const st = getFloor();
    if (!st.visited.nightShiftRegistry) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `夜班登记：领证 ${st.permitRuns} 次，无铃 ${st.muteBellRuns}，失名 ${st.blankNameRuns}，反面 ${st.reverseBadgeRuns}。`;
    memory.hidden = false;
  };

  /* 痕迹页单行：完成轮数 / 最佳路线 / 抬回 / 门债遣返，保持八张统计卡不变 */
  const paintFloorMemory = () => {
    const memory = $("#floor-memory");
    if (!memory) return;
    const st = getFloor();
    if (!st.visited.floor && !st.visited.ward && !st.visited.records && !st.visited.laundry) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `无号层值班：完成 ${st.completedRuns} 轮，最佳路线 ${st.bestRoute}，抬回 ${st.highRuns} 次，门债遣返 ${st.debtRuns} 次。`;
    memory.hidden = false;
  };

  /* ============================================================
     v37 午夜回拨台：守则其六 / 回返夹道双入口 + 三线现场回拨
     状态独立存 goddead_v37_midnight_callback，容错坏 JSON；
     不读不写 v28–v34、v35 结算字段与主线状态；
     点击即执行，无确认页、继续按钮或结算按钮。
     ============================================================ */
  const CALLBACK_KEY = "goddead_v37_midnight_callback";
  const CALLBACK_ENTRIES = ["neutral", "protocol", "passage"];
  const CALLBACK_LINES = ["ward", "records", "laundry"];
  const CALLBACK_MARKS = [
    "answeredProtocolSix", "answeredLateWallCall",
    "connectedWardLine", "connectedRecordsLine", "connectedLaundryLine",
    "reportedWardLine", "reportedRecordsLine", "reportedLaundryLine",
  ];
  const CALLBACK_NUM_CAP = 9999;
  const CALLBACK_LINE_VALUES = { ward: [3, 0], records: [2, 1], laundry: [1, 2] };
  const CALLBACK_ROOM_SCENE = { ward: "bellless-ward", records: "seeping-records", laundry: "reverse-laundry" };

  const getCallback = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(CALLBACK_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const visited = { callback: Boolean(raw.visited && raw.visited.callback === true) };
    const entry = CALLBACK_ENTRIES.includes(raw.entry) ? raw.entry : "neutral";
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(CALLBACK_NUM_CAP, Math.floor(n));
    };
    let cycle = num(raw.cycle);
    if (cycle < 1) cycle = 1;
    const completedLines = Array.isArray(raw.completedLines)
      ? [...new Set(raw.completedLines.filter((l) => CALLBACK_LINES.includes(l)))].slice(0, 2)
      : [];
    let pendingLine = raw.pendingLine === "none" || CALLBACK_LINES.includes(raw.pendingLine) ? raw.pendingLine : "none";
    /* pending 不能同时出现在 completedLines */
    if (completedLines.includes(pendingLine)) pendingLine = "none";
    /* 分值必须由 completedLines 唯一重算，不信任存档里的伪造分值 */
    let verification = 0;
    let lineDebt = 0;
    completedLines.forEach((l) => {
      verification += CALLBACK_LINE_VALUES[l][0];
      lineDebt += CALLBACK_LINE_VALUES[l][1];
    });
    /* 不足两条的 settled / outcome 归一为未结算；
       outcome 必须由 completedLines 唯一推导，不信任空白或与组合不匹配的存档值 */
    let derivedOutcome = "";
    if (completedLines.length >= 2) {
      if (completedLines.includes("ward") && completedLines.includes("records")) derivedOutcome = "clear";
      else if (completedLines.includes("ward") && completedLines.includes("laundry")) derivedOutcome = "uncertain";
      else derivedOutcome = "contaminated";
    }
    let settled = raw.settled === true;
    let outcome = derivedOutcome;
    if (completedLines.length < 2) { settled = false; outcome = ""; }
    if (!settled) outcome = "";
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => CALLBACK_MARKS.includes(m)))].slice(0, CALLBACK_MARKS.length)
      : [];
    return {
      visited, entry, cycle, pendingLine, completedLines,
      verification, lineDebt, settled, outcome,
      completedRuns: num(raw.completedRuns),
      clearRuns: num(raw.clearRuns),
      uncertainRuns: num(raw.uncertainRuns),
      contaminatedRuns: num(raw.contaminatedRuns),
      bestRoute: Math.min(4, num(raw.bestRoute)),
      marks,
    };
  };
  const saveCallback = (st) => store.set(CALLBACK_KEY, JSON.stringify(st));

  /* 入口登记：守则其六与回返夹道共用（只写 v37 键） */
  const markCallbackEntry = (entryId) => {
    const st = getCallback();
    st.entry = CALLBACK_ENTRIES.includes(entryId) ? entryId : "neutral";
    const mark = entryId === "protocol" ? "answeredProtocolSix" : "answeredLateWallCall";
    if (!st.marks.includes(mark)) st.marks.push(mark);
    saveCallback(st);
  };

  const syncCallbackLink = () => {
    const link = $("#callback-link");
    if (!link) return;
    if (getCallback().visited.callback) link.removeAttribute("hidden");
    else link.setAttribute("hidden", "");
  };

  const markCallbackVisited = () => {
    const st = getCallback();
    if (st.visited.callback) return;
    st.visited.callback = true;
    saveCallback(st);
    syncCallbackLink();
  };

  const CALLBACK_LINE_META = {
    ward: { btn: "#callback-line-ward", resultEl: "#callback-result-ward", mark: "connectedWardLine", response: "总机把没有铃声的那一段线路塞进你耳后。" },
    records: { btn: "#callback-line-records", resultEl: "#callback-result-records", mark: "connectedRecordsLine", response: "墨水沿电话线爬上来，把这一段接成了潮湿的黑色。" },
    laundry: { btn: "#callback-line-laundry", resultEl: "#callback-result-laundry", mark: "connectedLaundryLine", response: "黄铜线穿过镜面，把你的声音挂进那件工服。" },
  };
  const CALLBACK_REPORT_META = {
    "bellless-ward": { line: "ward", btn: "#ward-choice-callback", mark: "reportedWardLine", response: "你说“没有铃声”。总机记录了三次完全相同的铃响。" },
    "seeping-records": { line: "records", btn: "#records-choice-callback", mark: "reportedRecordsLine", response: "你念出空白姓名栏。总机用你的号码补上了那一格。" },
    "reverse-laundry": { line: "laundry", btn: "#laundry-choice-callback", mark: "reportedLaundryLine", response: "你报告“没有倒影”。滚筒替你留下了两份相反的录音。" },
  };

  const paintCallback = () => {
    const st = getCallback();
    const doneEl = $("#callback-stat-done");
    const verificationEl = $("#callback-stat-verification");
    const debtEl = $("#callback-stat-debt");
    const bestEl = $("#callback-stat-best");
    if (doneEl) doneEl.textContent = `${st.completedLines.length}/2`;
    if (verificationEl) verificationEl.textContent = st.verification;
    if (debtEl) debtEl.textContent = st.lineDebt;
    if (bestEl) bestEl.textContent = st.bestRoute;
    CALLBACK_LINES.forEach((line) => {
      const meta = CALLBACK_LINE_META[line];
      const btn = $(meta.btn);
      const resultEl = $(meta.resultEl);
      if (!btn) return;
      const isPending = st.pendingLine === line;
      const isDone = st.completedLines.includes(line);
      btn.disabled = st.settled || isDone || (st.pendingLine !== "none" && !isPending);
      btn.setAttribute("aria-pressed", isPending || isDone ? "true" : "false");
      if (resultEl) {
        if (isDone) resultEl.textContent = `已回拨 · 核实 +${CALLBACK_LINE_VALUES[line][0]} / 线债 +${CALLBACK_LINE_VALUES[line][1]}`;
        else if (isPending) resultEl.textContent = "接通中 · 在现场等你回拨";
        else resultEl.textContent = "";
      }
    });
  };

  /* 自动结算：完成两条后回到回拨台，一个反馈节拍后按组合分流；
     没有结算按钮、确认页或继续按钮 */
  const settleCallback = () => {
    const st = getCallback();
    if (st.settled || st.completedLines.length < 2) return;
    const routeScore = Math.max(0, st.verification - st.lineDebt);
    st.completedRuns = Math.min(CALLBACK_NUM_CAP, st.completedRuns + 1);
    st.bestRoute = Math.min(4, Math.max(st.bestRoute, routeScore));
    const has = (l) => st.completedLines.includes(l);
    const responseEl = $("#callback-response");
    let target;
    if (has("ward") && has("records")) {
      st.clearRuns = Math.min(CALLBACK_NUM_CAP, st.clearRuns + 1);
      st.outcome = "clear";
      target = "anomaly-review";
      if (responseEl) responseEl.textContent = "两条现场报告互相承认。复核科愿意把这次来电当成证据。";
    } else if (has("ward") && has("laundry")) {
      st.uncertainRuns = Math.min(CALLBACK_NUM_CAP, st.uncertainRuns + 1);
      st.outcome = "uncertain";
      target = "peephole-chamber";
      if (responseEl) responseEl.textContent = "两条线路只对上了一半。倒置窥孔要求亲眼再看一次。";
    } else {
      st.contaminatedRuns = Math.min(CALLBACK_NUM_CAP, st.contaminatedRuns + 1);
      st.outcome = "contaminated";
      target = "return-passage";
      if (responseEl) responseEl.textContent = "线债吃掉了全部核实。回返夹道接起第三条线，用你的声音说“回来”。";
    }
    st.settled = true;
    saveCallback(st);
    paintCallback();
    AudioEngine.knock(0.16);
    AutoAdvance.schedule("midnight-callback", target, { delay: branchDelay() });
  };

  /* 进入回拨台：已结算则开新 cycle（pending/completed/分值/outcome 清空，累计保留）；
     正在 pending 或只完成一条时原位恢复；直接 hash 只记 visited，不自动接线 */
  const enterCallback = () => {
    markCallbackVisited();
    const st = getCallback();
    if (st.settled) {
      st.cycle = Math.min(CALLBACK_NUM_CAP, st.cycle + 1);
      st.pendingLine = "none";
      st.completedLines = [];
      st.settled = false;
      st.outcome = "";
      saveCallback(st);
      const responseEl = $("#callback-response");
      if (responseEl) responseEl.textContent = "";
      paintCallback();
      return;
    }
    const responseEl = $("#callback-response");
    if (responseEl) responseEl.textContent = "";
    paintCallback();
    /* 第二次回拨回到台上：自动结算 */
    settleCallback();
  };

  /* 接通一条线路：只写 pending 与 pending mark，不加分值；
     有 pending 时另外两条 disabled；重进回拨台点已接通线路可重新接回现场，
     不重复写 mark、不加分值、不影响计数 */
  const connectLine = (line) => {
    const meta = CALLBACK_LINE_META[line];
    if (!meta) return;
    if (AutoAdvance.has("midnight-callback")) return;
    const st = getCallback();
    if (st.settled || st.completedLines.includes(line)) return;
    if (st.pendingLine !== "none" && st.pendingLine !== line) return;
    const reconnect = st.pendingLine === line;
    if (!reconnect) {
      st.pendingLine = line;
      if (!st.marks.includes(meta.mark)) st.marks.push(meta.mark);
      saveCallback(st);
    }
    paintCallback();
    const responseEl = $("#callback-response");
    if (responseEl) responseEl.textContent = meta.response;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule("midnight-callback", CALLBACK_ROOM_SCENE[line], { delay: branchDelay() });
  };

  CALLBACK_LINES.forEach((line) => {
    const btn = $(CALLBACK_LINE_META[line].btn);
    if (btn) btn.addEventListener("click", () => connectLine(line));
  });

  /* 现场回拨：与房间既有三动作共用首选锁；回拨成功才入 completedLines、
     加分值、清空 pending 并自动回回拨台；选择既有动作离开时 pending 保留 */
  const paintCallbackRoom = (sceneKey) => {
    const meta = CALLBACK_REPORT_META[sceneKey];
    if (!meta) return;
    const st = getCallback();
    const btn = $(meta.btn);
    if (!btn) return;
    btn.disabled = st.settled || st.pendingLine !== meta.line || st.completedLines.includes(meta.line);
    btn.setAttribute("aria-pressed", st.completedLines.includes(meta.line) ? "true" : "false");
  };

  const reportLine = (sceneKey) => {
    const meta = CALLBACK_REPORT_META[sceneKey];
    if (!meta) return;
    if (AutoAdvance.has(sceneKey)) return;
    const st = getCallback();
    if (st.settled || st.pendingLine !== meta.line || st.completedLines.includes(meta.line)) return;
    st.completedLines.push(meta.line);
    st.pendingLine = "none";
    /* 分值与 completedLines 同步重算后落盘，存档不得残留旧值 */
    st.verification += CALLBACK_LINE_VALUES[meta.line][0];
    st.lineDebt += CALLBACK_LINE_VALUES[meta.line][1];
    if (!st.marks.includes(meta.mark)) st.marks.push(meta.mark);
    saveCallback(st);
    paintCallbackRoom(sceneKey);
    const roomMeta = FLOOR_ROOM_META[sceneKey];
    const responseEl = roomMeta && $(roomMeta.responseEl);
    if (responseEl) responseEl.textContent = meta.response;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule(sceneKey, "midnight-callback", { delay: branchDelay() });
  };

  Object.keys(CALLBACK_REPORT_META).forEach((sceneKey) => {
    const btn = $(CALLBACK_REPORT_META[sceneKey].btn);
    if (btn) btn.addEventListener("click", () => reportLine(sceneKey));
  });

  /* 回返夹道第五入口：与原四动作共用首选锁 */
  const callbackEntryBtn = $("#return-choice-callback");
  if (callbackEntryBtn) callbackEntryBtn.addEventListener("click", () => {
    if (AutoAdvance.has("return-passage")) return;
    markCallbackEntry("passage");
    callbackEntryBtn.setAttribute("aria-pressed", "true");
    const responseEl = $("#return-response");
    if (responseEl) responseEl.textContent = "墙里的电话比铃声晚响了八分钟。听筒正在读守则其六。";
    AudioEngine.knock(0.16);
    AutoAdvance.schedule("return-passage", "midnight-callback", { delay: branchDelay() });
  });

  const paintCallbackEntry = (sceneKey) => {
    if (sceneKey !== "return-passage" || !callbackEntryBtn) return;
    callbackEntryBtn.setAttribute("aria-pressed", getCallback().marks.includes("answeredLateWallCall") ? "true" : "false");
  };

  /* 痕迹页单行：完成轮数 / 清线 / 疑线 / 污线 / 最佳线路，保持八张统计卡不变 */
  const paintCallbackMemory = () => {
    const memory = $("#callback-memory");
    if (!memory) return;
    const st = getCallback();
    if (!st.visited.callback) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `午夜回拨：完成 ${st.completedRuns} 轮，清线 ${st.clearRuns}，疑线 ${st.uncertainRuns}，污线 ${st.contaminatedRuns}，最佳线路 ${st.bestRoute}。`;
    memory.hidden = false;
  };

  /* ============================================================
     v38 门外代审窗：门板第四热点 / 守则其八双入口 + 三问两判
     状态独立存 goddead_v38_proxy_admission，容错坏 JSON；
     proof/debt/错误类型/outcome 必须由合法 decisions 重算；
     不读不写 v28–v37 与主线状态；点击即执行，无确认/继续按钮。
     ============================================================ */
  const PROXY_KEY = "goddead_v38_proxy_admission";
  const PROXY_ENTRIES = ["threshold", "protocol", "direct"];
  const PROXY_VISITOR_IDS = ["nurse", "postman", "umbrella", "widow"];
  const PROXY_QUESTION_IDS = ["name", "shadow", "knock"];
  const PROXY_MARKS = ["openedProxyWindow", "answeredProtocolEight", "judgedNurse", "judgedPostman", "judgedUmbrella", "judgedWidow"];
  const PROXY_NUM_CAP = 9999;

  /* 四轮确定性 roster：行 = cycle 0 的顺序，按（入口行 + cycle）循环移位 */
  const PROXY_ROSTER_MATRIX = [
    ["nurse", "postman", "umbrella"],
    ["postman", "widow", "nurse"],
    ["umbrella", "widow", "postman"],
    ["widow", "nurse", "umbrella"],
  ];
  const PROXY_ENTRY_ROW = { threshold: 0, protocol: 1, direct: 2 };
  const proxyRosterFor = (entry, cycle) => PROXY_ROSTER_MATRIX[(PROXY_ENTRY_ROW[entry] + cycle) % PROXY_ROSTER_MATRIX.length].slice();
  const isValidProxyRoster = (roster) => Array.isArray(roster) && roster.length === 3
    && roster.every((v) => PROXY_VISITOR_IDS.includes(v))
    && new Set(roster).size === 3;

  const PROXY_VISITORS = {
    nurse: {
      name: "无铃夜班护士", present: true, asset: "assets/proxy-visitor-nurse.webp",
      statement: "“我来接没人肯接的下一班。”",
      questions: { name: "“编号被铃声擦掉了，名字还在今天的值班簿里。”", shadow: "她抬手时，影子也在同一刻碰到玻璃。", knock: "三声。每一声都从门外传来。" },
      correct: "问讯窗承认她仍在场。你的名字从她的空编号牌上退了下来。",
      wrong: "你把仍在场的人留在门外。窥孔开始重新核对你。",
      judgedMark: "judgedNurse",
    },
    postman: {
      name: "倒签邮差", present: false, asset: "assets/proxy-visitor-postman.webp",
      statement: "“我只送还没有写完的那一封。”",
      questions: { name: "“收件人是你。寄件日期比你的到访早一天。”", shadow: "他的手没有动，影子已经把信封推进门缝。", knock: "嘴里数到三，门上却留下四次回声。" },
      correct: "黑封蜡停在门槛外。那封信只好继续写你的名字。",
      wrong: "你放行了发生在本人之前的投递。回返夹道多出一双脚印。",
      judgedMark: "judgedPostman",
    },
    umbrella: {
      name: "黑伞信使", present: true, asset: "assets/proxy-visitor-umbrella.webp",
      statement: "“伞是门里的人借我的。我来还。”",
      questions: { name: "“名字没有写在纸上。门环认得握过它的手。”", shadow: "信使、黑伞与三枚门环在地上同时偏向左侧。", knock: "他用伞柄敲三次；黄铜每次都留下新的凹痕。" },
      correct: "门环认出了那只手。黑伞合上时，门外少了一场雨。",
      wrong: "你拒绝了还伞的人。门后的雨开始从窥孔里落下。",
      judgedMark: "judgedUmbrella",
    },
    widow: {
      name: "空襁褓妇人", present: false, asset: "assets/proxy-visitor-widow.webp",
      statement: "“孩子已经睡了。请别让门把祂吵醒。”",
      questions: { name: "她报出的名字，正是代审簿刚写给你的那个。", shadow: "她的双臂是空的；墙上影子却在轻拍一个婴儿。", knock: "第一声从门后传来，随后她才抬起手。" },
      correct: "襁褓的影子留在墙上，妇人却从问讯窗外消失了。",
      wrong: "你让一个借用你名字的回声入内。失号龛替它擦掉了编号。",
      judgedMark: "judgedWidow",
    },
  };
  const PROXY_QUESTION_META = {
    name: { btn: "#proxy-question-name", resultEl: "#proxy-question-result-name" },
    shadow: { btn: "#proxy-question-shadow", resultEl: "#proxy-question-result-shadow" },
    knock: { btn: "#proxy-question-knock", resultEl: "#proxy-question-result-knock" },
  };
  const PROXY_OUTCOME_META = {
    verified: { target: "protocol", feedback: "三份证词互相承认。守则同意把你登记为访客。" },
    paranoid: { target: "peephole-chamber", feedback: "你把仍在场的人挡在门外。倒置窥孔要求先核对门卫。" },
    contaminated: { target: "return-passage", feedback: "你放行的那道回声已经从里面敲门。回返夹道负责把它送回来。" },
    unnamed: { target: "glyph-niche", feedback: "门债盖过了全部在场证。失号龛收走了代审簿上的名字。" },
  };

  const getProxy = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(PROXY_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const visited = Boolean(raw.visited === true);
    const entry = PROXY_ENTRIES.includes(raw.entry) ? raw.entry : "direct";
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(PROXY_NUM_CAP, Math.floor(n));
    };
    const cycle = num(raw.cycle);
    const roster = isValidProxyRoster(raw.roster) ? raw.roster.slice() : proxyRosterFor(entry, cycle);
    /* decisions 只接受当前 roster 内、按 roster 顺序形成的连续已判断前缀：
       off-roster 与跳位/out-of-order 决策全部丢弃，不得推进 index 或计分 */
    const decisions = {};
    if (raw.decisions && typeof raw.decisions === "object" && !Array.isArray(raw.decisions)) {
      for (const v of roster) {
        const c = raw.decisions[v];
        if (c === "admit" || c === "refuse") decisions[v] = c;
        else break;
      }
    }
    const decisionIds = Object.keys(decisions);
    /* questioned 至少丢弃 off-roster 数据，避免污染 UI 与已问统计 */
    const questioned = {};
    if (raw.questioned && typeof raw.questioned === "object" && !Array.isArray(raw.questioned)) {
      Object.keys(raw.questioned).forEach((v) => {
        if (roster.includes(v) && Array.isArray(raw.questioned[v])) {
          questioned[v] = [...new Set(raw.questioned[v].filter((q) => PROXY_QUESTION_IDS.includes(q)))].slice(0, 3);
        }
      });
    }
    /* proof/debt/错误类型必须由合法 decisions 重算，不信任存档伪造数字 */
    let proof = 0;
    let doorDebt = 0;
    let admittedEcho = false;
    let rejectedPresent = false;
    decisionIds.forEach((v) => {
      const meta = PROXY_VISITORS[v];
      const correct = (decisions[v] === "admit") === meta.present;
      if (correct) proof += 2;
      else {
        doorDebt += 1;
        if (decisions[v] === "admit") admittedEcho = true;
        else rejectedPresent = true;
      }
    });
    const index = decisionIds.length;
    /* settled 与 outcome 完全由三条有效、当前 roster、连续 decisions 推导：
       三条合法 decisions 即视为已结算（raw.settled 不被信任），
       修复状态在下一次正常保存时持久化 */
    let derivedOutcome = "";
    if (index >= 3) {
      if (proof === 6 && doorDebt === 0) derivedOutcome = "verified";
      else if (proof === 4 && rejectedPresent) derivedOutcome = "paranoid";
      else if (proof === 4 && admittedEcho) derivedOutcome = "contaminated";
      else derivedOutcome = "unnamed";
    }
    const settled = index >= 3;
    const outcome = settled ? derivedOutcome : "";
    /* settle 副作用的完成标记：派生值无法区分，单独持久化；
       不足三判时归一为未完成 */
    const settleDone = index >= 3 && raw.settleDone === true;
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => PROXY_MARKS.includes(m)))].slice(0, PROXY_MARKS.length)
      : [];
    return {
      visited, entry, cycle, roster, decisions, questioned, index,
      proof, doorDebt, admittedEcho, rejectedPresent, settled, outcome,
      bestProof: num(raw.bestProof),
      totalJudgments: num(raw.totalJudgments),
      marks,
      settleDone,
    };
  };
  const saveProxy = (st) => store.set(PROXY_KEY, JSON.stringify(st));

  /* 入口登记：门板第四热点与守则其八共用（只写 v38 键）；
     新 cycle 未开始时 roster 必须按当前 entry 重建 */
  const markProxyEntry = (entryId) => {
    const st = getProxy();
    st.entry = PROXY_ENTRIES.includes(entryId) ? entryId : "direct";
    if (st.index === 0) st.roster = proxyRosterFor(st.entry, st.cycle);
    const mark = entryId === "threshold" ? "openedProxyWindow" : "answeredProtocolEight";
    if (!st.marks.includes(mark)) st.marks.push(mark);
    saveProxy(st);
  };

  const syncProxyLink = () => {
    const link = $("#proxy-link");
    if (!link) return;
    if (getProxy().visited) link.removeAttribute("hidden");
    else link.setAttribute("hidden", "");
  };

  const markProxyVisited = () => {
    const st = getProxy();
    if (st.visited) return;
    st.visited = true;
    saveProxy(st);
    syncProxyLink();
  };

  const proxyDelay = () => reduced ? 300 : 900 + Math.floor(Math.random() * 300);

  /* 当前访客图换图：先隐去旧图，新图解码完成再现身，不留白不闪旧图 */
  const showProxyVisitor = (visitorId) => {
    const img = $("#proxy-visitor-img");
    const meta = PROXY_VISITORS[visitorId];
    if (!img || !meta) return;
    const showImg = () => img.classList.remove("is-loading");
    if (img.getAttribute("src") !== meta.asset) {
      img.classList.add("is-loading");
      img.addEventListener("load", showImg, { once: true });
      img.setAttribute("src", meta.asset);
      if (img.complete && img.naturalWidth > 0) showImg();
    } else {
      showImg();
    }
  };

  const paintProxy = () => {
    const st = getProxy();
    const doneEl = $("#proxy-stat-done");
    const proofEl = $("#proxy-stat-proof");
    const debtEl = $("#proxy-stat-debt");
    const askedEl = $("#proxy-stat-asked");
    const bestEl = $("#proxy-stat-best");
    const askedCount = Object.values(st.questioned).reduce((n, qs) => n + qs.length, 0);
    if (doneEl) doneEl.textContent = `${st.index}/3`;
    if (proofEl) proofEl.textContent = st.proof;
    if (debtEl) debtEl.textContent = st.doorDebt;
    if (askedEl) askedEl.textContent = askedCount;
    if (bestEl) bestEl.textContent = st.bestProof;
    /* 反馈节拍内仍显示刚被判的访客并锁死其按钮，拍点过后才换到下一位 */
    const beatPending = AutoAdvance.has("proxy-admission-step");
    const visitorId = st.roster[beatPending ? Math.max(0, st.index - 1) : Math.min(st.index, 2)];
    const meta = PROXY_VISITORS[visitorId];
    showProxyVisitor(visitorId);
    const nameEl = $("#proxy-visitor-name");
    const statementEl = $("#proxy-visitor-statement");
    if (nameEl) nameEl.textContent = meta.name;
    if (statementEl) statementEl.textContent = meta.statement;
    const askedHere = st.questioned[visitorId] || [];
    const locked = st.settled || beatPending || Boolean(st.decisions[visitorId]);
    PROXY_QUESTION_IDS.forEach((qId) => {
      const qMeta = PROXY_QUESTION_META[qId];
      const btn = $(qMeta.btn);
      const resultEl = $(qMeta.resultEl);
      if (!btn) return;
      const asked = askedHere.includes(qId);
      btn.disabled = locked;
      btn.setAttribute("aria-pressed", asked ? "true" : "false");
      if (resultEl) resultEl.textContent = asked ? meta.questions[qId] : "";
    });
    const admitBtn = $("#proxy-judge-admit");
    const refuseBtn = $("#proxy-judge-refuse");
    if (admitBtn) {
      admitBtn.disabled = locked;
      admitBtn.setAttribute("aria-pressed", st.decisions[visitorId] === "admit" ? "true" : "false");
    }
    if (refuseBtn) {
      refuseBtn.disabled = locked;
      refuseBtn.setAttribute("aria-pressed", st.decisions[visitorId] === "refuse" ? "true" : "false");
    }
  };

  /* 进入代审窗：已结算则开下一个确定性 cycle（历史 bestProof/totalJudgments 保留）；
     直接 hash 只记 visited，开启/恢复正常 cycle，不自动问讯或判断 */
  const enterProxy = () => {
    markProxyVisited();
    const st = getProxy();
    if (st.settled) {
      st.cycle = Math.min(PROXY_NUM_CAP, st.cycle + 1);
      st.roster = proxyRosterFor(st.entry, st.cycle);
      st.decisions = {};
      st.questioned = {};
      st.settled = false;
      st.settleDone = false;
      st.outcome = "";
      saveProxy(st);
    }
    const responseEl = $("#proxy-response");
    if (responseEl) responseEl.textContent = "";
    paintProxy();
  };

  /* 三项问讯：只展开证词并记录 questioned，不切场景、不加减分；
     已问项 pressed，重复询问只重播短声音 */
  const askProxy = (qId) => {
    const qMeta = PROXY_QUESTION_META[qId];
    if (!qMeta) return;
    if (AutoAdvance.has("proxy-admission") || AutoAdvance.has("proxy-admission-step")) return;
    const st = getProxy();
    if (st.settled) return;
    const visitorId = st.roster[Math.min(st.index, 2)];
    if (!visitorId || st.decisions[visitorId]) return;
    const askedHere = st.questioned[visitorId] || [];
    AudioEngine.knock(0.12);
    if (askedHere.includes(qId)) return;
    if (!st.questioned[visitorId]) st.questioned[visitorId] = [];
    st.questioned[visitorId].push(qId);
    saveProxy(st);
    paintProxy();
  };

  PROXY_QUESTION_IDS.forEach((qId) => {
    const btn = $(PROXY_QUESTION_META[qId].btn);
    if (btn) btn.addEventListener("click", () => askProxy(qId));
  });

  /* 第三人判断后自动结算一次，按 decisions 推导四档；
     settle 副作用以 settleDone 为完成标记：已结算过的批次不重复结算 */
  const settleProxy = () => {
    const st = getProxy();
    if (st.index < 3 || st.settleDone) return;
    st.settled = true;
    st.outcome = (() => {
      if (st.proof === 6 && st.doorDebt === 0) return "verified";
      if (st.proof === 4 && st.rejectedPresent) return "paranoid";
      if (st.proof === 4 && st.admittedEcho) return "contaminated";
      return "unnamed";
    })();
    st.settleDone = true;
    st.bestProof = Math.max(st.bestProof, st.proof);
    saveProxy(st);
    const meta = PROXY_OUTCOME_META[st.outcome];
    paintProxy();
    const responseEl = $("#proxy-response");
    if (responseEl) responseEl.textContent = meta.feedback;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule("proxy-admission", meta.target, { delay: proxyDelay() });
  };

  /* 两个判断：第一次被接受的判断锁住当前访客全部问讯与判断按钮；
     立即反馈并持久化，短节拍后自动换下一人；第三人自动结算 */
  const judgeProxy = (choice) => {
    if (AutoAdvance.has("proxy-admission") || AutoAdvance.has("proxy-admission-step")) return;
    const st = getProxy();
    if (st.settled || st.index >= 3) return;
    const visitorId = st.roster[st.index];
    const meta = visitorId && PROXY_VISITORS[visitorId];
    if (!meta || st.decisions[visitorId]) return;
    const correct = (choice === "admit") === meta.present;
    st.decisions[visitorId] = choice === "admit" ? "admit" : "refuse";
    st.totalJudgments = Math.min(PROXY_NUM_CAP, st.totalJudgments + 1);
    if (!st.marks.includes(meta.judgedMark)) st.marks.push(meta.judgedMark);
    saveProxy(st);
    const responseEl = $("#proxy-response");
    if (responseEl) responseEl.textContent = correct ? meta.correct : meta.wrong;
    AudioEngine.knock(0.16);
    if (Object.keys(st.decisions).length >= 3) {
      /* 第三人：先给判断反馈一个节拍，再换结算反馈并转场 */
      AutoAdvance.schedule("proxy-admission-step", "proxy-admission", {
        delay: proxyDelay(),
        before: () => settleProxy(),
      });
    } else {
      /* 步进与跨场景转场分 scope，离场由 clearAll 一并清除；
         先排定再重绘：节拍内仍显示刚被判的访客并锁死其按钮 */
      AutoAdvance.schedule("proxy-admission-step", "proxy-admission", {
        delay: proxyDelay(),
        before: () => {
          const el = $("#proxy-response");
          if (el) el.textContent = "";
          paintProxy();
        },
      });
    }
    paintProxy();
  };

  const proxyAdmitBtn = $("#proxy-judge-admit");
  const proxyRefuseBtn = $("#proxy-judge-refuse");
  if (proxyAdmitBtn) proxyAdmitBtn.addEventListener("click", () => judgeProxy("admit"));
  if (proxyRefuseBtn) proxyRefuseBtn.addEventListener("click", () => judgeProxy("refuse"));

  /* 门板第四热点：与门外三热点共用首选锁；干净存档立即可发现，
     第一个被接受的热点或第三次敲门决定去向 */
  const proxyHotspotBtn = $("#hotspot-proxy-admission");
  if (proxyHotspotBtn) proxyHotspotBtn.addEventListener("click", () => {
    if (AutoAdvance.has("threshold")) return;
    markProxyEntry("threshold");
    proxyHotspotBtn.classList.add("touched");
    setTimeout(() => proxyHotspotBtn.classList.remove("touched"), 1200);
    AudioEngine.knock();
    statusLine.textContent = "门缝从里面拉开。值班员把你的影子登记成了代理人。";
    AutoAdvance.schedule("threshold", "proxy-admission", { delay: branchDelay() });
  });

  /* 痕迹页单行：判断总数与最高在场证，保持八张统计卡不变 */
  const paintProxyMemory = () => {
    const memory = $("#proxy-memory");
    if (!memory) return;
    const st = getProxy();
    if (!st.visited) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `门外代审：你替门判断了 ${st.totalJudgments} 次；最高留下 ${st.bestProof} 份在场证。`;
    memory.hidden = false;
  };

  /* ============================================================
     v39 归路核验站：守则其五入口 + 三岔枢纽任选两条 + 每条两判断
     状态独立存 goddead_v39_return_audit，容错坏 JSON；
     recall/misstep/wrongRoute/settled/outcome 必须由合法 decisions 重算；
     不读不写 v28–v38 与主线状态；点击即执行，无确认/继续按钮。
     ============================================================ */
  const AUDIT_KEY = "goddead_v39_return_audit";
  const AUDIT_ENTRIES = ["protocol", "direct"];
  const AUDIT_ROUTES = ["echo", "vein", "confession"];
  const AUDIT_ROUTE_SCENES = ["echo-turn", "vein-turnstile", "confession-locker"];
  const AUDIT_SCENE_ROUTE = { "echo-turn": "echo", "vein-turnstile": "vein", "confession-locker": "confession" };
  /* v29 守卫窄例外：中间档 outcome 放行的既有支线场景 */
  const AUDIT_BRANCH_OUTCOME = { echo: "echoed", vein: "pulsed", confession: "confessed" };
  const AUDIT_MARKS = ["answeredProtocolFive", "auditedEcho", "auditedVein", "auditedConfession"];
  const AUDIT_NUM_CAP = 9999;

  const AUDIT_ROUTE_META = {
    echo: {
      scene: "echo-turn",
      responseEl: "#echo-turn-response",
      cardBtn: "#audit-route-echo",
      selectFeedback: "黄铜台面亮起声波纹。最近的门，反而最远。",
      choices: {
        first: { btn: "#echo-turn-choice-first", correct: true, feedback: "你走进最轻的那声。其余回声晚了一步，没能穿上你的影子。" },
        loud: { btn: "#echo-turn-choice-loud", correct: false, feedback: "最响的回声替你回答。岔廊把它登记成了先到的人。" },
      },
      mark: "auditedEcho",
    },
    vein: {
      scene: "vein-turnstile",
      responseEl: "#vein-turnstile-response",
      cardBtn: "#audit-route-vein",
      selectFeedback: "黄铜台面亮起脉管。闸机开始数你的心跳。",
      choices: {
        pale: { btn: "#vein-turnstile-choice-pale", correct: true, feedback: "停搏给你让出半步。闸机没有来得及记住你的体温。" },
        pulse: { btn: "#vein-turnstile-choice-pulse", correct: false, feedback: "红色脉冲把你夹进管壁。下一次心跳带走了你的方向。" },
      },
      mark: "auditedVein",
    },
    confession: {
      scene: "confession-locker",
      responseEl: "#confession-locker-response",
      cardBtn: "#audit-route-confession",
      selectFeedback: "黄铜台面亮起封蜡。寄存柜替你留出了一格。",
      choices: {
        blank: { btn: "#confession-locker-choice-blank", correct: true, feedback: "空白牌没有认出你。所有柜门同时假装从未打开。" },
        named: { btn: "#confession-locker-choice-named", correct: false, feedback: "你的名字从牌上消失，随即从每只柜子里被念了一遍。" },
      },
      mark: "auditedConfession",
    },
  };
  const AUDIT_OUTCOME_META = {
    verified: { target: "protocol", feedback: "两段路线互相承认。守则允许你继续记得回来。" },
    lost: { target: "return-passage", feedback: "两段路线都指向你身后。回返夹道已经替你转过身。" },
    echoed: { target: "echo", feedback: "错误的回声先一步抵达档案室。它正在等原件签收。" },
    pulsed: { target: "vein", feedback: "闸机把迷路登记成一次维护请求。血管井已为你开盖。" },
    confessed: { target: "confession", feedback: "寄存柜拒绝退还你的名字。忏悔称量室负责核对重量。" },
  };

  const getAudit = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(AUDIT_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const visited = Boolean(raw.visited === true);
    const entry = AUDIT_ENTRIES.includes(raw.entry) ? raw.entry : "direct";
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(AUDIT_NUM_CAP, Math.floor(n));
    };
    const cycle = num(raw.cycle);
    /* order：route 白名单过滤、去重、一轮最多两条 */
    let order = Array.isArray(raw.order)
      ? [...new Set(raw.order.filter((r) => AUDIT_ROUTES.includes(r)))].slice(0, 2)
      : [];
    /* decisions 只接受按 order 形成的连续合法前缀（decision 必须是该 route 的
       两个合法 choice 之一）；off-route 与跳位决策全部丢弃，不得推进计数 */
    const decisions = {};
    if (raw.decisions && typeof raw.decisions === "object" && !Array.isArray(raw.decisions)) {
      for (const r of order) {
        const c = raw.decisions[r];
        if (typeof c === "string" && AUDIT_ROUTE_META[r].choices[c]) decisions[r] = c;
        else break;
      }
    }
    order = order.slice(0, Object.keys(decisions).length);
    const completedCount = order.length;
    /* recall/misstep/wrongRoute/settled/outcome 全部由合法 decisions 重算，不信任存档 */
    let recall = 0;
    let misstep = 0;
    let wrongRoute = "";
    order.forEach((r) => {
      if (AUDIT_ROUTE_META[r].choices[decisions[r]].correct) recall += 1;
      else {
        misstep += 1;
        wrongRoute = r;
      }
    });
    const settled = completedCount >= 2;
    let outcome = "";
    if (settled) {
      if (recall === 2 && misstep === 0) outcome = "verified";
      else if (recall === 0 && misstep === 2) outcome = "lost";
      else outcome = AUDIT_BRANCH_OUTCOME[wrongRoute] || "";
    }
    /* settleDone / arrivalPending 只标记结算副作用与结算转场是否执行，不参与结果派生；
       不足两条合法 decisions 时归一为未完成 */
    const settleDone = settled && raw.settleDone === true;
    const arrivalPending = settled && raw.arrivalPending === true;
    /* pendingRoute 只能是未完成的白名单 route，否则清空 */
    const pendingRoute = !settled && AUDIT_ROUTES.includes(raw.pendingRoute) && !order.includes(raw.pendingRoute)
      ? raw.pendingRoute
      : "";
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => AUDIT_MARKS.includes(m)))].slice(0, AUDIT_MARKS.length)
      : [];
    return {
      visited, entry, cycle, pendingRoute, order, decisions, completedCount,
      recall, misstep, wrongRoute, settled, outcome, settleDone, arrivalPending,
      bestRecall: num(raw.bestRecall),
      totalAudits: num(raw.totalAudits),
      marks,
    };
  };
  const saveAudit = (st) => store.set(AUDIT_KEY, JSON.stringify(st));

  /* 守则其五入口登记（只写 v39 键） */
  const markAuditEntry = (entryId) => {
    const st = getAudit();
    st.entry = AUDIT_ENTRIES.includes(entryId) ? entryId : "direct";
    if (!st.marks.includes("answeredProtocolFive")) st.marks.push("answeredProtocolFive");
    saveAudit(st);
  };

  const syncAuditLink = () => {
    const link = $("#audit-link");
    if (!link) return;
    if (getAudit().visited) link.removeAttribute("hidden");
    else link.setAttribute("hidden", "");
  };

  const markAuditVisited = () => {
    const st = getAudit();
    if (st.visited) return;
    st.visited = true;
    saveAudit(st);
    syncAuditLink();
  };

  const auditDelay = () => reduced ? 300 : 900 + Math.floor(Math.random() * 300);

  const paintAudit = () => {
    const st = getAudit();
    const doneEl = $("#audit-stat-done");
    const recallEl = $("#audit-stat-recall");
    const misstepEl = $("#audit-stat-misstep");
    const bestEl = $("#audit-stat-best");
    if (doneEl) doneEl.textContent = `${st.completedCount}/2`;
    if (recallEl) recallEl.textContent = st.recall;
    if (misstepEl) misstepEl.textContent = st.misstep;
    if (bestEl) bestEl.textContent = st.bestRecall;
    const locked = st.settled || AutoAdvance.has("return-audit") || AutoAdvance.has("return-audit-step");
    AUDIT_ROUTES.forEach((r) => {
      const btn = $(AUDIT_ROUTE_META[r].cardBtn);
      if (!btn) return;
      const done = st.order.includes(r);
      btn.disabled = locked || done;
      btn.setAttribute("aria-pressed", done ? "true" : "false");
    });
  };

  const paintAuditRoute = (route) => {
    const meta = AUDIT_ROUTE_META[route];
    if (!meta) return;
    const st = getAudit();
    const decided = st.decisions[route];
    const locked = st.settled || Boolean(decided) || AutoAdvance.has("return-audit") || AutoAdvance.has("return-audit-step");
    Object.keys(meta.choices).forEach((c) => {
      const btn = $(meta.choices[c].btn);
      if (!btn) return;
      btn.disabled = locked;
      btn.setAttribute("aria-pressed", decided === c ? "true" : "false");
    });
  };

  /* 进入核验站：结算反馈未转场时先补结算节拍（刷新安全）；
     结算与转场都完成后开新 cycle（历史 bestRecall/totalAudits 保留）；
     直接 hash 只记 visited，开启/恢复正常 cycle，不自动选择路线 */
  const enterAudit = () => {
    markAuditVisited();
    const st = getAudit();
    const responseEl = $("#audit-response");
    if (st.settled && st.arrivalPending) {
      /* 结算节拍：第二条路线的即时反馈已在路线场景保留一拍，
         这里换结算反馈再保留一拍，随后自动进入派生目的地 */
      paintAudit();
      const meta = AUDIT_OUTCOME_META[st.outcome];
      if (meta) {
        if (responseEl) responseEl.textContent = meta.feedback;
        AudioEngine.knock(0.16);
        AutoAdvance.schedule("return-audit", meta.target, {
          delay: auditDelay(),
          before: () => {
            const s = getAudit();
            s.arrivalPending = false;
            saveAudit(s);
          },
        });
      }
      return;
    }
    if (st.settled) {
      st.cycle = Math.min(AUDIT_NUM_CAP, st.cycle + 1);
      st.order = [];
      st.decisions = {};
      st.pendingRoute = "";
      st.settleDone = false;
      st.arrivalPending = false;
      saveAudit(st);
    }
    if (responseEl) responseEl.textContent = "";
    paintAudit();
    /* 返回核验站后焦点落到第一个未完成路线卡 */
    if (st.order.length > 0) {
      const next = AUDIT_ROUTES.find((r) => !st.order.includes(r));
      const btn = next && $(AUDIT_ROUTE_META[next].cardBtn);
      if (btn) pendingSceneFocus = btn;
    }
  };

  /* 进入路线场景：恢复/登记 pendingRoute（刷新与直接 hash 安全），不自动判断。
     reload 窗口修复：判断写入后回程/结算 timer 只在内存——若即时反馈拍内刷新，
     该 route 已判断但节拍丢失，这里重播逐字即时反馈并重新排定：
     第一条继续自动回 hub；第二条继续 即时反馈→hub 结算反馈→派生目的地，
     settleAudit 以 settleDone 保证副作用严格一次 */
  const enterAuditRoute = (sceneName) => {
    const route = AUDIT_SCENE_ROUTE[sceneName];
    if (!route) return;
    const st = getAudit();
    if (!st.settled && !st.order.includes(route) && st.pendingRoute !== route) {
      st.pendingRoute = route;
      saveAudit(st);
    }
    const meta = AUDIT_ROUTE_META[route];
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = "";
    paintAuditRoute(route);
    const decided = st.decisions[route];
    if (decided && !st.arrivalPending) {
      const choice = meta.choices[decided];
      if (responseEl && choice) responseEl.textContent = choice.feedback;
      if (st.settled) {
        AutoAdvance.schedule("return-audit-step", "return-audit", {
          delay: auditDelay(),
          before: () => settleAudit(),
        });
      } else {
        AutoAdvance.schedule("return-audit-step", "return-audit", { delay: auditDelay() });
      }
    }
  };

  /* 选择路线：立即反馈并自动进入对应区域；已完成路线 disabled+pressed，
     第一条完成后不替玩家选择第二条 */
  const selectAuditRoute = (route) => {
    const meta = AUDIT_ROUTE_META[route];
    if (!meta) return;
    if (AutoAdvance.has("return-audit") || AutoAdvance.has("return-audit-step")) return;
    const st = getAudit();
    if (st.settled || st.order.includes(route) || st.order.length >= 2) return;
    st.pendingRoute = route;
    saveAudit(st);
    const responseEl = $("#audit-response");
    if (responseEl) responseEl.textContent = meta.selectFeedback;
    AudioEngine.knock(0.12);
    paintAudit();
    AutoAdvance.schedule("return-audit-step", meta.scene, { delay: auditDelay() });
  };

  AUDIT_ROUTES.forEach((route) => {
    const btn = $(AUDIT_ROUTE_META[route].cardBtn);
    if (btn) btn.addEventListener("click", () => selectAuditRoute(route));
  });

  /* 两条路线完成后自动结算一次；settleDone 为副作用完成标记，不参与派生 */
  const settleAudit = () => {
    const st = getAudit();
    if (!st.settled || st.settleDone) return;
    st.settleDone = true;
    st.arrivalPending = true;
    st.bestRecall = Math.max(st.bestRecall, st.recall);
    st.totalAudits = Math.min(AUDIT_NUM_CAP, st.totalAudits + 1);
    saveAudit(st);
  };

  /* 每条路线的两个判断：第一次被接受即锁定该区域两按钮（同节拍竞争只记一次）；
     即时反馈一拍后：第一条自动回核验站，第二条回核验站换结算反馈再自动转场。
     守卫：只接受当前场景对应且 pendingRoute 合法的 route——
     隐藏/off-route 按钮的程序化竞争不得推进 order/decisions */
  const judgeAudit = (route, choiceKey) => {
    const meta = AUDIT_ROUTE_META[route];
    const choice = meta && meta.choices[choiceKey];
    if (!choice) return;
    if (AutoAdvance.has("return-audit") || AutoAdvance.has("return-audit-step")) return;
    const st = getAudit();
    if (st.settled || st.decisions[route] || st.order.length >= 2) return;
    if (currentScene !== meta.scene || st.pendingRoute !== route) return;
    st.decisions[route] = choiceKey;
    st.order.push(route);
    st.pendingRoute = "";
    if (!st.marks.includes(meta.mark)) st.marks.push(meta.mark);
    saveAudit(st);
    /* v53：已被 v39 接受的判断在此沉淀信念计分（只写 v53 键） */
    recordBeliefChoice(route, choiceKey);
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = choice.feedback;
    AudioEngine.knock(0.16);
    paintAuditRoute(route);
    if (st.order.length >= 2) {
      /* 第二条：先保留即时反馈一拍；到核验站由 enterAudit 换结算反馈并转场 */
      AutoAdvance.schedule("return-audit-step", "return-audit", {
        delay: auditDelay(),
        before: () => settleAudit(),
      });
    } else {
      /* 第一条：即时反馈一拍后自动回核验站 */
      AutoAdvance.schedule("return-audit-step", "return-audit", { delay: auditDelay() });
    }
  };

  AUDIT_ROUTES.forEach((route) => {
    const meta = AUDIT_ROUTE_META[route];
    Object.keys(meta.choices).forEach((choiceKey) => {
      const btn = $(meta.choices[choiceKey].btn);
      if (btn) btn.addEventListener("click", () => judgeAudit(route, choiceKey));
    });
  });

  /* 痕迹页单行：完成轮数与最佳归路，保持八张统计卡不变 */
  const paintAuditMemory = () => {
    const memory = $("#audit-memory");
    if (!memory) return;
    const st = getAudit();
    if (!st.visited) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `归路核验：完成 ${st.totalAudits} 轮核验；最佳归路 ${st.bestRecall}。`;
    memory.hidden = false;
  };

  /* ============================================================
     v53 归路信念：跨轮选择沉淀守则/感官信任，路线图三态变异 +
     变异阈值第三热点 + 矛盾翻转核验牌
     独立容错状态键 BELIEF_KEY（v53 唯一存储键），容错坏 JSON；
     globalOfficial/globalSensory/variant/pendingTarget 全部派生重算；
     只观察 v39 已接受的判断，从不读写 v39 key 与其它模块状态。
     ============================================================ */
  const BELIEF_KEY = "goddead_v53_route_belief";
  const BELIEF_ROUTES = ["echo", "vein", "confession"];
  const BELIEF_SIDES = ["official", "sensory"];
  const BELIEF_NUM_CAP = 9999;
  const BELIEF_HISTORY_CAP = 16;
  /* 七条信念分支落点：camelCase key → 既有场景名 */
  const BELIEF_BRANCH_SCENE = {
    counterKnockGallery: "counter-knock-gallery",
    echoArchive: "echo",
    belllessWard: "bellless-ward",
    veinWell: "vein",
    blankNameCloakroom: "blank-name-cloakroom",
    confessionWeighing: "confession",
    protocolDrift: "protocol-drift",
  };
  const BELIEF_BRANCH_KEYS = Object.keys(BELIEF_BRANCH_SCENE);
  /* v29 三场景 → 对应信念分支 key（守卫窄例外用） */
  const BELIEF_SCENE_BRANCH = { echo: "echoArchive", vein: "veinWell", confession: "confessionWeighing" };
  /* 阈值机关落点：路线 × 变异态 → 既有分支场景 */
  const BELIEF_THRESHOLD_TARGET = {
    echo: { official: "counter-knock-gallery", sensory: "echo" },
    vein: { official: "bellless-ward", sensory: "vein" },
    confession: { official: "blank-name-cloakroom", sensory: "confession" },
  };
  const BELIEF_ROUTE_META = {
    echo: {
      scene: "echo-turn",
      responseEl: "#echo-turn-response",
      thresholdBtn: "#echo-turn-belief-threshold",
      baseImg: "assets/return-audit-echo.webp",
      baseFigLabel: "同一扇黑门沿弧形回廊重复出现，黄铜听音管在每扇门间穿行，最近的门最暗，地面波纹由远到近依次扩散",
      choiceSide: { first: "official", loud: "sensory" },
      official: {
        img: "assets/v53-echo-official-belief.webp",
        figLabel: "回声岔廊守则变异：最近的门透出金边，廊心升起一座嵌铜盘的黑石台",
        branch: "counterKnockGallery",
        title: "转动廊心铜盘",
        short: "廊心铜盘",
        hint: "守则说，回声应该排队",
        feedback: "铜盘转了一格。所有回声同时安静下来，像在等点名。",
      },
      sensory: {
        img: "assets/v53-echo-sensory-belief.webp",
        figLabel: "回声岔廊感官变异：右墙贴上巨型喇叭，红色声纹沿墙扩散",
        branch: "echoArchive",
        title: "凑近台座的喇叭",
        short: "台座喇叭",
        hint: "它一直在学你的呼吸",
        feedback: "喇叭里没有声音。只有你自己的吸气声，早了半拍。",
      },
    },
    vein: {
      scene: "vein-turnstile",
      responseEl: "#vein-turnstile-response",
      thresholdBtn: "#vein-turnstile-belief-threshold",
      baseImg: "assets/return-audit-vein.webp",
      baseFigLabel: "黑石检票厅，粗大的暗红脉管穿过黄铜闸机，三盏红灯随脉搏涨落，一次苍白的停搏在闸口留下短暂空隙",
      choiceSide: { pale: "official", pulse: "sensory" },
      official: {
        img: "assets/v53-vein-official-belief.webp",
        figLabel: "检票闸守则变异：闸后缝隙更加苍白，中央表盘停在零",
        branch: "belllessWard",
        title: "校准苍白表盘",
        short: "苍白表盘",
        hint: "停搏的读数应该归零",
        feedback: "指针归零。闸机第一次承认自己也会累。",
      },
      sensory: {
        img: "assets/v53-vein-sensory-belief.webp",
        figLabel: "检票闸感官变异：中央表盘涨成暗红，右侧脉管红得发亮",
        branch: "veinWell",
        title: "贴上红色表盘",
        short: "红色表盘",
        hint: "听它跳得多急",
        feedback: "表盘里不是血。是很多只贴上来听过的耳朵。",
      },
    },
    confession: {
      scene: "confession-locker",
      responseEl: "#confession-locker-response",
      thresholdBtn: "#confession-locker-belief-threshold",
      baseImg: "assets/return-audit-confession.webp",
      baseFigLabel: "狭长黑石寄存室，两侧黄铜小柜与黑蜡封条，中央台上一枚空白寄存牌，旁边一枚牌子像刚被擦掉名字，柜门缝里纸页轻微起伏",
      choiceSide: { blank: "official", named: "sensory" },
      official: {
        img: "assets/v53-confession-official-belief.webp",
        figLabel: "寄存所守则变异：中央台上立起空白铜牌，两枚寄存牌并排静放",
        branch: "blankNameCloakroom",
        title: "核对空白铜牌",
        short: "空白铜牌",
        hint: "无名的牌子才是登记过的",
        feedback: "铜牌背面有一枚验收章：此名未使用。",
      },
      sensory: {
        img: "assets/v53-confession-sensory-belief.webp",
        figLabel: "寄存所感官变异：中央升起一台忏悔秤，右侧寄存牌烧出红色裂纹",
        branch: "confessionWeighing",
        title: "坐上忏悔秤",
        short: "忏悔秤",
        hint: "它记得每一个名字的重量",
        feedback: "秤盘下沉。你的忏悔被称了两遍，两遍不一样重。",
      },
    },
  };
  /* 翻转核验牌：contradiction >= 2 时出现，只去守则漂移，不触碰 v39 进度 */
  const BELIEF_FLIP = {
    btn: "#audit-belief-flip",
    branch: "protocolDrift",
    target: "protocol-drift",
    feedback: "铜牌翻面。守则自己也开始漂移。",
  };

  /* 每路变异态：严格占优且 >= 2 才变异，平局回中性 */
  const beliefVariantOf = (routeSt) => {
    if (routeSt.official >= 2 && routeSt.official > routeSt.sensory) return "official";
    if (routeSt.sensory >= 2 && routeSt.sensory > routeSt.official) return "sensory";
    return "neutral";
  };

  const getBelief = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(BELIEF_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(BELIEF_NUM_CAP, Math.floor(n));
    };
    /* routes：白名单三路，数值封顶，lastChoice 必须是该路合法判断否则清空 */
    const routes = {};
    BELIEF_ROUTES.forEach((r) => {
      const rr = raw.routes && typeof raw.routes[r] === "object" && !Array.isArray(raw.routes[r]) ? raw.routes[r] : {};
      routes[r] = {
        official: num(rr.official),
        sensory: num(rr.sensory),
        lastChoice: BELIEF_ROUTE_META[r].choiceSide[rr.lastChoice] ? rr.lastChoice : "",
      };
    });
    /* branches：白名单七个 key，visits/actions 同样封顶 */
    const branches = {};
    BELIEF_BRANCH_KEYS.forEach((k) => {
      const bb = raw.branches && typeof raw.branches[k] === "object" && !Array.isArray(raw.branches[k]) ? raw.branches[k] : {};
      branches[k] = { visits: num(bb.visits), actions: num(bb.actions) };
    });
    /* pending 仅两种严格形状，逐字段校验（kind/route/side/target/feedback 全部
       白名单 + 逐字反馈重算），任一不符 → null（伪造 pending 归一） */
    let pending = null;
    if (raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const p = raw.pending;
      if (p.kind === "threshold" && BELIEF_ROUTES.includes(p.route) && BELIEF_SIDES.includes(p.side)) {
        const meta = BELIEF_ROUTE_META[p.route][p.side];
        const target = BELIEF_THRESHOLD_TARGET[p.route][p.side];
        if (p.target === target && p.feedback === meta.feedback) {
          pending = { kind: "threshold", route: p.route, side: p.side, target, feedback: meta.feedback };
        }
      } else if (p.kind === "drift" && p.target === BELIEF_FLIP.target && p.feedback === BELIEF_FLIP.feedback) {
        pending = { kind: "drift", target: BELIEF_FLIP.target, feedback: BELIEF_FLIP.feedback };
      }
    }
    /* history 有界：仅保留白名单形状条目，最多 16 条 */
    let history = [];
    if (Array.isArray(raw.history)) {
      for (const h of raw.history) {
        if (!h || typeof h !== "object" || Array.isArray(h)) continue;
        if (h.type === "choice" && BELIEF_ROUTES.includes(h.route) && BELIEF_ROUTE_META[h.route].choiceSide[h.choice]) {
          history.push({ type: "choice", route: h.route, choice: h.choice });
        } else if (h.type === "threshold" && BELIEF_ROUTES.includes(h.route) && BELIEF_SIDES.includes(h.side)) {
          history.push({ type: "threshold", route: h.route, side: h.side });
        } else if (h.type === "drift") {
          history.push({ type: "drift" });
        }
      }
    }
    history = history.slice(-BELIEF_HISTORY_CAP);
    /* 派生：总分永远从三路重算（伪造总分归一），变异态与 pendingTarget 不信任存档 */
    let globalOfficial = 0;
    let globalSensory = 0;
    const variants = {};
    BELIEF_ROUTES.forEach((r) => {
      globalOfficial += routes[r].official;
      globalSensory += routes[r].sensory;
      variants[r] = beliefVariantOf(routes[r]);
    });
    return {
      routes,
      contradiction: num(raw.contradiction),
      branches,
      pending,
      pendingTarget: pending ? pending.target : "",
      history,
      globalOfficial,
      globalSensory,
      variants,
    };
  };
  /* 只持久化 canonical 五部分：派生的 globalOfficial/globalSensory/variants/
     pendingTarget 永不落盘（永远重算），history 裁到 ≤16 再存 */
  const saveBelief = (st) => store.set(BELIEF_KEY, JSON.stringify({
    routes: st.routes,
    contradiction: st.contradiction,
    branches: st.branches,
    pending: st.pending,
    history: st.history.slice(-BELIEF_HISTORY_CAP),
  }));

  /* 有任何计分、矛盾或分支动作/访问即视为信念活动（目录与记忆行恢复） */
  const beliefActive = (st) =>
    st.globalOfficial > 0 || st.globalSensory > 0 || st.contradiction > 0
    || BELIEF_BRANCH_KEYS.some((k) => st.branches[k].visits > 0 || st.branches[k].actions > 0);

  /* 计分：只挂在 v39 judgeAudit 接受点之后（first-lock / live-scene /
     pendingRoute 全部通过、order/decisions 已持久化才调用），重复点击与
     合成点击被 v39 守卫挡在钩子之前 → 零重复计分；只写 v53 键 */
  const recordBeliefChoice = (route, choiceKey) => {
    const meta = BELIEF_ROUTE_META[route];
    const side = meta && meta.choiceSide[choiceKey];
    if (!side) return;
    const st = getBelief();
    const r = st.routes[route];
    r[side] = Math.min(BELIEF_NUM_CAP, r[side] + 1);
    if (r.lastChoice && r.lastChoice !== choiceKey) st.contradiction = Math.min(BELIEF_NUM_CAP, st.contradiction + 1);
    r.lastChoice = choiceKey;
    st.history.push({ type: "choice", route, choice: choiceKey });
    saveBelief(st);
    syncBeliefRoute(route);
    paintBelief();
  };

  /* 变异图原子切换：单 img src、figure aria-label、修饰类与阈值热点同拍完成；
     中性（含平局）回 v39 原图，阈值热点回 hidden */
  const syncBeliefRoute = (route) => {
    const meta = BELIEF_ROUTE_META[route];
    if (!meta) return;
    const st = getBelief();
    const variant = st.variants[route];
    const side = variant === "neutral" ? "" : variant;
    const section = $(`#scene-${meta.scene}`);
    if (!section) return;
    const figure = section.querySelector("figure.branch-figure");
    const img = figure && figure.querySelector(".branch-img");
    const wantSrc = side ? meta[side].img : meta.baseImg;
    setSceneImageSrc(img, wantSrc);
    if (figure) {
      figure.setAttribute("aria-label", side ? meta[side].figLabel : meta.baseFigLabel);
      figure.classList.toggle("belief-variant-official", variant === "official");
      figure.classList.toggle("belief-variant-sensory", variant === "sensory");
    }
    const btn = $(meta.thresholdBtn);
    if (btn) {
      if (side) {
        const titleEl = btn.querySelector(".bb-title");
        const shortEl = btn.querySelector(".bb-short");
        const hintEl = btn.querySelector(".bb-hint");
        if (titleEl) titleEl.textContent = meta[side].title;
        if (shortEl) shortEl.textContent = meta[side].short;
        if (hintEl) hintEl.textContent = meta[side].hint;
        btn.removeAttribute("hidden");
        btn.setAttribute("aria-pressed", "false");
      } else {
        btn.setAttribute("hidden", "");
        btn.setAttribute("aria-pressed", "false");
      }
    }
  };

  /* 枢纽重绘：三紧凑统计（派生总分）+ 翻转核验牌显隐（contradiction >= 2） */
  const paintBelief = () => {
    const st = getBelief();
    const officialEl = $("#belief-stat-official");
    const sensoryEl = $("#belief-stat-sensory");
    const contraEl = $("#belief-stat-contradiction");
    if (officialEl) officialEl.textContent = st.globalOfficial;
    if (sensoryEl) sensoryEl.textContent = st.globalSensory;
    if (contraEl) contraEl.textContent = st.contradiction;
    const flip = $(BELIEF_FLIP.btn);
    if (flip) {
      if (st.contradiction >= 2) flip.removeAttribute("hidden");
      else { flip.setAttribute("hidden", ""); flip.setAttribute("aria-pressed", "false"); }
    }
  };

  /* 阈值机关：live scene + 实时重算变异态非中性 + 与 v39 共享 first-lock；
     接受后只写 v53（branch actions+1、history、严格 pending），不算 v39
     路线判断、不污染 order/decisions/settle；逐字反馈一拍后自动转场，
     before 里清 pending、首访 visits+1（重复进入不重复首访计数） */
  const chooseBeliefThreshold = (route) => {
    const meta = BELIEF_ROUTE_META[route];
    if (!meta) return;
    if (currentScene !== meta.scene) return;
    const st = getBelief();
    const side = st.variants[route];
    if (side === "neutral") return;
    if (AutoAdvance.has("return-audit") || AutoAdvance.has("return-audit-step")) return;
    const target = BELIEF_THRESHOLD_TARGET[route][side];
    const branch = meta[side].branch;
    st.branches[branch].actions = Math.min(BELIEF_NUM_CAP, st.branches[branch].actions + 1);
    st.history.push({ type: "threshold", route, side });
    st.pending = { kind: "threshold", route, side, target, feedback: meta[side].feedback };
    saveBelief(st);
    const btn = $(meta.thresholdBtn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = meta[side].feedback;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule("return-audit-step", target, {
      delay: auditDelay(),
      before: () => {
        const s = getBelief();
        if (s.pending && s.pending.kind === "threshold" && s.pending.route === route && s.pending.side === side) {
          s.pending = null;
          if (s.branches[branch].visits === 0) s.branches[branch].visits = 1;
          saveBelief(s);
        }
        syncBeliefLink();
        paintBeliefMemory();
      },
    });
  };

  /* 翻转核验牌：live scene = 核验站 + 实时重算 contradiction >= 2 + 共享
     first-lock；接受后只记 v53（protocolDrift actions+1、history、严格
     pending），v39 进度不变，回来后核验继续 */
  const chooseBeliefFlip = () => {
    if (currentScene !== "return-audit") return;
    const st = getBelief();
    if (st.contradiction < 2) return;
    if (AutoAdvance.has("return-audit") || AutoAdvance.has("return-audit-step")) return;
    st.branches.protocolDrift.actions = Math.min(BELIEF_NUM_CAP, st.branches.protocolDrift.actions + 1);
    st.history.push({ type: "drift" });
    st.pending = { kind: "drift", target: BELIEF_FLIP.target, feedback: BELIEF_FLIP.feedback };
    saveBelief(st);
    const btn = $(BELIEF_FLIP.btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $("#audit-response");
    if (responseEl) responseEl.textContent = BELIEF_FLIP.feedback;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule("return-audit", BELIEF_FLIP.target, {
      delay: auditDelay(),
      before: () => {
        const s = getBelief();
        if (s.pending && s.pending.kind === "drift") {
          s.pending = null;
          if (s.branches.protocolDrift.visits === 0) s.branches.protocolDrift.visits = 1;
          saveBelief(s);
        }
        syncBeliefLink();
        paintBeliefMemory();
      },
    });
  };

  /* reload 节拍恢复：合法 pending 属于当前场景时重播逐字反馈并精确重挂
     一次转场（actions 在接受时已计，这里只清 pending 与首访计数） */
  const replayBeliefPending = (sceneName) => {
    const st = getBelief();
    const p = st.pending;
    if (!p) return;
    if (p.kind === "threshold") {
      const meta = BELIEF_ROUTE_META[p.route];
      if (!meta || meta.scene !== sceneName) return;
      const responseEl = $(meta.responseEl);
      if (responseEl) responseEl.textContent = p.feedback;
      const branch = meta[p.side].branch;
      AutoAdvance.schedule("return-audit-step", p.target, {
        delay: auditDelay(),
        before: () => {
          const s = getBelief();
          if (s.pending && s.pending.kind === "threshold") {
            s.pending = null;
            if (s.branches[branch].visits === 0) s.branches[branch].visits = 1;
            saveBelief(s);
          }
          syncBeliefLink();
          paintBeliefMemory();
        },
      });
      return;
    }
    if (p.kind === "drift" && sceneName === "return-audit") {
      const responseEl = $("#audit-response");
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule("return-audit", p.target, {
        delay: auditDelay(),
        before: () => {
          const s = getBelief();
          if (s.pending && s.pending.kind === "drift") {
            s.pending = null;
            if (s.branches.protocolDrift.visits === 0) s.branches.protocolDrift.visits = 1;
            saveBelief(s);
          }
          syncBeliefLink();
          paintBeliefMemory();
        },
      });
    }
  };

  /* 目录 01τ½：有任何计分、矛盾或分支动作/访问即恢复显示 */
  const syncBeliefLink = () => {
    const link = $("#belief-link");
    if (!link) return;
    if (beliefActive(getBelief())) link.removeAttribute("hidden");
    else link.setAttribute("hidden", "");
  };

  /* 痕迹页单行：信念三值，保持八张统计卡不变 */
  const paintBeliefMemory = () => {
    const memory = $("#belief-memory");
    if (!memory) return;
    const st = getBelief();
    if (!beliefActive(st)) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `归路信念：守则信任 ${st.globalOfficial}，感官诱信 ${st.globalSensory}，自相矛盾 ${st.contradiction}。`;
    memory.hidden = false;
  };

  BELIEF_ROUTES.forEach((route) => {
    const btn = $(BELIEF_ROUTE_META[route].thresholdBtn);
    if (btn) btn.addEventListener("click", () => chooseBeliefThreshold(route));
    /* 六张变异图随场景预载，阈值切换无闪烁 */
    BELIEF_SIDES.forEach((side) => {
      prefetchWithScene(BELIEF_ROUTE_META[route].scene, BELIEF_ROUTE_META[route][side].img);
    });
  });
  const beliefFlipBtn = $(BELIEF_FLIP.btn);
  if (beliefFlipBtn) beliefFlipBtn.addEventListener("click", chooseBeliefFlip);
  BELIEF_ROUTES.forEach(syncBeliefRoute);
  paintBelief();

  /* ============================================================
     v54 迫近回访：v29 三房共同记账、迫近异动与第四热点九分流
     独立容错状态键 PRESSURE_KEY（v54 唯一存储键），与 v29/v30 完全独立；
     只持久化 canonical 五部分（scores/choices/breaches/pending/history），
     total/approach 等派生值只重算不落盘；坏 JSON/数组/错型/负数/浮点/
     超大数/未知键/伪造 pending 全部规范化。
     ============================================================ */
  const PRESSURE_KEY = "goddead_v54_return_pressure";
  const PRESSURE_SCENES = ["echo", "vein", "confession"];
  const PRESSURE_CHOICES = {
    echo: ["knock", "steps", "bell"],
    vein: ["down", "up", "isolate"],
    confession: ["door", "seven", "refuse"],
  };
  const PRESSURE_NUM_CAP = 9999;
  const PRESSURE_HISTORY_CAP = 16;
  const PRESSURE_APPROACH_IMG = 3; /* 迫近 >= 3：三房同步切到 v54 异动图 */
  const PRESSURE_BREACH_MIN = 6;   /* 迫近 >= 6：第四热点可用，一次消费 6 点 */
  const PRESSURE_BASE_IMG = {
    echo: "assets/echo-archive.webp",
    vein: "assets/vein-maintenance-well.webp",
    confession: "assets/confession-weighing-room.webp",
  };
  const PRESSURE_IMG = {
    echo: "assets/v54-echo-approach.webp",
    vein: "assets/v54-vein-approach.webp",
    confession: "assets/v54-confession-approach.webp",
  };
  const PRESSURE_BASE_FIGLABEL = {
    echo: "三只悬吊的旧听筒与桌面上三口黄铜听井",
    vein: "环形井室与三只黄铜阀门控制器",
    confession: "一架黄铜天平，左盘放着信封，中盘盛着灰烬，右盘空着",
  };
  const PRESSURE_FIGLABEL = {
    echo: "回声档案室迫近异动：三口听井的铜圈发红，中央架上横着一只蜡封的断线听筒",
    vein: "维修井迫近异动：中央脉管涨红，顶部过压表的指针越过最后一道刻度",
    confession: "称量室迫近异动：横梁左端渗出红蜡，左上悬着一只半开的迫近抽屉",
  };
  /* 第四热点九分流：房间 × 该房合法 v29 lastChoice → 目标与逐字反馈 */
  const PRESSURE_BREACH = {
    echo: {
      btn: "#echo-breach-receiver",
      knock: { target: "counter-knock-gallery", feedback: "蜡封在听筒里裂开。门外那三记敲声被倒送进回敲廊。" },
      steps: { target: "lagging-shadow-cloister", feedback: "听筒没有线，脚步却从滞后的影子里接通。" },
      bell: { target: "minute-before-archive", feedback: "03:17 从听筒里提前了一分钟。档案井已经在等。" },
    },
    vein: {
      btn: "#vein-breach-gauge",
      down: { target: "seeping-records", feedback: "红柱顺流坠下，把井水压进渗水档案池。" },
      up: { target: "reverse-laundry", feedback: "指针倒着越过零。逆照洗衣房开始回流。" },
      isolate: { target: "bellless-ward", feedback: "玻璃里只剩一段无声脉搏。无铃病房替它开门。" },
    },
    confession: {
      btn: "#confession-breach-drawer",
      door: { target: "blank-receipt-press", feedback: "抽屉退回一张空白收据，敲门被压成未填项目。" },
      seven: { target: "protocol-drift", feedback: "第七条从抽屉背面翻出，守则的字开始漂移。" },
      refuse: { target: "blank-name-cloakroom", feedback: "黑色名带没有写字，却替你寄存了拒绝。" },
    },
  };

  const getPressure = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(PRESSURE_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(PRESSURE_NUM_CAP, Math.floor(n));
    };
    /* scores/choices/breaches：白名单重建，未知键一律丢弃 */
    const scores = {};
    const choices = {};
    const breaches = {};
    PRESSURE_SCENES.forEach((r) => {
      scores[r] = num(raw.scores && raw.scores[r]);
      breaches[r] = num(raw.breaches && raw.breaches[r]);
      const rc = raw.choices && typeof raw.choices[r] === "object" && !Array.isArray(raw.choices[r]) ? raw.choices[r] : {};
      choices[r] = {};
      PRESSURE_CHOICES[r].forEach((c) => { choices[r][c] = num(rc[c]); });
    });
    const total = PRESSURE_SCENES.reduce((n, r) => n + scores[r], 0);
    const breachTotal = PRESSURE_SCENES.reduce((n, r) => n + breaches[r], 0);
    /* history 有界：仅保留白名单形状条目，最多 16 条（先解析，
       pending 的「刚消费过」跨字段证明依赖 canonical history） */
    let history = [];
    if (Array.isArray(raw.history)) {
      for (const h of raw.history) {
        if (!h || typeof h !== "object" || Array.isArray(h)) continue;
        if ((h.type === "choice" || h.type === "breach") && PRESSURE_SCENES.includes(h.room) && PRESSURE_CHOICES[h.room].includes(h.choice)) {
          history.push({ type: h.type, room: h.room, choice: h.choice });
        }
      }
    }
    history = history.slice(-PRESSURE_HISTORY_CAP);
    /* pending 严格白名单：只接受恰好 {room,choice,target,feedback} 四键（额外键即伪造），
       target 与逐字反馈由九分流映射重算；另须同时具备「确实刚消费过」的跨字段证据：
       breachTotal >= 1 且该房 breaches >= 1（从未消费过的干净伪存档直接拒绝）、
       total >= 6 * breachTotal（六点曾完整存在——存盘后 approach 已下降，
       不得再要求 approach>=6）、且 canonical history 最后一项正是同 room/choice 的
       breach（接受第四热点时才追加，转场前不会有任何新事件）。任一不符 → null */
    let pending = null;
    if (raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const p = raw.pending;
      const last = history.length ? history[history.length - 1] : null;
      if (Object.keys(p).sort().join(",") === "choice,feedback,room,target"
        && PRESSURE_SCENES.includes(p.room) && PRESSURE_CHOICES[p.room].includes(p.choice)
        && breachTotal >= 1 && breaches[p.room] >= 1 && total >= 6 * breachTotal
        && last && last.type === "breach" && last.room === p.room && last.choice === p.choice) {
        const meta = PRESSURE_BREACH[p.room][p.choice];
        if (p.target === meta.target && p.feedback === meta.feedback) {
          pending = { room: p.room, choice: p.choice, target: meta.target, feedback: meta.feedback };
        }
      }
    }
    /* 派生：total / approach 只重算，不落盘 */
    const approach = Math.max(0, total - 6 * breachTotal);
    return { scores, choices, breaches, pending, history, total, breachTotal, approach };
  };
  /* 只持久化 canonical 五部分；派生字段永不落盘，history 先裁后存 */
  const savePressure = (st) => store.set(PRESSURE_KEY, JSON.stringify({
    scores: st.scores,
    choices: st.choices,
    breaches: st.breaches,
    pending: st.pending,
    history: st.history.slice(-PRESSURE_HISTORY_CAP),
  }));

  /* 有任何计分或异动即视为迫近活动（目录与记忆行恢复） */
  const pressureActive = (st) => st.total > 0 || st.breachTotal > 0;

  /* v29 旧选择被合法接受后计分：只挂在 chooseBranch 守卫之后，
     合成/离场/连点/锁定调用都被挡在钩子之前 → 零重复累计；只写 v54 键 */
  const recordPressureChoice = (room, choice) => {
    if (!PRESSURE_SCENES.includes(room) || !PRESSURE_CHOICES[room].includes(choice)) return;
    const st = getPressure();
    st.scores[room] = Math.min(PRESSURE_NUM_CAP, st.scores[room] + 1);
    st.choices[room][choice] = Math.min(PRESSURE_NUM_CAP, st.choices[room][choice] + 1);
    st.history.push({ type: "choice", room, choice });
    savePressure(st);
    syncPressureRoom(room);
    paintPressure();
  };

  /* 房间重绘：迫近 >= 3 切 v54 异动图（单 img 原子切换 + aria-label）；
     第四热点仅在 迫近 >= 6 且该房有合法 v29 lastChoice 时显示可聚焦 */
  const syncPressureRoom = (room) => {
    if (!PRESSURE_SCENES.includes(room)) return;
    const st = getPressure();
    const section = $(`#scene-${room}`);
    if (!section) return;
    const figure = section.querySelector("figure.branch-figure");
    const img = figure && figure.querySelector(".branch-img");
    const moved = st.approach >= PRESSURE_APPROACH_IMG;
    const wantSrc = moved ? PRESSURE_IMG[room] : PRESSURE_BASE_IMG[room];
    setSceneImageSrc(img, wantSrc);
    if (figure) figure.setAttribute("aria-label", moved ? PRESSURE_FIGLABEL[room] : PRESSURE_BASE_FIGLABEL[room]);
    const lastChoice = getBranches().lastChoice[room];
    const armed = st.approach >= PRESSURE_BREACH_MIN && !!PRESSURE_BREACH[room][lastChoice];
    const btn = $(PRESSURE_BREACH[room].btn);
    if (btn) {
      if (armed) btn.removeAttribute("hidden");
      else { btn.setAttribute("hidden", ""); btn.setAttribute("aria-pressed", "false"); }
    }
  };

  /* 统计签四处读数同步（三房各一块 class 挂钩） */
  const paintPressure = () => {
    const st = getPressure();
    $$("[data-pressure-echo]").forEach((el) => { el.textContent = st.scores.echo; });
    $$("[data-pressure-vein]").forEach((el) => { el.textContent = st.scores.vein; });
    $$("[data-pressure-confession]").forEach((el) => { el.textContent = st.scores.confession; });
    $$("[data-pressure-approach]").forEach((el) => { el.textContent = `${Math.min(PRESSURE_BREACH_MIN, st.approach)}/${PRESSURE_BREACH_MIN}`; });
  };

  /* 第四热点：live scene + 与 v29 共享 first-lock + 点击前 approach>=6 +
     该房合法 v29 lastChoice；接受即 breach+1（等价消耗 6 点）、history、
     严格 pending，逐字反馈一拍后自动去映射目标；before 里只清 pending，
     重复进入/刷新/伪造不得二次消费或二次转场 */
  const choosePressureBreach = (room) => {
    if (!PRESSURE_SCENES.includes(room)) return;
    if (currentScene !== room) return;
    if (AutoAdvance.has(room)) return;
    const st = getPressure();
    if (st.approach < PRESSURE_BREACH_MIN) return;
    const lastChoice = getBranches().lastChoice[room];
    const meta = lastChoice ? PRESSURE_BREACH[room][lastChoice] : null;
    if (!meta) return;
    st.breaches[room] = Math.min(PRESSURE_NUM_CAP, st.breaches[room] + 1);
    st.history.push({ type: "breach", room, choice: lastChoice });
    st.pending = { room, choice: lastChoice, target: meta.target, feedback: meta.feedback };
    savePressure(st);
    const btn = $(PRESSURE_BREACH[room].btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $(BRANCH_META[room].responseEl);
    if (responseEl) responseEl.textContent = meta.feedback;
    AudioEngine.knock(0.16);
    paintPressure();
    AutoAdvance.schedule(room, meta.target, {
      delay: branchDelay(),
      before: () => {
        const s = getPressure();
        if (s.pending && s.pending.room === room) {
          s.pending = null;
          savePressure(s);
        }
        syncPressureLink();
        paintPressureMemory();
      },
    });
  };

  /* reload 节拍恢复：合法 pending 属于当前房间时重播逐字反馈并精确重挂
     一次转场（breach 在接受时已计，这里只清 pending，不再校验 approach） */
  const replayPressurePending = (sceneName) => {
    const st = getPressure();
    const p = st.pending;
    if (!p || p.room !== sceneName) return;
    const responseEl = $(BRANCH_META[p.room].responseEl);
    if (responseEl) responseEl.textContent = p.feedback;
    AutoAdvance.schedule(p.room, p.target, {
      delay: branchDelay(),
      before: () => {
        const s = getPressure();
        if (s.pending && s.pending.room === p.room) {
          s.pending = null;
          savePressure(s);
        }
        syncPressureLink();
        paintPressureMemory();
      },
    });
  };

  /* 目录 01δ½：有任何计分或异动即恢复显示 */
  const syncPressureLink = () => {
    const link = $("#pressure-link");
    if (!link) return;
    if (pressureActive(getPressure())) link.removeAttribute("hidden");
    else link.setAttribute("hidden", "");
  };

  /* 痕迹页单行：四项读数 + 异动次数，保持八张统计卡不变 */
  const paintPressureMemory = () => {
    const memory = $("#pressure-memory");
    if (!memory) return;
    const st = getPressure();
    if (!pressureActive(st)) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `迫近回访：回声累计 ${st.scores.echo}，脉压 ${st.scores.vein}，名重 ${st.scores.confession}；房间在你不看的时候移动过 ${st.breachTotal} 次。`;
    memory.hidden = false;
  };

  PRESSURE_SCENES.forEach((room) => {
    const btn = $(PRESSURE_BREACH[room].btn);
    if (btn) btn.addEventListener("click", () => choosePressureBreach(room));
    /* 三张异动图随场景预载，阈值切换无闪烁 */
    prefetchWithScene(room, PRESSURE_IMG[room]);
    syncPressureRoom(room);
  });
  paintPressure();

  /* ============================================================
     v55 失常交班：v35 三房巡检循环 + 三个异常后室
     独立容错状态键 ANOMALY_KEY（v55 唯一存储键），只持久化白名单
     canonical 字段；verified/falseReports/missed/streak 是累计 canonical
     计数器，归一后照常落盘，只有 contamination 与 pendingTarget 派生
     重算不落盘；坏 JSON/数组/错型/负数/浮点/超大数/未知键/伪造
     pending 全部归一。v35 signal/debt 的增减是设计内计分
     （cap 已按新理论上限安全扩到 15/14），其余旧 key 不读写。
     ============================================================ */
  const ANOMALY_KEY = "goddead_v55_floor_anomaly";
  const ANOMALY_ROOMS = ["ward", "records", "laundry"];
  const ANOMALY_ROOM_SCENE = { ward: "bellless-ward", records: "seeping-records", laundry: "reverse-laundry" };
  const ANOMALY_SCENE_ROOM = { "bellless-ward": "ward", "seeping-records": "records", "reverse-laundry": "laundry" };
  const ANOMALY_BACKROOMS = ["underbed", "countersign", "negative"];
  const ANOMALY_BACKROOM_SCENE = { underbed: "underbed-call-station", countersign: "countersign-drain", negative: "negative-laundry-locker" };
  const ANOMALY_SCENE_BACKROOM = { "underbed-call-station": "underbed", "countersign-drain": "countersign", "negative-laundry-locker": "negative" };
  const ANOMALY_BACKROOM_SCENES = ["underbed-call-station", "countersign-drain", "negative-laundry-locker"];
  const ANOMALY_ROOM_BACKROOM = { ward: "underbed-call-station", records: "countersign-drain", laundry: "negative-laundry-locker" };
  const ANOMALY_NUM_CAP = 9999;
  const ANOMALY_HISTORY_CAP = 16;
  /* 每轮至少 1 间异常且至少 1 间正常；下轮按 (cycle + follow + 2*contain + 3*submit) 轮换，
     创建即持久化——本轮计分变化不回改分配（reload 稳定、无 Math.random） */
  const ANOMALY_PATTERNS = [
    { ward: "anomaly", records: "normal", laundry: "normal" },
    { ward: "normal", records: "anomaly", laundry: "normal" },
    { ward: "normal", records: "normal", laundry: "anomaly" },
    { ward: "anomaly", records: "anomaly", laundry: "normal" },
    { ward: "normal", records: "anomaly", laundry: "anomaly" },
    { ward: "anomaly", records: "normal", laundry: "anomaly" },
  ];
  const ANOMALY_BASE_IMG = { ward: "assets/bellless-ward.webp", records: "assets/seeping-records.webp", laundry: "assets/reverse-laundry.webp" };
  const ANOMALY_IMG = { ward: "assets/v55-ward-anomaly.webp", records: "assets/v55-records-anomaly.webp", laundry: "assets/v55-laundry-anomaly.webp" };
  const ANOMALY_BASE_FIGLABEL = {
    ward: "一间病房：会呼吸的空床、没有铃的床头柜、一条穿进墙里的输液管",
    records: "一间下沉档案室：晾着的无名页、渗字的水池、继续下沉的档案井",
    laundry: "一间工业洗衣房：先停下的滚筒、没有倒影的工服、像门一样的镜面机舱",
  };
  const ANOMALY_FIGLABEL = {
    ward: "病房巡检：床单上多出一枚呼叫钮，床头柜的抽屉开着",
    records: "档案池巡检：黑水从池心向天花板逆流",
    laundry: "洗衣房巡检：右侧机舱里挂着一件刚洗好的白工服",
  };
  /* 四种报告结果：逐字反馈 + 落点（发现异常/漏报异常 → 该房异常后室；误报/正确正常 → 无号层） */
  const ANOMALY_REPORT_META = {
    ward: {
      responseEl: "#ward-response",
      correctAnomaly: { target: "underbed-call-station", feedback: "你指出床单上的呼叫钮。它刚才确实不在那里。床下有什么开始回铃。" },
      missed: { target: "underbed-call-station", feedback: "你说这里一切正常。床单上的呼叫钮记下你的声音，替你按了自己。" },
      falseReport: { target: "unnumbered-floor", feedback: "你上报了异常。复核铃没有响——那东西一直在那里。楼层记下一次误报。" },
      correctNormal: { target: "unnumbered-floor", feedback: "你确认本室正常。空床、柜子与输液管轮流点头，楼层把这次巡检登记为有效。" },
    },
    records: {
      responseEl: "#records-response",
      correctAnomaly: { target: "countersign-drain", feedback: "你指出逆流的黑水。档案池承认它正在往上游写。" },
      missed: { target: "countersign-drain", feedback: "你说这里一切正常。黑水在你的签名旁边逆流。" },
      falseReport: { target: "unnumbered-floor", feedback: "你上报了异常。复核铃没有响——水池本来就往下渗。楼层记下一次误报。" },
      correctNormal: { target: "unnumbered-floor", feedback: "你确认本室正常。无名页、水池与抽屉墙都在原处，楼层把这次巡检登记为有效。" },
    },
    laundry: {
      responseEl: "#laundry-response",
      correctAnomaly: { target: "negative-laundry-locker", feedback: "你指出右机里的白工服。它比你先下班了。" },
      missed: { target: "negative-laundry-locker", feedback: "你说这里一切正常。右机的门在你身后开了一条缝。" },
      falseReport: { target: "unnumbered-floor", feedback: "你上报了异常。复核铃没有响——机舱里本来只有倒影。楼层记下一次误报。" },
      correctNormal: { target: "unnumbered-floor", feedback: "你确认本室正常。滚筒、工服与镜柜都在原处，楼层把这次巡检登记为有效。" },
    },
  };
  /* 三个异常后室：九动作，倾向计数影响下一轮分配 */
  const ANOMALY_BACKROOM_META = {
    underbed: {
      responseEl: "#underbed-response",
      actions: {
        wax: { btn: "#underbed-action-wax", target: "midnight-callback", tendency: "follow", amount: 1, feedback: "蜡撕开时里面先响了一声。午夜的回拨台正在等这条线。" },
        button: { btn: "#underbed-action-button", target: "bellless-ward", tendency: "contain", amount: 1, feedback: "呼叫钮被按回床垫。上面的呼吸停顿了一拍，病房恢复原样。" },
        horn: { btn: "#underbed-action-horn", target: "countersign-drain", tendency: "submit", amount: 1, feedback: "输液管把床下的声音送进喇叭。排水渠开始反着签名。" },
      },
    },
    countersign: {
      responseEl: "#countersign-response",
      actions: {
        print: { btn: "#countersign-action-print", target: "return-audit", tendency: "follow", amount: 1, feedback: "指纹替你签了空页。核验站要求重新核对回来的路。" },
        wheel: { btn: "#countersign-action-wheel", target: "seeping-records", tendency: "contain", amount: 1, feedback: "闸轮倒转，墨水沿抽屉链爬回档案池。" },
        drawer: { btn: "#countersign-action-drawer", target: "negative-laundry-locker", tendency: "submit", amount: 1, feedback: "你沿抽屉链下到排水井。井底是一层负照的更衣室。" },
      },
    },
    negative: {
      responseEl: "#negative-response",
      actions: {
        uniform: { btn: "#negative-action-uniform", target: "lagging-shadow-cloister", tendency: "submit", amount: 2, feedback: "白工服的反面没有缝线。你的影子被留在回廊里滞后了一步。" },
        press: { btn: "#negative-action-press", target: "protocol-drift", tendency: "follow", amount: 1, feedback: "空号牌压进红蜡。守则的第七条在旁边轻轻翻身。" },
        figure: { btn: "#negative-action-figure", target: "underbed-call-station", tendency: "contain", amount: 2, feedback: "空人形在你身后合上柜门。床下的回铃台又响了一次。" },
      },
    },
  };
  const ANOMALY_TENDENCIES = ["follow", "contain", "submit"];

  const getAnomaly = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(ANOMALY_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(ANOMALY_NUM_CAP, Math.floor(n));
    };
    const flag = (v) => (v === 1 || v === true ? 1 : 0);
    /* cycle 对齐 v35：floor cycle 变化即重置轮内字段（pending 一并失效），累计保留 */
    const floorCycle = getFloor().cycle;
    const sameCycle = num(raw.cycle) === floorCycle;
    const cycle = floorCycle;
    /* assignment 必须逐字段等于六个合法模式之一，否则清空待重建 */
    let assignment = null;
    if (sameCycle && raw.assignment && typeof raw.assignment === "object" && !Array.isArray(raw.assignment)) {
      const match = ANOMALY_PATTERNS.find((p) => ANOMALY_ROOMS.every((r) => raw.assignment[r] === p[r]));
      if (match) assignment = { ...match };
    }
    const inspected = {};
    const backrooms = {};
    const visits = {};
    ANOMALY_ROOMS.forEach((r) => { inspected[r] = sameCycle ? flag(raw.inspected && raw.inspected[r]) : 0; });
    ANOMALY_BACKROOMS.forEach((b) => {
      backrooms[b] = sameCycle ? flag(raw.backrooms && raw.backrooms[b]) : 0;
      visits[b] = num(raw.visits && raw.visits[b]);
    });
    const verified = num(raw.verified);
    const falseReports = num(raw.falseReports);
    const missed = num(raw.missed);
    const streak = num(raw.streak);
    const tendencies = {};
    ANOMALY_TENDENCIES.forEach((t) => { tendencies[t] = num(raw.tendencies && raw.tendencies[t]); });
    /* history 有界：仅保留白名单形状条目，最多 16 条（先解析，pending 证明依赖它） */
    let history = [];
    if (Array.isArray(raw.history)) {
      for (const h of raw.history) {
        if (!h || typeof h !== "object" || Array.isArray(h)) continue;
        if (h.type === "report" && ANOMALY_ROOMS.includes(h.room) && (h.report === "anomaly" || h.report === "normal")) {
          history.push({ type: "report", room: h.room, report: h.report });
        } else if (h.type === "action" && ANOMALY_BACKROOMS.includes(h.scene) && ANOMALY_BACKROOM_META[h.scene].actions[h.action]) {
          history.push({ type: "action", scene: h.scene, action: h.action });
        }
      }
    }
    history = history.slice(-ANOMALY_HISTORY_CAP);
    /* pending 严格白名单 +「确实刚结算」跨字段证据（v54 同款防伪）：
       严格键集、映射重算 target/feedback、本轮结算标记、history 末项一致、cycle 一致 */
    let pending = null;
    if (sameCycle && raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const p = raw.pending;
      const last = history.length ? history[history.length - 1] : null;
      if (p.kind === "report" && Object.keys(p).sort().join(",") === "feedback,kind,report,room,target"
        && ANOMALY_ROOMS.includes(p.room) && (p.report === "anomaly" || p.report === "normal")
        && assignment && inspected[p.room] === 1
        && last && last.type === "report" && last.room === p.room && last.report === p.report) {
        const truth = assignment[p.room];
        const outcome = p.report === truth ? (truth === "anomaly" ? "correctAnomaly" : "correctNormal") : (truth === "anomaly" ? "missed" : "falseReport");
        const meta = ANOMALY_REPORT_META[p.room][outcome];
        if (p.target === meta.target && p.feedback === meta.feedback) {
          pending = { kind: "report", room: p.room, report: p.report, target: meta.target, feedback: meta.feedback };
        }
      } else if (p.kind === "action" && Object.keys(p).sort().join(",") === "action,feedback,kind,scene,target"
        && ANOMALY_BACKROOMS.includes(p.scene) && ANOMALY_BACKROOM_META[p.scene].actions[p.action]
        && backrooms[p.scene] === 1
        && last && last.type === "action" && last.scene === p.scene && last.action === p.action) {
        const meta = ANOMALY_BACKROOM_META[p.scene].actions[p.action];
        if (p.target === meta.target && p.feedback === meta.feedback) {
          pending = { kind: "action", scene: p.scene, action: p.action, target: meta.target, feedback: meta.feedback };
        }
      }
    }
    /* 派生：contamination 与 pendingTarget 只重算，不落盘 */
    const contamination = falseReports + 2 * missed;
    return {
      cycle, assignment, inspected, backrooms, visits,
      verified, falseReports, missed, streak, tendencies,
      pending, pendingTarget: pending ? pending.target : "",
      history, contamination,
    };
  };
  /* 只持久化白名单 canonical 字段；派生字段永不落盘，history 先裁后存 */
  const saveAnomaly = (st) => store.set(ANOMALY_KEY, JSON.stringify({
    cycle: st.cycle,
    assignment: st.assignment,
    inspected: st.inspected,
    backrooms: st.backrooms,
    visits: st.visits,
    verified: st.verified,
    falseReports: st.falseReports,
    missed: st.missed,
    streak: st.streak,
    tendencies: st.tendencies,
    pending: st.pending,
    history: st.history.slice(-ANOMALY_HISTORY_CAP),
  }));

  /* 有任何巡检/后室活动（目录与记忆行恢复） */
  const anomalyActive = (st) =>
    st.verified > 0 || st.falseReports > 0 || st.missed > 0
    || ANOMALY_TENDENCIES.some((t) => st.tendencies[t] > 0)
    || ANOMALY_BACKROOMS.some((b) => st.visits[b] > 0);

  /* 创建本轮分配：reload 稳定、倾向影响下轮换、创建即持久化不再漂移 */
  const ensureAnomalyAssignment = () => {
    const st = getAnomaly();
    if (st.assignment) return st;
    const idx = (st.cycle + st.tendencies.follow + 2 * st.tendencies.contain + 3 * st.tendencies.submit) % ANOMALY_PATTERNS.length;
    st.assignment = { ...ANOMALY_PATTERNS[idx] };
    saveAnomaly(st);
    return st;
  };

  /* 巡检态判定：本房本轮值班已完成且尚未巡检结算 */
  const anomalyInspecting = (room) => {
    const st = getAnomaly();
    const floorSt = getFloor();
    return !!(st.assignment && floorSt.completed.includes(room) && st.inspected[room] === 0);
  };

  /* 房间重绘：值班态（旧四热点 + 平静图）/ 巡检态（两报告热点 + 正常或异常图）；
     巡检结算后回值班态（值班动作维持 disabled） */
  const syncAnomalyRoom = (sceneKey) => {
    const room = ANOMALY_SCENE_ROOM[sceneKey];
    if (!room) return;
    const floorSt = getFloor();
    if (floorSt.completed.includes(room) && getAnomaly().inspected[room] === 0) ensureAnomalyAssignment();
    const st = getAnomaly();
    const inspecting = anomalyInspecting(room);
    const section = $(`#scene-${sceneKey}`);
    if (!section) return;
    const figure = section.querySelector("figure.branch-figure");
    const img = figure && figure.querySelector(".branch-img");
    const wantSrc = inspecting && st.assignment[room] === "anomaly" ? ANOMALY_IMG[room] : ANOMALY_BASE_IMG[room];
    setSceneImageSrc(img, wantSrc);
    if (figure) figure.setAttribute("aria-label", inspecting && st.assignment[room] === "anomaly" ? ANOMALY_FIGLABEL[room] : ANOMALY_BASE_FIGLABEL[room]);
    const meta = FLOOR_ROOM_META[sceneKey];
    Object.keys(meta.choices).forEach((mark) => {
      const btn = $(meta.choices[mark].btn);
      if (!btn) return;
      if (inspecting) btn.setAttribute("hidden", "");
      else btn.removeAttribute("hidden");
    });
    const callbackBtn = $(CALLBACK_REPORT_META[sceneKey] && CALLBACK_REPORT_META[sceneKey].btn);
    if (callbackBtn) {
      if (inspecting) callbackBtn.setAttribute("hidden", "");
      else callbackBtn.removeAttribute("hidden");
    }
    ["anomaly", "normal"].forEach((report) => {
      const btn = $(`#${room}-report-${report}`);
      if (!btn) return;
      if (inspecting) btn.removeAttribute("hidden");
      else { btn.setAttribute("hidden", ""); btn.setAttribute("aria-pressed", "false"); }
    });
    paintAnomaly();
  };

  /* 统计签：三房巡检五项 + 后室倾向与结算标记（class/data 挂钩一次全刷） */
  const paintAnomaly = () => {
    const st = getAnomaly();
    $$("[data-anomaly-verified]").forEach((el) => { el.textContent = st.verified; });
    $$("[data-anomaly-false]").forEach((el) => { el.textContent = st.falseReports; });
    $$("[data-anomaly-missed]").forEach((el) => { el.textContent = st.missed; });
    $$("[data-anomaly-streak]").forEach((el) => { el.textContent = st.streak; });
    $$("[data-anomaly-contamination]").forEach((el) => { el.textContent = st.contamination; });
    ANOMALY_TENDENCIES.forEach((t) => {
      $$(`[data-tendency-${t}]`).forEach((el) => { el.textContent = st.tendencies[t]; });
    });
    ANOMALY_BACKROOMS.forEach((b) => {
      $$(`[data-backroom-settled="${b}"]`).forEach((el) => { el.textContent = st.backrooms[b] === 1 ? "已结算" : "未结算"; });
    });
  };

  /* v35 计分写入：cap 已按巡检新理论上限扩到 15/14，旧存档与结局含义不变 */
  const addAnomalyFloorScore = (sig, deb) => {
    const st = getFloor();
    st.signal = Math.min(FLOOR_SIGNAL_CAP, st.signal + sig);
    st.debt = Math.min(FLOOR_DEBT_CAP, st.debt + deb);
    saveFloor(st);
  };

  /* 巡检报告：live scene + 与 v35/v37 共享 first-lock + 巡检态 + 本轮未结算；
     四种结果逐字反馈，核验/误报/漏报/连对与 v35 signal/debt 精确入账 */
  const chooseAnomalyReport = (sceneKey, report) => {
    const room = ANOMALY_SCENE_ROOM[sceneKey];
    if (!room || (report !== "anomaly" && report !== "normal")) return;
    if (currentScene !== sceneKey) return;
    if (AutoAdvance.has(sceneKey)) return;
    if (!anomalyInspecting(room)) return;
    const st = getAnomaly();
    const truth = st.assignment[room];
    const outcome = report === truth ? (truth === "anomaly" ? "correctAnomaly" : "correctNormal") : (truth === "anomaly" ? "missed" : "falseReport");
    const meta = ANOMALY_REPORT_META[room][outcome];
    if (outcome === "correctAnomaly") { st.verified = Math.min(ANOMALY_NUM_CAP, st.verified + 2); st.streak = Math.min(ANOMALY_NUM_CAP, st.streak + 1); addAnomalyFloorScore(1, 0); }
    else if (outcome === "correctNormal") { st.verified = Math.min(ANOMALY_NUM_CAP, st.verified + 1); st.streak = Math.min(ANOMALY_NUM_CAP, st.streak + 1); addAnomalyFloorScore(1, 0); }
    else if (outcome === "falseReport") { st.falseReports = Math.min(ANOMALY_NUM_CAP, st.falseReports + 1); st.streak = 0; addAnomalyFloorScore(0, 1); }
    else { st.missed = Math.min(ANOMALY_NUM_CAP, st.missed + 1); st.streak = 0; addAnomalyFloorScore(0, 2); }
    st.inspected[room] = 1;
    st.history.push({ type: "report", room, report });
    /* v56 有意挂钩：第三间报告结算且本轮深查 >= 2 时，v56 暂存原落点
       （deferredTarget）并把这次转场改去症状交班台；v55 不挂 pending，
       由 v56 自己的严格 pending 接管节拍与防伪，v55 计分语义不变 */
    const evidenceDefer = recordEvidenceReport(room, outcome, meta.target, meta.feedback);
    if (evidenceDefer) {
      saveAnomaly(st);
      const btnD = $(`#${room}-report-${report}`);
      if (btnD) btnD.setAttribute("aria-pressed", "true");
      const responseElD = $(ANOMALY_REPORT_META[room].responseEl);
      if (responseElD) responseElD.textContent = meta.feedback;
      AudioEngine.knock(0.16);
      paintAnomaly();
      AutoAdvance.schedule(sceneKey, "symptom-handover-hub", {
        delay: branchDelay(),
        before: () => {
          const s = getEvidence();
          if (s.visits.hub === 0) s.visits.hub = 1;
          if (s.pending && s.pending.kind === "defer") s.pending = null;
          saveEvidence(s);
          syncEvidenceLinks();
          paintEvidenceAuditMemory();
        },
      });
      return;
    }
    st.pending = { kind: "report", room, report, target: meta.target, feedback: meta.feedback };
    saveAnomaly(st);
    const btn = $(`#${room}-report-${report}`);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $(ANOMALY_REPORT_META[room].responseEl);
    if (responseEl) responseEl.textContent = meta.feedback;
    AudioEngine.knock(0.16);
    paintAnomaly();
    AutoAdvance.schedule(sceneKey, meta.target, {
      delay: branchDelay(),
      before: () => {
        const s = getAnomaly();
        /* 落点是异常后室时，转场触发即记合法到访（v53 同款：guard 在 goScene 时读不到已清 pending） */
        const brTarget = ANOMALY_SCENE_BACKROOM[meta.target];
        if (brTarget && s.visits[brTarget] === 0) s.visits[brTarget] = 1;
        if (s.pending && s.pending.kind === "report" && s.pending.room === room) s.pending = null;
        saveAnomaly(s);
        syncAnomalyLinks();
        paintFloorAnomalyMemory();
      },
    });
  };

  /* 后室动作：live scene + first-lock；导航永远可用，倾向分值每房每 cycle
     只结算首次（防止三房环路刷分），已结算在签上明示 */
  const chooseAnomalyAction = (sceneKey, actionKey) => {
    const backroom = ANOMALY_SCENE_BACKROOM[sceneKey];
    const meta = backroom && ANOMALY_BACKROOM_META[backroom].actions[actionKey];
    if (!meta) return;
    if (currentScene !== sceneKey) return;
    if (AutoAdvance.has(sceneKey)) return;
    const st = getAnomaly();
    if (st.backrooms[backroom] === 0) {
      st.backrooms[backroom] = 1;
      st.tendencies[meta.tendency] = Math.min(ANOMALY_NUM_CAP, st.tendencies[meta.tendency] + meta.amount);
      st.history.push({ type: "action", scene: backroom, action: actionKey });
      st.pending = { kind: "action", scene: backroom, action: actionKey, target: meta.target, feedback: meta.feedback };
      saveAnomaly(st);
    }
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $(ANOMALY_BACKROOM_META[backroom].responseEl);
    if (responseEl) responseEl.textContent = meta.feedback;
    AudioEngine.knock(0.16);
    paintAnomaly();
    AutoAdvance.schedule(sceneKey, meta.target, {
      delay: branchDelay(),
      before: () => {
        const s = getAnomaly();
        const brTarget = ANOMALY_SCENE_BACKROOM[meta.target];
        if (brTarget && s.visits[brTarget] === 0) s.visits[brTarget] = 1;
        if (s.pending && s.pending.kind === "action") s.pending = null;
        saveAnomaly(s);
        syncAnomalyLinks();
        paintFloorAnomalyMemory();
      },
    });
  };

  /* reload 节拍恢复：合法 pending 属于当前场景时重播逐字反馈并精确重挂
     一次转场（结算在接受时已计，这里只清 pending，不再校验分值） */
  const replayAnomalyPending = (sceneName) => {
    const st = getAnomaly();
    const p = st.pending;
    if (!p) return;
    if (p.kind === "report" && ANOMALY_ROOM_SCENE[p.room] === sceneName) {
      const responseEl = $(ANOMALY_REPORT_META[p.room].responseEl);
      if (responseEl) responseEl.textContent = p.feedback;
    } else if (p.kind === "action" && ANOMALY_BACKROOM_SCENE[p.scene] === sceneName) {
      const responseEl = $(ANOMALY_BACKROOM_META[p.scene].responseEl);
      if (responseEl) responseEl.textContent = p.feedback;
    } else return;
    AutoAdvance.schedule(sceneName, p.target, {
      delay: branchDelay(),
      before: () => {
        const s = getAnomaly();
        const brTarget = ANOMALY_SCENE_BACKROOM[p.target];
        if (brTarget && s.visits[brTarget] === 0) s.visits[brTarget] = 1;
        if (s.pending) s.pending = null;
        saveAnomaly(s);
        syncAnomalyLinks();
        paintFloorAnomalyMemory();
      },
    });
  };

  /* 后室进入：守卫已证明合法到达（本轮 pending 或历史到访），此处记 visit、
     清响应、刷签；目录入口首次合法到访后原子恢复 */
  const enterAnomalyBackroom = (sceneName) => {
    const backroom = ANOMALY_SCENE_BACKROOM[sceneName];
    if (!backroom) return;
    const st = getAnomaly();
    if (st.visits[backroom] === 0) {
      st.visits[backroom] = 1;
      saveAnomaly(st);
      syncAnomalyLinks();
    }
    const responseEl = $(ANOMALY_BACKROOM_META[backroom].responseEl);
    if (responseEl) responseEl.textContent = "";
    paintAnomaly();
  };

  /* v56 设计内挂钩：症状交班漏报 / 自扣封条的落点是既有异常后室，
     转场 before 先记合法到访再清 pending（与 v55 自家 before 同契约） */
  const grantAnomalyBackroomVisit = (sceneName) => {
    const key = ANOMALY_SCENE_BACKROOM[sceneName];
    if (!key) return;
    const st = getAnomaly();
    if (st.visits[key] === 0) {
      st.visits[key] = 1;
      saveAnomaly(st);
      syncAnomalyLinks();
    }
  };

  const ANOMALY_LINKS = { underbed: "#underbed-link", countersign: "#countersign-link", negative: "#negative-link" };
  const syncAnomalyLinks = () => {
    const st = getAnomaly();
    ANOMALY_BACKROOMS.forEach((b) => {
      const link = $(ANOMALY_LINKS[b]);
      if (!link) return;
      if (st.visits[b] > 0) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  /* 痕迹页单行：巡检四项 + 污染，保持八张统计卡不变 */
  const paintFloorAnomalyMemory = () => {
    const memory = $("#floor-anomaly-memory");
    if (!memory) return;
    const st = getAnomaly();
    if (!anomalyActive(st)) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `失常交班：核验 ${st.verified}，误报 ${st.falseReports}，漏报 ${st.missed}，污染 ${st.contamination}。`;
    memory.hidden = false;
  };

  ANOMALY_ROOMS.forEach((room) => {
    ["anomaly", "normal"].forEach((report) => {
      const btn = $(`#${room}-report-${report}`);
      if (btn) btn.addEventListener("click", () => chooseAnomalyReport(ANOMALY_ROOM_SCENE[room], report));
    });
    /* 三张异常图随场景预载，巡检切换无闪烁 */
    prefetchWithScene(ANOMALY_ROOM_SCENE[room], ANOMALY_IMG[room]);
  });
  ANOMALY_BACKROOMS.forEach((backroom) => {
    Object.keys(ANOMALY_BACKROOM_META[backroom].actions).forEach((actionKey) => {
      const btn = $(ANOMALY_BACKROOM_META[backroom].actions[actionKey].btn);
      if (btn) btn.addEventListener("click", () => chooseAnomalyAction(ANOMALY_BACKROOM_SCENE[backroom], actionKey));
    });
  });
  paintAnomaly();

  /* ============================================================
     v56 症状交接：三房巡检核验封条 + 症状交班台 + 证据编组室
     独立容错状态键 EVIDENCE_KEY（v56 唯一存储键），只持久化白名单
     canonical 字段；credibility 与 pendingTarget 派生重算不落盘；
     真值永远从 v55 规范状态（getAnomaly().assignment）读取，不信任
     任何持久化的 assignment；坏 JSON/数组/错型/负数/浮点/超大数/
     未知键/额外键 pending/错映射/无历史证据/跨 cycle 全部归一。
     ============================================================ */
  const EVIDENCE_KEY = "goddead_v56_evidence_audit";
  const EVIDENCE_ROOMS = ["ward", "records", "laundry"];
  const EVIDENCE_SCENE_KEYS = ["hub", "switchboard"];
  const EVIDENCE_KEY_SCENE = { hub: "symptom-handover-hub", switchboard: "evidence-switchboard" };
  const EVIDENCE_SCENE_KEY = { "symptom-handover-hub": "hub", "evidence-switchboard": "switchboard" };
  const EVIDENCE_SCENES = ["symptom-handover-hub", "evidence-switchboard"];
  const EVIDENCE_NUM_CAP = 9999;
  const EVIDENCE_HISTORY_CAP = 16;
  /* 封条预算：基础 2 枚；credibility >= 4 下一轮 3 枚，<= -2 下一轮 1 枚。
     每个 v35/v55 cycle 首次进入巡检时创建一次并冻结，reload 稳定，严禁随机 */
  const EVIDENCE_BUDGET_BY_CREDIBILITY = (cred) => (cred >= 4 ? 3 : cred <= -2 ? 1 : 2);
  const EVIDENCE_CHECK_META = {
    ward: {
      btn: "#ward-evidence-check",
      anomalyImg: "assets/v56-ward-deep-anomaly.webp", normalImg: "assets/v56-ward-deep-normal.webp",
      anomalyLabel: "病房深查：黑线从回铃机穿过床单接回那枚呼叫钮",
      normalLabel: "病房深查：黑线止在瓷封里，床上没有第二个接点",
      anomalyFeedback: "黑线没有通向墙。它从床单下面接回那枚呼叫钮。",
      normalFeedback: "黑线止在瓷封里。床上没有第二个接点。",
    },
    records: {
      btn: "#records-evidence-check",
      anomalyImg: "assets/v56-records-deep-anomaly.webp", normalImg: "assets/v56-records-deep-normal.webp",
      anomalyLabel: "档案池深查：背光里墨迹从纸纤维向上爬",
      normalLabel: "档案池深查：背光穿透整页，没有藏第二份姓名",
      anomalyFeedback: "背光里，墨迹从纸纤维向上爬，和池心的逆流同拍。",
      normalFeedback: "背光穿透整页。纸纤维里没有藏第二份姓名。",
    },
    laundry: {
      btn: "#laundry-evidence-check",
      anomalyImg: "assets/v56-laundry-deep-anomaly.webp", normalImg: "assets/v56-laundry-deep-normal.webp",
      anomalyLabel: "洗衣房深查：黑线穿过机壳接在倒影里的白工服上",
      normalLabel: "洗衣房深查：两根铜线封死在瓷帽里，圆窗后仍是空走廊",
      anomalyFeedback: "黑线穿过机壳，接在倒影里的白工服上。第二道影子朝错方向落下。",
      normalFeedback: "两根铜线都封死在瓷帽里。圆窗后的走廊仍是空的。",
    },
  };
  /* 症状交班台四种结果（按该房本轮 v56 report 是否正确 + 是否深查过 + 真值） */
  const EVIDENCE_HANDOVER_META = {
    trusted: { target: "evidence-switchboard", feedback: "封条和报告同时咬住同一结论。证据编组室把门打开了。" },
    blind: { target: "evidence-switchboard", feedback: "没有封条的报告仍然猜中了门后那一间。证据编组室接受这次盲判。" },
    falseReport: { target: "innocent-quarantine", feedback: "你交上去的症状在台面上恢复正常。误报井先签收了你。" },
    missed: { target: "omission-transfer-shaft", feedback: "你交上去的正常结论在台面上开始呼吸。对应后室把原件取走了。" },
  };
  const EVIDENCE_SWITCH_META = {
    press: { btn: "#switch-action-press", target: "evidence-vault", feedback: "压机合拢。两份证据从此只允许一种死法。" },
    burn: { btn: "#switch-action-burn", target: "false-positive-shaft", feedback: "红蜡只烧掉不同意你的那一份。误报井收到了灰。" },
    selfseal: { btn: "#switch-action-selfseal", feedback: "封条绕过手腕和喉咙。你成了这批证据唯一还活着的附件。" },
  };
  /* v57：press 分流所需的 handover 判定完全由既有 canonical 状态派生（不落盘）——
     trusted = 该房报告正确且深查过；blind = 正确但未深查；其余回落证物库 */
  const evidenceHandoverKind = (st) => {
    if (!st || !EVIDENCE_ROOMS.includes(st.handover)) return "";
    if (st.correct[st.handover] !== 1) return "";
    return st.checks[st.handover] === 1 ? "trusted" : "blind";
  };

  const getEvidence = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(EVIDENCE_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(EVIDENCE_NUM_CAP, Math.floor(n));
    };
    const flag = (v) => (v === 1 || v === true ? 1 : 0);
    /* cycle 对齐 v35/v55：floor cycle 变化即重置轮内字段，累计保留 */
    const floorCycle = getFloor().cycle;
    const sameCycle = num(raw.cycle) === floorCycle;
    const cycle = floorCycle;
    /* 预算只接受合法三值；remaining 不超过 budget */
    let budget = sameCycle && [1, 2, 3].includes(raw.budget) ? raw.budget : 0;
    let remaining = sameCycle ? num(raw.remaining) : 0;
    if (budget === 0) remaining = 0;
    remaining = Math.min(remaining, budget);
    const checks = {};
    const reports = {};
    const correct = {};
    EVIDENCE_ROOMS.forEach((r) => {
      checks[r] = sameCycle ? flag(raw.checks && raw.checks[r]) : 0;
      reports[r] = sameCycle ? flag(raw.reports && raw.reports[r]) : 0;
      correct[r] = sameCycle ? flag(raw.correct && raw.correct[r]) : 0;
    });
    const deepCount = sameCycle ? Math.min(3, num(raw.deepCount)) : 0;
    const handover = sameCycle && EVIDENCE_ROOMS.includes(raw.handover) ? raw.handover : "";
    /* deferredTarget 只能是 v55 四种结果落点之一（异常后室或无号层） */
    const deferredPool = ["unnumbered-floor", "underbed-call-station", "countersign-drain", "negative-laundry-locker"];
    const deferredTarget = sameCycle && deferredPool.includes(raw.deferredTarget) ? raw.deferredTarget : "";
    const resolved = {};
    const visits = {};
    EVIDENCE_SCENE_KEYS.forEach((k) => {
      resolved[k] = sameCycle ? flag(raw.resolved && raw.resolved[k]) : 0;
      visits[k] = num(raw.visits && raw.visits[k]);
    });
    const counters = {};
    ["proofs", "blindCorrect", "contradictions", "exposure", "chains", "suppressed", "selfSeals", "trustedHandovers", "blindHandovers", "failedHandovers"].forEach((k) => {
      counters[k] = num(raw[k]);
    });
    /* history 有界：仅保留白名单形状条目，最多 16 条（先解析，pending 证明依赖它） */
    let history = [];
    if (Array.isArray(raw.history)) {
      for (const h of raw.history) {
        if (!h || typeof h !== "object" || Array.isArray(h)) continue;
        if (h.type === "check" && EVIDENCE_ROOMS.includes(h.room)) {
          history.push({ type: "check", room: h.room });
        } else if (h.type === "report" && EVIDENCE_ROOMS.includes(h.room) && ["correctAnomaly", "correctNormal", "falseReport", "missed"].includes(h.outcome)) {
          history.push({ type: "report", room: h.room, outcome: h.outcome });
        } else if (h.type === "handover" && EVIDENCE_ROOMS.includes(h.room)) {
          history.push({ type: "handover", room: h.room });
        } else if (h.type === "action" && Object.keys(EVIDENCE_SWITCH_META).includes(h.action)) {
          history.push({ type: "action", action: h.action });
        }
      }
    }
    history = history.slice(-EVIDENCE_HISTORY_CAP);
    /* pending 严格白名单 + 结算证据 + canonical history 末项交叉验证（v54/v55 同款防伪） */
    let pending = null;
    if (sameCycle && raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const p = raw.pending;
      const last = history.length ? history[history.length - 1] : null;
      if (p.kind === "defer" && Object.keys(p).sort().join(",") === "feedback,kind,outcome,room,target"
        && EVIDENCE_ROOMS.includes(p.room) && ["correctAnomaly", "correctNormal", "falseReport", "missed"].includes(p.outcome)
        && p.target === "symptom-handover-hub" && deferredTarget !== "" && reports[p.room] === 1
        && last && last.type === "report" && last.room === p.room && last.outcome === p.outcome) {
        const meta = ANOMALY_REPORT_META[p.room][p.outcome];
        if (p.feedback === meta.feedback) {
          pending = { kind: "defer", room: p.room, outcome: p.outcome, target: "symptom-handover-hub", feedback: meta.feedback };
        }
      } else if (p.kind === "handover" && Object.keys(p).sort().join(",") === "feedback,kind,room,target"
        && EVIDENCE_ROOMS.includes(p.room) && resolved.hub === 1 && handover === p.room
        && last && last.type === "handover" && last.room === p.room) {
        const truthState = getAnomaly();
        const truth = truthState.assignment && truthState.assignment[p.room];
        const okC = correct[p.room] === 1;
        const kind2 = okC ? (checks[p.room] === 1 ? "trusted" : "blind") : (truth === "normal" ? "falseReport" : "missed");
        const target = EVIDENCE_HANDOVER_META[kind2].target;
        const feedback = EVIDENCE_HANDOVER_META[kind2].feedback;
        if (p.target === target && p.feedback === feedback) {
          pending = { kind: "handover", room: p.room, target, feedback };
        }
      } else if (p.kind === "action" && Object.keys(p).sort().join(",") === "action,feedback,kind,target"
        && Object.keys(EVIDENCE_SWITCH_META).includes(p.action) && resolved.switchboard === 1
        && last && last.type === "action" && last.action === p.action) {
        const meta = EVIDENCE_SWITCH_META[p.action];
        /* v57：press 按派生的 handover 判定分流后果场景（trusted→共证剧场 /
           blind→错绑交班，其余回证物库）；burn 前插无辜留置；selfseal 前插错绑交班 */
        const target = p.action === "press"
          ? (evidenceHandoverKind({ handover, correct, checks }) === "trusted" ? "concordance-theatre"
            : evidenceHandoverKind({ handover, correct, checks }) === "blind" ? "misbound-handover" : "evidence-vault")
          : p.action === "burn" ? "innocent-quarantine" : "misbound-handover";
        if (p.target === target && p.feedback === meta.feedback) {
          pending = { kind: "action", action: p.action, target, feedback: meta.feedback };
        }
      }
    }
    /* 派生：credibility 与 pendingTarget 只重算，不落盘 */
    const credibility = counters.proofs + 2 * counters.blindCorrect + counters.chains - counters.contradictions - counters.suppressed;
    return {
      cycle, budget, remaining, checks, reports, correct, deepCount, handover, deferredTarget,
      resolved, visits, ...counters, pending, pendingTarget: pending ? pending.target : "",
      history, credibility,
    };
  };
  /* 只持久化白名单 canonical 字段；派生字段永不落盘，history 先裁后存 */
  const saveEvidence = (st) => store.set(EVIDENCE_KEY, JSON.stringify({
    cycle: st.cycle,
    budget: st.budget,
    remaining: st.remaining,
    checks: st.checks,
    reports: st.reports,
    correct: st.correct,
    deepCount: st.deepCount,
    handover: st.handover,
    deferredTarget: st.deferredTarget,
    resolved: st.resolved,
    visits: st.visits,
    proofs: st.proofs,
    blindCorrect: st.blindCorrect,
    contradictions: st.contradictions,
    exposure: st.exposure,
    chains: st.chains,
    suppressed: st.suppressed,
    selfSeals: st.selfSeals,
    trustedHandovers: st.trustedHandovers,
    blindHandovers: st.blindHandovers,
    failedHandovers: st.failedHandovers,
    pending: st.pending,
    history: st.history.slice(-EVIDENCE_HISTORY_CAP),
  }));

  const evidenceActive = (st) =>
    st.proofs > 0 || st.blindCorrect > 0 || st.contradictions > 0 || st.exposure > 0
    || st.chains > 0 || st.suppressed > 0 || st.selfSeals > 0
    || st.trustedHandovers > 0 || st.blindHandovers > 0 || st.failedHandovers > 0
    || EVIDENCE_SCENE_KEYS.some((k) => st.visits[k] > 0);

  /* 每个 v35/v55 cycle 首次进入巡检时创建本轮预算并冻结（reload 稳定，严禁随机） */
  const ensureEvidenceBudget = () => {
    const st = getEvidence();
    if (st.budget > 0) return st;
    st.budget = EVIDENCE_BUDGET_BY_CREDIBILITY(st.credibility);
    st.remaining = st.budget;
    saveEvidence(st);
    return st;
  };

  /* 房间重绘（排在 v55 syncAnomalyRoom 之后）：巡检态显示核验热点
     （封条余量 > 0 且本房未深查）；深查后按真值原子切到 v56 deep 图 */
  const syncEvidenceRoom = (sceneKey) => {
    const room = ANOMALY_SCENE_ROOM[sceneKey];
    if (!room) return;
    const floorSt = getFloor();
    const inspectingNow = floorSt.completed.includes(room) && getAnomaly().inspected[room] === 0;
    if (inspectingNow) ensureEvidenceBudget();
    const st = getEvidence();
    const inspecting = anomalyInspecting(room);
    const meta = EVIDENCE_CHECK_META[room];
    const btn = $(meta.btn);
    if (btn) {
      if (inspecting && st.remaining > 0 && st.checks[room] === 0) btn.removeAttribute("hidden");
      else { btn.setAttribute("hidden", ""); btn.setAttribute("aria-pressed", "false"); }
    }
    if (inspecting && st.checks[room] === 1) {
      const truth = getAnomaly().assignment[room];
      const section = $(`#scene-${sceneKey}`);
      const figure = section && section.querySelector("figure.branch-figure");
      const img = figure && figure.querySelector(".branch-img");
      const wantSrc = truth === "anomaly" ? meta.anomalyImg : meta.normalImg;
      setSceneImageSrc(img, wantSrc);
      if (figure) figure.setAttribute("aria-label", truth === "anomaly" ? meta.anomalyLabel : meta.normalLabel);
    }
    paintEvidence();
  };

  /* 统计签：三房封条/证据/盲判/矛盾/暴露/可信度 + 两新场景状态签 */
  const paintEvidence = () => {
    const st = getEvidence();
    $$("[data-evidence-remaining]").forEach((el) => { el.textContent = st.remaining; });
    $$("[data-evidence-proofs]").forEach((el) => { el.textContent = st.proofs; });
    $$("[data-evidence-blind]").forEach((el) => { el.textContent = st.blindCorrect; });
    $$("[data-evidence-contradictions]").forEach((el) => { el.textContent = st.contradictions; });
    $$("[data-evidence-exposure]").forEach((el) => { el.textContent = st.exposure; });
    $$("[data-evidence-credibility]").forEach((el) => { el.textContent = st.credibility; });
    $$("[data-evidence-chains]").forEach((el) => { el.textContent = st.chains; });
    $$("[data-evidence-suppressed]").forEach((el) => { el.textContent = st.suppressed; });
    $$("[data-evidence-selfseals]").forEach((el) => { el.textContent = st.selfSeals; });
    $$("[data-handover-trusted]").forEach((el) => { el.textContent = st.trustedHandovers; });
    $$("[data-handover-blind]").forEach((el) => { el.textContent = st.blindHandovers; });
    $$("[data-handover-failed]").forEach((el) => { el.textContent = st.failedHandovers; });
    $$("[data-handover-settled]").forEach((el) => { el.textContent = st.resolved.hub === 1 ? "已交班" : "未交班"; });
    $$("[data-switchboard-settled]").forEach((el) => { el.textContent = st.resolved.switchboard === 1 ? "已编组" : "未编组"; });
  };

  /* 深查：live scene + 共享 first-lock + 巡检态 + 封条余量 + 本房未深查；
     原地切图与证据反馈，不转场；报告热点始终可立即选择 */
  const chooseEvidenceCheck = (sceneKey) => {
    const room = ANOMALY_SCENE_ROOM[sceneKey];
    if (!room) return;
    if (currentScene !== sceneKey) return;
    if (AutoAdvance.has(sceneKey)) return;
    if (!anomalyInspecting(room)) return;
    const st = getEvidence();
    if (st.budget === 0 || st.remaining === 0 || st.checks[room] === 1) return;
    st.remaining = Math.max(0, st.remaining - 1);
    st.deepCount = Math.min(3, st.deepCount + 1);
    st.checks[room] = 1;
    st.exposure = Math.min(EVIDENCE_NUM_CAP, st.exposure + 1);
    st.history.push({ type: "check", room });
    saveEvidence(st);
    const truth = getAnomaly().assignment[room];
    const meta = EVIDENCE_CHECK_META[room];
    const section = $(`#scene-${sceneKey}`);
    const figure = section && section.querySelector("figure.branch-figure");
    const img = figure && figure.querySelector(".branch-img");
    const wantSrc = truth === "anomaly" ? meta.anomalyImg : meta.normalImg;
    setSceneImageSrc(img, wantSrc);
    if (figure) figure.setAttribute("aria-label", truth === "anomaly" ? meta.anomalyLabel : meta.normalLabel);
    const btn = $(meta.btn);
    if (btn) {
      btn.setAttribute("aria-pressed", "true");
      btn.setAttribute("hidden", "");
    }
    const responseEl = $(ANOMALY_REPORT_META[room].responseEl);
    if (responseEl) responseEl.textContent = truth === "anomaly" ? meta.anomalyFeedback : meta.normalFeedback;
    AudioEngine.knock(0.16);
    paintEvidence();
  };

  /* v55 报告结算时只记一次 v56 结果：深查后报告正确 proofs+1；
     未深查盲判正确 blindCorrect+1；任何错误 contradictions+1。
     第三间报告且本轮深查 >= 2 时暂存原落点并改道症状交班台（每轮一次） */
  const recordEvidenceReport = (room, outcome, v55Target, v55Feedback) => {
    const st = getEvidence();
    if (st.reports[room] === 1) return "";
    st.reports[room] = 1;
    const isCorrect = outcome === "correctAnomaly" || outcome === "correctNormal";
    st.correct[room] = isCorrect ? 1 : 0;
    if (isCorrect) {
      if (st.checks[room] === 1) st.proofs = Math.min(EVIDENCE_NUM_CAP, st.proofs + 1);
      else st.blindCorrect = Math.min(EVIDENCE_NUM_CAP, st.blindCorrect + 1);
    } else {
      st.contradictions = Math.min(EVIDENCE_NUM_CAP, st.contradictions + 1);
    }
    st.history.push({ type: "report", room, outcome });
    const reportCount = EVIDENCE_ROOMS.reduce((n, r) => n + st.reports[r], 0);
    if (reportCount === 3 && st.deepCount >= 2 && st.deferredTarget === "") {
      st.deferredTarget = v55Target;
      st.pending = { kind: "defer", room, outcome, target: "symptom-handover-hub", feedback: v55Feedback };
      saveEvidence(st);
      return "symptom-handover-hub";
    }
    saveEvidence(st);
    return "";
  };

  /* 症状交班台：只接受首次；按该房本轮 v56 report 是否正确 + 是否深查 +
     真值分流四种逐字结果 */
  const chooseEvidenceHandover = (room) => {
    if (!EVIDENCE_ROOMS.includes(room)) return;
    if (currentScene !== "symptom-handover-hub") return;
    if (AutoAdvance.has("symptom-handover-hub")) return;
    const st = getEvidence();
    if (st.resolved.hub === 1 || st.reports[room] !== 1) return;
    const truthState = getAnomaly();
    const truth = truthState.assignment && truthState.assignment[room];
    if (!truth) return;
    const isCorrect = st.correct[room] === 1;
    const kind = isCorrect ? (st.checks[room] === 1 ? "trusted" : "blind") : (truth === "normal" ? "falseReport" : "missed");
    const target = EVIDENCE_HANDOVER_META[kind].target;
    const feedback = EVIDENCE_HANDOVER_META[kind].feedback;
    if (kind === "trusted") st.trustedHandovers = Math.min(EVIDENCE_NUM_CAP, st.trustedHandovers + 1);
    else if (kind === "blind") st.blindHandovers = Math.min(EVIDENCE_NUM_CAP, st.blindHandovers + 1);
    else st.failedHandovers = Math.min(EVIDENCE_NUM_CAP, st.failedHandovers + 1);
    st.handover = room;
    st.resolved.hub = 1;
    st.history.push({ type: "handover", room });
    st.pending = { kind: "handover", room, target, feedback };
    saveEvidence(st);
    const btn = $(`#handover-choice-${room}`);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $("#handover-response");
    if (responseEl) responseEl.textContent = feedback;
    AudioEngine.knock(0.16);
    paintEvidence();
    AutoAdvance.schedule("symptom-handover-hub", target, {
      delay: branchDelay(),
      before: () => {
        const s = getEvidence();
        if (target === "evidence-switchboard" && s.visits.switchboard === 0) s.visits.switchboard = 1;
        if (s.pending && s.pending.kind === "handover") s.pending = null;
        saveEvidence(s);
        /* v57：交班 falseReport → 无辜留置、missed → 漏报移交，before 原子记 v57 visit */
        if (LEDGER_SCENE_KEY[target]) grantLedgerVisit(target);
        syncEvidenceLinks();
        paintEvidenceAuditMemory();
      },
    });
  };

  /* 证据编组室：导航常开，分值每 cycle 只结算首次（压因果 chains+1 /
     烧矛盾 suppressed+1 / 自扣封条 selfSeals+1 且 exposure+2） */
  const chooseEvidenceSwitchAction = (actionKey) => {
    const meta = EVIDENCE_SWITCH_META[actionKey];
    if (!meta) return;
    if (currentScene !== "evidence-switchboard") return;
    if (AutoAdvance.has("evidence-switchboard")) return;
    const st = getEvidence();
    /* v57 改道：press 按派生的 handover 判定去共证剧场/错绑交班（否则证物库），
       burn 前插无辜留置，selfseal 前插错绑交班；chains/suppressed/selfSeals/exposure 不变 */
    const handoverKind = evidenceHandoverKind(st);
    const target = actionKey === "press"
      ? (handoverKind === "trusted" ? "concordance-theatre" : handoverKind === "blind" ? "misbound-handover" : "evidence-vault")
      : actionKey === "burn" ? "innocent-quarantine" : "misbound-handover";
    if (st.resolved.switchboard === 0) {
      st.resolved.switchboard = 1;
      if (actionKey === "press") st.chains = Math.min(EVIDENCE_NUM_CAP, st.chains + 1);
      else if (actionKey === "burn") st.suppressed = Math.min(EVIDENCE_NUM_CAP, st.suppressed + 1);
      else {
        st.selfSeals = Math.min(EVIDENCE_NUM_CAP, st.selfSeals + 1);
        st.exposure = Math.min(EVIDENCE_NUM_CAP, st.exposure + 2);
      }
      st.history.push({ type: "action", action: actionKey });
      st.pending = { kind: "action", action: actionKey, target, feedback: meta.feedback };
      saveEvidence(st);
    }
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $("#switchboard-response");
    if (responseEl) responseEl.textContent = meta.feedback;
    AudioEngine.knock(0.16);
    paintEvidence();
    AutoAdvance.schedule("evidence-switchboard", target, {
      delay: branchDelay(),
      before: () => {
        const s = getEvidence();
        if (s.pending && s.pending.kind === "action") s.pending = null;
        saveEvidence(s);
        if (target === "evidence-vault") markReviewVisited("evidence-vault");
        if (LEDGER_SCENE_KEY[target]) grantLedgerVisit(target);
        syncEvidenceLinks();
        paintEvidenceAuditMemory();
      },
    });
  };

  /* reload 节拍恢复：合法 pending 属于当前场景时重播逐字反馈并精确重挂一次 */
  const replayEvidencePending = (sceneName) => {
    const st = getEvidence();
    const p = st.pending;
    if (!p) return;
    if (p.kind === "defer" && ANOMALY_ROOM_SCENE[p.room] === sceneName) {
      const responseEl = $(ANOMALY_REPORT_META[p.room].responseEl);
      if (responseEl) responseEl.textContent = p.feedback;
    } else if (p.kind === "handover" && sceneName === "symptom-handover-hub") {
      const responseEl = $("#handover-response");
      if (responseEl) responseEl.textContent = p.feedback;
    } else if (p.kind === "action" && sceneName === "evidence-switchboard") {
      const responseEl = $("#switchboard-response");
      if (responseEl) responseEl.textContent = p.feedback;
    } else return;
    AutoAdvance.schedule(sceneName, p.target, {
      delay: branchDelay(),
      before: () => {
        const s = getEvidence();
        if (p.target === "evidence-switchboard" && s.visits.switchboard === 0) s.visits.switchboard = 1;
        if (p.target === "symptom-handover-hub" && s.visits.hub === 0) s.visits.hub = 1;
        if (s.pending) s.pending = null;
        saveEvidence(s);
        if (p.target === "evidence-vault") markReviewVisited("evidence-vault");
        if (LEDGER_SCENE_KEY[p.target]) grantLedgerVisit(p.target);
        syncEvidenceLinks();
        paintEvidenceAuditMemory();
      },
    });
  };

  /* 两新场景进入：清响应 + 刷签（visit 已在转场 before 原子记录，这里幂等） */
  const enterEvidenceScene = (sceneName) => {
    const key = EVIDENCE_SCENE_KEY[sceneName];
    if (!key) return;
    const st = getEvidence();
    if (st.visits[key] === 0) {
      st.visits[key] = 1;
      saveEvidence(st);
      syncEvidenceLinks();
    }
    const responseEl = $(key === "hub" ? "#handover-response" : "#switchboard-response");
    if (responseEl) responseEl.textContent = "";
    paintEvidence();
  };

  const EVIDENCE_LINKS = { hub: "#handover-link", switchboard: "#switchboard-link" };
  const syncEvidenceLinks = () => {
    const st = getEvidence();
    EVIDENCE_SCENE_KEYS.forEach((k) => {
      const link = $(EVIDENCE_LINKS[k]);
      if (!link) return;
      if (st.visits[k] > 0) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  /* 痕迹页单行：证据审计五项，保持八张统计卡不变 */
  const paintEvidenceAuditMemory = () => {
    const memory = $("#evidence-audit-memory");
    if (!memory) return;
    const st = getEvidence();
    if (!evidenceActive(st)) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `证据审计：核验 ${st.proofs}，盲判 ${st.blindCorrect}，矛盾 ${st.contradictions}，暴露 ${st.exposure}，可信度 ${st.credibility}。`;
    memory.hidden = false;
  };

  EVIDENCE_ROOMS.forEach((room) => {
    const checkBtn = $(EVIDENCE_CHECK_META[room].btn);
    if (checkBtn) checkBtn.addEventListener("click", () => chooseEvidenceCheck(ANOMALY_ROOM_SCENE[room]));
    const handoverBtn = $(`#handover-choice-${room}`);
    if (handoverBtn) handoverBtn.addEventListener("click", () => chooseEvidenceHandover(room));
    /* 六张深查图随场景预载，深查切换无闪烁 */
    prefetchWithScene(ANOMALY_ROOM_SCENE[room], EVIDENCE_CHECK_META[room].anomalyImg);
    prefetchWithScene(ANOMALY_ROOM_SCENE[room], EVIDENCE_CHECK_META[room].normalImg);
  });
  Object.keys(EVIDENCE_SWITCH_META).forEach((actionKey) => {
    const btn = $(EVIDENCE_SWITCH_META[actionKey].btn);
    if (btn) btn.addEventListener("click", () => chooseEvidenceSwitchAction(actionKey));
  });
  paintEvidence();

  /* ============================================================
     v57 判词后果层：四后果场景 12 动作 + 责任账房 3 动作
     独立容错状态键 LEDGER_KEY（v57 唯一存储键），只持久化白名单
     canonical 字段；liability 与 pendingTarget 派生重算不落盘；
     坏 JSON/数组/错型/负数/浮点/超大数/未知键/额外键 pending/
     错映射/无结算证据/跨 cycle 全部归一。
     ============================================================ */
  const LEDGER_KEY = "goddead_v57_consequence_ledger";
  const LEDGER_KEYS = ["theatre", "quarantine", "shaft", "misbound", "ledger"];
  const LEDGER_CONSEQUENCE_KEYS = ["theatre", "quarantine", "shaft", "misbound"];
  const LEDGER_KEY_SCENE = {
    theatre: "concordance-theatre",
    quarantine: "innocent-quarantine",
    shaft: "omission-transfer-shaft",
    misbound: "misbound-handover",
    ledger: "liability-ledger",
  };
  const LEDGER_SCENE_KEY = {
    "concordance-theatre": "theatre",
    "innocent-quarantine": "quarantine",
    "omission-transfer-shaft": "shaft",
    "misbound-handover": "misbound",
    "liability-ledger": "ledger",
  };
  const LEDGER_SCENES = ["concordance-theatre", "innocent-quarantine", "omission-transfer-shaft", "misbound-handover", "liability-ledger"];
  const LEDGER_NUM_CAP = 9999;
  const LEDGER_HISTORY_CAP = 16;
  const LEDGER_SCORE_KEYS = ["concordance", "repair", "transfer", "selfBurden"];
  /* handover 房匹配的 v55 后室（无法安全恢复 → 无号层） */
  const ledgerHandoverBackroom = () => {
    const ev = getEvidence();
    return ev.handover && ANOMALY_ROOM_BACKROOM[ev.handover] ? ANOMALY_ROOM_BACKROOM[ev.handover] : "unnumbered-floor";
  };
  const LEDGER_ACTION_META = {
    theatre: {
      responseEl: "#theatre-response",
      actions: {
        "bind-testimony": { btn: "#theatre-action-bind-testimony", scores: { concordance: 2 }, target: "evidence-vault", feedback: "两份证词被压成同一枚指纹。证物库只承认它们一起存在。" },
        "preserve-dissent": { btn: "#theatre-action-preserve-dissent", scores: { concordance: 1, selfBurden: 1 }, target: "protocol-drift", feedback: "你把分歧留在卷宗里，也把解释它的责任留给自己。" },
        "substitute-witness": { btn: "#theatre-action-substitute-witness", scores: { selfBurden: 2 }, target: "misbound-handover", feedback: "镜面把你的轮廓钉在证词空位上。错绑交班开始呼叫你的名字。" },
      },
    },
    quarantine: {
      responseEl: "#quarantine-response",
      actions: {
        "release-innocent": { btn: "#quarantine-action-release-innocent", scores: { repair: 2 }, target: "unnumbered-floor", feedback: "红蜡断开以后，舱里没有病人。只有一份被你延迟承认的正常。" },
        "extend-quarantine": { btn: "#quarantine-action-extend-quarantine", scores: { transfer: 2 }, target: "false-positive-shaft", feedback: "你把怀疑续签给一个空舱。误报井替你保管了它。" },
        "stand-in": { btn: "#quarantine-action-stand-in", scores: { repair: 1, selfBurden: 1 }, target: "misbound-handover", feedback: "空工服接受了你的号牌。它没有获释，只是换成你被留置。" },
      },
    },
    shaft: {
      responseEl: "#omission-response",
      actions: {
        "descend-after": { btn: "#shaft-action-descend-after", scores: { repair: 2 }, dynamic: "handoverBackroom", feedback: "你跟着漏掉的症状下井。它在原房间的背面等你补签。" },
        "transfer-omission": { btn: "#shaft-action-transfer-omission", scores: { transfer: 2 }, target: "blank-receipt-press", feedback: "移交单没有收件人。空白回执仍替你签收了这次漏报。" },
        "seal-omission": { btn: "#shaft-action-seal-omission", scores: { concordance: 1, transfer: 1 }, target: "evidence-vault", feedback: "你封住了井口，也封住了谁本应看见它。证物库收下一只仍在下坠的箱子。" },
      },
    },
    misbound: {
      responseEl: "#misbound-response",
      actions: {
        "admit-misbind": { btn: "#misbound-action-admit-misbind", scores: { selfBurden: 2 }, dynamic: "handoverBackroom", feedback: "你承认正确的结论绑错了证人。后室把责任和你一起叫回去。" },
        "reassign-empty": { btn: "#misbound-action-reassign-empty", scores: { transfer: 2 }, target: "blank-name-cloakroom", feedback: "空名接过了手铐。它从来没有出现过，所以最适合承担证明。" },
        "break-cuffs": { btn: "#misbound-action-break-cuffs", scores: { repair: 1, selfBurden: 1 }, target: "protocol-drift", feedback: "链断了，绑定却没有消失。守则开始重写“证人”的定义。" },
      },
    },
    ledger: {
      responseEl: "#ledger-response",
      actions: {
        "return-verdict": { btn: "#ledger-action-return-verdict", scores: { concordance: 1 } },
        "sign-self": { btn: "#ledger-action-sign-self", scores: { selfBurden: 2 } },
        "assign-vacancy": { btn: "#ledger-action-assign-vacancy", scores: { transfer: 2 } },
      },
    },
  };
  const LEDGER_ACTION_SCENE = {};
  Object.keys(LEDGER_ACTION_META).forEach((k) => {
    Object.keys(LEDGER_ACTION_META[k].actions).forEach((a) => { LEDGER_ACTION_SCENE[a] = k; });
  });
  const LEDGER_ACTION_KEYS = Object.keys(LEDGER_ACTION_SCENE);
  const LEDGER_DEFERRED_POOL = ["evidence-vault", "false-positive-shaft", "protocol-drift", "unnumbered-floor", "blank-receipt-press", "blank-name-cloakroom", "underbed-call-station", "countersign-drain", "negative-laundry-locker", "misbound-handover"];
  /* 责任账逐字反馈（结算后责任值插值，重算可复现） */
  const ledgerFeedback = (actionKey, target, liability) => {
    if (actionKey === "return-verdict") return `责任值 ${liability}。原判被退回你留下的那条路。账房替你销了一页。`;
    if (actionKey === "sign-self") {
      return target === "evidence-vault"
        ? `责任值 ${liability}。你把判决签回自己身上。证物库承认这副肩膀。`
        : `责任值 ${liability}。你把判决签回自己身上。还不够重的那部分，由后室认领。`;
    }
    return target === "false-positive-shaft"
      ? `责任值 ${liability}。空席接住了这份判决。误报井承认它早就该来。`
      : `责任值 ${liability}。空席接住了这份判决。空名寄存处为它留了位置。`;
  };
  /* 账房动作的目标由点击前责任值决定：接受时先加分再落盘 */
  const ledgerActionTarget = (st, actionKey, preLiability) => {
    if (actionKey === "return-verdict") {
      return st.deferredTarget !== "" ? st.deferredTarget : (preLiability >= 0 ? "evidence-vault" : "false-positive-shaft");
    }
    if (actionKey === "sign-self") {
      return preLiability >= 4 ? "evidence-vault" : ledgerHandoverBackroom();
    }
    return preLiability <= -2 ? "false-positive-shaft" : "blank-name-cloakroom";
  };
  /* 分值触顶 9999 时固定增量反推会失真，故账房结算把点击前责任值记入
     canonical history 末项的 pre；校验时用它重算目标，并与落盘分值交叉核对——
     post−pre 必须落在固定增量区间内，短于增量时必须由受影响分值触顶解释 */
  const LEDGER_LIABILITY_DELTA = { "return-verdict": 1, "sign-self": 2, "assign-vacancy": -4 };
  const LEDGER_DELTA_SCORE = { "return-verdict": "concordance", "sign-self": "selfBurden", "assign-vacancy": "transfer" };
  const LEDGER_LIABILITY_MIN = -2 * LEDGER_NUM_CAP;
  const LEDGER_LIABILITY_MAX = 3 * LEDGER_NUM_CAP;

  const getLedger = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(LEDGER_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(LEDGER_NUM_CAP, Math.floor(n));
    };
    const flag = (v) => (v === 1 || v === true ? 1 : 0);
    /* cycle 对齐 v35：floor cycle 变化只重置 settled 与 pending，累计保留 */
    const floorCycle = getFloor().cycle;
    const sameCycle = num(raw.cycle) === floorCycle;
    const cycle = floorCycle;
    const scores = {};
    LEDGER_SCORE_KEYS.forEach((k) => { scores[k] = num(raw.scores && raw.scores[k]); });
    const visits = {};
    const settled = {};
    LEDGER_KEYS.forEach((k) => {
      visits[k] = num(raw.visits && raw.visits[k]);
      settled[k] = sameCycle ? flag(raw.settled && raw.settled[k]) : 0;
    });
    const actions = {};
    LEDGER_ACTION_KEYS.forEach((a) => { actions[a] = num(raw.actions && raw.actions[a]); });
    const deferredTarget = LEDGER_DEFERRED_POOL.includes(raw.deferredTarget) ? raw.deferredTarget : "";
    /* history 有界：仅保留白名单形状条目，最多 16 条（先解析，pending 证明依赖它） */
    let history = [];
    if (Array.isArray(raw.history)) {
      for (const h of raw.history) {
        if (!h || typeof h !== "object" || Array.isArray(h)) continue;
        if (h.type === "action" && LEDGER_KEYS.includes(h.scene) && LEDGER_ACTION_META[h.scene].actions[h.action]) {
          const entry = { type: "action", scene: h.scene, action: h.action };
          /* 账房条目可携带点击前责任值 pre（饱和交叉校验用）；非整数/越界即剥除 */
          if (h.scene === "ledger" && Number.isInteger(h.pre) && h.pre >= LEDGER_LIABILITY_MIN && h.pre <= LEDGER_LIABILITY_MAX) entry.pre = h.pre;
          history.push(entry);
        }
      }
    }
    history = history.slice(-LEDGER_HISTORY_CAP);
    /* pending 严格白名单：恰好六键 {action,cycle,feedback,kind,scene,target}（额外键即
       伪造）；target/feedback 逐字重算（账房阈值经 history 末项 pre 交叉校验、后果改道
       经 deferredTarget 证明）；结算证据 settled[scene]===1 且 actions[action]>=1
       + canonical history 末项 + cycle 一致 */
    let pending = null;
    if (sameCycle && raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const p = raw.pending;
      const last = history.length ? history[history.length - 1] : null;
      if (p.kind === "action" && Object.keys(p).sort().join(",") === "action,cycle,feedback,kind,scene,target"
        && LEDGER_KEYS.includes(p.scene) && LEDGER_ACTION_META[p.scene].actions[p.action]
        && settled[p.scene] === 1 && actions[p.action] >= 1 && num(p.cycle) === cycle
        && last && last.type === "action" && last.scene === p.scene && last.action === p.action) {
        const st = { scores, deferredTarget, liability: scores.concordance + scores.repair + scores.selfBurden - 2 * scores.transfer };
        if (p.scene === "ledger") {
          /* 点击前责任值只信 canonical history 末项的 pre 并交叉核对：
             post−pre 落在固定增量区间内；短于增量时受影响分值必须已触顶，
             否则（含无 pre 的旧条目/被剥除的脏 pre）一律视为伪造 */
          const delta = LEDGER_LIABILITY_DELTA[p.action];
          const gap = st.liability - last.pre;
          const proven = Number.isInteger(last.pre)
            && (delta > 0 ? (gap >= 0 && gap <= delta) : (gap <= 0 && gap >= delta))
            && (gap === delta || scores[LEDGER_DELTA_SCORE[p.action]] === LEDGER_NUM_CAP);
          if (proven) {
            const target = ledgerActionTarget(st, p.action, last.pre);
            const feedback = ledgerFeedback(p.action, target, st.liability);
            if (p.target === target && p.feedback === feedback) {
              pending = { kind: "action", scene: "ledger", action: p.action, target, feedback, cycle };
            }
          }
        } else {
          const meta = LEDGER_ACTION_META[p.scene].actions[p.action];
          const normalTarget = meta.dynamic === "handoverBackroom" ? ledgerHandoverBackroom() : meta.target;
          /* 第三不同后果场景首次结算的改道证明：deferredTarget 正是本动作原目的地 */
          const distinct = LEDGER_CONSEQUENCE_KEYS.filter((k) => Object.keys(LEDGER_ACTION_META[k].actions).some((a) => actions[a] > 0)).length;
          const defer = distinct >= 3 && visits.ledger === 0 && deferredTarget !== "" && deferredTarget === normalTarget;
          const target = defer ? "liability-ledger" : normalTarget;
          if (p.target === target && p.feedback === meta.feedback) {
            pending = { kind: "action", scene: p.scene, action: p.action, target, feedback: meta.feedback, cycle };
          }
        }
      }
    }
    /* 派生：liability 与 pendingTarget 只重算，不落盘 */
    const liability = scores.concordance + scores.repair + scores.selfBurden - 2 * scores.transfer;
    return {
      cycle, scores, visits, settled, actions, deferredTarget, pending,
      pendingTarget: pending ? pending.target : "", history, liability,
    };
  };
  /* 只持久化白名单 canonical 字段；派生字段永不落盘，history 先裁后存 */
  const saveLedger = (st) => store.set(LEDGER_KEY, JSON.stringify({
    cycle: st.cycle,
    scores: st.scores,
    visits: st.visits,
    settled: st.settled,
    actions: st.actions,
    deferredTarget: st.deferredTarget,
    pending: st.pending,
    history: st.history.slice(-LEDGER_HISTORY_CAP),
  }));

  const ledgerActive = (st) =>
    LEDGER_SCORE_KEYS.some((k) => st.scores[k] > 0) || LEDGER_KEYS.some((k) => st.visits[k] > 0);

  /* 责任签：四项分值 + 责任值 + 五场景本轮结清态 */
  const paintLedger = () => {
    const st = getLedger();
    $$("[data-ledger-concordance]").forEach((el) => { el.textContent = st.scores.concordance; });
    $$("[data-ledger-repair]").forEach((el) => { el.textContent = st.scores.repair; });
    $$("[data-ledger-transfer]").forEach((el) => { el.textContent = st.scores.transfer; });
    $$("[data-ledger-selfburden]").forEach((el) => { el.textContent = st.scores.selfBurden; });
    $$("[data-ledger-liability]").forEach((el) => { el.textContent = st.liability; });
    LEDGER_KEYS.forEach((k) => {
      $$(`[data-ledger-settled="${k}"]`).forEach((el) => { el.textContent = st.settled[k] === 1 ? "已结清" : "未结清"; });
    });
  };

  /* 转场 before 通用尾件：原子记 visit/visited 再清 pending（避开守卫竞争） */
  const ledgerBeforeArrive = (target) => {
    const s = getLedger();
    if (LEDGER_SCENE_KEY[target] && s.visits[LEDGER_SCENE_KEY[target]] === 0) s.visits[LEDGER_SCENE_KEY[target]] = 1;
    if (s.pending) s.pending = null;
    saveLedger(s);
    if (target === "evidence-vault") markReviewVisited("evidence-vault");
    if (target === "false-positive-shaft") markReviewVisited("false-positive-shaft");
    if (ANOMALY_SCENE_BACKROOM[target]) grantAnomalyBackroomVisit(target);
    syncLedgerLinks();
    paintLedgerMemory();
  };

  /* v56 前插路径的 visit 授予（交班/编组 before 调用，与 v55 同款契约） */
  const grantLedgerVisit = (sceneName) => {
    const key = LEDGER_SCENE_KEY[sceneName];
    if (!key) return;
    const st = getLedger();
    if (st.visits[key] === 0) {
      st.visits[key] = 1;
      saveLedger(st);
      syncLedgerLinks();
    }
  };

  /* 后果动作：live scene + 共享 first-lock；导航常开，分值每场景每 cycle 只结算
     首次；第三不同后果场景首次结算时暂存原目的地并改道责任账房（每存档一次） */
  const chooseConsequenceAction = (sceneKey, actionKey) => {
    const meta = LEDGER_ACTION_META[sceneKey] && LEDGER_ACTION_META[sceneKey].actions[actionKey];
    if (!meta) return;
    const sceneName = LEDGER_KEY_SCENE[sceneKey];
    if (currentScene !== sceneName) return;
    if (AutoAdvance.has(sceneName)) return;
    const st = getLedger();
    let target = meta.dynamic === "handoverBackroom" ? ledgerHandoverBackroom() : meta.target;
    if (st.settled[sceneKey] === 0) {
      st.settled[sceneKey] = 1;
      Object.keys(meta.scores).forEach((k) => { st.scores[k] = Math.min(LEDGER_NUM_CAP, st.scores[k] + meta.scores[k]); });
      st.actions[actionKey] = Math.min(LEDGER_NUM_CAP, st.actions[actionKey] + 1);
      st.history.push({ type: "action", scene: sceneKey, action: actionKey });
      const distinct = LEDGER_CONSEQUENCE_KEYS.filter((k) => Object.keys(LEDGER_ACTION_META[k].actions).some((a) => st.actions[a] > 0)).length;
      if (distinct >= 3 && st.visits.ledger === 0 && st.deferredTarget === "") {
        st.deferredTarget = target;
        target = "liability-ledger";
      }
      st.pending = { kind: "action", scene: sceneKey, action: actionKey, target, feedback: meta.feedback, cycle: st.cycle };
      saveLedger(st);
    }
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $(LEDGER_ACTION_META[sceneKey].responseEl);
    if (responseEl) responseEl.textContent = meta.feedback;
    AudioEngine.knock(0.16);
    paintLedger();
    AutoAdvance.schedule(sceneName, target, {
      delay: branchDelay(),
      before: () => ledgerBeforeArrive(target),
    });
  };

  /* 责任账动作：目标由点击前责任值决定，反馈逐字带结算后责任值与落点理由；
     return-verdict 有合法 deferredTarget 时回它并在到达时清空 */
  const chooseLedgerAction = (actionKey) => {
    const meta = LEDGER_ACTION_META.ledger.actions[actionKey];
    if (!meta) return;
    if (currentScene !== "liability-ledger") return;
    if (AutoAdvance.has("liability-ledger")) return;
    const st = getLedger();
    const target = ledgerActionTarget(st, actionKey, st.liability);
    let feedback;
    if (st.settled.ledger === 0) {
      st.settled.ledger = 1;
      Object.keys(meta.scores).forEach((k) => { st.scores[k] = Math.min(LEDGER_NUM_CAP, st.scores[k] + meta.scores[k]); });
      st.actions[actionKey] = Math.min(LEDGER_NUM_CAP, st.actions[actionKey] + 1);
      st.history.push({ type: "action", scene: "ledger", action: actionKey, pre: st.liability });
      const postLiability = st.scores.concordance + st.scores.repair + st.scores.selfBurden - 2 * st.scores.transfer;
      feedback = ledgerFeedback(actionKey, target, postLiability);
      st.pending = { kind: "action", scene: "ledger", action: actionKey, target, feedback, cycle: st.cycle };
      saveLedger(st);
    } else {
      feedback = ledgerFeedback(actionKey, target, st.liability);
    }
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $("#ledger-response");
    if (responseEl) responseEl.textContent = feedback;
    AudioEngine.knock(0.16);
    paintLedger();
    AutoAdvance.schedule("liability-ledger", target, {
      delay: branchDelay(),
      before: () => {
        if (actionKey === "return-verdict") {
          const s = getLedger();
          s.deferredTarget = "";
          saveLedger(s);
        }
        ledgerBeforeArrive(target);
      },
    });
  };

  /* reload 节拍恢复：合法 pending 属于当前场景时重播逐字反馈并精确重挂一次 */
  const replayLedgerPending = (sceneName) => {
    const st = getLedger();
    const p = st.pending;
    if (!p || LEDGER_KEY_SCENE[p.scene] !== sceneName) return;
    const responseEl = $(LEDGER_ACTION_META[p.scene].responseEl);
    if (responseEl) responseEl.textContent = p.feedback;
    AutoAdvance.schedule(sceneName, p.target, {
      delay: branchDelay(),
      before: () => {
        if (p.action === "return-verdict") {
          const s = getLedger();
          s.deferredTarget = "";
          saveLedger(s);
        }
        ledgerBeforeArrive(p.target);
      },
    });
  };

  /* 五场景进入：幂等补记 visit（before 已原子记录为主）、清响应、刷签 */
  const enterLedgerScene = (sceneName) => {
    const key = LEDGER_SCENE_KEY[sceneName];
    if (!key) return;
    grantLedgerVisit(sceneName);
    const responseEl = $(LEDGER_ACTION_META[key].responseEl);
    if (responseEl) responseEl.textContent = "";
    paintLedger();
  };

  const LEDGER_LINKS = { theatre: "#theatre-link", quarantine: "#quarantine-link", shaft: "#omission-link", misbound: "#misbound-link", ledger: "#ledger-link" };
  const syncLedgerLinks = () => {
    const st = getLedger();
    LEDGER_KEYS.forEach((k) => {
      const link = $(LEDGER_LINKS[k]);
      if (!link) return;
      if (st.visits[k] > 0) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  /* 痕迹页单行：责任账五项，保持八张统计卡不变 */
  const paintLedgerMemory = () => {
    const memory = $("#consequence-ledger-memory");
    if (!memory) return;
    const st = getLedger();
    if (!ledgerActive(st)) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `责任账：共证 ${st.scores.concordance}，修复 ${st.scores.repair}，转嫁 ${st.scores.transfer}，自担 ${st.scores.selfBurden}，责任值 ${st.liability}。`;
    memory.hidden = false;
  };

  /* v57 合成守卫：15 动作监听只接受真实用户产生的 click（isTrusted）——
     合成 HTMLElement.click() 在 active 场景同样零副作用；
     鼠标/触控/Tab+Enter/Space 与 CDP page.click 均派发 trusted click，不受影响 */
  LEDGER_CONSEQUENCE_KEYS.forEach((sceneKey) => {
    Object.keys(LEDGER_ACTION_META[sceneKey].actions).forEach((actionKey) => {
      const btn = $(LEDGER_ACTION_META[sceneKey].actions[actionKey].btn);
      if (btn) btn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseConsequenceAction(sceneKey, actionKey); });
    });
  });
  Object.keys(LEDGER_ACTION_META.ledger.actions).forEach((actionKey) => {
    const btn = $(LEDGER_ACTION_META.ledger.actions[actionKey].btn);
    if (btn) btn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseLedgerAction(actionKey); });
  });
  paintLedger();

  /* ============================================================
     v58 异议总署：总署 hub + 三复核室 9 动作 + 结案纯函数路由
     独立容错状态键 APPEAL_KEY（v58 唯一存储键），只持久化白名单
     canonical 字段（version/cycle/visits/history/pending）；
     objection/precedent/contamination、已结算房间、可否结案、
     v57 profile（dominantResponsibility/liability/最近后果房）与
     最终 target 全部由可信 history 与当前合法 v57 状态重算，
     永不落盘。坏 JSON/错版本/额外键/错 cycle/错 action/跨字段
     伪造全部归一；pending 逐字重算 target/feedback，只消费一次。
     ============================================================ */
  const APPEAL_KEY = "goddead_v58_appeal";
  const APPEAL_VERSION = 58;
  const APPEAL_NUM_CAP = 9999;
  const APPEAL_HISTORY_CAP = 16;
  const APPEAL_SCORE_KEYS = ["objection", "precedent", "contamination"];
  const APPEAL_ROOM_KEYS = ["identity", "evidence", "destination"];
  const APPEAL_VISIT_KEYS = ["registry", "identity", "evidence", "destination"];
  const APPEAL_KEY_SCENE = {
    registry: "appeal-registry",
    identity: "identity-correction",
    evidence: "evidence-contradiction",
    destination: "destination-review-shaft",
  };
  const APPEAL_SCENE_KEY = {
    "appeal-registry": "registry",
    "identity-correction": "identity",
    "evidence-contradiction": "evidence",
    "destination-review-shaft": "destination",
  };
  const APPEAL_SCENES = ["appeal-registry", "identity-correction", "evidence-contradiction", "destination-review-shaft"];
  const APPEAL_ACTION_META = {
    identity: {
      responseEl: "#identity-response",
      actions: {
        "accept-subject": { btn: "#identity-action-accept-subject", scores: { precedent: 2 } },
        "substitute-subject": { btn: "#identity-action-substitute-subject", scores: { objection: 1, contamination: 1 } },
        "erase-subject": { btn: "#identity-action-erase-subject", scores: { objection: 2, contamination: 1 } },
      },
    },
    evidence: {
      responseEl: "#contradiction-response",
      actions: {
        "merge-records": { btn: "#contradiction-action-merge-records", scores: { precedent: 2 } },
        "preserve-conflict": { btn: "#contradiction-action-preserve-conflict", scores: { objection: 2 } },
        "destroy-copy": { btn: "#contradiction-action-destroy-copy", scores: { contamination: 2, precedent: 1 } },
      },
    },
    destination: {
      responseEl: "#destination-response",
      actions: {
        "return-origin": { btn: "#destination-action-return-origin", scores: { objection: 2 } },
        "assign-vacancy": { btn: "#destination-action-assign-vacancy", scores: { precedent: 2, contamination: 1 } },
        "drop-below-map": { btn: "#destination-action-drop-below-map", scores: { contamination: 2 } },
      },
    },
  };
  const APPEAL_RETURN_BTN = { identity: "#identity-return-registry", evidence: "#contradiction-return-registry", destination: "#destination-return-registry" };
  const APPEAL_HUB_META = {
    identity: { btn: "#appeal-enter-identity", feedback: "身份装置的电话先响了。勘误室接听你的责任簿。" },
    evidence: { btn: "#appeal-enter-evidence", feedback: "双份卷宗同时摊开。对照库只问哪一页先说谎。" },
    destination: { btn: "#appeal-enter-destination", feedback: "三路分发台的指针各偏一格。复核井等你选一条轨。" },
  };
  const APPEAL_ENTRY_FEEDBACK = "封签断开。异议总署收下你的责任簿，三本索引同时翻开。";
  const APPEAL_CLOSE_LOCKED_FEEDBACK = "锁链还压着账本：任意两间复核室结清后，印才会松。";
  /* 历史回响：平局时 dominantResponsibility 的固定优先顺序（文档化，不可改序） */
  const APPEAL_DOMINANT_ORDER = ["selfBurden", "transfer", "repair", "concordance"];
  const APPEAL_DOMINANT_LABEL = { concordance: "共证", repair: "修复", transfer: "转嫁", selfBurden: "自担", none: "无" };
  const APPEAL_LASTROOM_LABEL = { theatre: "共证剧场", quarantine: "无辜留置舱", shaft: "漏报移交井", misbound: "错绑交班台" };
  /* v57 profile 完全由合法 v57 canonical 状态派生：dominant（平局按固定顺序）、
     liability、最近一次后果房、入口资格（≥3 不同后果房结算 + ≥1 账房动作结算） */
  const appealProfile = () => {
    const l = getLedger();
    let dominant = "none";
    let best = 0;
    APPEAL_DOMINANT_ORDER.forEach((k) => { if (l.scores[k] > best) { best = l.scores[k]; dominant = k; } });
    let lastRoom = "";
    for (let i = l.history.length - 1; i >= 0; i--) {
      const h = l.history[i];
      if (h.type === "action" && LEDGER_CONSEQUENCE_KEYS.includes(h.scene)) { lastRoom = h.scene; break; }
    }
    const distinct = LEDGER_CONSEQUENCE_KEYS.filter((k) => Object.keys(LEDGER_ACTION_META[k].actions).some((a) => l.actions[a] > 0)).length;
    const ledgerActions = ["return-verdict", "sign-self", "assign-vacancy"].reduce((n, a) => n + l.actions[a], 0);
    const eligible = distinct >= 3 && ledgerActions >= 1;
    return { dominant, liability: l.liability, lastRoom, eligible };
  };
  /* 三房动作逐字反馈：每房至少一条按 v57 profile 真实变化 */
  const appealActionFeedback = (room, action, profile) => {
    if (room === "identity") {
      if (action === "accept-subject") return "名牌嵌进证人椅。先例不需要脸，只需要一个被承认坐过的位置。";
      if (action === "substitute-subject") return "裂镜把你的轮廓试进空制服。制服合身的那一刻，证词开始认错人。";
      if (profile.dominant === "concordance") return "你拨通电话，让共证过的声音亲口否认那张肖像。空画框收下一段被撤回的同台。";
      if (profile.dominant === "repair") return "你拨通电话，逐条报出你修过的记录，把肖像从墙上请了下来。空画框记得这双手。";
      if (profile.dominant === "transfer") return "你拨通电话，把肖像的存在说成别人的误会。空画框替你挂断了电话。";
      if (profile.dominant === "selfBurden") return "你拨通电话，用自己的名字换下肖像的编号。空画框从此归你保管。";
      return "电话接通又挂断。空肖像没有等来去电，只剩一圈拨号音。";
    }
    if (room === "evidence") {
      if (action === "merge-records") return "错位玻璃被压到同一刻度。两页对照片合成一份先例，裂缝归进注释。";
      if (action === "destroy-copy") return "污卷宗送进焚盘。灰被称重归档：先例多了一页，污染多了一撮。";
      if (profile.lastRoom === "theatre") return "白卷宗保持空白。共证剧场同台过的两份证词，在这里被允许继续不一致。";
      if (profile.lastRoom === "quarantine") return "白卷宗保持空白。无辜留置舱教过你：写满不一定等于写对。";
      if (profile.lastRoom === "shaft") return "白卷宗保持空白。漏报移交井里那只下坠的箱子提醒你，缺页也是一种记录。";
      if (profile.lastRoom === "misbound") return "白卷宗保持空白。错绑交班台拆开过的结，不该在这里重新绑死。";
      return "白卷宗保持空白。没有后果房为它作保，空白本身就是证词。";
    }
    if (action === "return-origin") return "回程轮轨倒转半圈。封箱被退回出发的一侧，异议随箱原路返回。";
    if (action === "drop-below-map") return "断轨尽头的落井杆被压下。封箱坠到地图以下，污染沉入没有编号的深度。";
    return profile.liability >= 0
      ? `悬吊封箱挂上新的去向牌。你的责任值 ${profile.liability} 非负，空位承认这次指派有效。`
      : `悬吊封箱挂上新的去向牌。责任值 ${profile.liability} 为负，空位先收下箱子，再向你追认指派。`;
  };
  /* 结案路由：纯函数，点击前分值决定目标（2/2/2 特殊平衡仅限三房全完成） */
  const appealCloseTarget = (scores, settledCount, liability, lastRoom) => {
    const o = scores.objection;
    const p = scores.precedent;
    const c = scores.contamination;
    if (settledCount === 3 && o === p && p === c && o > 0) return "unnumbered-floor";
    if (p > o && p > c) return liability >= 0 ? "concordance-theatre" : "misbound-handover";
    if (o > p && o > c) return (lastRoom === "quarantine" || lastRoom === "shaft") ? "protocol-drift" : "evidence-vault";
    if (c > o && c > p) return liability < 0 ? "false-positive-shaft" : "omission-transfer-shaft";
    if (o === p && o > c) return "liability-ledger";
    if (o === c && o > p) return "blank-name-cloakroom";
    if (p === c && p > o) return "misbound-handover";
    return "liability-ledger";
  };
  /* 结案反馈：说清哪类异议占上风 + 为什么被送到该处（逐字重算可复现） */
  const appealCloseFeedback = (target, scores, profile) => {
    const o = scores.objection;
    const p = scores.precedent;
    const c = scores.contamination;
    const L = profile.liability;
    if (target === "unnumbered-floor") return `三类异议完全拉平（各 ${o} 点），没有一类占上风。总署拒绝归类，结案送去无号层——唯一不编号的楼层。`;
    if (target === "concordance-theatre") return `先例异议占上风（先例 ${p} 点压过其余），责任值 ${L} 非负。先例需要同台复核，结案送去共证剧场。`;
    if (target === "misbound-handover" && p > o && p > c) return `先例异议占上风（先例 ${p} 点），但责任值 ${L} 为负。先例绑错了承担者，结案退回错绑交班台。`;
    if (target === "misbound-handover") return `先例与污染各 ${p} 点拉平、压过异议。占上风者拒绝单独署名，结案退回错绑交班台。`;
    if (target === "protocol-drift") return `异议占上风（异议 ${o} 点），最近结清的${APPEAL_LASTROOM_LABEL[profile.lastRoom]}留下程序疑点。结案移交守则漂移，由守则重写自己。`;
    if (target === "evidence-vault") return `异议占上风（异议 ${o} 点），没有程序疑点随案。结案按原证据链退回异常保全。`;
    if (target === "false-positive-shaft") return `污染占上风（污染 ${c} 点），责任值 ${L} 为负。污染被怀疑本是误报，结案坠入误报回收井。`;
    if (target === "omission-transfer-shaft") return `污染占上风（污染 ${c} 点），责任值 ${L} 非负。污染按漏报流程移交，结案沉入漏报移交井。`;
    if (target === "blank-name-cloakroom") return `异议与污染各 ${o} 点拉平、压过先例。两类都不愿署名，结案寄存到空名寄存处。`;
    if (o === p && o > c) return `异议与先例各 ${o} 点拉平、压过污染。没有单一占上风者，结案退回责任账房重秤。`;
    return "三类异议无法裁定占上风者。结案退回责任账房，由账本重新过秤。";
  };
  /* 总署说明：资格齐备时按 v57 profile 变化，否则安全中性渲染（不伪造资格） */
  const appealHubDesc = (profile) => profile.eligible
    ? `责任簿已受理：${APPEAL_DOMINANT_LABEL[profile.dominant]}在你的后果账上占上风（责任值 ${profile.liability}），最近结清的是${APPEAL_LASTROOM_LABEL[profile.lastRoom]}。左侧身份装置、中左双份卷宗、右侧三路分发台各归一类异议；锁链账本在任意两间结清后开印。`
    : "判决生效之后，异议才成立。总署只受理已经结清的后果；你的责任簿上还没有可复核的记录。";

  const getAppeal = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(APPEAL_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    /* 错版本整体丢弃：v58 之前的任何同键内容一律不算数 */
    if (raw.version !== APPEAL_VERSION) raw = {};
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(APPEAL_NUM_CAP, Math.floor(n));
    };
    /* cycle 对齐 v35：跨 cycle 的 history 条目保留但不参与本轮派生 */
    const cycle = getFloor().cycle;
    const sameCycle = num(raw.cycle) === cycle;
    const visits = {};
    APPEAL_VISIT_KEYS.forEach((k) => { visits[k] = num(raw.visits && raw.visits[k]); });
    /* history 有界白名单：entry/close/action 三种形状，最多 16 条 */
    let history = [];
    if (Array.isArray(raw.history)) {
      for (const h of raw.history) {
        if (!h || typeof h !== "object" || Array.isArray(h)) continue;
        if (h.type === "entry" || h.type === "close") {
          history.push({ type: h.type, cycle: num(h.cycle) });
        } else if (h.type === "action" && APPEAL_ROOM_KEYS.includes(h.room) && APPEAL_ACTION_META[h.room].actions[h.action]) {
          history.push({ type: "action", room: h.room, action: h.action, cycle: num(h.cycle) });
        }
      }
    }
    history = history.slice(-APPEAL_HISTORY_CAP);
    /* 派生（永不落盘）：本轮分值 / 已结算房间 / 可否结案，同一房间同一 cycle
       只计首次；伪造的重复条目由 !settled 守卫挡下 */
    const scores = { objection: 0, precedent: 0, contamination: 0 };
    const settled = { identity: false, evidence: false, destination: false };
    history.forEach((h) => {
      if (h.type === "action" && h.cycle === cycle && !settled[h.room]) {
        settled[h.room] = true;
        const sc = APPEAL_ACTION_META[h.room].actions[h.action].scores;
        Object.keys(sc).forEach((k) => { scores[k] = Math.min(APPEAL_NUM_CAP, scores[k] + sc[k]); });
      }
    });
    const settledCount = APPEAL_ROOM_KEYS.filter((k) => settled[k]).length;
    const profile = appealProfile();
    /* pending 严格白名单：entry/close 恰好五键、action 恰好六键（额外键即伪造）；
       target/feedback 逐字重算；结算证据 = canonical history 末项一致 + cycle 一致
       + 当前派生资格（入口须 v57 资格仍在，结案须本轮仍满两间） */
    let pending = null;
    if (sameCycle && raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const p = raw.pending;
      const keys = Object.keys(p).sort().join(",");
      const last = history.length ? history[history.length - 1] : null;
      if (p.kind === "entry" && keys === "cycle,feedback,kind,scene,target"
        && p.scene === "liability-ledger" && num(p.cycle) === cycle
        && profile.eligible
        && last && last.type === "entry" && last.cycle === cycle
        && p.target === "appeal-registry" && p.feedback === APPEAL_ENTRY_FEEDBACK) {
        pending = { kind: "entry", scene: "liability-ledger", target: "appeal-registry", feedback: APPEAL_ENTRY_FEEDBACK, cycle };
      } else if (p.kind === "action" && keys === "action,cycle,feedback,kind,scene,target"
        && APPEAL_ROOM_KEYS.includes(APPEAL_SCENE_KEY[p.scene])
        && APPEAL_ACTION_META[APPEAL_SCENE_KEY[p.scene]].actions[p.action]
        && num(p.cycle) === cycle
        && last && last.type === "action" && last.room === APPEAL_SCENE_KEY[p.scene] && last.action === p.action && last.cycle === cycle
        && settled[APPEAL_SCENE_KEY[p.scene]]) {
        const feedback = appealActionFeedback(APPEAL_SCENE_KEY[p.scene], p.action, profile);
        if (p.target === "appeal-registry" && p.feedback === feedback) {
          pending = { kind: "action", scene: p.scene, action: p.action, target: "appeal-registry", feedback, cycle };
        }
      } else if (p.kind === "close" && keys === "cycle,feedback,kind,scene,target"
        && p.scene === "appeal-registry" && num(p.cycle) === cycle
        && settledCount >= 2
        && last && last.type === "close" && last.cycle === cycle) {
        const target = appealCloseTarget(scores, settledCount, profile.liability, profile.lastRoom);
        const feedback = appealCloseFeedback(target, scores, profile);
        if (p.target === target && p.feedback === feedback) {
          pending = { kind: "close", scene: "appeal-registry", target, feedback, cycle };
        }
      }
    }
    return {
      cycle, visits, history, pending, scores, settled, settledCount,
      pendingTarget: pending ? pending.target : "",
    };
  };
  /* 只持久化白名单 canonical 字段；派生字段永不落盘，history 先裁后存 */
  const saveAppeal = (st) => store.set(APPEAL_KEY, JSON.stringify({
    version: APPEAL_VERSION,
    cycle: st.cycle,
    visits: st.visits,
    pending: st.pending,
    history: st.history.slice(-APPEAL_HISTORY_CAP),
  }));

  const appealActive = (st) => APPEAL_VISIT_KEYS.some((k) => st.visits[k] > 0) || st.history.length > 0;

  /* 异议签：三类分值 + 已复核间数 + 每房本轮结清态 + 结案开印态 */
  const paintAppeal = () => {
    const st = getAppeal();
    $$("[data-appeal-objection]").forEach((el) => { el.textContent = st.scores.objection; });
    $$("[data-appeal-precedent]").forEach((el) => { el.textContent = st.scores.precedent; });
    $$("[data-appeal-contamination]").forEach((el) => { el.textContent = st.scores.contamination; });
    $$("[data-appeal-settled-count]").forEach((el) => { el.textContent = `${st.settledCount}/3`; });
    APPEAL_ROOM_KEYS.forEach((k) => {
      $$(`[data-appeal-room="${k}"]`).forEach((el) => { el.textContent = st.settled[k] ? "已结清" : "未结清"; });
    });
    const canClose = st.settledCount >= 2;
    $$("[data-appeal-close]").forEach((el) => { el.textContent = canClose ? "可开印" : "待两间"; });
    const closeBtn = $("#appeal-close");
    if (closeBtn) closeBtn.setAttribute("aria-disabled", canClose ? "false" : "true");
  };

  /* 入口封签：只在责任账房复访且 v57 资格齐备时显露（资格纯派生，不可伪造） */
  const syncAppealSeal = () => {
    const seal = $("#ledger-appeal-seal");
    if (!seal) return;
    if (appealProfile().eligible) seal.removeAttribute("hidden");
    else seal.setAttribute("hidden", "");
  };

  /* 转场 before 通用尾件：原子记 visit 再清 pending，并补齐目标场景的旧守卫凭证 */
  const appealBeforeArrive = (target) => {
    const s = getAppeal();
    if (APPEAL_SCENE_KEY[target] && s.visits[APPEAL_SCENE_KEY[target]] === 0) s.visits[APPEAL_SCENE_KEY[target]] = 1;
    if (s.pending) s.pending = null;
    saveAppeal(s);
    if (LEDGER_SCENE_KEY[target]) grantLedgerVisit(target);
    if (target === "evidence-vault") markReviewVisited("evidence-vault");
    if (target === "false-positive-shaft") markReviewVisited("false-positive-shaft");
    syncAppealLinks();
    paintAppealMemory();
  };

  /* 入口节拍：只记 v58 入口，不改 v57 任何分值；一拍后自动到总署 */
  const chooseAppealEntry = () => {
    if (currentScene !== "liability-ledger") return;
    if (AutoAdvance.has("liability-ledger")) return;
    if (!appealProfile().eligible) return;
    const st = getAppeal();
    st.history.push({ type: "entry", cycle: st.cycle });
    st.pending = { kind: "entry", scene: "liability-ledger", target: "appeal-registry", feedback: APPEAL_ENTRY_FEEDBACK, cycle: st.cycle };
    saveAppeal(st);
    const btn = $("#ledger-appeal-seal");
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $("#ledger-response");
    if (responseEl) responseEl.textContent = APPEAL_ENTRY_FEEDBACK;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule("liability-ledger", "appeal-registry", {
      delay: branchDelay(),
      before: () => appealBeforeArrive("appeal-registry"),
    });
  };

  /* 复核动作：首次一拍计分并自动回总署；同 cycle 复访只重播反馈、不二次计分、
     不自动转场（回总署走画面内回总署热点） */
  const chooseAppealAction = (roomKey, actionKey) => {
    const meta = APPEAL_ACTION_META[roomKey] && APPEAL_ACTION_META[roomKey].actions[actionKey];
    if (!meta) return;
    const sceneName = APPEAL_KEY_SCENE[roomKey];
    if (currentScene !== sceneName) return;
    if (AutoAdvance.has(sceneName)) return;
    const profile = appealProfile();
    const feedback = appealActionFeedback(roomKey, actionKey, profile);
    const st = getAppeal();
    const firstSettle = !st.settled[roomKey];
    if (firstSettle) {
      st.history.push({ type: "action", room: roomKey, action: actionKey, cycle: st.cycle });
      st.pending = { kind: "action", scene: sceneName, action: actionKey, target: "appeal-registry", feedback, cycle: st.cycle };
      saveAppeal(st);
    }
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $(APPEAL_ACTION_META[roomKey].responseEl);
    if (responseEl) responseEl.textContent = feedback;
    AudioEngine.knock(0.16);
    paintAppeal();
    if (firstSettle) {
      AutoAdvance.schedule(sceneName, "appeal-registry", {
        delay: branchDelay(),
        before: () => appealBeforeArrive("appeal-registry"),
      });
    }
  };

  /* 画面内回总署热点：纯导航节拍，不计分不写 history */
  const chooseAppealReturn = (roomKey) => {
    const sceneName = APPEAL_KEY_SCENE[roomKey];
    if (currentScene !== sceneName) return;
    if (AutoAdvance.has(sceneName)) return;
    const responseEl = $(APPEAL_ACTION_META[roomKey].responseEl);
    if (responseEl) responseEl.textContent = "复核记录已归档。你沿原路退回总署柜台。";
    AudioEngine.knock(0.16);
    AutoAdvance.schedule(sceneName, "appeal-registry", {
      delay: branchDelay(),
      before: () => appealBeforeArrive("appeal-registry"),
    });
  };

  /* 总署 hub：三路导航常开；锁链账本结案需本轮任意两间结清，不强制、不抢第三间 */
  const chooseAppealHub = (hubKey) => {
    if (currentScene !== "appeal-registry") return;
    if (AutoAdvance.has("appeal-registry")) return;
    const responseEl = $("#appeal-response");
    if (hubKey === "close") {
      const st = getAppeal();
      if (st.settledCount < 2) {
        if (responseEl) responseEl.textContent = APPEAL_CLOSE_LOCKED_FEEDBACK;
        AudioEngine.knock(0.12);
        paintAppeal();
        return;
      }
      const profile = appealProfile();
      const target = appealCloseTarget(st.scores, st.settledCount, profile.liability, profile.lastRoom);
      const feedback = appealCloseFeedback(target, st.scores, profile);
      st.history.push({ type: "close", cycle: st.cycle });
      /* v59 交叉听证窄钩子（在原目标/反馈计算之后）：本轮深查 ≥2 间且本轮
         尚未交付结案时，v58 原 target/feedback/close history 完全照旧，
         只抑制 pending 转场——v58 pending 保持 null，原目标存入 v59
         deferredTarget，结案改送交叉听证台；不复制任何 v58 路由 */
      const crossSt = getCross();
      if (crossSt.deepCount >= 2 && !crossSt.resolved) {
        saveAppeal(st);
        crossSt.history.push({ type: "intercept", target, cycle: crossSt.cycle });
        crossSt.deferredTarget = target;
        crossSt.pending = { kind: "intercept", scene: "appeal-registry", target: "cross-examination-desk", deferredTarget: target, feedback: CROSS_INTERCEPT_FEEDBACK, cycle: crossSt.cycle };
        saveCross(crossSt);
        const btn = $("#appeal-close");
        if (btn) btn.setAttribute("aria-pressed", "true");
        if (responseEl) responseEl.textContent = CROSS_INTERCEPT_FEEDBACK;
        AudioEngine.knock(0.16);
        paintAppeal();
        paintCross();
        AutoAdvance.schedule("appeal-registry", "cross-examination-desk", {
          delay: branchDelay(),
          before: () => crossBeforeArrive("cross-examination-desk"),
        });
        return;
      }
      st.pending = { kind: "close", scene: "appeal-registry", target, feedback, cycle: st.cycle };
      saveAppeal(st);
      const btn = $("#appeal-close");
      if (btn) btn.setAttribute("aria-pressed", "true");
      if (responseEl) responseEl.textContent = feedback;
      AudioEngine.knock(0.16);
      paintAppeal();
      AutoAdvance.schedule("appeal-registry", target, {
        delay: branchDelay(),
        before: () => appealBeforeArrive(target),
      });
      return;
    }
    const meta = APPEAL_HUB_META[hubKey];
    if (!meta) return;
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    if (responseEl) responseEl.textContent = meta.feedback;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule("appeal-registry", APPEAL_KEY_SCENE[hubKey], {
      delay: branchDelay(),
      before: () => appealBeforeArrive(APPEAL_KEY_SCENE[hubKey]),
    });
  };

  /* reload 节拍恢复：合法 pending 属于当前场景时重播逐字反馈并精确重挂一次 */
  const replayAppealPending = (sceneName) => {
    const st = getAppeal();
    const p = st.pending;
    if (!p || p.scene !== sceneName) return;
    if (p.kind === "entry") {
      const responseEl = $("#ledger-response");
      if (responseEl) responseEl.textContent = p.feedback;
    } else if (p.kind === "action") {
      const responseEl = $(APPEAL_ACTION_META[APPEAL_SCENE_KEY[p.scene]].responseEl);
      if (responseEl) responseEl.textContent = p.feedback;
    } else {
      const responseEl = $("#appeal-response");
      if (responseEl) responseEl.textContent = p.feedback;
    }
    AutoAdvance.schedule(sceneName, p.target, {
      delay: branchDelay(),
      before: () => appealBeforeArrive(p.target),
    });
  };

  /* 四场景进入：幂等补记 visit、清响应、总署说明按 v57 profile 重绘 */
  const enterAppealScene = (sceneName) => {
    const key = APPEAL_SCENE_KEY[sceneName];
    if (!key) return;
    const st = getAppeal();
    if (st.visits[key] === 0) {
      st.visits[key] = 1;
      saveAppeal(st);
      syncAppealLinks();
    }
    if (sceneName === "appeal-registry") {
      const desc = $("#appeal-desc");
      if (desc) desc.textContent = appealHubDesc(appealProfile());
      const responseEl = $("#appeal-response");
      if (responseEl) responseEl.textContent = "";
    } else {
      const responseEl = $(APPEAL_ACTION_META[key].responseEl);
      if (responseEl) responseEl.textContent = "";
    }
    paintAppeal();
  };

  const APPEAL_LINKS = { registry: "#appeal-link", identity: "#correction-link", evidence: "#contradiction-link", destination: "#destination-link" };
  const syncAppealLinks = () => {
    const st = getAppeal();
    APPEAL_VISIT_KEYS.forEach((k) => {
      const link = $(APPEAL_LINKS[k]);
      if (!link) return;
      if (st.visits[k] > 0) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  /* 痕迹页单行：异议署四类派生值，保持八张统计卡不变 */
  const paintAppealMemory = () => {
    const memory = $("#appeal-memory");
    if (!memory) return;
    const st = getAppeal();
    if (!appealActive(st)) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `异议署：异议 ${st.scores.objection}，先例 ${st.scores.precedent}，污染 ${st.scores.contamination}，本轮已复核 ${st.settledCount}/3。`;
    memory.hidden = false;
  };

  /* v58 合成守卫：全部监听只接受真实用户产生的 click（isTrusted）——
     合成 HTMLElement.click() 在 active 场景同样零副作用；
     鼠标/触控/Tab+Enter/Space 与 CDP page.click 均派发 trusted click，不受影响 */
  { const sealBtn = $("#ledger-appeal-seal");
    if (sealBtn) sealBtn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseAppealEntry(); }); }
  Object.keys(APPEAL_HUB_META).forEach((hubKey) => {
    const btn = $(APPEAL_HUB_META[hubKey].btn);
    if (btn) btn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseAppealHub(hubKey); });
  });
  { const closeBtn = $("#appeal-close");
    if (closeBtn) closeBtn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseAppealHub("close"); }); }
  APPEAL_ROOM_KEYS.forEach((roomKey) => {
    Object.keys(APPEAL_ACTION_META[roomKey].actions).forEach((actionKey) => {
      const btn = $(APPEAL_ACTION_META[roomKey].actions[actionKey].btn);
      if (btn) btn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseAppealAction(roomKey, actionKey); });
    });
    const retBtn = $(APPEAL_RETURN_BTN[roomKey]);
    if (retBtn) retBtn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseAppealReturn(roomKey); });
  });
  paintAppeal();

  /* ============================================================
     v59 交叉听证：v58 三房深查 + 结案延迟拦截 + 交叉听证台
     独立容错状态键 CROSS_KEY（v59 唯一存储键），只持久化白名单
     canonical 字段（version/cycle/visits/history/pending/deferredTarget）；
     convergence/coercion/residue、已深查房间、可否拦截、可否无字席
     全部由可信 history（仅当前 cycle 计分，同一房间同一 cycle 只计
     首次）与当前合法 v58 状态重算，永不落盘。v59 只读 v58/v57，
     从不改写；v58 只通过拦截点合法追加 close history。坏 JSON/错
     版本/额外键/错 cycle/错 action/错 target/deferredTarget 与当前
     v58 重算不符全部归一；pending 逐字重算，只消费一次。
     ============================================================ */
  const CROSS_KEY = "goddead_v59_cross_examination";
  const CROSS_VERSION = 59;
  const CROSS_NUM_CAP = 9999;
  const CROSS_HISTORY_CAP = 16;
  const CROSS_VISIT_KEYS = ["identity", "evidence", "destination", "desk"];
  const CROSS_SCENE = "cross-examination-desk";
  /* v58 结案真值表的全部可能落点（含 v59 自指的无号层） */
  const CROSS_CLOSE_TARGETS = ["concordance-theatre", "protocol-drift", "misbound-handover", "blank-name-cloakroom", "evidence-vault", "liability-ledger", "unnumbered-floor"];
  const CROSS_TARGET_LABEL = {
    "concordance-theatre": "共证剧场",
    "protocol-drift": "守则漂移",
    "misbound-handover": "错绑交班台",
    "blank-name-cloakroom": "空名寄存处",
    "evidence-vault": "异常保全",
    "liability-ledger": "责任账房",
    "unnumbered-floor": "无号层",
  };
  /* 三房深查：封签、图面互换与两个深查动作（逐字反馈与分值冻结） */
  const CROSS_DEEP_META = {
    identity: {
      sealBtn: "#identity-hearing-seal",
      baseImg: "assets/v58-identity-correction.webp",
      img: "assets/v59-identity-cross-exam.webp",
      baseFigLabel: "身份勘误室：左侧电话与空肖像、中央空证人椅与名牌、右侧裂镜与空制服",
      figLabel: "身份勘误室·深查：左侧放音鼓与听筒、中央玻璃听证椅、右侧裂镜与空制服",
      sealFeedback: "听证封签断开。电话那头的喘息被准许再做一次证。",
      responseEl: "#identity-response",
      actions: {
        "replay-voice": { btn: "#identity-action-replay-voice", scores: { convergence: 2 }, feedback: "来电里的喘息与登记台的漏拍重合。两份证词开始共享同一条呼吸。" },
        "force-name": { btn: "#identity-action-force-name", scores: { coercion: 2, residue: 1 }, feedback: "针尖替空白写下姓名；椅背先收紧，余音才承认那个人存在。" },
      },
    },
    evidence: {
      sealBtn: "#contradiction-hearing-seal",
      baseImg: "assets/v58-evidence-contradiction.webp",
      img: "assets/v59-evidence-cross-exam.webp",
      baseFigLabel: "证据对照库：左侧白卷宗、中央错位玻璃对照片、右侧污卷宗与焚盘",
      figLabel: "证据对照库·深查：中央三表齿轮仪、右侧玻璃罩与血蜡",
      sealFeedback: "听证封签断开。对照库准许重新称一次血蜡的温度。",
      responseEl: "#contradiction-response",
      actions: {
        "align-timestamps": { btn: "#contradiction-action-align-timestamps", scores: { convergence: 2 }, feedback: "三枚停住的秒针在同一刻复动。矛盾没有消失，只被迫共用一个时间。" },
        "lift-blood-wax": { btn: "#contradiction-action-lift-blood-wax", scores: { residue: 2 }, feedback: "罩下的血蜡仍在回温。被删去的证据以指纹的形状留了下来。" },
      },
    },
    destination: {
      sealBtn: "#destination-hearing-seal",
      baseImg: "assets/v58-destination-review-shaft.webp",
      img: "assets/v59-destination-cross-exam.webp",
      baseFigLabel: "去向复核井：左侧回程轮轨、中央悬吊封箱、右侧断轨与落井杆",
      figLabel: "去向复核井·深查：左侧仪表与绕行缆线、中央悬吊封箱、右侧听音喇叭",
      sealFeedback: "听证封签断开。复核井准许再听一次井底的呼吸。",
      responseEl: "#destination-response",
      actions: {
        "trace-cable": { btn: "#destination-action-trace-cable", scores: { convergence: 1, coercion: 1, residue: 2 }, feedback: "缆线绕过门牌，直接勒住收件人的座位。目的地与命令来自同一只手。" },
        "listen-below": { btn: "#destination-action-listen-below", scores: { residue: 2, coercion: 1 }, feedback: "井底没有回声，只有下一位收件人被提前念出的呼吸。" },
      },
    },
  };
  const CROSS_INTERCEPT_FEEDBACK = "结案印没有落下。三张听证封签把原裁定扣在桌下，要求交叉询问。";
  /* 听证台四动作：归并/标记/封存各给自己的分值 +2（点击前分值路由后再入账），
     无字席不计分 */
  const CROSS_DESK_META = {
    "merge-testimonies": { btn: "#cross-action-merge-testimonies", banks: "convergence" },
    "mark-coercion": { btn: "#cross-action-mark-coercion", banks: "coercion" },
    "archive-residue": { btn: "#cross-action-archive-residue", banks: "residue" },
    "blank-seat": { btn: "#cross-action-blank-seat", banks: "" },
  };
  /* 听证台路由：纯函数，点击前分值决定目标与逐字反馈；
     merge 通过时原 deferredTarget 获得第二次生效 */
  const crossDeskResolve = (action, pre, deferredTarget) => {
    const cv = pre.convergence;
    const co = pre.coercion;
    const re = pre.residue;
    if (action === "blank-seat") return { target: "unnumbered-floor", feedback: "第四块铭牌没有刻字。你坐下后，楼层编号从目录里退了一格。" };
    if (action === "merge-testimonies") {
      if (cv >= co && cv >= re) return { target: deferredTarget, feedback: "证词被编成一股绳，原裁定因此获得第二次生效。" };
      return { target: "concordance-theatre", feedback: "三份证词被强行并排；它们同意的，恰好是从未发生的部分。" };
    }
    if (action === "mark-coercion") {
      if (co >= re) return { target: "protocol-drift", feedback: "勒痕被标在规程上。命令终于暴露了它自己的手腕。" };
      return { target: "misbound-handover", feedback: "勒痕没有指向命令，只把错误的名字又绑紧了一层。" };
    }
    if (re >= cv) return { target: "blank-name-cloakroom", feedback: "余响被封进无名档案。被擦掉的那个人在空衣架后继续呼吸。" };
    return { target: "evidence-vault", feedback: "余响被归档为证物；它不再说话，却开始替所有缺口作证。" };
  };
  /* 无字席条件（冻结）：三房全部深查且点击前三分值完全拉平且为正 */
  const crossBlankSeatArmed = (pre, deepCount) => deepCount === 3
    && pre.convergence === pre.coercion && pre.coercion === pre.residue && pre.convergence > 0;

  const getCross = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(CROSS_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    /* 错版本整体丢弃：v59 之前的任何同键内容一律不算数 */
    if (raw.version !== CROSS_VERSION) raw = {};
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(CROSS_NUM_CAP, Math.floor(n));
    };
    /* cycle 对齐 v35：跨 cycle 的 history 条目保留但不参与本轮派生 */
    const cycle = getFloor().cycle;
    const sameCycle = num(raw.cycle) === cycle;
    const visits = {};
    CROSS_VISIT_KEYS.forEach((k) => { visits[k] = num(raw.visits && raw.visits[k]); });
    /* history 有界白名单：action（房+动作双白名单）/ intercept / resolve
       （动作与目标双白名单）三种形状，最多 16 条 */
    let history = [];
    if (Array.isArray(raw.history)) {
      for (const h of raw.history) {
        if (!h || typeof h !== "object" || Array.isArray(h)) continue;
        if (h.type === "action" && CROSS_DEEP_META[h.room] && CROSS_DEEP_META[h.room].actions[h.action]) {
          history.push({ type: "action", room: h.room, action: h.action, cycle: num(h.cycle) });
        } else if (h.type === "intercept" && CROSS_CLOSE_TARGETS.includes(h.target)) {
          history.push({ type: "intercept", target: h.target, cycle: num(h.cycle) });
        } else if (h.type === "resolve" && CROSS_DESK_META[h.action] && CROSS_CLOSE_TARGETS.includes(h.target)) {
          history.push({ type: "resolve", action: h.action, target: h.target, cycle: num(h.cycle) });
        }
      }
    }
    history = history.slice(-CROSS_HISTORY_CAP);
    /* 派生（永不落盘）：本轮分值 / 已深查房间 / 是否已拦截 / 是否已交付，
       同一房间同一 cycle 只计首次；resolve 条目给自己的分值入账 +2
       （无字席不计分），点击前分值 = 派生分值减去本动作入账 */
    const scores = { convergence: 0, coercion: 0, residue: 0 };
    const deep = { identity: "", evidence: "", destination: "" };
    let intercepted = false;
    let resolved = false;
    history.forEach((h) => {
      if (h.cycle !== cycle) return;
      if (h.type === "action" && !deep[h.room]) {
        deep[h.room] = h.action;
        const sc = CROSS_DEEP_META[h.room].actions[h.action].scores;
        Object.keys(sc).forEach((k) => { scores[k] = Math.min(CROSS_NUM_CAP, scores[k] + sc[k]); });
      } else if (h.type === "intercept") {
        intercepted = true;
      } else if (h.type === "resolve") {
        resolved = true;
        const bank = CROSS_DESK_META[h.action].banks;
        if (bank) scores[bank] = Math.min(CROSS_NUM_CAP, scores[bank] + 2);
      }
    });
    const deepCount = APPEAL_ROOM_KEYS.filter((k) => deep[k]).length;
    /* deferredTarget 严格重算：只在「本轮有拦截、尚未交付、v58 canonical
       history 末项是本轮 close、且当前 v58 状态重算出同一目标」时成立，
       其余一律丢弃——reload 不接受任何与现状不符的被扣裁定。交付在途
       （末条 resolve 已入账、其 pending 尚未消费）不算已交付：候选形状
       先放宽进来，严格七键白名单校验不过时由下方 resolved 收回统一丢弃 */
    const appeal = getAppeal();
    const profile = appealProfile();
    const closeLast = appeal.history.length > 0
      && appeal.history[appeal.history.length - 1].type === "close"
      && appeal.history[appeal.history.length - 1].cycle === cycle;
    const recomputed = appealCloseTarget(appeal.scores, appeal.settledCount, profile.liability, profile.lastRoom);
    const pendingIsResolveCandidate = raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)
      && raw.pending.kind === "resolve";
    let deferredTarget = "";
    if (sameCycle && intercepted && (!resolved || pendingIsResolveCandidate) && deepCount >= 2 && closeLast && !appeal.pending
      && CROSS_CLOSE_TARGETS.includes(raw.deferredTarget) && raw.deferredTarget === recomputed) {
      deferredTarget = raw.deferredTarget;
    }
    /* pending 严格白名单：action/resolve 各恰好七键、intercept 恰好六键
       （额外键即伪造）；scene/action/room/target/deferredTarget/feedback 逐字重算；
       结算证据 = canonical history 末项一致 + cycle 一致 + 当前派生资格 */
    let pending = null;
    if (sameCycle && raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const p = raw.pending;
      const keys = Object.keys(p).sort().join(",");
      const last = history.length ? history[history.length - 1] : null;
      if (p.kind === "action" && keys === "action,cycle,feedback,kind,room,scene,target"
        && CROSS_DEEP_META[p.room] && CROSS_DEEP_META[p.room].actions[p.action]
        && p.scene === APPEAL_KEY_SCENE[p.room] && num(p.cycle) === cycle
        && p.target === "appeal-registry"
        && p.feedback === CROSS_DEEP_META[p.room].actions[p.action].feedback
        && last && last.type === "action" && last.room === p.room && last.action === p.action && last.cycle === cycle
        && deep[p.room] === p.action) {
        pending = { kind: "action", scene: p.scene, room: p.room, action: p.action, target: "appeal-registry", feedback: p.feedback, cycle };
      } else if (p.kind === "intercept" && keys === "cycle,deferredTarget,feedback,kind,scene,target"
        && p.scene === "appeal-registry" && p.target === CROSS_SCENE && num(p.cycle) === cycle
        && p.feedback === CROSS_INTERCEPT_FEEDBACK
        && last && last.type === "intercept" && last.cycle === cycle
        && deferredTarget && p.deferredTarget === deferredTarget) {
        pending = { kind: "intercept", scene: "appeal-registry", target: CROSS_SCENE, deferredTarget, feedback: CROSS_INTERCEPT_FEEDBACK, cycle };
      } else if (p.kind === "resolve" && keys === "action,cycle,deferredTarget,feedback,kind,scene,target"
        && p.scene === CROSS_SCENE && CROSS_DESK_META[p.action] && num(p.cycle) === cycle
        && deferredTarget && p.deferredTarget === deferredTarget
        && last && last.type === "resolve" && last.action === p.action && last.cycle === cycle) {
        /* 点击前分值 = 派生分值减去本动作入账，路由/反馈逐字重算 */
        const pre = { ...scores };
        const bank = CROSS_DESK_META[p.action].banks;
        if (bank) pre[bank] = Math.max(0, pre[bank] - 2);
        const r = crossDeskResolve(p.action, pre, deferredTarget);
        const blankOk = p.action !== "blank-seat" || crossBlankSeatArmed(pre, deepCount);
        if (blankOk && p.target === r.target && p.feedback === r.feedback) {
          pending = { kind: "resolve", scene: CROSS_SCENE, action: p.action, target: r.target, deferredTarget, feedback: r.feedback, cycle };
        }
      }
    }
    /* 已交付（resolve 已入账且无合法 pending 在途）或候选收回：被扣裁定
       一律丢弃——交付只发生一次，伪造的 resolve 候选同样保不住 deferredTarget */
    if (resolved && !pending) deferredTarget = "";
    return {
      cycle, visits, history, pending, deferredTarget, scores, deep, deepCount, intercepted, resolved,
      pendingTarget: pending ? pending.target : "",
    };
  };
  /* 只持久化白名单 canonical 六键；派生字段永不落盘，history 先裁后存 */
  const saveCross = (st) => store.set(CROSS_KEY, JSON.stringify({
    version: CROSS_VERSION,
    cycle: st.cycle,
    visits: st.visits,
    history: st.history.slice(-CROSS_HISTORY_CAP),
    pending: st.pending,
    deferredTarget: st.deferredTarget || null,
  }));

  const crossActive = (st) => CROSS_VISIT_KEYS.some((k) => st.visits[k] > 0) || st.history.length > 0;

  /* 听证签：三类分值 + 本轮深查间数 + 听证台说明（原裁定去向氛围化）+ 无字席显露 */
  const paintCross = () => {
    const st = getCross();
    $$("[data-cross-convergence]").forEach((el) => { el.textContent = st.scores.convergence; });
    $$("[data-cross-coercion]").forEach((el) => { el.textContent = st.scores.coercion; });
    $$("[data-cross-residue]").forEach((el) => { el.textContent = st.scores.residue; });
    $$("[data-cross-deep-count]").forEach((el) => { el.textContent = `${st.deepCount}/3`; });
    const desc = $("#cross-exam-desc");
    if (desc) {
      desc.textContent = st.deferredTarget
        ? `结案印被扣在桌下：原裁定本要送往「${CROSS_TARGET_LABEL[st.deferredTarget]}」。合流 ${st.scores.convergence}、胁迫 ${st.scores.coercion}、残响 ${st.scores.residue}，听证台等一个动作。`
        : "结案印被扣在桌下。交叉听证只质询已经深查过的房间。";
    }
    const blankBtn = $("#cross-action-blank-seat");
    if (blankBtn) {
      if (st.deferredTarget && crossBlankSeatArmed(st.scores, st.deepCount)) blankBtn.removeAttribute("hidden");
      else blankBtn.setAttribute("hidden", "");
    }
  };

  /* 会话内封签激活态：可信封签点击立即换深查图并揭示两个深查热点
     （不计分不写 canonical）；离场/遗忘后由 canonical 派生回弹 */
  const crossArmed = { identity: false, evidence: false, destination: false };
  const resetCrossArmed = () => { APPEAL_ROOM_KEYS.forEach((roomKey) => { crossArmed[roomKey] = false; }); };

  /* 三复核室图面同步：结清未深查 → 显露听证封签；封签激活或已深查 →
     换 v59 深查图、隐藏原 v58 三动作、显露两个深查热点、回总署热点保留，
     已深查时示出既往结果；未结清/遗忘后 → 全部回弹出厂态 */
  const syncCrossRoom = (roomKey) => {
    const meta = CROSS_DEEP_META[roomKey];
    if (!meta) return;
    const st = getCross();
    const appeal = getAppeal();
    const deepAction = st.deep[roomKey];
    const isDeep = Boolean(deepAction) || crossArmed[roomKey];
    const section = $(`#scene-${APPEAL_KEY_SCENE[roomKey]}`);
    if (!section) return;
    const img = section.querySelector(".branch-img");
    setSceneImageSrc(img, isDeep ? meta.img : meta.baseImg);
    const figure = section.querySelector(".branch-figure");
    if (figure) figure.setAttribute("aria-label", isDeep ? meta.figLabel : meta.baseFigLabel);
    const seal = $(meta.sealBtn);
    if (seal) {
      if (appeal.settled[roomKey] && !isDeep) seal.removeAttribute("hidden");
      else seal.setAttribute("hidden", "");
    }
    Object.keys(APPEAL_ACTION_META[roomKey].actions).forEach((a) => {
      const btn = $(APPEAL_ACTION_META[roomKey].actions[a].btn);
      if (!btn) return;
      if (isDeep) btn.setAttribute("hidden", "");
      else btn.removeAttribute("hidden");
    });
    Object.keys(meta.actions).forEach((a) => {
      const btn = $(meta.actions[a].btn);
      if (!btn) return;
      if (isDeep) btn.removeAttribute("hidden");
      else btn.setAttribute("hidden", "");
      btn.setAttribute("aria-pressed", deepAction === a ? "true" : "false");
    });
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = deepAction ? meta.actions[deepAction].feedback : "";
  };

  /* 封签节拍：可信激活立即换深查图并揭示两个深查热点，不计分不写 history；
     结清前/已深查后点击（含合成点击）零副作用 */
  const chooseCrossSeal = (roomKey) => {
    const sceneName = APPEAL_KEY_SCENE[roomKey];
    if (currentScene !== sceneName) return;
    if (AutoAdvance.has(sceneName)) return;
    if (!getAppeal().settled[roomKey]) return;
    if (getCross().deep[roomKey]) return;
    const meta = CROSS_DEEP_META[roomKey];
    crossArmed[roomKey] = true;
    syncCrossRoom(roomKey);
    const seal = $(meta.sealBtn);
    if (seal) seal.setAttribute("aria-pressed", "true");
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = meta.sealFeedback;
    AudioEngine.knock(0.16);
  };

  /* 深查动作：首次一拍计分、逐字反馈、自动回总署；同 cycle 复访只重播
     既往结果、不二次计分、不自动转场 */
  const chooseCrossAction = (roomKey, actionKey) => {
    const meta = CROSS_DEEP_META[roomKey] && CROSS_DEEP_META[roomKey].actions[actionKey];
    if (!meta) return;
    const sceneName = APPEAL_KEY_SCENE[roomKey];
    if (currentScene !== sceneName) return;
    if (AutoAdvance.has(sceneName)) return;
    if (!getAppeal().settled[roomKey]) return;
    const st = getCross();
    const doneAction = st.deep[roomKey];
    const firstDeep = !doneAction;
    const feedback = firstDeep ? meta.feedback : CROSS_DEEP_META[roomKey].actions[doneAction].feedback;
    if (firstDeep) {
      st.history.push({ type: "action", room: roomKey, action: actionKey, cycle: st.cycle });
      st.pending = { kind: "action", scene: sceneName, room: roomKey, action: actionKey, target: "appeal-registry", feedback: meta.feedback, cycle: st.cycle };
      saveCross(st);
    }
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $(CROSS_DEEP_META[roomKey].responseEl);
    if (responseEl) responseEl.textContent = feedback;
    AudioEngine.knock(0.16);
    paintCross();
    if (firstDeep) {
      AutoAdvance.schedule(sceneName, "appeal-registry", {
        delay: branchDelay(),
        before: () => crossBeforeArrive("appeal-registry"),
      });
    }
  };

  /* 转场 before 通用尾件（深查/拦截）：原子记 desk visit 再清 pending；
     deferredTarget 只在最终交付时清除 */
  const crossBeforeArrive = (target) => {
    const s = getCross();
    if (target === CROSS_SCENE && s.visits.desk === 0) s.visits.desk = 1;
    if (s.pending) s.pending = null;
    saveCross(s);
    if (LEDGER_SCENE_KEY[target]) grantLedgerVisit(target);
    if (target === "evidence-vault") markReviewVisited("evidence-vault");
    syncCrossLink();
    paintCrossMemory();
  };

  /* 最终交付：清 pending 与 deferredTarget（结案只交付一次），并补齐目标
     场景旧守卫凭证 */
  const crossResolveArrive = (target) => {
    const s = getCross();
    if (s.pending) s.pending = null;
    if (s.deferredTarget) s.deferredTarget = "";
    saveCross(s);
    if (LEDGER_SCENE_KEY[target]) grantLedgerVisit(target);
    if (target === "evidence-vault") markReviewVisited("evidence-vault");
    syncCrossLink();
    paintCrossMemory();
  };

  /* 听证台动作：点击前分值路由 → 写入 resolve 并入账 +2 → 一拍后自动转场；
     无被扣裁定或本轮已交付时全部零副作用；无字席只在拉平时显露且不计分 */
  const chooseCrossDesk = (actionKey) => {
    const meta = CROSS_DESK_META[actionKey];
    if (!meta) return;
    if (currentScene !== CROSS_SCENE) return;
    if (AutoAdvance.has(CROSS_SCENE)) return;
    const st = getCross();
    if (st.resolved) return;
    if (!st.deferredTarget) return;
    const pre = { ...st.scores };
    if (actionKey === "blank-seat" && !crossBlankSeatArmed(pre, st.deepCount)) return;
    const r = crossDeskResolve(actionKey, pre, st.deferredTarget);
    st.history.push({ type: "resolve", action: actionKey, target: r.target, cycle: st.cycle });
    st.pending = { kind: "resolve", scene: CROSS_SCENE, action: actionKey, target: r.target, deferredTarget: st.deferredTarget, feedback: r.feedback, cycle: st.cycle };
    saveCross(st);
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $("#cross-exam-response");
    if (responseEl) responseEl.textContent = r.feedback;
    AudioEngine.knock(0.16);
    paintCross();
    AutoAdvance.schedule(CROSS_SCENE, r.target, {
      delay: branchDelay(),
      before: () => crossResolveArrive(r.target),
    });
  };

  /* reload 节拍恢复：合法 pending 属于当前场景时重播逐字反馈并精确重挂一次，
     不二次计分 */
  const replayCrossPending = (sceneName) => {
    const st = getCross();
    const p = st.pending;
    if (!p || p.scene !== sceneName) return;
    if (p.kind === "action") {
      const responseEl = $(CROSS_DEEP_META[p.room].responseEl);
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule(sceneName, p.target, {
        delay: branchDelay(),
        before: () => crossBeforeArrive(p.target),
      });
    } else if (p.kind === "intercept") {
      const responseEl = $("#appeal-response");
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule(sceneName, p.target, {
        delay: branchDelay(),
        before: () => crossBeforeArrive(p.target),
      });
    } else {
      const responseEl = $("#cross-exam-response");
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule(sceneName, p.target, {
        delay: branchDelay(),
        before: () => crossResolveArrive(p.target),
      });
    }
  };

  /* 听证台进入：幂等补记 desk visit、清响应、按被扣裁定重绘说明 */
  const enterCrossDesk = () => {
    const st = getCross();
    if (st.visits.desk === 0) {
      st.visits.desk = 1;
      saveCross(st);
      syncCrossLink();
    }
    const responseEl = $("#cross-exam-response");
    if (responseEl) responseEl.textContent = "";
    paintCross();
  };

  const CROSS_LINK = "#cross-exam-link";
  const syncCrossLink = () => {
    const link = $(CROSS_LINK);
    if (!link) return;
    if (getCross().visits.desk > 0) link.removeAttribute("hidden");
    else link.setAttribute("hidden", "");
  };

  /* 痕迹页单行：交叉听证四类派生值，保持八张统计卡不变 */
  const paintCrossMemory = () => {
    const memory = $("#cross-exam-memory");
    if (!memory) return;
    const st = getCross();
    if (!crossActive(st)) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `交叉听证：合流 ${st.scores.convergence}，胁迫 ${st.scores.coercion}，残响 ${st.scores.residue}，本轮深查 ${st.deepCount}/3。`;
    memory.hidden = false;
  };

  /* v59 合成守卫：封签/深查动作/听证台三组监听只接受真实用户产生的
     click（isTrusted）——合成 HTMLElement.click() 在 active 场景同样零副作用 */
  APPEAL_ROOM_KEYS.forEach((roomKey) => {
    const sealBtn = $(CROSS_DEEP_META[roomKey].sealBtn);
    if (sealBtn) sealBtn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseCrossSeal(roomKey); });
    Object.keys(CROSS_DEEP_META[roomKey].actions).forEach((actionKey) => {
      const btn = $(CROSS_DEEP_META[roomKey].actions[actionKey].btn);
      if (btn) btn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseCrossAction(roomKey, actionKey); });
    });
  });
  Object.keys(CROSS_DESK_META).forEach((actionKey) => {
    const btn = $(CROSS_DESK_META[actionKey].btn);
    if (btn) btn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseCrossDesk(actionKey); });
  });
  paintCross();

  /* ============================================================
     v60 证物链：v33/v34 两结果房图内化 + 证物链办公室
     状态独立存 goddead_v60_chain_of_custody（全仓库唯一 key），容错坏 JSON；
     canonical 八键显式投影落盘（visited 三布尔 / scores / cycleActions ≤8 /
     lastSource / lastAction / officeRuns / transfers / pending），数字整数 0..9999。
     只读写自己的键：旧动作仍照常写 v33/v34 键，v60 不伪造不改写任何
     v28–v59 结果。pending 恰好四键（scene/action/target/feedback，额外键
     即伪造），target/feedback 逐字重算，只消费一次。每轮同一源动作只计
     一次分；本轮第一个使解锁条件（≥3 个不同动作且两房各至少一个）成立
     的合法点击，在完成旧副作用后把目的地截留为证物链办公室。
     ============================================================ */
  const CUSTODY_KEY = "goddead_v60_chain_of_custody";
  const CUSTODY_NUM_CAP = 9999;
  const CUSTODY_OFFICE = "chain-of-custody-office";
  const CUSTODY_SOURCE_SCENES = ["evidence-vault", "false-positive-shaft"];
  const CUSTODY_SCENE_SOURCE = { "evidence-vault": "vault", "false-positive-shaft": "shaft" };
  /* 八个合法源动作：固定分值映射（每轮每动作只计首次） */
  const CUSTODY_SOURCE_ACTIONS = {
    sealedClearestAnomaly: { source: "vault", scores: { custody: 2 } },
    returnedBaselineToVestibule: { source: "vault", scores: { claim: 2 } },
    leftThroughBrokenSeal: { source: "vault", scores: { revision: 2 } },
    sentEvidenceToValuation: { source: "vault", scores: { custody: 1, claim: 1 } },
    retrievedRejectedCase: { source: "shaft", scores: { custody: 1, claim: 1 } },
    appendedFalseReport: { source: "shaft", scores: { revision: 2 } },
    admittedExtraItem: { source: "shaft", scores: { claim: 2 } },
    declaredRejectAsAsset: { source: "shaft", scores: { revision: 1, claim: 1 } },
  };
  const CUSTODY_ACTION_IDS = Object.keys(CUSTODY_SOURCE_ACTIONS);
  const CUSTODY_INTERCEPT_SUFFIX = "证物链扣住了原去向。办公室的门在这时打开。";
  const CUSTODY_OFFICE_ACTIONS = {
    reseal: { btn: "#chain-action-reseal", bank: "custody" },
    amend: { btn: "#chain-action-amend", bank: "revision" },
    claim: { btn: "#chain-action-claim", bank: "claim" },
    void: { btn: "#chain-action-void", bank: "" },
  };
  const CUSTODY_SOURCE_BTNS = {
    "evidence-vault": ["#vault-choice-seal", "#vault-choice-return", "#vault-choice-leave", "#vault-choice-valuation"],
    "false-positive-shaft": ["#shaft-choice-retrieve", "#shaft-choice-append", "#shaft-choice-admit", "#shaft-choice-valuation"],
  };
  /* 源动作旧反馈逐字：截留反馈 = 旧句 + v60 后缀，pending 重算以此为据 */
  const custodyBaseResponse = (actionId) => {
    const a = CUSTODY_SOURCE_ACTIONS[actionId];
    if (!a) return "";
    const scene = a.source === "vault" ? "evidence-vault" : "false-positive-shaft";
    if (REVIEW_RESULT_META[scene].choices[actionId]) return REVIEW_RESULT_META[scene].choices[actionId].response;
    return VAL_ENTRY_META[scene].response;
  };
  /* 解锁条件（冻结）：本轮 cycleActions ≥3 个不同动作，且两房各至少一个 */
  const custodyUnlocked = (actions) => actions.length >= 3
    && actions.some((a) => CUSTODY_SOURCE_ACTIONS[a].source === "vault")
    && actions.some((a) => CUSTODY_SOURCE_ACTIONS[a].source === "shaft");
  /* 空白见证位条件（冻结）：点击前三项完全拉平且为正 */
  const custodyVoidArmed = (scores) => scores.custody === scores.revision && scores.revision === scores.claim && scores.custody > 0;
  /* 办公室分流纯函数：常规动作先入账 +2 再按点击后分值路由；
     三项全等（含常规动作补齐的拉平）退回责任账房 */
  const custodyOfficeRoute = (actionId, pre) => {
    if (actionId === "void") return { target: "unnumbered-floor", feedback: "见证位空了。你抽走的那一格从未存在，楼层编号又退了一格。" };
    const post = { custody: pre.custody, revision: pre.revision, claim: pre.claim };
    post[CUSTODY_OFFICE_ACTIONS[actionId].bank] = Math.min(CUSTODY_NUM_CAP, post[CUSTODY_OFFICE_ACTIONS[actionId].bank] + 2);
    const c = post.custody;
    const r = post.revision;
    const k = post.claim;
    const tally = `保全 ${c}、改写 ${r}、认领 ${k}`;
    if (c === r && r === k) return { target: "liability-ledger", feedback: `${tally}，三项完全拉平。链条拒绝指出责任方，整链退回责任账房过秤。` };
    if (c > r && c > k) return { target: "retention-vault", feedback: `${tally}，保全占上风。链条只进不出，证物送去留置空库。` };
    if (r > c && r > k) return { target: "protocol-drift", feedback: `${tally}，改写占上风。被改写过的环节需要守则重写自己，证物送去守则漂移。` };
    if (k > c && k > r) return { target: "returned-address-cabinet", feedback: `${tally}，认领占上风。每一环都有了签收人，证物送去退址格柜。` };
    if (c === r) return { target: "false-confirmation-desk", feedback: `${tally}，保全与改写拉平、压过认领。封得好与改得对互相确认，证物送去假确认台。` };
    if (c === k) return { target: "witness-carbon-archive", feedback: `${tally}，保全与认领拉平、压过改写。每一环都有人见证，副本送去见证复写库。` };
    return { target: "blank-name-cloakroom", feedback: `${tally}，改写与认领拉平、压过保全。改掉的名字无人认领，证物寄存到空名寄存处。` };
  };

  const getCustody = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(CUSTODY_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(CUSTODY_NUM_CAP, Math.floor(n));
    };
    const visited = {};
    ["vault", "shaft", "office"].forEach((k) => { visited[k] = Boolean(raw.visited && raw.visited[k] === true); });
    const scores = {};
    ["custody", "revision", "claim"].forEach((k) => { scores[k] = num(raw.scores && raw.scores[k]); });
    /* 本轮动作登记：白名单、去重、最多 8 个 */
    const cycleActions = Array.isArray(raw.cycleActions)
      ? [...new Set(raw.cycleActions.filter((a) => CUSTODY_ACTION_IDS.includes(a)))].slice(0, 8)
      : [];
    const lastSource = ["vault", "shaft"].includes(raw.lastSource) ? raw.lastSource : "";
    const lastAction = CUSTODY_ACTION_IDS.includes(raw.lastAction) ? raw.lastAction : "";
    const officeRuns = num(raw.officeRuns);
    const transfers = num(raw.transfers);
    /* pending 恰好四键（额外键即伪造）；target/feedback 逐字重算：
       源 pending 须 action 仍登记在本轮且解锁条件成立；
       办公室 pending 由当前分值重算分流（点击后分值已含 +2，回减重算），
       void 另需拉平条件成立 */
    let pending = null;
    if (raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const p = raw.pending;
      if (Object.keys(p).sort().join(",") === "action,feedback,scene,target") {
        if (CUSTODY_SOURCE_SCENES.includes(p.scene) && CUSTODY_ACTION_IDS.includes(p.action)
          && CUSTODY_SOURCE_ACTIONS[p.action].source === CUSTODY_SCENE_SOURCE[p.scene]
          && p.target === CUSTODY_OFFICE
          && p.feedback === custodyBaseResponse(p.action) + CUSTODY_INTERCEPT_SUFFIX
          && cycleActions.includes(p.action) && custodyUnlocked(cycleActions)) {
          pending = { scene: p.scene, action: p.action, target: CUSTODY_OFFICE, feedback: p.feedback };
        } else if (p.scene === CUSTODY_OFFICE && CUSTODY_OFFICE_ACTIONS[p.action]) {
          const bank = CUSTODY_OFFICE_ACTIONS[p.action].bank;
          const pre = { custody: scores.custody, revision: scores.revision, claim: scores.claim };
          if (bank) pre[bank] = Math.max(0, pre[bank] - 2);
          const r = custodyOfficeRoute(p.action, pre);
          const voidOk = p.action !== "void" || custodyVoidArmed(scores);
          if (voidOk && p.target === r.target && p.feedback === r.feedback) {
            pending = { scene: CUSTODY_OFFICE, action: p.action, target: r.target, feedback: r.feedback };
          }
        }
      }
    }
    return { visited, scores, cycleActions, lastSource, lastAction, officeRuns, transfers, pending };
  };
  /* 只持久化白名单 canonical 八键 */
  const saveCustody = (st) => store.set(CUSTODY_KEY, JSON.stringify({
    visited: st.visited,
    scores: st.scores,
    cycleActions: st.cycleActions.slice(0, 8),
    lastSource: st.lastSource,
    lastAction: st.lastAction,
    officeRuns: st.officeRuns,
    transfers: st.transfers,
    pending: st.pending,
  }));

  /* 第一拍接受后全热点同步 disabled；回场景/遗忘时恢复 */
  const custodyLockButtons = (sceneKey) => {
    const sels = sceneKey === CUSTODY_OFFICE
      ? Object.keys(CUSTODY_OFFICE_ACTIONS).map((a) => CUSTODY_OFFICE_ACTIONS[a].btn)
      : (CUSTODY_SOURCE_BTNS[sceneKey] || []);
    sels.forEach((sel) => { const b = $(sel); if (b) b.disabled = true; });
  };
  const custodyUnlockButtons = (sceneKey) => {
    const sels = sceneKey === CUSTODY_OFFICE
      ? Object.keys(CUSTODY_OFFICE_ACTIONS).map((a) => CUSTODY_OFFICE_ACTIONS[a].btn)
      : (CUSTODY_SOURCE_BTNS[sceneKey] || []);
    sels.forEach((sel) => { const b = $(sel); if (b) b.disabled = false; });
  };

  /* 源动作 v60 节拍：旧副作用完成后调用。每轮每动作只计首次（重复动作
     继续走旧目的地、不刷分、不计入本轮解锁）；本轮第一个使解锁条件成立
     的合法点击把目的地截留为办公室并持久化 pending；已有 pending 时不再
     截留，旧目的地逐字保持 */
  const custodySourceBeat = (sceneKey, actionId, baseTarget) => {
    const meta = CUSTODY_SOURCE_ACTIONS[actionId];
    if (!meta || CUSTODY_SCENE_SOURCE[sceneKey] !== meta.source) return { target: baseTarget, suffix: "", intercepted: false };
    const st = getCustody();
    if (!st.visited[meta.source]) st.visited[meta.source] = true;
    let intercepted = false;
    if (!st.cycleActions.includes(actionId)) {
      const wasUnlocked = custodyUnlocked(st.cycleActions);
      st.cycleActions.push(actionId);
      Object.keys(meta.scores).forEach((k) => { st.scores[k] = Math.min(CUSTODY_NUM_CAP, st.scores[k] + meta.scores[k]); });
      st.lastSource = meta.source;
      st.lastAction = actionId;
      intercepted = !st.pending && !wasUnlocked && custodyUnlocked(st.cycleActions);
    }
    if (intercepted) {
      st.pending = { scene: sceneKey, action: actionId, target: CUSTODY_OFFICE, feedback: custodyBaseResponse(actionId) + CUSTODY_INTERCEPT_SUFFIX };
    }
    saveCustody(st);
    paintCustodyMemory();
    return intercepted ? { target: CUSTODY_OFFICE, suffix: CUSTODY_INTERCEPT_SUFFIX, intercepted: true } : { target: baseTarget, suffix: "", intercepted: false };
  };

  /* 截留到达办公室：原子记 visit 再清 pending（consume once） */
  const custodySourceArrive = () => {
    const s = getCustody();
    if (!s.visited.office) s.visited.office = true;
    if (s.pending) s.pending = null;
    saveCustody(s);
    syncCustodyLink();
    paintCustodyMemory();
  };

  /* 办公室动作到达：清 pending、officeRuns/transfers 各 +1、清空
     cycleActions 开新轮（累计 scores 保留），并补齐目标场景旧守卫凭证 */
  const custodyOfficeArrive = (target) => {
    const s = getCustody();
    if (s.pending) s.pending = null;
    s.officeRuns = Math.min(CUSTODY_NUM_CAP, s.officeRuns + 1);
    s.transfers = Math.min(CUSTODY_NUM_CAP, s.transfers + 1);
    s.cycleActions = [];
    s.lastSource = "";
    s.lastAction = "";
    saveCustody(s);
    if (LEDGER_SCENE_KEY[target]) grantLedgerVisit(target);
    syncCustodyLink();
    paintCustodyMemory();
  };

  /* 办公室动作：先校验 live scene / 合法 action / 无 pending / 无同 scope
     AutoAdvance，再有任何副作用；第一拍接受后全部机关同步 disabled */
  const chooseCustodyOffice = (actionId) => {
    const meta = CUSTODY_OFFICE_ACTIONS[actionId];
    if (!meta) return;
    if (currentScene !== CUSTODY_OFFICE) return;
    if (AutoAdvance.has(CUSTODY_OFFICE)) return;
    const st = getCustody();
    if (st.pending) return;
    if (actionId === "void" && !custodyVoidArmed(st.scores)) return;
    const r = custodyOfficeRoute(actionId, st.scores);
    if (meta.bank) st.scores[meta.bank] = Math.min(CUSTODY_NUM_CAP, st.scores[meta.bank] + 2);
    st.pending = { scene: CUSTODY_OFFICE, action: actionId, target: r.target, feedback: r.feedback };
    saveCustody(st);
    custodyLockButtons(CUSTODY_OFFICE);
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $("#chain-response");
    if (responseEl) responseEl.textContent = r.feedback;
    AudioEngine.knock(0.16);
    paintCustody();
    AutoAdvance.schedule(CUSTODY_OFFICE, r.target, { delay: branchDelay(), before: () => custodyOfficeArrive(r.target) });
  };

  /* reload/离开重返节拍恢复：合法 pending 属于当前场景时逐字重播反馈并
     精确重挂一次，不二次计分；重播期间该场景全部热点重新 disabled
     （视觉与 pending 锁一致），办公室 pending 另恢复被选机关的 aria-pressed */
  const replayCustodyPending = (sceneName) => {
    const st = getCustody();
    const p = st.pending;
    if (!p || p.scene !== sceneName) return;
    if (p.scene === CUSTODY_OFFICE) {
      custodyLockButtons(CUSTODY_OFFICE);
      const btn = $(CUSTODY_OFFICE_ACTIONS[p.action].btn);
      if (btn) btn.setAttribute("aria-pressed", "true");
      const responseEl = $("#chain-response");
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule(sceneName, p.target, { delay: branchDelay(), before: () => custodyOfficeArrive(p.target) });
    } else {
      custodyLockButtons(sceneName);
      const responseEl = $(p.scene === "evidence-vault" ? "#vault-response" : "#shaft-response");
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule(sceneName, CUSTODY_OFFICE, { delay: branchDelay(), before: () => custodySourceArrive() });
    }
  };

  /* 办公室进入：幂等补记 office visit（目录原子恢复）、解锁机关、清响应、重绘 */
  const enterCustodyOffice = () => {
    const st = getCustody();
    if (!st.visited.office) {
      st.visited.office = true;
      saveCustody(st);
      syncCustodyLink();
    }
    custodyUnlockButtons(CUSTODY_OFFICE);
    Object.keys(CUSTODY_OFFICE_ACTIONS).forEach((a) => {
      const b = $(CUSTODY_OFFICE_ACTIONS[a].btn);
      if (b) b.setAttribute("aria-pressed", "false");
    });
    const responseEl = $("#chain-response");
    if (responseEl) responseEl.textContent = "";
    paintCustody();
  };

  /* 签条：三项分值 + 本轮登记数；空白见证位只在拉平且无 pending 时显露 */
  const paintCustody = () => {
    const st = getCustody();
    $$("[data-chain-custody]").forEach((el) => { el.textContent = st.scores.custody; });
    $$("[data-chain-revision]").forEach((el) => { el.textContent = st.scores.revision; });
    $$("[data-chain-claim]").forEach((el) => { el.textContent = st.scores.claim; });
    $$("[data-chain-count]").forEach((el) => { el.textContent = `${st.cycleActions.length}/8`; });
    const voidBtn = $("#chain-action-void");
    if (voidBtn) {
      if (custodyVoidArmed(st.scores) && !st.pending) voidBtn.removeAttribute("hidden");
      else voidBtn.setAttribute("hidden", "");
    }
  };

  const syncCustodyLink = () => {
    const link = $("#custody-chain-link");
    if (!link) return;
    if (getCustody().visited.office) link.removeAttribute("hidden");
    else link.setAttribute("hidden", "");
  };

  /* 痕迹页单行：累计交接、办公室结算、三项分值、本轮登记数；八卡不变 */
  const paintCustodyMemory = () => {
    const memory = $("#custody-chain-memory");
    if (!memory) return;
    const st = getCustody();
    const active = st.visited.vault || st.visited.shaft || st.visited.office
      || st.officeRuns > 0 || st.transfers > 0 || st.cycleActions.length > 0;
    if (!active) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `证物链：交接 ${st.transfers} 次，办公室结算 ${st.officeRuns} 次；保全 ${st.scores.custody}，改写 ${st.scores.revision}，认领 ${st.scores.claim}，本轮已登记 ${st.cycleActions.length}/8。`;
    memory.hidden = false;
  };

  Object.keys(CUSTODY_OFFICE_ACTIONS).forEach((actionId) => {
    const btn = $(CUSTODY_OFFICE_ACTIONS[actionId].btn);
    if (btn) btn.addEventListener("click", () => chooseCustodyOffice(actionId));
  });
  paintCustody();

  /* ============================================================
     v61 故障重演：v30 三深房基础态图内化 + 三房重演证据 + 故障重演台
     状态独立存 goddead_v61_failure_reconstruction（全仓库唯一 key，
     version 61），容错坏 JSON；canonical 九键显式投影落盘，印证/失真/
     归责分值、说明句、齐备与可否结算全部由三房 selection 派生，永不
     落盘。只读写自己的键；到达受守卫目标时只调用现有最窄 helper
     （grantLedgerVisit / markReviewVisited），不改写 v29/v30/v54/v57/
     v60 或主线结果。pending 四类（board/clue/return/settle）按精确键集
     逐字重算，只消费一次；重播重锁热点并恢复 aria-pressed。
     ============================================================ */
  const FAILURE_KEY = "goddead_v61_failure_reconstruction";
  const FAILURE_VERSION = 61;
  const FAILURE_NUM_CAP = 9999;
  const FAILURE_DESK = "failure-reconstruction-desk";
  const FAILURE_ROOMS = ["echo", "pump", "ledger"];
  const FAILURE_ROOM_SCENE = { echo: "echo-transfer", pump: "vein-pump", ledger: "confession-ledger" };
  const FAILURE_SCENE_ROOM = { "echo-transfer": "echo", "vein-pump": "pump", "confession-ledger": "ledger" };
  const FAILURE_OUTCOME_TARGETS = ["evidence-vault", "protocol-drift", "liability-ledger", "false-confirmation-desk", "witness-carbon-archive", "blank-name-cloakroom", "chain-of-custody-office"];
  /* 九条证据：标签短名 / 分值 / 句段 / 反馈（逐字冻结） */
  const FAILURE_CLUES = {
    echo: {
      "sealed-voice": { btn: "#failure-echo-sealed-voice", short: "声筒", scores: { confirm: 2 }, phrase: "声音被封在蜡筒里", feedback: "声筒回放了你尚未说出的尾音。它把这句证词归到曾经发生。" },
      "cut-relay": { btn: "#failure-echo-cut-relay", short: "拨叉", scores: { distort: 2 }, phrase: "转接器自己剪断了来路", feedback: "拨叉两端同时带电。线路不是被切断，而是在两边各自继续。" },
      "late-bell": { btn: "#failure-echo-late-bell", short: "铃牌", scores: { blame: 2 }, phrase: "迟到的铃替来电签了收", feedback: "空白铃牌先落下蜡印，来电才在档案里出现。" },
    },
    pump: {
      "reverse-needle": { btn: "#failure-pump-reverse-needle", short: "倒行表", scores: { distort: 2 }, phrase: "倒走的表针替事故加压", feedback: "表针每退一格，管道就多出一段从未发生的压力。" },
      "tagged-reservoir": { btn: "#failure-pump-tagged-reservoir", short: "沉积槽", scores: { blame: 2 }, phrase: "黑沉积槽认领了回流", feedback: "沉积物在空白名牌下凝固。没人签字，它却知道该向谁追责。" },
      "triple-seal-ladder": { btn: "#failure-pump-triple-seal-ladder", short: "封签梯", scores: { confirm: 1, distort: 1, blame: 1 }, phrase: "三枚封签让无号梯级同时作证", feedback: "三枚封签互不相认，却在同一级梯上留下同一枚鞋印。" },
    },
    ledger: {
      "witness-carbon": { btn: "#failure-ledger-witness-carbon", short: "复写章", scores: { confirm: 2 }, phrase: "复写章证明见证人仍在场", feedback: "第二张空纸先显出压痕。见证人还没出现，副本已经替他作证。" },
      "erasure-blade": { btn: "#failure-ledger-erasure-blade", short: "擦名刀", scores: { distort: 2 }, phrase: "擦名刀把同一页改成两份", feedback: "刀锋没有刮掉名字，只把同一处空白分成了两种说法。" },
      "refusal-drawer": { btn: "#failure-ledger-refusal-drawer", short: "拒收屉", scores: { blame: 2 }, phrase: "拒收抽屉保存了责任人的位置", feedback: "抽屉里没有姓名，只有一块始终为某个人留空的凹槽。" },
    },
  };
  const FAILURE_ROOM_META = {
    echo: {
      entryBtn: "#failure-echo-entry", returnBtn: "#failure-echo-return", responseEl: "#echo-transfer-response",
      baseImg: "assets/echo-transfer-chamber.webp", reconImg: "assets/v61-failure-echo-transfer.webp",
      baseFigLabel: "布满分线器与蜡筒的转接台，铜管沿墙汇入黑暗",
      reconFigLabel: "失真转接室·重演：左侧封存声筒、中央断路拨叉、右侧迟到铃牌、后方返回孔",
      baseBtns: ["#echo-transfer-choice-relay", "#echo-transfer-choice-seal", "#echo-transfer-choice-bell"],
      entryFeedback: "封签断开。转接室把那次失真重新摆上台面。",
    },
    pump: {
      entryBtn: "#failure-pump-entry", returnBtn: "#failure-pump-return", responseEl: "#vein-pump-response",
      baseImg: "assets/reverse-flow-pump-room.webp", reconImg: "assets/v61-failure-vein-pump.webp",
      baseFigLabel: "倒转的压力表与铜制泵体，墙角一架应急梯",
      reconFigLabel: "逆流泵房·重演：左侧倒行压力表、中央责任沉积槽、右侧三封签梯、后方返回门",
      baseBtns: ["#vein-pump-choice-release", "#vein-pump-choice-sediment", "#vein-pump-choice-ladder"],
      entryFeedback: "倒放阀转动。泵房把那次逆流重新压回管道。",
    },
    ledger: {
      entryBtn: "#failure-ledger-entry", returnBtn: "#failure-ledger-return", responseEl: "#confession-ledger-response",
      baseImg: "assets/nameless-ledger-vault.webp", reconImg: "assets/v61-failure-confession-ledger.webp",
      baseFigLabel: "高耸的罪籍架与摊开的无名册页，墨水瓶还开着",
      reconFigLabel: "无名罪籍库·重演：左侧见证复写章、中央擦名刀与空账、右侧责任拒收屉、后方返回门",
      baseBtns: ["#ledger-choice-crossout", "#ledger-choice-archive", "#ledger-choice-reject"],
      entryFeedback: "重演抽屉滑开。罪籍库把那页空白重新摊开。",
    },
  };
  const FAILURE_RETURN_FEEDBACK = "你退回重演台。已取的证词留在板上。";
  const FAILURE_BOARD_META = {
    echo: { btn: "#failure-board-echo", emptyTitle: "选择转接室证据", emptyPhrase: "转接室的证词槽还空着", feedback: "转接室的证词板被抽回房间。重演在原来的机台上继续。" },
    pump: { btn: "#failure-board-pump", emptyTitle: "选择泵房证据", emptyPhrase: "泵房的证词槽还空着", feedback: "泵房的证词板被抽回房间。重演在原来的机台上继续。" },
    ledger: { btn: "#failure-board-ledger", emptyTitle: "选择罪籍库证据", emptyPhrase: "罪籍库的证词槽还空着", feedback: "罪籍库的证词板被抽回房间。重演在原来的机台上继续。" },
  };
  /* 重演台分流纯函数：当前派生分值直接路由，不额外加分；全等按 v60 开放契约去证物链办公室 */
  const failureSettleRoute = (scores) => {
    const c = scores.confirm;
    const d = scores.distort;
    const b = scores.blame;
    if (c === d && d === b) return { target: "chain-of-custody-office", feedback: "三项拉平。证物链办公室要求接手这次没有主因的事故。" };
    if (c > d && c > b) return { target: "evidence-vault", feedback: "三段重演彼此印证。证词被送往异常保全库，等它继续证明自己。" };
    if (d > c && d > b) return { target: "protocol-drift", feedback: "重演中的失真压过其余两项。守则被迫承认，故障发生在叙述之前。" };
    if (b > c && b > d) return { target: "liability-ledger", feedback: "责任留下了最重的刻痕。事故被送回责任账房，重新称一次名字。" };
    if (c === d) return { target: "false-confirmation-desk", feedback: "印证与失真彼此作证。故障被送去假确认台，那里只记录一致的错误。" };
    if (c === b) return { target: "witness-carbon-archive", feedback: "印证与归责互相盖章。见证副本被送进复写库，等待原件承认。" };
    return { target: "blank-name-cloakroom", feedback: "失真与归责共同指向一个被擦掉的名字。事故寄存在空名衣柜。" };
  };
  const failureScores = (st) => {
    const scores = { confirm: 0, distort: 0, blame: 0 };
    FAILURE_ROOMS.forEach((room) => {
      const sel = st.selections[room];
      if (!sel) return;
      const sc = FAILURE_CLUES[room][sel].scores;
      Object.keys(sc).forEach((k) => { scores[k] = Math.min(FAILURE_NUM_CAP, scores[k] + sc[k]); });
    });
    return scores;
  };

  const getFailure = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(FAILURE_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    /* 错版本整体丢弃 */
    if (raw.version !== FAILURE_VERSION) raw = {};
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(FAILURE_NUM_CAP, Math.floor(n));
    };
    const cycle = num(raw.cycle) || 1;
    const visited = {};
    FAILURE_ROOMS.concat(["desk"]).forEach((k) => { visited[k] = Boolean(raw.visited && raw.visited[k] === true); });
    const selections = {};
    FAILURE_ROOMS.forEach((room) => {
      selections[room] = raw.selections && FAILURE_CLUES[room][raw.selections[room]] ? raw.selections[room] : "";
    });
    const outcomeCounts = {};
    FAILURE_OUTCOME_TARGETS.forEach((t) => { outcomeCounts[t] = num(raw.outcomeCounts && raw.outcomeCounts[t]); });
    const lastOutcome = FAILURE_OUTCOME_TARGETS.includes(raw.lastOutcome) ? raw.lastOutcome : "";
    const replayRoom = FAILURE_ROOMS.includes(raw.replayRoom) ? raw.replayRoom : "";
    const completedRuns = num(raw.completedRuns);
    const scores = failureScores({ selections });
    const complete = FAILURE_ROOMS.every((r) => selections[r]);
    /* pending 四类精确键集（额外键即伪造），逐字重算 + 严格证据：
       board = replayRoom 同房；clue = selections 恰为该条；return = replayRoom
       同房；settle = 三房齐备且 target/feedback 由当前派生分值逐字重算 */
    let pending = null;
    if (raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const p = raw.pending;
      const keys = Object.keys(p).sort().join(",");
      if (p.kind === "board" && keys === "action,cycle,feedback,kind,scene,target"
        && p.scene === FAILURE_DESK && FAILURE_ROOMS.includes(p.action)
        && p.target === FAILURE_ROOM_SCENE[p.action] && num(p.cycle) === cycle
        && p.feedback === FAILURE_BOARD_META[p.action].feedback
        && replayRoom === p.action) {
        pending = { kind: "board", scene: FAILURE_DESK, action: p.action, target: p.target, feedback: p.feedback, cycle };
      } else if (p.kind === "clue" && keys === "action,cycle,feedback,kind,room,scene,target"
        && FAILURE_ROOMS.includes(p.room) && p.scene === FAILURE_ROOM_SCENE[p.room]
        && FAILURE_CLUES[p.room][p.action] && p.target === FAILURE_DESK && num(p.cycle) === cycle
        && p.feedback === FAILURE_CLUES[p.room][p.action].feedback
        && selections[p.room] === p.action) {
        pending = { kind: "clue", scene: p.scene, room: p.room, action: p.action, target: FAILURE_DESK, feedback: p.feedback, cycle };
      } else if (p.kind === "return" && keys === "cycle,feedback,kind,room,scene,target"
        && FAILURE_ROOMS.includes(p.room) && p.scene === FAILURE_ROOM_SCENE[p.room]
        && p.target === FAILURE_DESK && num(p.cycle) === cycle
        && p.feedback === FAILURE_RETURN_FEEDBACK
        && replayRoom === p.room) {
        pending = { kind: "return", scene: p.scene, room: p.room, target: FAILURE_DESK, feedback: p.feedback, cycle };
      } else if (p.kind === "settle" && keys === "cycle,feedback,kind,scene,target"
        && p.scene === FAILURE_DESK && num(p.cycle) === cycle && complete) {
        const r = failureSettleRoute(scores);
        if (p.target === r.target && p.feedback === r.feedback) {
          pending = { kind: "settle", scene: FAILURE_DESK, target: r.target, feedback: r.feedback, cycle };
        }
      }
    }
    return {
      cycle, visited, selections, completedRuns, outcomeCounts, lastOutcome, replayRoom, pending,
      pendingTarget: pending ? pending.target : "",
    };
  };
  /* 只持久化白名单 canonical 九键；派生字段永不落盘 */
  const saveFailure = (st) => store.set(FAILURE_KEY, JSON.stringify({
    version: FAILURE_VERSION,
    cycle: st.cycle,
    visited: st.visited,
    selections: st.selections,
    completedRuns: st.completedRuns,
    outcomeCounts: st.outcomeCounts,
    lastOutcome: st.lastOutcome,
    replayRoom: st.replayRoom,
    pending: st.pending,
  }));

  /* 第一拍接受后全热点同步 disabled；回场景/遗忘时恢复 */
  const failureLockRoom = (room) => {
    const sels = Object.keys(FAILURE_CLUES[room]).map((c) => FAILURE_CLUES[room][c].btn).concat([FAILURE_ROOM_META[room].returnBtn]);
    sels.forEach((sel) => { const b = $(sel); if (b) b.disabled = true; });
  };
  const failureLockDesk = () => {
    FAILURE_ROOMS.forEach((room) => { const b = $(FAILURE_BOARD_META[room].btn); if (b) b.disabled = true; });
    const lever = $("#failure-lever");
    if (lever) lever.disabled = true;
  };
  const failureUnlockDesk = () => {
    FAILURE_ROOMS.forEach((room) => { const b = $(FAILURE_BOARD_META[room].btn); if (b) b.disabled = false; });
    const lever = $("#failure-lever");
    if (lever) lever.disabled = false;
  };

  /* 三房图面同步：replayRoom 命中 → 换 v61 重演图、隐藏并禁用旧三动作与
     入口、显示三条证据热点与退回热点；否则回弹基础图与旧三动作 */
  const syncFailureRoom = (room) => {
    const meta = FAILURE_ROOM_META[room];
    if (!meta) return;
    const st = getFailure();
    const isRecon = st.replayRoom === room;
    const section = $(`#scene-${FAILURE_ROOM_SCENE[room]}`);
    if (!section) return;
    const img = section.querySelector(".branch-img");
    setSceneImageSrc(img, isRecon ? meta.reconImg : meta.baseImg);
    const figure = section.querySelector(".branch-figure");
    if (figure) figure.setAttribute("aria-label", isRecon ? meta.reconFigLabel : meta.baseFigLabel);
    meta.baseBtns.concat([meta.entryBtn]).forEach((sel) => {
      const b = $(sel);
      if (!b) return;
      if (isRecon) { b.setAttribute("hidden", ""); b.disabled = true; }
      else { b.removeAttribute("hidden"); b.disabled = false; }
    });
    Object.keys(FAILURE_CLUES[room]).forEach((clueId) => {
      const b = $(FAILURE_CLUES[room][clueId].btn);
      if (!b) return;
      if (isRecon) { b.removeAttribute("hidden"); b.disabled = false; }
      else { b.setAttribute("hidden", ""); b.disabled = true; }
      b.setAttribute("aria-pressed", st.selections[room] === clueId ? "true" : "false");
    });
    const retBtn = $(meta.returnBtn);
    if (retBtn) {
      if (isRecon) { retBtn.removeAttribute("hidden"); retBtn.disabled = false; }
      else { retBtn.setAttribute("hidden", ""); retBtn.disabled = true; }
    }
  };

  /* 重演入口：可信点击只换图与揭示热点，不计分不写 selection */
  const chooseFailureEntry = (room) => {
    const sceneName = FAILURE_ROOM_SCENE[room];
    if (currentScene !== sceneName) return;
    if (AutoAdvance.has(sceneName)) return;
    const st = getFailure();
    if (st.pending) return;
    if (st.replayRoom === room) return;
    st.replayRoom = room;
    if (!st.visited[room]) st.visited[room] = true;
    saveFailure(st);
    syncFailureRoom(room);
    const meta = FAILURE_ROOM_META[room];
    const entryBtn = $(meta.entryBtn);
    if (entryBtn) entryBtn.setAttribute("aria-pressed", "true");
    const responseEl = $(meta.responseEl);
    if (responseEl) responseEl.textContent = meta.entryFeedback;
    AudioEngine.knock(0.16);
    paintFailureMemory();
  };

  /* 到达重演台通用尾件（clue/return）：原子记 desk visit、清 replayRoom、
     清 pending（consume once） */
  const failureDeskArrive = () => {
    const s = getFailure();
    if (!s.visited.desk) s.visited.desk = true;
    if (s.replayRoom) s.replayRoom = "";
    if (s.pending) s.pending = null;
    saveFailure(s);
    syncFailureLink();
    paintFailureMemory();
  };

  /* 证据选择：selection 原子替换（重选同条只是重播同值，派生分值自然不变），
     持久化严格 pending，一拍自动回重演台 */
  const chooseFailureClue = (room, clueId) => {
    const meta = FAILURE_CLUES[room] && FAILURE_CLUES[room][clueId];
    if (!meta) return;
    const sceneName = FAILURE_ROOM_SCENE[room];
    if (currentScene !== sceneName) return;
    if (AutoAdvance.has(sceneName)) return;
    const st = getFailure();
    if (st.pending) return;
    if (st.replayRoom !== room) return;
    st.selections[room] = clueId;
    st.pending = { kind: "clue", scene: sceneName, room, action: clueId, target: FAILURE_DESK, feedback: meta.feedback, cycle: st.cycle };
    saveFailure(st);
    failureLockRoom(room);
    const btn = $(meta.btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $(FAILURE_ROOM_META[room].responseEl);
    if (responseEl) responseEl.textContent = meta.feedback;
    AudioEngine.knock(0.16);
    paintFailureMemory();
    AutoAdvance.schedule(sceneName, FAILURE_DESK, { delay: branchDelay(), before: () => failureDeskArrive() });
  };

  /* 退回重演台：不改 selection，短反馈后回台 */
  const chooseFailureReturn = (room) => {
    const sceneName = FAILURE_ROOM_SCENE[room];
    if (currentScene !== sceneName) return;
    if (AutoAdvance.has(sceneName)) return;
    const st = getFailure();
    if (st.pending) return;
    if (st.replayRoom !== room) return;
    st.pending = { kind: "return", scene: sceneName, room, target: FAILURE_DESK, feedback: FAILURE_RETURN_FEEDBACK, cycle: st.cycle };
    saveFailure(st);
    failureLockRoom(room);
    const responseEl = $(FAILURE_ROOM_META[room].responseEl);
    if (responseEl) responseEl.textContent = FAILURE_RETURN_FEEDBACK;
    AudioEngine.knock(0.16);
    AutoAdvance.schedule(sceneName, FAILURE_DESK, { delay: branchDelay(), before: () => failureDeskArrive() });
  };

  /* 证词板：先持久化 replayRoom 再转场，到达旧房即重演态；旧 selection 保留 */
  const chooseFailureBoard = (room) => {
    if (currentScene !== FAILURE_DESK) return;
    if (AutoAdvance.has(FAILURE_DESK)) return;
    const st = getFailure();
    if (st.pending) return;
    st.replayRoom = room;
    if (!st.visited[room]) st.visited[room] = true;
    st.pending = { kind: "board", scene: FAILURE_DESK, action: room, target: FAILURE_ROOM_SCENE[room], feedback: FAILURE_BOARD_META[room].feedback, cycle: st.cycle };
    saveFailure(st);
    failureLockDesk();
    const btn = $(FAILURE_BOARD_META[room].btn);
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $("#failure-response");
    if (responseEl) responseEl.textContent = FAILURE_BOARD_META[room].feedback;
    AudioEngine.knock(0.16);
    paintFailureMemory();
    AutoAdvance.schedule(FAILURE_DESK, FAILURE_ROOM_SCENE[room], { delay: branchDelay(), before: () => failureBoardArrive() });
  };
  const failureBoardArrive = () => {
    const s = getFailure();
    if (s.pending) s.pending = null;
    saveFailure(s);
  };

  /* 重演总栓：三房齐备才可点；当前派生分值直接路由，不额外加分；
     到达目标 before 才原子结算开新轮，并补最窄旧守卫凭证 */
  const chooseFailureLever = () => {
    if (currentScene !== FAILURE_DESK) return;
    if (AutoAdvance.has(FAILURE_DESK)) return;
    const st = getFailure();
    if (st.pending) return;
    if (!FAILURE_ROOMS.every((r) => st.selections[r])) return;
    const r = failureSettleRoute(failureScores(st));
    st.pending = { kind: "settle", scene: FAILURE_DESK, target: r.target, feedback: r.feedback, cycle: st.cycle };
    saveFailure(st);
    failureLockDesk();
    const btn = $("#failure-lever");
    if (btn) btn.setAttribute("aria-pressed", "true");
    const responseEl = $("#failure-response");
    if (responseEl) responseEl.textContent = r.feedback;
    AudioEngine.knock(0.16);
    paintFailure();
    AutoAdvance.schedule(FAILURE_DESK, r.target, { delay: branchDelay(), before: () => failureSettleArrive(r.target) });
  };
  const failureSettleArrive = (target) => {
    const s = getFailure();
    if (s.pending) s.pending = null;
    s.completedRuns = Math.min(FAILURE_NUM_CAP, s.completedRuns + 1);
    if (s.outcomeCounts[target] !== undefined) s.outcomeCounts[target] = Math.min(FAILURE_NUM_CAP, s.outcomeCounts[target] + 1);
    s.lastOutcome = FAILURE_OUTCOME_TARGETS.includes(target) ? target : "";
    s.cycle = Math.min(FAILURE_NUM_CAP, s.cycle + 1);
    FAILURE_ROOMS.forEach((room) => { s.selections[room] = ""; });
    s.replayRoom = "";
    saveFailure(s);
    if (LEDGER_SCENE_KEY[target]) grantLedgerVisit(target);
    if (target === "evidence-vault") markReviewVisited("evidence-vault");
    syncFailureLink();
    paintFailureMemory();
  };

  /* reload/离开重返节拍恢复：逐字重播反馈并精确重挂一次，不二次选证/结算；
     重播期间重新锁定相关全部热点并恢复被选项 aria-pressed */
  const replayFailurePending = (sceneName) => {
    const st = getFailure();
    const p = st.pending;
    if (!p || p.scene !== sceneName) return;
    if (p.kind === "board" || p.kind === "settle") {
      failureLockDesk();
      const btn = $(p.kind === "board" ? FAILURE_BOARD_META[p.action].btn : "#failure-lever");
      if (btn) btn.setAttribute("aria-pressed", "true");
      const responseEl = $("#failure-response");
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule(sceneName, p.target, { delay: branchDelay(), before: p.kind === "board" ? () => failureBoardArrive() : () => failureSettleArrive(p.target) });
    } else {
      failureLockRoom(p.room);
      if (p.kind === "clue") {
        const btn = $(FAILURE_CLUES[p.room][p.action].btn);
        if (btn) btn.setAttribute("aria-pressed", "true");
      }
      const responseEl = $(FAILURE_ROOM_META[p.room].responseEl);
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule(sceneName, FAILURE_DESK, { delay: branchDelay(), before: () => failureDeskArrive() });
    }
  };

  /* 重演台进入：幂等补记 desk visit、解锁机关、清响应、按派生重绘 */
  const enterFailureDesk = () => {
    const st = getFailure();
    if (!st.visited.desk) {
      st.visited.desk = true;
      saveFailure(st);
      syncFailureLink();
    }
    failureUnlockDesk();
    const responseEl = $("#failure-response");
    if (responseEl) responseEl.textContent = "";
    paintFailure();
  };

  /* 台面重绘：说明句（三句段）/ 签条 / 证词板标签与 aria / 总栓显露 */
  const paintFailure = () => {
    const st = getFailure();
    const scores = failureScores(st);
    $$("[data-failure-confirm]").forEach((el) => { el.textContent = scores.confirm; });
    $$("[data-failure-distort]").forEach((el) => { el.textContent = scores.distort; });
    $$("[data-failure-blame]").forEach((el) => { el.textContent = scores.blame; });
    const picked = FAILURE_ROOMS.filter((r) => st.selections[r]).length;
    $$("[data-failure-count]").forEach((el) => { el.textContent = `${picked}/3`; });
    const desc = $("#failure-desc");
    if (desc) {
      desc.textContent = `${FAILURE_ROOMS.map((room) => (st.selections[room] ? FAILURE_CLUES[room][st.selections[room]].phrase : FAILURE_BOARD_META[room].emptyPhrase)).join("；")}。`;
    }
    FAILURE_ROOMS.forEach((room) => {
      const btn = $(FAILURE_BOARD_META[room].btn);
      if (!btn) return;
      const sel = st.selections[room];
      const title = btn.querySelector(".bb-title");
      if (title) title.textContent = sel ? `重选：${FAILURE_CLUES[room][sel].short}` : FAILURE_BOARD_META[room].emptyTitle;
      btn.setAttribute("aria-pressed", sel ? "true" : "false");
    });
    const lever = $("#failure-lever");
    if (lever) {
      if (picked === 3 && !st.pending) lever.removeAttribute("hidden");
      else lever.setAttribute("hidden", "");
    }
  };

  const syncFailureLink = () => {
    const link = $("#failure-link");
    if (!link) return;
    if (getFailure().visited.desk) link.removeAttribute("hidden");
    else link.setAttribute("hidden", "");
  };

  /* 痕迹页单行：完成轮数、四类落点计数摘要、本轮取证数；八卡不变 */
  const paintFailureMemory = () => {
    const memory = $("#failure-memory");
    if (!memory) return;
    const st = getFailure();
    const active = FAILURE_ROOMS.some((r) => st.visited[r]) || st.visited.desk || st.completedRuns > 0
      || FAILURE_ROOMS.some((r) => st.selections[r]) || Boolean(st.replayRoom);
    if (!active) {
      memory.hidden = true;
      return;
    }
    const oc = st.outcomeCounts;
    const ties = oc["false-confirmation-desk"] + oc["witness-carbon-archive"] + oc["blank-name-cloakroom"] + oc["chain-of-custody-office"];
    const picked = FAILURE_ROOMS.filter((r) => st.selections[r]).length;
    memory.textContent = `故障重演：完成 ${st.completedRuns} 轮；印证 ${oc["evidence-vault"]}、失真 ${oc["protocol-drift"]}、归责 ${oc["liability-ledger"]}、拉平 ${ties}，本轮已取证 ${picked}/3。`;
    memory.hidden = false;
  };

  /* v61 合成守卫：入口/证据/退回/证词板/总栓全部只接受 isTrusted 真实 click */
  FAILURE_ROOMS.forEach((room) => {
    const entryBtn = $(FAILURE_ROOM_META[room].entryBtn);
    if (entryBtn) entryBtn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseFailureEntry(room); });
    Object.keys(FAILURE_CLUES[room]).forEach((clueId) => {
      const btn = $(FAILURE_CLUES[room][clueId].btn);
      if (btn) btn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseFailureClue(room, clueId); });
    });
    const retBtn = $(FAILURE_ROOM_META[room].returnBtn);
    if (retBtn) retBtn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseFailureReturn(room); });
    const boardBtn = $(FAILURE_BOARD_META[room].btn);
    if (boardBtn) boardBtn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseFailureBoard(room); });
  });
  const failureLeverBtn = $("#failure-lever");
  if (failureLeverBtn) failureLeverBtn.addEventListener("click", (ev) => { if (!ev.isTrusted) return; chooseFailureLever(); });
  paintFailure();

  /* ============================================================
     v40 门外侧廊：首页纵深环境层 + 左右廊热点 + 三个画面热点场景
     状态独立存 goddead_v40_lateral_corridors，容错坏 JSON；
     pending 必须是 {scene, action, target, feedback} 完整合法映射；
     不读不写 v28–v39 与主线状态；点击即执行，无确认/继续按钮。
     ============================================================ */
  const LATERAL_KEY = "goddead_v40_lateral_corridors";
  const LATERAL_SCENES = ["lamp", "shadow", "hinge"];
  const LATERAL_SCENE_NAMES = ["unlit-lamp-gallery", "borrowed-shadow-gallery", "hinge-sorting-room"];
  const LATERAL_SCENE_NAME = { lamp: "unlit-lamp-gallery", shadow: "borrowed-shadow-gallery", hinge: "hinge-sorting-room" };
  const LATERAL_NAME_SCENE = { "unlit-lamp-gallery": "lamp", "borrowed-shadow-gallery": "shadow", "hinge-sorting-room": "hinge" };
  const LATERAL_ENTRIES = ["threshold-left", "threshold-right", "lamp", "shadow", "direct"];
  const LATERAL_MARKS = [
    "enteredLeftCorridor", "enteredRightCorridor",
    "touchedUnlitLamp", "followedLampRail", "escapedLampGallery",
    "stoodInBorrowedShadow", "openedShadowDoor", "followedDoorShadow",
    "fittedInwardHinge", "fittedOutwardHinge", "removedFinalHinge",
  ];
  const LATERAL_NUM_CAP = 9999;

  const LATERAL_ACTIONS = {
    lamp: {
      lamp: { btn: "#lamp-hotspot-lamp", target: "borrowed-shadow-gallery", feedback: "灯没有亮，影子却换到了你的脚下。", mark: "touchedUnlitLamp" },
      shadow: { btn: "#lamp-hotspot-rail", target: "hinge-sorting-room", feedback: "铜轨先在墙里拐弯，随后拖着走廊一起转向。", mark: "followedLampRail" },
      passage: { btn: "#lamp-hotspot-squeeze", target: "return-passage", feedback: "两排灯把你夹成一条更窄的回来。", mark: "escapedLampGallery" },
    },
    shadow: {
      stand: { btn: "#shadow-hotspot-stand", target: "unlit-lamp-gallery", feedback: "影子替你站住，灯廊因此空出一个位置。", mark: "stoodInBorrowedShadow" },
      shadowDoor: { btn: "#shadow-hotspot-door", target: "hinge-sorting-room", feedback: "没有门的铰链先响了。墙面向两侧让开。", mark: "openedShadowDoor" },
      peephole: { btn: "#shadow-hotspot-follow", target: "peephole-chamber", feedback: "门影从窥孔背面经过。你只好从里面去看它。", mark: "followedDoorShadow" },
    },
    hinge: {
      inward: { btn: "#hinge-hotspot-inward", target: "glyph-niche", feedback: "门轴把你的选择数成了第九道刻痕。", mark: "fittedInwardHinge" },
      remove: { btn: "#hinge-hotspot-remove", target: "return-audit", feedback: "门从路线中被删除。核验站要求你证明还记得来路。", mark: "removedFinalHinge" },
      outward: { btn: "#hinge-hotspot-outward", target: "proxy-admission", feedback: "门框向门外打开。代审窗已经在等下一位访客。", mark: "fittedOutwardHinge" },
    },
  };
  /* v31 门前守卫的 v40 窄例外表：lateral action → 唯一放行的 v31 场景 */
  const LATERAL_V31_TARGET = { passage: "return-passage", peephole: "peephole-chamber", inward: "glyph-niche" };
  const LATERAL_RESPONSE_EL = { lamp: "#lamp-response", shadow: "#shadow-response", hinge: "#hinge-response" };
  const LATERAL_LINKS = { lamp: "#lamp-link", shadow: "#shadow-link", hinge: "#hinge-link" };

  const getLateral = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(LATERAL_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    /* visited 只接受 lamp / shadow / hinge 三个布尔键 */
    const visited = {};
    LATERAL_SCENES.forEach((s) => {
      visited[s] = Boolean(raw.visited && raw.visited[s] === true);
    });
    const entry = LATERAL_ENTRIES.includes(raw.entry) ? raw.entry : "direct";
    /* pending 必须是 {scene, action, target, feedback} 的完整合法映射，
       四字段与白名单表严格对应；伪造 target/feedback 等任何错配即清空。
       pending 只用于恢复已接受但尚未完成的自动转场，不作为已访问或计数依据 */
    let pending = null;
    if (raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const acts = LATERAL_ACTIONS[raw.pending.scene];
      const act = acts && acts[raw.pending.action];
      if (act && raw.pending.target === act.target && raw.pending.feedback === act.feedback) {
        pending = { scene: raw.pending.scene, action: raw.pending.action, target: act.target, feedback: act.feedback };
      }
    }
    /* lastScene / lastAction 只接受白名单且必须互相匹配 */
    const lastScene = LATERAL_SCENES.includes(raw.lastScene) ? raw.lastScene : "";
    const lastAction = lastScene && LATERAL_ACTIONS[lastScene][raw.lastAction] ? raw.lastAction : "";
    let traversals = Number(raw.traversals);
    if (!Number.isFinite(traversals) || traversals < 0) traversals = 0;
    traversals = Math.min(LATERAL_NUM_CAP, Math.floor(traversals));
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => LATERAL_MARKS.includes(m)))].slice(0, LATERAL_MARKS.length)
      : [];
    return { visited, entry, pending, lastScene, lastAction, traversals, marks };
  };
  const saveLateral = (st) => store.set(LATERAL_KEY, JSON.stringify(st));

  const syncLateralLinks = () => {
    const st = getLateral();
    LATERAL_SCENES.forEach((s) => {
      const link = $(LATERAL_LINKS[s]);
      if (!link) return;
      if (st.visited[s]) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  /* 到访标记在点击/进入时立即持久化：即便转场被回退取消，目录入口也已出现 */
  const markLateralVisited = (sceneKey) => {
    const st = getLateral();
    if (!LATERAL_SCENES.includes(sceneKey) || st.visited[sceneKey]) return;
    st.visited[sceneKey] = true;
    saveLateral(st);
    syncLateralLinks();
  };

  const lateralDelay = () => reduced ? 300 : 900 + Math.floor(Math.random() * 300);

  const paintLateralScene = (sceneKey) => {
    const st = getLateral();
    const locked = AutoAdvance.has("lateral-" + sceneKey);
    Object.keys(LATERAL_ACTIONS[sceneKey]).forEach((actionId) => {
      const btn = $(LATERAL_ACTIONS[sceneKey][actionId].btn);
      if (!btn) return;
      btn.disabled = locked;
      btn.setAttribute("aria-pressed", st.marks.includes(LATERAL_ACTIONS[sceneKey][actionId].mark) ? "true" : "false");
    });
  };

  /* 进入侧廊场景：到访标记；若合法 pending 属于本场景（reload/离场后重返），
     重播逐字反馈并恢复转场，timer 真正触发前才清 pending */
  const enterLateral = (sceneKey) => {
    markLateralVisited(sceneKey);
    const st = getLateral();
    const responseEl = $(LATERAL_RESPONSE_EL[sceneKey]);
    if (responseEl) responseEl.textContent = "";
    if (st.pending && st.pending.scene === sceneKey) {
      const p = st.pending;
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule("lateral-" + sceneKey, p.target, {
        delay: lateralDelay(),
        before: () => {
          const s = getLateral();
          if (s.pending && s.pending.scene === sceneKey && s.pending.action === p.action) {
            s.pending = null;
            saveLateral(s);
          }
        },
      });
    }
    paintLateralScene(sceneKey);
  };

  /* 九个画面动作：第一项被接受后同场景全部热点立即 disabled（同节拍竞争只接受第一项），
     逐字反馈写入 aria-live，pending 持久化后自动进入目的地。
     守卫：只接受当前活动场景的 hotspot——隐藏 DOM 的脚本化点击在任何
     状态读取/写入、声音、反馈与 timer 之前被拦截 */
  const runLateralAction = (sceneKey, actionId) => {
    const act = LATERAL_ACTIONS[sceneKey] && LATERAL_ACTIONS[sceneKey][actionId];
    if (!act) return;
    if (currentScene !== LATERAL_SCENE_NAME[sceneKey]) return;
    if (AutoAdvance.has("lateral-" + sceneKey)) return;
    const st = getLateral();
    st.lastScene = sceneKey;
    st.lastAction = actionId;
    if (!st.marks.includes(act.mark)) st.marks.push(act.mark);
    st.traversals = Math.min(LATERAL_NUM_CAP, st.traversals + 1);
    st.pending = { scene: sceneKey, action: actionId, target: act.target, feedback: act.feedback };
    if (sceneKey === "lamp" || sceneKey === "shadow") st.entry = sceneKey;
    saveLateral(st);
    const responseEl = $(LATERAL_RESPONSE_EL[sceneKey]);
    if (responseEl) responseEl.textContent = act.feedback;
    AudioEngine.knock(0.16);
    /* 先排定再重绘：节拍内同场景全部热点保持 disabled（同 v38 教训） */
    AutoAdvance.schedule("lateral-" + sceneKey, act.target, {
      delay: lateralDelay(),
      before: () => {
        const s = getLateral();
        if (s.pending && s.pending.scene === sceneKey && s.pending.action === actionId) {
          s.pending = null;
          saveLateral(s);
        }
      },
    });
    paintLateralScene(sceneKey);
  };

  LATERAL_SCENES.forEach((sceneKey) => {
    Object.keys(LATERAL_ACTIONS[sceneKey]).forEach((actionId) => {
      const btn = $(LATERAL_ACTIONS[sceneKey][actionId].btn);
      if (btn) btn.addEventListener("click", () => runLateralAction(sceneKey, actionId));
    });
  });

  /* 首页左右廊热点：与日蚀/符号/回来/代审/三敲共用 threshold 首选锁；
     到访标记与 entry 在点击时立即持久化 */
  const LATERAL_THRESHOLD_SPOTS = {
    "hotspot-lateral-left": { entry: "threshold-left", scene: "lamp", target: "unlit-lamp-gallery", feedback: "左侧黑暗向后退了一步。门没有移动，走廊却从它旁边长了出来。", mark: "enteredLeftCorridor" },
    "hotspot-lateral-right": { entry: "threshold-right", scene: "shadow", target: "borrowed-shadow-gallery", feedback: "右侧墙面折进门影。你还站在门外，但影子已经先行。", mark: "enteredRightCorridor" },
  };
  Object.keys(LATERAL_THRESHOLD_SPOTS).forEach((id) => {
    const btn = $("#" + id);
    const spot = LATERAL_THRESHOLD_SPOTS[id];
    if (!btn) return;
    btn.addEventListener("click", () => {
      /* 守卫：离开首页后隐藏的侧廊热点不得被脚本触发（任何副作用之前拦截） */
      if (currentScene !== "threshold") return;
      if (AutoAdvance.has("threshold")) return;
      const st = getLateral();
      st.entry = spot.entry;
      st.visited[spot.scene] = true;
      if (!st.marks.includes(spot.mark)) st.marks.push(spot.mark);
      st.traversals = Math.min(LATERAL_NUM_CAP, st.traversals + 1);
      saveLateral(st);
      syncLateralLinks();
      btn.classList.add("touched");
      setTimeout(() => btn.classList.remove("touched"), 1200);
      AudioEngine.knock();
      statusLine.textContent = spot.feedback;
      AutoAdvance.schedule("threshold", spot.target, { delay: branchDelay() });
    });
  });

  /* 痕迹页单行：穿行次数与已见场景数，保持八张统计卡不变 */
  const paintLateralMemory = () => {
    const memory = $("#lateral-memory");
    if (!memory) return;
    const st = getLateral();
    const seen = LATERAL_SCENES.filter((s) => st.visited[s]).length;
    if (seen === 0) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `门外侧廊：穿行 ${st.traversals} 次；无灯 / 借影 / 铰链已见 ${seen}/3。`;
    memory.hidden = false;
  };

  /* ============================================================
     v41 守则背室：布告板三入口 + 三间画面热点背室
     状态独立存 goddead_v41_protocol_backrooms，容错坏 JSON；
     pending 必须是 {scene, action, target, feedback} 完整合法映射；
     不读不写 v28–v40 与主线状态；点击即执行，无确认/继续按钮。
     ============================================================ */
  const BACKROOM_KEY = "goddead_v41_protocol_backrooms";
  const BACKROOM_SCENES = ["thread", "name", "bell"];
  const BACKROOM_SCENE_NAMES = ["red-thread-registry", "blank-name-cloakroom", "clapperless-bell-desk"];
  const BACKROOM_SCENE_NAME = { thread: "red-thread-registry", name: "blank-name-cloakroom", bell: "clapperless-bell-desk" };
  const BACKROOM_NAME_SCENE = { "red-thread-registry": "thread", "blank-name-cloakroom": "name", "clapperless-bell-desk": "bell" };
  const BACKROOM_ENTRIES = ["protocol-thread", "protocol-name", "protocol-bell", "thread", "name", "bell", "direct"];
  const BACKROOM_MARKS = [
    "enteredThreadRegistry", "enteredBlankNameCloakroom", "enteredClapperlessBellDesk",
    "loosenedRedSpool", "pressedWitnessSeal", "followedThreadGap",
    "woreOwnerlessCoat", "hungBlankName", "turnedBlankClaimToken",
    "pressedClapperlessBell", "spokeIntoDeskTube", "pulledRedSignalCord",
  ];
  const BACKROOM_NUM_CAP = 9999;

  const BACKROOM_ACTIONS = {
    thread: {
      spool: { btn: "#thread-hotspot-spool", target: "blank-name-cloakroom", feedback: "线轴吐出一截没有去处的红线。寄存处替它挂上一件空外套。", mark: "loosenedRedSpool" },
      seal: { btn: "#thread-hotspot-seal", target: "return-audit", feedback: "黑蜡没有留下图案，只留下你确实按过它的重量。", mark: "pressedWitnessSeal" },
      gap: { btn: "#thread-hotspot-gap", target: "corridor", feedback: "红线从柜后穿过去，拖着八张纸一起通向经文走廊。", mark: "followedThreadGap" },
    },
    name: {
      coat: { btn: "#name-hotspot-coat", target: "proxy-admission", feedback: "外套认出了你的肩膀。代审窗把这当成另一份在场证。", mark: "woreOwnerlessCoat" },
      hook: { btn: "#name-hotspot-hook", target: "red-thread-registry", feedback: "你的名字没有被写下，只被一根红线挂到了另一面墙。", mark: "hungBlankName" },
      token: { btn: "#name-hotspot-token", target: "clapperless-bell-desk", feedback: "圆牌翻到背面。无舌铃台把空白的一面当成了叫号。", mark: "turnedBlankClaimToken" },
    },
    bell: {
      bell: { btn: "#bell-hotspot-bell", target: "midnight-callback", feedback: "铃帽下降了一次。午夜回拨台替它补上了迟到的声音。", mark: "pressedClapperlessBell" },
      tube: { btn: "#bell-hotspot-tube", target: "blank-name-cloakroom", feedback: "管内没有人回答，只有衣架互相碰了一下。", mark: "spokeIntoDeskTube" },
      cord: { btn: "#bell-hotspot-cord", target: "protocol", feedback: "红绳把接待台折回布告板背面。八条守则还在原处等你。", mark: "pulledRedSignalCord" },
    },
  };
  const BACKROOM_RESPONSE_EL = { thread: "#thread-response", name: "#name-response", bell: "#bell-response" };
  const BACKROOM_LINKS = { thread: "#thread-link", name: "#name-link", bell: "#bell-link" };

  const getBackrooms = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(BACKROOM_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    /* visited 只接受 thread / name / bell 三个布尔键 */
    const visited = {};
    BACKROOM_SCENES.forEach((s) => {
      visited[s] = Boolean(raw.visited && raw.visited[s] === true);
    });
    const entry = BACKROOM_ENTRIES.includes(raw.entry) ? raw.entry : "direct";
    /* pending 仅用于三间背室的九动作，必须是 {scene, action, target, feedback}
       完整合法映射；任何 target/feedback/scene/action 错配即清空。
       pending 只用于恢复已接受但尚未完成的自动转场，不作为已访问或计数依据 */
    let pending = null;
    if (raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const acts = BACKROOM_ACTIONS[raw.pending.scene];
      const act = acts && acts[raw.pending.action];
      if (act && raw.pending.target === act.target && raw.pending.feedback === act.feedback) {
        pending = { scene: raw.pending.scene, action: raw.pending.action, target: act.target, feedback: act.feedback };
      }
    }
    /* lastScene / lastAction 只接受白名单且必须互相匹配 */
    const lastScene = BACKROOM_SCENES.includes(raw.lastScene) ? raw.lastScene : "";
    const lastAction = lastScene && BACKROOM_ACTIONS[lastScene][raw.lastAction] ? raw.lastAction : "";
    let traversals = Number(raw.traversals);
    if (!Number.isFinite(traversals) || traversals < 0) traversals = 0;
    traversals = Math.min(BACKROOM_NUM_CAP, Math.floor(traversals));
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => BACKROOM_MARKS.includes(m)))].slice(0, BACKROOM_MARKS.length)
      : [];
    return { visited, entry, pending, lastScene, lastAction, traversals, marks };
  };
  const saveBackrooms = (st) => store.set(BACKROOM_KEY, JSON.stringify(st));

  const syncBackroomLinks = () => {
    const st = getBackrooms();
    BACKROOM_SCENES.forEach((s) => {
      const link = $(BACKROOM_LINKS[s]);
      if (!link) return;
      if (st.visited[s]) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  /* 到访标记在点击/进入时立即持久化：即便转场被回退取消，目录入口也已出现 */
  const markBackroomVisited = (sceneKey) => {
    const st = getBackrooms();
    if (!BACKROOM_SCENES.includes(sceneKey) || st.visited[sceneKey]) return;
    st.visited[sceneKey] = true;
    saveBackrooms(st);
    syncBackroomLinks();
  };

  const backroomDelay = () => reduced ? 300 : 900 + Math.floor(Math.random() * 300);

  const paintBackroomScene = (sceneKey) => {
    const st = getBackrooms();
    const locked = AutoAdvance.has("backroom-" + sceneKey);
    Object.keys(BACKROOM_ACTIONS[sceneKey]).forEach((actionId) => {
      const btn = $(BACKROOM_ACTIONS[sceneKey][actionId].btn);
      if (!btn) return;
      btn.disabled = locked;
      btn.setAttribute("aria-pressed", st.marks.includes(BACKROOM_ACTIONS[sceneKey][actionId].mark) ? "true" : "false");
    });
  };

  /* 进入背室场景：到访标记；若合法 pending 属于本场景（reload/离场后重返），
     重播逐字反馈并恢复转场，timer 真正触发前才清 pending */
  const enterBackroom = (sceneKey) => {
    markBackroomVisited(sceneKey);
    const st = getBackrooms();
    const responseEl = $(BACKROOM_RESPONSE_EL[sceneKey]);
    if (responseEl) responseEl.textContent = "";
    if (st.pending && st.pending.scene === sceneKey) {
      const p = st.pending;
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule("backroom-" + sceneKey, p.target, {
        delay: backroomDelay(),
        before: () => {
          const s = getBackrooms();
          if (s.pending && s.pending.scene === sceneKey && s.pending.action === p.action) {
            s.pending = null;
            saveBackrooms(s);
          }
        },
      });
    }
    paintBackroomScene(sceneKey);
  };

  /* 九个画面动作：在任何状态访问与副作用前校验当前场景（隐藏/off-route
     脚本化点击零副作用）；第一项被接受后同场景全部热点立即 disabled
     （同节拍竞争只接受第一项），逐字反馈写入 aria-live，pending 持久化后自动转场 */
  const runBackroomAction = (sceneKey, actionId) => {
    const act = BACKROOM_ACTIONS[sceneKey] && BACKROOM_ACTIONS[sceneKey][actionId];
    if (!act) return;
    if (currentScene !== BACKROOM_SCENE_NAME[sceneKey]) return;
    if (AutoAdvance.has("backroom-" + sceneKey)) return;
    const st = getBackrooms();
    st.lastScene = sceneKey;
    st.lastAction = actionId;
    if (!st.marks.includes(act.mark)) st.marks.push(act.mark);
    st.traversals = Math.min(BACKROOM_NUM_CAP, st.traversals + 1);
    st.pending = { scene: sceneKey, action: actionId, target: act.target, feedback: act.feedback };
    st.entry = sceneKey;
    saveBackrooms(st);
    const responseEl = $(BACKROOM_RESPONSE_EL[sceneKey]);
    if (responseEl) responseEl.textContent = act.feedback;
    AudioEngine.knock(0.16);
    /* 先排定再重绘：节拍内同场景全部热点保持 disabled */
    AutoAdvance.schedule("backroom-" + sceneKey, act.target, {
      delay: backroomDelay(),
      before: () => {
        const s = getBackrooms();
        if (s.pending && s.pending.scene === sceneKey && s.pending.action === actionId) {
          s.pending = null;
          saveBackrooms(s);
        }
      },
    });
    paintBackroomScene(sceneKey);
  };

  BACKROOM_SCENES.forEach((sceneKey) => {
    Object.keys(BACKROOM_ACTIONS[sceneKey]).forEach((actionId) => {
      const btn = $(BACKROOM_ACTIONS[sceneKey][actionId].btn);
      if (btn) btn.addEventListener("click", () => runBackroomAction(sceneKey, actionId));
    });
  });

  /* 守则布告板三入口：与八条守则共用 protocol 首选锁（第一条被接受的规则或
     热点决定本拍归宿）；在任何状态读取/写入、声音、反馈与 timer 之前校验
     currentScene === "protocol"；反馈写入独立的 #protocol-backroom-response，
     不复用或覆盖八条守则原反馈；玖异常不并入 v41 状态 */
  const BACKROOM_PROTOCOL_SPOTS = {
    "protocol-hotspot-thread": { entry: "protocol-thread", scene: "thread", target: "red-thread-registry", feedback: "红线从八条守则背后抽紧。布告板让出一条只容卷宗通过的缝。", mark: "enteredThreadRegistry" },
    "protocol-hotspot-nameplate": { entry: "protocol-name", scene: "name", target: "blank-name-cloakroom", feedback: "空白名牌记住了你的按痕，却仍拒绝写出名字。", mark: "enteredBlankNameCloakroom" },
    "protocol-hotspot-bell": { entry: "protocol-bell", scene: "bell", target: "clapperless-bell-desk", feedback: "铃钮陷进墙里。没有铃声，接待台却已经叫到你。", mark: "enteredClapperlessBellDesk" },
  };
  Object.keys(BACKROOM_PROTOCOL_SPOTS).forEach((id) => {
    const btn = $("#" + id);
    const spot = BACKROOM_PROTOCOL_SPOTS[id];
    if (!btn) return;
    btn.addEventListener("click", () => {
      if (currentScene !== "protocol") return;
      if (AutoAdvance.has("protocol")) return;
      const st = getBackrooms();
      st.entry = spot.entry;
      st.visited[spot.scene] = true;
      if (!st.marks.includes(spot.mark)) st.marks.push(spot.mark);
      st.traversals = Math.min(BACKROOM_NUM_CAP, st.traversals + 1);
      saveBackrooms(st);
      syncBackroomLinks();
      btn.classList.add("touched");
      setTimeout(() => btn.classList.remove("touched"), 1200);
      AudioEngine.knock();
      const responseEl = $("#protocol-backroom-response");
      if (responseEl) responseEl.textContent = spot.feedback;
      AutoAdvance.schedule("protocol", spot.target, {
        delay: branchDelay(),
        before: () => { protocolConsumed = true; },
      });
    });
  });

  /* 痕迹页单行：穿行次数与已见场景数，保持八张统计卡不变 */
  const paintBackroomMemory = () => {
    const memory = $("#backroom-memory");
    if (!memory) return;
    const st = getBackrooms();
    const seen = BACKROOM_SCENES.filter((s) => st.visited[s]).length;
    if (seen === 0) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `守则背室：穿行 ${st.traversals} 次；红线 / 空名 / 无舌铃已见 ${seen}/3。`;
    memory.hidden = false;
  };

  /* ============================================================
     v42 守则漂移：v41 两间背室解锁第四入口 + 四拍巡查判断
     状态独立存 goddead_v42_protocol_drift，容错坏 JSON；
     只读 v41 visited 用于解锁，不改写 v28–v41 与主线任何键；
     pending 与固定规则表逐字段一致；点击即执行，无确认/继续按钮。
     ============================================================ */
  const DRIFT_KEY = "goddead_v42_protocol_drift";
  const DRIFT_SEQ = ["thread", "normal", "bell", "name", "thread", "bell", "normal", "name"];
  const DRIFT_ROUNDS = ["normal", "thread", "name", "bell"];
  const DRIFT_ANSWERS = ["forward", "thread", "name", "bell", "exit"];
  const DRIFT_NUM_CAP = 9999;
  const DRIFT_MARKS = [
    "unlockedProtocolDrift", "enteredProtocolDrift",
    "reportedThreadDrift", "reportedNameDrift", "reportedBellDrift", "passedCleanBoard",
    "misreportedThread", "misreportedName", "misreportedBell", "missedRealDrift",
    "completedCleanCycle", "completedThreadCycle", "completedNameCycle", "completedBellCycle",
  ];
  const DRIFT_ROUND_IMG = {
    normal: "assets/visitor-protocol-board.webp",
    thread: "assets/protocol-drift-thread.webp",
    name: "assets/protocol-drift-nameplate.webp",
    bell: "assets/protocol-drift-bell.webp",
  };
  const DRIFT_CORRECT_FEEDBACK = {
    normal: "旧蜡印没有移动。你放行了一个仍然服从原样的夜晚。",
    thread: "你指出第九个绳结。它松开时，墙后传来一张纸被撤回的声音。",
    name: "空名牌退回墙里。那枚没有号码的取物牌也跟着消失了。",
    bell: "你在它响以前认出了铃口。黑色液体沿原路缩回黄铜里面。",
  };
  const DRIFT_COMPLETE = {
    normal: { target: "protocol", feedback: "三次巡查没有留下误差。守则允许你从正面回去。", mark: "completedCleanCycle" },
    thread: { target: "red-thread-registry", feedback: "三次巡查缠成同一根线。登记室要求保存这份连对记录。", mark: "completedThreadCycle" },
    name: { target: "blank-name-cloakroom", feedback: "三次巡查仍没有写出名字。寄存处替你保留了空白。", mark: "completedNameCycle" },
    bell: { target: "clapperless-bell-desk", feedback: "三次巡查都先于铃声。接待台把沉默记作合格。", mark: "completedBellCycle" },
  };
  const DRIFT_ROOM = { thread: "red-thread-registry", name: "blank-name-cloakroom", bell: "clapperless-bell-desk" };
  const DRIFT_MISREPORT = {
    thread: { feedback: "你报告了红线，但红线没有移动。误报把你送进登记室重新认线。", mark: "misreportedThread" },
    name: { feedback: "你报告了空名牌，但它仍然闭合。寄存处要求你核对自己的名字。", mark: "misreportedName" },
    bell: { feedback: "你报告了铃钮，但它还没有张口。接待台仍把误报当成一次叫号。", mark: "misreportedBell" },
  };
  const DRIFT_MISSED = {
    thread: "你放行了第九个绳结。红线从布告板背面把你拖进登记室。",
    name: "你放行了半开的空名牌。取物牌把你领进寄存处。",
    bell: "你放行了渗液的铃口。没有声音的叫号仍然轮到了你。",
  };
  const DRIFT_WRONG_SPOT = {
    "thread>name": "你报告了空名牌，但漂移的是红线。寄存处收下了这次错报，第九个绳结仍留在原处。",
    "thread>bell": "你报告了铃钮，但漂移的是红线。接待台收下了这次错报，第九个绳结仍留在原处。",
    "name>thread": "你报告了红线，但漂移的是空名牌。登记室收下了这次错报，半开的名牌仍留在原处。",
    "name>bell": "你报告了铃钮，但漂移的是空名牌。接待台收下了这次错报，半开的名牌仍留在原处。",
    "bell>thread": "你报告了红线，但漂移的是铃钮。登记室收下了这次错报，渗液的铃口仍留在原处。",
    "bell>name": "你报告了空名牌，但漂移的是铃钮。寄存处收下了这次错报，渗液的铃口仍留在原处。",
  };
  const DRIFT_REPORT_MARK = { thread: "reportedThreadDrift", name: "reportedNameDrift", bell: "reportedBellDrift" };

  /* 固定规则表：给定拍面/作答/接受后 streak，推导唯一合法的
     correct/target/feedback/nextCycle/nextCursor（handler 与 pending 校验共用） */
  const driftResolve = (round, answer, cycle, cursor, streak) => {
    const correct = answer === "forward" ? round === "normal" : answer === round;
    if (correct) {
      if (streak >= 3) {
        const c = DRIFT_COMPLETE[round];
        return { round, answer, correct: true, target: c.target, feedback: c.feedback, nextCycle: cycle + 1, nextCursor: 0 };
      }
      return { round, answer, correct: true, target: "protocol-drift", feedback: DRIFT_CORRECT_FEEDBACK[round], nextCycle: cycle, nextCursor: cursor + 1 };
    }
    let target;
    let feedback;
    if (round === "normal") {
      target = DRIFT_ROOM[answer];
      feedback = DRIFT_MISREPORT[answer].feedback;
    } else if (answer === "forward") {
      target = DRIFT_ROOM[round];
      feedback = DRIFT_MISSED[round];
    } else {
      target = DRIFT_ROOM[answer];
      feedback = DRIFT_WRONG_SPOT[`${round}>${answer}`];
    }
    return { round, answer, correct: false, target, feedback, nextCycle: cycle + 1, nextCursor: 0 };
  };

  const getDrift = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(DRIFT_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    const num = (v) => {
      let n = Number(v);
      if (!Number.isFinite(n) || n < 0) n = 0;
      return Math.min(DRIFT_NUM_CAP, Math.floor(n));
    };
    const visited = raw.visited === true;
    const cycle = num(raw.cycle);
    /* cursor 只接受 0–7，非法归 0；round 永远按 cycle + 固定序列重算 */
    let cursor = num(raw.cursor);
    if (cursor > 7) cursor = 0;
    const round = DRIFT_SEQ[(cycle * 3 + cursor) % DRIFT_SEQ.length];
    /* streak / bestStreak 只接受 0–3；bestStreak 不得小于 streak */
    let streak = num(raw.streak);
    if (streak > 3) streak = 3;
    let bestStreak = num(raw.bestStreak);
    if (bestStreak > 3) bestStreak = 3;
    if (bestStreak < streak) bestStreak = streak;
    const correct = num(raw.correct);
    const misreports = num(raw.misreports);
    const inspections = num(raw.inspections);
    /* lastRound / lastAnswer 只接受合法组合；不合法一起清空 */
    let lastRound = DRIFT_ROUNDS.includes(raw.lastRound) ? raw.lastRound : "";
    let lastAnswer = DRIFT_ANSWERS.includes(raw.lastAnswer) ? raw.lastAnswer : "";
    if (!lastRound || !lastAnswer) {
      lastRound = "";
      lastAnswer = "";
    }
    /* pending 必须是 {round, answer, correct, target, feedback, nextCycle, nextCursor}
       完整映射并与固定规则表逐字段一致；任一字段错配即清空。
       pending 只用于恢复已接受但尚未完成的反馈/换图/转场，不得重复累计 */
    let pending = null;
    if (raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const p = raw.pending;
      if (p.round === round && DRIFT_ANSWERS.includes(p.answer) && p.answer !== "exit") {
        const expected = driftResolve(round, p.answer, cycle, cursor, streak);
        if (p.correct === expected.correct && p.target === expected.target && p.feedback === expected.feedback
          && p.nextCycle === expected.nextCycle && p.nextCursor === expected.nextCursor) {
          pending = { ...expected };
        }
      }
    }
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => DRIFT_MARKS.includes(m)))].slice(0, DRIFT_MARKS.length)
      : [];
    return { visited, cycle, cursor, round, streak, bestStreak, correct, misreports, inspections, lastRound, lastAnswer, pending, marks };
  };
  const saveDrift = (st) => store.set(DRIFT_KEY, JSON.stringify(st));

  /* 解锁：只读 v41 visited，任意两间背室为 true 即显露；坏存档按全 false */
  const driftUnlocked = () => BACKROOM_SCENES.filter((s) => getBackrooms().visited[s]).length >= 2;

  const syncDriftEntry = () => {
    const btn = $("#protocol-hotspot-drift");
    if (!btn) return;
    if (driftUnlocked()) {
      if (btn.hasAttribute("hidden")) {
        btn.removeAttribute("hidden");
        const st = getDrift();
        if (!st.marks.includes("unlockedProtocolDrift")) {
          st.marks.push("unlockedProtocolDrift");
          saveDrift(st);
        }
      }
    } else {
      btn.setAttribute("hidden", "");
    }
  };

  const syncDriftLink = () => {
    const link = $("#drift-link");
    if (!link) return;
    if (getDrift().visited) link.removeAttribute("hidden");
    else link.setAttribute("hidden", "");
  };

  const driftDelay = () => reduced ? 300 : 900 + Math.floor(Math.random() * 300);

  /* 换图：先隐去旧图，新图解码完成再现身（可感知换图节拍，不闪旧图不留白） */
  const showDriftImage = (round) => {
    const img = $("#drift-img");
    const asset = DRIFT_ROUND_IMG[round];
    if (!img || !asset) return;
    const showImg = () => img.classList.remove("is-loading");
    if (img.getAttribute("src") !== asset) {
      img.classList.add("is-loading");
      img.addEventListener("load", showImg, { once: true });
      img.setAttribute("src", asset);
      if (img.complete && img.naturalWidth > 0) showImg();
    } else {
      showImg();
    }
  };

  const paintDrift = () => {
    const st = getDrift();
    showDriftImage(st.round);
    const statusEl = $("#drift-status");
    if (statusEl) statusEl.textContent = `连对 ${st.streak} / 3 · 最佳 ${st.bestStreak} / 3 · 正确 ${st.correct} · 误报 ${st.misreports}`;
    const locked = AutoAdvance.has("protocol-drift") || AutoAdvance.has("protocol-drift-step");
    ["#drift-hotspot-thread", "#drift-hotspot-nameplate", "#drift-hotspot-bell", "#drift-hotspot-forward"].forEach((sel) => {
      const btn = $(sel);
      if (btn) btn.disabled = locked;
    });
  };

  /* timer 真正触发前清 pending 并应用下一拍坐标；只恢复动作，不重复累计。
     完成拍落地时连对归零（下一轮从头连对）；误判在作答时已归零 */
  const fireDriftPending = () => {
    const st = getDrift();
    if (!st.pending) return;
    if (st.pending.correct && st.pending.target !== "protocol-drift") st.streak = 0;
    st.cycle = st.pending.nextCycle;
    st.cursor = st.pending.nextCursor;
    st.pending = null;
    saveDrift(st);
  };

  const advanceDriftBeat = (target) => {
    fireDriftPending();
    if (target === "protocol-drift") {
      paintDrift();
      /* 下一拍焦点回到第一判断热点 */
      const first = $("#drift-hotspot-thread");
      if (first) focusReliably(first);
    }
  };

  /* 进入巡查台：到访标记（直 hash 始终允许，不自动作答）；
     合法 pending 属于本场景（reload/离场后重返）时重播原反馈并完成原动作 */
  const enterDrift = () => {
    const st0 = getDrift();
    if (!st0.visited) {
      st0.visited = true;
      saveDrift(st0);
      syncDriftLink();
    }
    const st = getDrift();
    const responseEl = $("#drift-response");
    if (responseEl) responseEl.textContent = "";
    if (st.pending) {
      const p = st.pending;
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule("protocol-drift-step", p.target, {
        delay: driftDelay(),
        before: () => advanceDriftBeat(p.target),
      });
    }
    paintDrift();
  };

  /* 四个判断：在任何 v42 状态读写、反馈、声音或 timer 前校验当前场景；
     同拍只接受第一项，接受后四个判断热点立即 disabled */
  const answerDrift = (answer) => {
    if (!["forward", "thread", "name", "bell"].includes(answer)) return;
    if (currentScene !== "protocol-drift") return;
    if (AutoAdvance.has("protocol-drift") || AutoAdvance.has("protocol-drift-step")) return;
    const st = getDrift();
    const round = st.round;
    const correct = answer === "forward" ? round === "normal" : answer === round;
    st.lastRound = round;
    st.lastAnswer = answer;
    st.inspections = Math.min(DRIFT_NUM_CAP, st.inspections + 1);
    if (correct) {
      st.correct = Math.min(DRIFT_NUM_CAP, st.correct + 1);
      st.streak = Math.min(3, st.streak + 1);
      st.bestStreak = Math.max(st.bestStreak, st.streak);
      const mark = answer === "forward" ? "passedCleanBoard" : DRIFT_REPORT_MARK[answer];
      if (!st.marks.includes(mark)) st.marks.push(mark);
      if (st.streak >= 3) {
        const cm = DRIFT_COMPLETE[round].mark;
        if (!st.marks.includes(cm)) st.marks.push(cm);
      }
    } else {
      st.misreports = Math.min(DRIFT_NUM_CAP, st.misreports + 1);
      st.streak = 0;
      if (answer !== "forward") {
        const mm = DRIFT_MISREPORT[answer].mark;
        if (!st.marks.includes(mm)) st.marks.push(mm);
      }
      if (round !== "normal" && !st.marks.includes("missedRealDrift")) st.marks.push("missedRealDrift");
    }
    const resolution = driftResolve(round, answer, st.cycle, st.cursor, st.streak);
    st.pending = { ...resolution };
    saveDrift(st);
    const responseEl = $("#drift-response");
    if (responseEl) responseEl.textContent = resolution.feedback;
    AudioEngine.knock(0.16);
    /* 先排定再重绘：节拍内四个判断热点保持 disabled */
    AutoAdvance.schedule("protocol-drift-step", resolution.target, {
      delay: driftDelay(),
      before: () => advanceDriftBeat(resolution.target),
    });
    paintDrift();
  };

  [
    ["#drift-hotspot-thread", "thread"],
    ["#drift-hotspot-nameplate", "name"],
    ["#drift-hotspot-bell", "bell"],
    ["#drift-hotspot-forward", "forward"],
  ].forEach(([sel, answer]) => {
    const btn = $(sel);
    if (btn) btn.addEventListener("click", () => answerDrift(answer));
  });

  /* 守则板第四入口：与八条守则及 v41 三入口共用 protocol 首选锁；
     在任何状态读写、声音、反馈或 timer 前校验 currentScene === "protocol" */
  const driftSpotBtn = $("#protocol-hotspot-drift");
  if (driftSpotBtn) driftSpotBtn.addEventListener("click", () => {
    if (currentScene !== "protocol") return;
    if (AutoAdvance.has("protocol")) return;
    if (!driftUnlocked()) return;
    const st = getDrift();
    st.visited = true;
    if (!st.marks.includes("enteredProtocolDrift")) st.marks.push("enteredProtocolDrift");
    saveDrift(st);
    syncDriftLink();
    driftSpotBtn.classList.add("touched");
    setTimeout(() => driftSpotBtn.classList.remove("touched"), 1200);
    AudioEngine.knock();
    const responseEl = $("#protocol-backroom-response");
    if (responseEl) responseEl.textContent = "旧蜡印比上一次更软。布告板要求你证明，自己还记得它原来的样子。";
    AutoAdvance.schedule("protocol", "protocol-drift", {
      delay: branchDelay(),
      before: () => { protocolConsumed = true; },
    });
  });

  /* 痕迹页单行：巡查/正确/最佳连对/误报，保持八张统计卡不变 */
  const paintDriftMemory = () => {
    const memory = $("#drift-memory");
    if (!memory) return;
    const st = getDrift();
    if (!st.visited) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `守则漂移：巡查 ${st.inspections} 次；正确 ${st.correct} 次；最佳连对 ${st.bestStreak}/3；误报 ${st.misreports} 次。`;
    memory.hidden = false;
  };

  /* ============================================================
     v43 门内回敲网：第一敲后门板三回敲 + 三个画面热点场景
     状态独立存 goddead_v43_counter_knock，容错坏 JSON；
     pending 必须是 {scene, action, target, feedback} 完整合法映射；
     不读不写 v28–v42 与主线状态；点击即执行，无确认/继续按钮。
     ============================================================ */
  const KNOCK_KEY = "goddead_v43_counter_knock";
  const KNOCK_SCENES = ["gallery", "vestibule", "dispatch"];
  const KNOCK_SCENE_NAMES = ["counter-knock-gallery", "unanswered-vestibule", "undersill-dispatch"];
  const KNOCK_SCENE_NAME = { gallery: "counter-knock-gallery", vestibule: "unanswered-vestibule", dispatch: "undersill-dispatch" };
  const KNOCK_NAME_SCENE = { "counter-knock-gallery": "gallery", "unanswered-vestibule": "vestibule", "undersill-dispatch": "dispatch" };
  const KNOCK_ENTRIES = ["threshold-left", "threshold-seam", "threshold-right", "gallery", "vestibule", "dispatch", "direct"];
  const KNOCK_MARKS = [
    "struckInwardKnocker", "heldStillKnocker", "followedEarlyShadow",
    "registeredFirstKnock", "heardSecondKnock", "erasedThirdKnock",
    "acceptedBlackSeal", "returnedBlankSlip", "climbedHingeRail",
  ];
  const KNOCK_NUM_CAP = 9999;

  const KNOCK_ACTIONS = {
    gallery: {
      inward: { btn: "#counter-knock-action-inward", target: "peephole-chamber", feedback: "门环向墙里落下。倒置窥孔从另一面替你睁开。", mark: "struckInwardKnocker" },
      still: { btn: "#counter-knock-action-still", target: "unanswered-vestibule", feedback: "门环没有动。未应门前厅却替它登记了第二声。", mark: "heldStillKnocker" },
      shadow: { btn: "#counter-knock-action-shadow", target: "undersill-dispatch", feedback: "影子钻进门槛。投递轨把你的脚步当成一封未封口的信。", mark: "followedEarlyShadow" },
    },
    vestibule: {
      first: { btn: "#unanswered-action-first", target: "protocol", feedback: "第一声获得编号。访客守则承认你已经来过一次。", mark: "registeredFirstKnock" },
      second: { btn: "#unanswered-action-second", target: "counter-knock-gallery", feedback: "第二声找到了原来的门环。回敲廊重新向你打开。", mark: "heardSecondKnock" },
      third: { btn: "#unanswered-action-third", target: "return-passage", feedback: "第三声被撤销。回返夹道替你保存了一条没有开门的路线。", mark: "erasedThirdKnock" },
    },
    dispatch: {
      seal: { btn: "#undersill-action-seal", target: "proxy-admission", feedback: "封件没有名字，代审窗仍把它当成一位夜访者。", mark: "acceptedBlackSeal" },
      blank: { btn: "#undersill-action-blank", target: "glyph-niche", feedback: "纸条从门缝出去时，多带走了一个编号。失号龛替它留出空位。", mark: "returnedBlankSlip" },
      hinge: { btn: "#undersill-action-hinge", target: "hinge-sorting-room", feedback: "投递轨向上翻成门轴。铰链分拣室开始决定你应该向哪边打开。", mark: "climbedHingeRail" },
    },
  };
  /* v31 门前守卫的 v43 窄例外表：knock action → 唯一放行的 v31 场景 */
  const KNOCK_V31_TARGET = { inward: "peephole-chamber", third: "return-passage", blank: "glyph-niche" };
  const KNOCK_RESPONSE_EL = { gallery: "#gallery-response", vestibule: "#unanswered-vestibule-response", dispatch: "#dispatch-response" };
  const KNOCK_LINKS = { gallery: "#knock-gallery-link", vestibule: "#unanswered-link", dispatch: "#undersill-link" };

  const getKnockNet = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(KNOCK_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    /* visited 只接受 gallery / vestibule / dispatch 三个布尔键 */
    const visited = {};
    KNOCK_SCENES.forEach((s) => {
      visited[s] = Boolean(raw.visited && raw.visited[s] === true);
    });
    const entry = KNOCK_ENTRIES.includes(raw.entry) ? raw.entry : "direct";
    /* pending 必须是 {scene, action, target, feedback} 完整合法映射，
       四字段与动作表逐字段一致；任一字段缺失或错配即清空。
       pending 只用于恢复已接受但尚未完成的自动转场，不作为已访问或计数依据 */
    let pending = null;
    if (raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const acts = KNOCK_ACTIONS[raw.pending.scene];
      const act = acts && acts[raw.pending.action];
      if (act && raw.pending.target === act.target && raw.pending.feedback === act.feedback) {
        pending = { scene: raw.pending.scene, action: raw.pending.action, target: act.target, feedback: act.feedback };
      }
    }
    /* lastScene / lastAction 只接受白名单且必须互相匹配 */
    const lastScene = KNOCK_SCENES.includes(raw.lastScene) ? raw.lastScene : "";
    const lastAction = lastScene && KNOCK_ACTIONS[lastScene][raw.lastAction] ? raw.lastAction : "";
    let traversals = Number(raw.traversals);
    if (!Number.isFinite(traversals) || traversals < 0) traversals = 0;
    traversals = Math.min(KNOCK_NUM_CAP, Math.floor(traversals));
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => KNOCK_MARKS.includes(m)))].slice(0, KNOCK_MARKS.length)
      : [];
    return { visited, entry, pending, lastScene, lastAction, traversals, marks };
  };
  const saveKnockNet = (st) => store.set(KNOCK_KEY, JSON.stringify(st));

  const syncKnockLinks = () => {
    const st = getKnockNet();
    KNOCK_SCENES.forEach((s) => {
      const link = $(KNOCK_LINKS[s]);
      if (!link) return;
      if (st.visited[s]) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  /* 到访标记在点击/进入时立即持久化：即便转场被回退取消，目录入口也已出现 */
  const markKnockVisited = (sceneKey) => {
    const st = getKnockNet();
    if (!KNOCK_SCENES.includes(sceneKey) || st.visited[sceneKey]) return;
    st.visited[sceneKey] = true;
    saveKnockNet(st);
    syncKnockLinks();
  };

  const knockNetDelay = () => reduced ? 300 : 900 + Math.floor(Math.random() * 300);

  const paintKnockScene = (sceneKey) => {
    const st = getKnockNet();
    const locked = AutoAdvance.has("knocknet-" + sceneKey);
    Object.keys(KNOCK_ACTIONS[sceneKey]).forEach((actionId) => {
      const btn = $(KNOCK_ACTIONS[sceneKey][actionId].btn);
      if (!btn) return;
      btn.disabled = locked;
      btn.setAttribute("aria-pressed", st.marks.includes(KNOCK_ACTIONS[sceneKey][actionId].mark) ? "true" : "false");
    });
  };

  /* 进入回敲场景：到访标记；若合法 pending 属于本场景（reload/离场后重返），
     重播逐字反馈并恢复转场，timer 真正触发前才清 pending */
  const enterKnockNet = (sceneKey) => {
    markKnockVisited(sceneKey);
    const st = getKnockNet();
    const responseEl = $(KNOCK_RESPONSE_EL[sceneKey]);
    if (responseEl) responseEl.textContent = "";
    if (st.pending && st.pending.scene === sceneKey) {
      const p = st.pending;
      if (responseEl) responseEl.textContent = p.feedback;
      AutoAdvance.schedule("knocknet-" + sceneKey, p.target, {
        delay: knockNetDelay(),
        before: () => {
          const s = getKnockNet();
          if (s.pending && s.pending.scene === sceneKey && s.pending.action === p.action) {
            s.pending = null;
            saveKnockNet(s);
          }
        },
      });
    }
    paintKnockScene(sceneKey);
  };

  /* 九个画面动作：在任何状态访问与副作用前校验 live scene（隐藏/off-route
     脚本化点击零副作用）；第一项被接受后同场景全部热点立即 disabled
     （同节拍竞争只接受第一项），逐字反馈写入 aria-live，pending 持久化后自动转场 */
  const runKnockAction = (sceneKey, actionId) => {
    const act = KNOCK_ACTIONS[sceneKey] && KNOCK_ACTIONS[sceneKey][actionId];
    if (!act) return;
    if (currentScene !== KNOCK_SCENE_NAME[sceneKey]) return;
    if (AutoAdvance.has("knocknet-" + sceneKey)) return;
    const st = getKnockNet();
    st.lastScene = sceneKey;
    st.lastAction = actionId;
    if (!st.marks.includes(act.mark)) st.marks.push(act.mark);
    st.traversals = Math.min(KNOCK_NUM_CAP, st.traversals + 1);
    st.pending = { scene: sceneKey, action: actionId, target: act.target, feedback: act.feedback };
    st.entry = sceneKey;
    saveKnockNet(st);
    const responseEl = $(KNOCK_RESPONSE_EL[sceneKey]);
    if (responseEl) responseEl.textContent = act.feedback;
    AudioEngine.knock(0.16);
    /* 先排定再重绘：节拍内同场景全部热点保持 disabled */
    AutoAdvance.schedule("knocknet-" + sceneKey, act.target, {
      delay: knockNetDelay(),
      before: () => {
        const s = getKnockNet();
        if (s.pending && s.pending.scene === sceneKey && s.pending.action === actionId) {
          s.pending = null;
          saveKnockNet(s);
        }
      },
    });
    paintKnockScene(sceneKey);
  };

  KNOCK_SCENES.forEach((sceneKey) => {
    Object.keys(KNOCK_ACTIONS[sceneKey]).forEach((actionId) => {
      const btn = $(KNOCK_ACTIONS[sceneKey][actionId].btn);
      if (btn) btn.addEventListener("click", () => runKnockAction(sceneKey, actionId));
    });
  });

  /* 门内回敲窗口：第一/第二敲后三回敲显露（第二敲更急促），
     第三敲/第四敲/敲门衰减/离开首页或首选锁已排定时隐藏 */
  const COUNTER_KNOCK_IDS = ["hotspot-counter-knock-left", "hotspot-counter-knock-seam", "hotspot-counter-knock-right"];
  const syncCounterKnockWindow = () => {
    const show = currentScene === "threshold" && (knocks === 1 || knocks === 2) && !thresholdConsumed && !AutoAdvance.has("threshold");
    COUNTER_KNOCK_IDS.forEach((id) => {
      const btn = $("#" + id);
      if (!btn) return;
      if (show) btn.removeAttribute("hidden");
      else btn.setAttribute("hidden", "");
      btn.classList.toggle("counter-urgent", show && knocks === 2);
    });
  };

  /* 三处回敲：与三敲、v31 三热点、v38 代审、v40 左右廊共用 threshold 首选锁；
     在读取状态、写反馈、播放声音或排 timer 前校验 live scene、窗口可见与敲门数 */
  const KNOCK_THRESHOLD_SPOTS = {
    "hotspot-counter-knock-left": { entry: "threshold-left", scene: "gallery", target: "counter-knock-gallery", feedback: "左扇门板从里面先敲了一次。那声回敲把门后的一整条廊道震亮。" },
    "hotspot-counter-knock-seam": { entry: "threshold-seam", scene: "vestibule", target: "unanswered-vestibule", feedback: "第二声没有来自门后。它被门缝收走，登记成一次从未发生的来访。" },
    "hotspot-counter-knock-right": { entry: "threshold-right", scene: "dispatch", target: "undersill-dispatch", feedback: "右扇没有振动。回敲沿把手向下滑，落进门槛下面的投递轨。" },
  };
  Object.keys(KNOCK_THRESHOLD_SPOTS).forEach((id) => {
    const btn = $("#" + id);
    const spot = KNOCK_THRESHOLD_SPOTS[id];
    if (!btn) return;
    btn.addEventListener("click", () => {
      if (currentScene !== "threshold") return;
      if (btn.hasAttribute("hidden")) return;
      if (knocks !== 1 && knocks !== 2) return;
      if (AutoAdvance.has("threshold")) return;
      const st = getKnockNet();
      st.entry = spot.entry;
      st.visited[spot.scene] = true;
      st.traversals = Math.min(KNOCK_NUM_CAP, st.traversals + 1);
      saveKnockNet(st);
      syncKnockLinks();
      btn.classList.add("touched");
      setTimeout(() => btn.classList.remove("touched"), 1200);
      /* 任一回敲被接受后立即隐藏全部三处并失去焦点 */
      COUNTER_KNOCK_IDS.forEach((other) => {
        const b = $("#" + other);
        if (b) b.setAttribute("hidden", "");
      });
      AudioEngine.knock();
      statusLine.textContent = spot.feedback;
      AutoAdvance.schedule("threshold", spot.target, { delay: branchDelay() });
    });
  });

  /* 痕迹页单行：改道次数与已见场景数，保持八张统计卡不变 */
  const paintKnockNetMemory = () => {
    const memory = $("#knocknet-memory");
    if (!memory) return;
    const st = getKnockNet();
    const seen = KNOCK_SCENES.filter((s) => st.visited[s]).length;
    if (seen === 0) {
      memory.hidden = true;
      return;
    }
    memory.textContent = `门内回敲：改道 ${st.traversals} 次；回敲 / 未应 / 门槛下已见 ${seen}/3。`;
    memory.hidden = false;
  };

  /* ============================================================
     v44 页后空层：残页 f1/f5/f8 首读改线 + 三个画面热点场景
     状态独立存 goddead_v44_paperback_spaces，容错坏 JSON；
     pending 必须是 {scene, action, target, feedback} 完整合法映射；
     不读不写 v28–v43 与主线状态；点击即执行，无确认/继续按钮。
     ============================================================ */
  const PAPERBACK_KEY = "goddead_v44_paperback_spaces";
  const PAPERBACK_SCENES = ["shadow", "foundry", "retention"];
  const PAPERBACK_SCENE_NAMES = ["lagging-shadow-cloister", "ash-door-foundry", "retention-vault"];
  const PAPERBACK_SCENE_NAME = { shadow: "lagging-shadow-cloister", foundry: "ash-door-foundry", retention: "retention-vault" };
  const PAPERBACK_NAME_SCENE = { "lagging-shadow-cloister": "shadow", "ash-door-foundry": "foundry", "retention-vault": "retention" };
  const PAPERBACK_ENTRIES = ["fragment-f1", "fragment-f5", "fragment-f8", "shadow", "foundry", "retention", "direct"];
  const PAPERBACK_MARKS = [
    "pulledShadowNail", "enteredOwnerlessOutline", "waitedForLateShadow",
    "workedColdBellows", "tookCinderKey", "crossedUnfinishedDoor",
    "woreBlankRetentionTag", "touchedMissingRelicImprint", "leftFragmentOnPlinth",
  ];
  const PAPERBACK_NUM_CAP = 9999;

  const PAPERBACK_ACTIONS = {
    shadow: {
      pin: { btn: "#paperback-shadow-action-pin", target: "borrowed-shadow-gallery", feedback: "钉子一松，墙上的影子立刻借走了你的站姿。", mark: "pulledShadowNail" },
      outline: { btn: "#paperback-shadow-action-outline", target: "ash-door-foundry", feedback: "轮廓比门更早关上。灰门铸室在纸背后亮起。", mark: "enteredOwnerlessOutline" },
      catch: { btn: "#paperback-shadow-action-catch", target: "return-passage", feedback: "影子从身后赶到，却从你的前面走进回返夹道。", mark: "waitedForLateShadow" },
    },
    foundry: {
      bellows: { btn: "#paperback-foundry-action-bellows", target: "protocol", feedback: "风箱吐出一口冷灰。灰尘在墙上排成第一条访客守则。", mark: "workedColdBellows" },
      key: { btn: "#paperback-foundry-action-key", target: "retention-vault", feedback: "钥匙没有齿，却准确打开了留置空库里最空的一格。", mark: "tookCinderKey" },
      door: { btn: "#paperback-foundry-action-door", target: "unlit-lamp-gallery", feedback: "你从缺少一侧门框的地方穿过去。无灯灯廊替它补上了黑暗。", mark: "crossedUnfinishedDoor" },
    },
    retention: {
      tag: { btn: "#paperback-retention-action-tag", target: "counter-knock-gallery", feedback: "标签贴住你以后，门内先替你敲了一声。", mark: "woreBlankRetentionTag" },
      imprint: { btn: "#paperback-retention-action-imprint", target: "lagging-shadow-cloister", feedback: "灰尘记住了手指，却把影子送回另一条回廊。", mark: "touchedMissingRelicImprint" },
      page: { btn: "#paperback-retention-action-page", target: "corridor", feedback: "纸留在原地，纸上的字却先一步回到了走廊。", mark: "leftFragmentOnPlinth" },
    },
  };
  const PAPERBACK_RESPONSE_EL = { shadow: "#paperback-shadow-response", foundry: "#paperback-foundry-response", retention: "#paperback-retention-response" };
  const PAPERBACK_LINKS = { shadow: "#paperback-shadow-link", foundry: "#paperback-foundry-link", retention: "#paperback-retention-link" };

  const getPaperback = () => {
    let raw = {};
    try {
      raw = JSON.parse(store.get(PAPERBACK_KEY, "{}")) || {};
    } catch { raw = {}; }
    if (typeof raw !== "object" || Array.isArray(raw)) raw = {};
    /* visited 只接受 shadow / foundry / retention 三个布尔键 */
    const visited = {};
    PAPERBACK_SCENES.forEach((s) => {
      visited[s] = Boolean(raw.visited && raw.visited[s] === true);
    });
    const entry = PAPERBACK_ENTRIES.includes(raw.entry) ? raw.entry : "direct";
    /* pending 必须是 {scene, action, target, feedback} 完整合法映射，
       四字段与动作表逐项完全对应；缺字段、伪造 target/feedback、
       scene/action 错配全部归一为 null。
       pending 只用于恢复已接受但尚未完成的自动转场，不作为已访问或计数依据 */
    let pending = null;
    if (raw.pending && typeof raw.pending === "object" && !Array.isArray(raw.pending)) {
      const acts = PAPERBACK_ACTIONS[raw.pending.scene];
      const act = acts && acts[raw.pending.action];
      if (act && raw.pending.target === act.target && raw.pending.feedback === act.feedback) {
        pending = { scene: raw.pending.scene, action: raw.pending.action, target: act.target, feedback: act.feedback };
      }
    }
    /* lastScene / lastAction 只接受白名单且必须互相匹配 */
    const lastScene = PAPERBACK_SCENES.includes(raw.lastScene) ? raw.lastScene : "";
    const lastAction = lastScene && PAPERBACK_ACTIONS[lastScene][raw.lastAction] ? raw.lastAction : "";
    let traversals = Number(raw.traversals);
    if (!Number.isFinite(traversals) || traversals < 0) traversals = 0;
    traversals = Math.min(PAPERBACK_NUM_CAP, Math.floor(traversals));
    const marks = Array.isArray(raw.marks)
      ? [...new Set(raw.marks.filter((m) => PAPERBACK_MARKS.includes(m)))].slice(0, PAPERBACK_MARKS.length)
      : [];
    return { visited, entry, pending, lastScene, lastAction, traversals, marks };
  };
  const savePaperback = (st) => store.set(PAPERBACK_KEY, JSON.stringify(st));

  const syncPaperbackLinks = () => {
    const st = getPaperback();
    PAPERBACK_SCENES.forEach((s) => {
      const link = $(PAPERBACK_LINKS[s]);
      if (!link) return;
      if (st.visited[s]) link.removeAttribute("hidden");
      else link.setAttribute("hidden", "");
    });
  };

  /* 到访标记在点击/进入时立即持久化：即便转场被回退取消，目录入口也已出现 */
  const markPaperbackVisited = (sceneKey) => {
    const st = getPaperback();
    if (!PAPERBACK_SCENES.includes(sceneKey) || st.visited[sceneKey]) return;
    st.visited[sceneKey] = true;
    savePaperback(st);
    syncPaperbackLinks();
  };

