  const SIDETONE_KEY = "goddead_v46_sidetones";
  const SIDETONE_SCENES = ["booth", "jack", "morgue"];
  const SIDETONE_SCENE_NAMES = ["unseated-listening-booth", "unnumbered-jack-field", "return-ring-morgue"];
