    version: SELF_AUTHENTICITY_VERSION,
    visited: { office: false, vault: false, examination: false, tribunal: false },
    draft: { claimant: '', provenance: '' },
    certificates: [],
    tribunalOutcomes: [],
    examRuns: 0,
