      st.pending = null;
      saveSelfAuthenticity(st);
      syncSelfAuthenticityOffice();
      syncSelfAuthenticityVault();
      syncSelfAuthenticityExamination();
      syncSelfAuthenticityTribunal();
      syncSelfAuthenticityAuthenticators();
