    const preSt = {
      version: WITNESS_PROTECTION_VERSION,
      visited,
      draft,
      placements,
      courtOutcomes,
      placementRuns,
      courtRuns,
      witnessTallies,
      lastOutcome,
      activeHandler,
      pending: null,
      _v84unlocked: true,
    };
    const pending = normalizeWitnessPending(raw.pending, preSt);

    return {
      version: WITNESS_PROTECTION_VERSION,
      visited,
      draft,
      placements,
      courtOutcomes,
      placementRuns,
      courtRuns,
      witnessTallies,
      lastOutcome,
      activeHandler,
      pending,
    };
